typedef long long ll;

#define reps(i, s, e) for (ll i = s; i < e; ++i)
#define rep(i, n) reps(i, 0, n)
#define rreps(i, s, e) for (ll i = e-1; i >= s; --i)
#define rrep(i, n) rreps(i, 0, n)

// const ll LL_INF = 1LL<<60;

template <class T> inline void chmin(T& a, T b) {if (a > b) {a = b;}}
template <class T> inline void chmax(T& a, T b) {if (a < b) {a = b;}}

using namespace std;

ll A;
int k;
vector<ll> l;
vector<ll> r;
char ch[20000];
vector<ll> height;

inline void strip_l(int& start, const int& end) {
    reps(i, start, end) {
        if (ch[i]=='/' || ch[i]=='_') start++;
        else break;
    }
}

inline void strip_r(const int& start, int& end) {
    rreps(i, start, end) {
        if (ch[i]=='\\' || ch[i]=='_') end--;
        else break;
    }
}

inline int calc_l(int& start, const int& end) {
    double area = 0;
    int depth = 0;
    reps(i, start, end) {
        if (depth==1 && ch[i]=='/') {
            area += (2*depth-1)/2.;
            start = i+1;
            break;
        } 
        else if (ch[i]=='/') area += (2*(depth--)-1)/2.;
        else if (ch[i]=='_') area += depth;
        else if (ch[i]=='\\') area += (2*(depth++)+1)/2.;
    }
    l.push_back(ll(area));
    return area;
}

inline int calc_r(const int& start, int& end) {
    double area = 0;
    int depth = 0;

    rreps(i, start, end) {
        if (depth==1 && ch[i]=='\\') {
            area += (2*depth-1)/2.;
            end = i;
            break;
        } 
        else if (ch[i]=='\\') area += (2*(depth--)-1)/2.;
        else if (ch[i]=='_') area += depth;
        else if (ch[i]=='/') area += (2*(depth++)+1)/2.;
    }
    r.push_back(ll(area));
    return area;
}


int main() {
    scanf("%s", ch);
    int start = 0;
    int end = strlen(ch);
    height.assign(end, 0LL);

    // 端の文字列を削除
    strip_r(start, end);
    strip_l(start, end);

    reps(i, 1, end) {
        if(ch[i]=='/') height[i] = height[i-1] + 1;
        else if(ch[i]=='_') height[i] = height[i-1];
        else height[i] = height[i-1] - 1;
    }

    while(end - start >= 1) {
        // 先頭から
        if (height[start] < height[end-1]) {
            A += calc_l(start, end);
            strip_l(start, end);
        } else {
            A += calc_r(start, end);
            strip_r(start, end);
        }
    }

    cout << A << endl;
    cout << l.size()+r.size();

    rep(i, l.size()) cout << " " << l[i];
    rrep(i, r.size()) cout << " " << r[i];
    cout << endl;
}

