	while (cin >> c) {
		if (c == '\\') {
			area2 += depth * 2 + 1;
			depth++;
		}
		else if (c == '_' && depth > 0) {
			area2 += depth * 2;
		}
		else if (c == '/') {
			if (depth > 1) {
				area2 += depth * 2 - 1;
				depth--;
			}
