#include	<iostream>
#include	<deque>
#include	<string>
#include	<algorithm>
#include	<utility>

using namespace std;

typedef pair<int, int>		StartAndArea;

int main()
{
	string			str;
	getline(cin, str);

	deque<int>		st;
	deque<StartAndArea>		areas;
	int				pos = 0;

	for (auto it : str)
	{
		switch (it)
		{
		case '/':
			if (st.size() != 0)
			{
				int		spos = st.front();
				st.pop_front();

				int		area = pos - spos;

				int		cnt = 0;

				for (auto i = 0u; i < areas.size(); i++)
				{
					if (areas[i].first >= spos)
					{
						area += areas[i].second;
						cnt++;
					}
				}

				for (int i = 0; i < cnt; i++)
				{
					areas.pop_front();
				}

				areas.push_front(make_pair(spos, area));
			}
			break;
		case '\\':
			st.push_front(pos);
			break;
		default:
			break;
		}

		pos++;
	}

	int		AnsSum = 0;
	for (auto it : areas)
	{
		AnsSum += it.second;
	}

	cout << AnsSum << "\n";
	cout << areas.size();
	for (int i = static_cast<int>(areas.size() - 1); i >= 0; i--)
	{
		cout << " ";
		cout << areas[i].second;
	}
	cout << "\n";

	return 0;
}

#include "iostream"
