      height[i] = height[i-1];
    }
  }
  int mv = INT_MIN;
  for(int i = 0; i < height.size(); i++){
    mv = max(mv, height[i]);
    lmax[i] = mv;
  }
  mv = INT_MIN;
  for(int i = height.size()-1; i >= 0; i--){
