const char FLAT = '_';

class Graph {
public:
  Graph() :
    size_(0) {}
  void add(int y);
  int getYat(int x);
  int size() { return size_; }
  int slop(int x0, int x1);
  void print();
private:
  static const int MAX_SIZE = 20000 + 1;
  int maxY();
  int minY();
  int y_[MAX_SIZE];
  int size_;
};

void Graph::add(int y)
{
  y_[size_] = y;
  size_++;
}

int Graph::getYat(int x)
{
  assert(x < size_);
  return y_[x];
}

int Graph::slop(int x0, int x1)
{
  assert(x0 != x1);
  int yd = getYat(x1) - getYat(x0);
  int xd = x1 - x0;
  return yd/xd;
}

void Graph::print()
{
  int max = maxY();
  int min = minY();
  const int maxX = size();
  const int maxY = max - min + 1;
  char c[maxY][maxX];

  for (int y = 0; y < maxY; y++) {
    for (int x = 0; x < maxX; x++) {
      c[y][x] = ' ';
    }
  }

  for (int x = 0; x < size(); x++) {
    int y = getYat(x) - min;
    c[y][x] = '+';
  }

  for (int y = maxY-1; y > -1; y--) {
    for (int x = 0; x < maxX; x++) {
      printf("%c", c[y][x]);
    }
    cout << endl;
  }

  for( int x = 0; x < maxX; x++) {
    if (x % 10 == 0)  cout << '|';
    else              cout << ' ';
  }
  cout << endl;
}

int Graph::maxY()
{
  int y = INT_MIN;
  for (int i = 0; i < size(); i++) {
    if (getYat(i) > y)
      y = getYat(i);
  }
  return y;
}

int Graph::minY()
{
  int y = INT_MAX;
  for (int i = 0; i < size(); i++) {
    if (getYat(i) < y)
      y = getYat(i);
  }
  return y;
}

