int main(){
    char c;
    vector<int> v;
    vector<int> w;
    queue<int> q1;
    v.push_back(0);
    int i = 0, s = 0, number, m;
    while(cin >> c){
        if (c == '/'){
            i++;
            v.push_back(i);
        }
        else if (c == '_'){
            v.push_back(i);
        }
        else {
            i--;
            v.push_back(i);
        }
    }
    int n = 0;
    w.push_back(v[0]);
    while(n < v.size()){
        while(v[n] <= v[n+1] ){
            w.push_back(v[n]);
            n++;
            if(n >= v.size()-1) break;
        }
        if(n != v.size()-1) {
            m = n+1;
        }
        else {
            w.push_back(v[n]);
            break;
        }
        while(v[m] != v[n]){
            m++;
            if(m >= v.size()) break;
        }
        if(m == v.size()) {
            w.push_back(v[n]);
            n++;
        }
        else {
            for(int j = n+1; j <= m; j++){
                w.push_back(v[n]);
            }
            q1.push(m);
            n = m;
        }

    }
    number = q1.size()-1;
    queue<int> q2;
    int ss = 0;
    for(int j = 0; j < v.size()-1; j++){
        ss += (w[j]-v[j]+w[j+1]-v[j+1]);
        if(j+1 == q1.front()){
            q2.push(ss);
            s += ss;
            ss = 0;
            q1.pop();
        }
    }
    if(q2.empty()){
        cout << 0 << "\n" << 0 << endl;
    }
    else {
        cout << s/2 << endl << number << " ";
        for(int j = 0; j < number; j++){
            cout << (q2.front())/2;
            if (j != number-1) cout << " ";
            q2.pop();
        }
    }
    cout << endl;

    return 0;
}

