#include <iostream>
#include <vector>
#include <numeric>

std::vector<size_t> solve(const std::string s){
	std::vector<size_t> ponds;
	size_t sum = 0;
	size_t end = 0;
	for(size_t i = 0; i < s.size(); ++i){
		if(i >= end && sum != 0){ponds.push_back(sum);sum=0;}
		if(s[i] == '\\'){
			int depth = -1;
			for(size_t j = i+1; j < s.size(); ++j){
				switch(s[j]){
					case '\\':
						--depth;
						break;
					case '/':
						++depth;
						if(depth == 0){
							sum += j-i;
							if(end < j) end = j;
							goto END;
						}
						break;
				}
			}
			END:;
		}
	}

	if(end == s.size()-1 && sum != 0) ponds.push_back(end);

	return ponds;
}

