int popValue(stack<int> *S) {
    int retVal = S->top();
    S->pop();
    return retVal;
}

struct depthAndAmount {
    int depth;
    int amount;
};

depthAndAmount popValue(stack<depthAndAmount> *S) {
    depthAndAmount retVal = S->top();
    S->pop();
    return retVal;
}

int main(int argc, const char * argv[]) {
    stack<int> S;
    stack<depthAndAmount> S2;
    string s;
    int i = 0;
    int total = 0;
    int depth = 0;
    cin >> s;

    while(i < s.length()){
        if (s[i] == '\\') {
            depth++;
            S.push(i);
        } else if (s[i] == '/') {
            int plus = 0;
            depth--;
            if (S.empty() == false) {
                int prevJ = popValue(&S);
                plus = i - prevJ;
            }
            total += plus;
            if (S2.empty() == false && S2.top().depth > depth) {
                depthAndAmount daa = S2.top();
                int amount = 0;
                do {
//                    cout << "/1 " << S2.top().depth << ", " << S2.top().amount << endl;
                    S2.pop();
                    amount += daa.amount;


                    if (S2.empty() == false) {
                        daa = S2.top();
                    } else {
                        break;
                    }
                } while (daa.depth > depth);
                daa.depth = depth;
                daa.amount = amount + plus;
                S2.push(daa);
            } else {
                depthAndAmount daa;
                daa.depth = depth;
                daa.amount = plus;
                S2.push(daa);

//                cout << "/2 " << S2.top().depth << ", " << S2.top().amount << endl;
            }
        } else if (s[i] == '_') {
        }
        i++;
    }
    string output;
    while (S2.empty() == false) {
        output = " " + IntToString(popValue(&S2).amount) + output;
    }

    cout << IntToString(total) << output << endl;

    return 0;
}

