void height(std::string value, scenery& list) {
    list.push_back(std::make_pair(0,0));
    for(int i = 0; i < value.size(); i++) {
       if(value.compare(i,1,"\\")==0) {
            list.push_back(std::make_pair(i+1,list.back().second-1));
        } else if (value.compare(i,1,"/")==0) {
            list.push_back(std::make_pair(i+1,list.back().second+1));
        } else {
            list.push_back(std::make_pair(i+1,list.back().second));
        }
    }
}

std::pair<int,point> highestPeak(scenery& list) {
    int pos=0;
    point peak = list[pos];
    for(int i=1; i<list.size();i++) {
        if(list[i].second>peak.second) {
            peak = list[i];
            pos= i;
        }
    }
    return std::make_pair(pos,peak);
}

void findPeaks(scenery& list, scenery& peaks) {
    std::pair<int,point> peak = highestPeak(list);
    if (peak.first!=0) {
        peaks.push_back(peak.second);
    }
    int i;
    for(i=peak.first+1; i<list.size();i++){
        if(list[i].second<peaks.back().second)
            break;
    }
