using namespace std;

class stack
{
	public:
	int s[10000];
	int t;

public:
	void initialize();
	void push(int x);
	int pop();
	int size();
};

void stack::initialize()
{
	t = 0;
}

void stack::push(int x)
{
	t++;
	s[t] = x;
}

int stack::pop()
{
	t--;
	return s[t];
}
int stack::size()
{
	return t;
}



int main()
{
	stack slash;
	stack backslash;
	queue<int>  Lake;
	stack  Lake2;
	int A;
	int n,start,countslash,countbackslash;
	double lake;
	string str;

	getline(cin,str);
	n = str.length();
	start = 0;

	slash.initialize();
	backslash.initialize();

	for(int i = start; i < n; i++)
	{

		if (str[i] == '\\')
		{
			//cout << "\\" << endl;
			slash.push(i);
			lake += (slash.size() - 0.5);

			//cout << slash.size();

			countslash++;

			//cout << "lake = " << lake << endl;
		}
		else if (str[i] == '/')
		{
			countbackslash++;

			if (slash.size() != 0)
			{
				//cout << "/" << endl;
				backslash.push(i);
				lake += (slash.size() - backslash.size() + 0.5);
				//cout << "lake = " << lake << endl;
			}
		}else
		{
			lake += slash.size();
			//cout << "lake = " << lake << endl;
		}

		if (slash.size() != 0 && slash.size() == backslash.size())
		{
			Lake.push(lake);
			A += lake;
			start = i+1;
			slash.initialize();
			backslash.initialize();
		}
	}

	if (countslash != countbackslash)
	{
		start = n-1;

		for(int i = start; i >= 0; i--)
		{
			slash.initialize();
			backslash.initialize();	

			if (str[i] == '/')
			{
				backslash.push(i);
				lake += (backslash.size() - 0.5);
			}
			else if (str[i] == '\\')
			{
				if (!backslash.size())
				{
					slash.push(i);
					lake += (backslash.size() - slash.size() + 0.5);
				}
			}else
			{
				lake += backslash.size();
			}	

			if (backslash.size() != 0 && slash.size() == backslash.size())
			{
				Lake2.push(lake);
				A += lake;
				start = i+1;
				slash.initialize();
				backslash.initialize();
			}
		}
	}

	while (Lake2.size() != 0)
	{
		Lake.push(Lake2.pop());
	}

	printf("%d\n", A);
	printf("%ld ", Lake.size());

	for(int i = 1; i <= Lake.size(); i++)
	{

		printf("%d ", Lake.front());
		if (i != Lake.size())
		{
			//printf(" ");
			Lake.pop();

		}else
		{
			printf("\n");
		}
	}

	return 0;
}

