	cnt+=(maxH-nowH)*2-1;
      }

    }
  }

  maxH=nowH=20000LL;
  maxW=(int)str.size()-1;

  cnt=0;

  for(int i=(int)str.size()-1;i>=0;i--){
    if(str[i]=='\\'){
      nowH++;
      if(maxH==nowH){
	cnt++;
	ans.push_back(P(maxW,cnt/2));
	cnt=0;
      }else if(maxH<nowH){
	maxH=nowH;
	maxW=i;
      }else{
	cnt+=(maxH-nowH)*2+1;
      }
    }else if(str[i]=='_'){
      if(maxH>nowH){
	cnt+=(maxH-nowH)*2;

      }else if(maxH==nowH){
	maxW=i;
      }
    }else{
      if(nowH==maxH)maxW=i;
      nowH--;
      if(maxH>nowH){
	cnt+=(maxH-nowH)*2-1;
      }
    }
  }

  sort(ans.begin(),ans.end());
  anssum=anssize=0;
