		if (s[i] == '/') {
			act++;
			flag = calc(act, &num);
			m[num].top = act;
			m[num].topn = i + 1;
			wind = 1;
		}
		if (s[i] == '_')m[num].topn = i + 1;
		if (s[i] == '\\') {
			if (flag)num++, flag = 0;
			ff = 0, act--, wind = 1;
