		for (int j = 0; j < num;j++)m[j].dis++;
	}

	int aa = 0, fff = 0, j = 0;
	for (int i = 0; i < num; i++)aa += area[i];
	//cout << num << "   ";
	if (!area[num - 1])num--;
	if (!area[0])num--, fff = 1, j++;
