#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector< int > heights;
vector< int > areas;

int getMinPointInValley(int i) {
  int currentMin = heights[i], currentPosn = i;
  // go left
  for (int iter = i-1; iter >= 0; iter--) {
    if (heights[iter] < currentMin) {
      currentMin = heights[iter];
      currentPosn = iter;
    }
    if (heights[iter] >= heights[i])
      break;
  }
  // go right
  for (int iter = i+1; iter < heights.size(); iter++) {
    if (heights[iter] < currentMin) {
      currentMin = heights[iter];
      currentPosn = iter;
    }
    if (heights[iter] >= heights[i])
      break;
  }
  return currentPosn;
}

int getLeftWall(int i) {
  int iter = i-1, currentMin = -100000;
  while (iter >= 0) {
    if (heights[iter] > currentMin) {
      i = iter;
      currentMin = heights[iter];
    }
    iter--;
  }
  return i;
}

int getRightWall(int i) {
  int iter = i+1, currentMin = -100000;
  while (iter < heights.size()) {
    if (heights[iter] > currentMin) {
      i = iter;
      currentMin = heights[iter];
    }
    iter++;
  }
  return i;
}

// returns the next starting position to search for a dip
int getArea(int i) {
  // add getMinpointinvalley of i and use that to find walls instead of i
  int min = getMinPointInValley(i);
  int left = getLeftWall(min), right = getRightWall(min);
  int realLeft = min, realRight = min;
  if (heights[left] < heights[right]) {
    realLeft = left;
    while (realRight <= right) {
      if (heights[realRight] == heights[realLeft])
	break;
      realRight++;
    }
  } else {
    realRight = right;
    while (realLeft >= left) {
      if (heights[realRight] == heights[realLeft])
	break;
      realLeft--;
    }
  }
  int area = 0;
  int toAdd = 0;
  for (i = realLeft+1; i <= realRight; i++) {
    if (heights[i] < heights[i-1]) {
      area += 1+toAdd;
      toAdd += 2;
    } else if (heights[i] > heights[i-1]) {
      toAdd -= 2;
      area += 1+toAdd;
    } else
      area += toAdd;
  }
  areas.push_back(area/2);
  return realRight;
}

int main(int argc, char **argv) {
  ios_base::sync_with_stdio(false);
  string input;
  cin >> input;
  heights = vector< int > (input.size()+1, 0);
  for (int i = 0; i < input.size(); i++) {
    if (input[i] == '\\')
      heights[i+1] = heights[i]-1;
    else if (input[i] == '/')
      heights[i+1] = heights[i]+1;
    else
      heights[i+1] = heights[i];
  }
  for (int i = 1; i < heights.size(); i++) {
    if (heights[i] < heights[i-1]) {
      i = getArea(i);
      if (!areas.back())
	areas.pop_back();
    }
  }
  int sum = 0;
  for (int i = 0; i < areas.size(); i++)
    sum += areas[i];
  cout << sum << endl;
  cout << areas.size();
  if (areas.size())
    cout << ' ';
  else
    cout << '\n';
  for (int i = 0; i < areas.size(); i++) {
    cout << areas[i];
    if (i == areas.size()-1)
      cout << '\n';
    else
      cout << ' ';
  }
  return 0;
}

