			}
		}
	}
	printf("%d\n%d ", sum, end2);
	if(end2 != 0){
		for(int i=0;i<end2;i++){
			printf("%d", stack2[i].qty);
			if(i != end2-1) printf(" ");
		}
	}
	printf("\n");
	return 0;
}

