struct SResult
{
	int begin;
	int end;
	int val;

	SResult(){ Init(); }

	void Init()
	{
		begin	= -1;
		end		= -1;
		val		= -1;
	}

	bool operator < ( const SResult& e) const
	{
		return begin < e.begin;
	}
	bool operator > (const SResult& e) const
	{
		return begin > e.begin;
	}
	bool IsValid() const
	{
		return ( begin >= 0 ) && ( end >= 0 ) && ( val >= 0 );
	}
};

