#include <iostream>
#include <string>
#include <map>
#include <set>
#include <vector>

using namespace std;

int
main()
{
    string line;
    getline(cin, line);

    int level = 0;
    vector<int> levels(line.length() + 1); // level at the point
    levels[0] = level;
    map<int, pair<int, int> > areas; // start, end, area
    map<int, int> working; // start, workarea
    for (int i = 0; i < line.length(); i++) {
        working.insert(map<int, int>::value_type(i, 0));

        set<int> delist;
        switch (line[i]) {
          case '\\':
            level--;
            for (auto& it : working) {
                working[it.first] += 2 * (levels[it.first] - level) - 1;
            }
            break;
          case '_':
            for (auto& it : working) {
                if (levels[it.first] == level) { delist.insert(it.first); }
                working[it.first] += 2 * (levels[it.first] - level);
            }
            break;
          case '/':
            level++;
            for (auto& it : working) {
                if (levels[it.first] <= level) { delist.insert(it.first); }
                if (levels[it.first] < level) break;
                working[it.first] += 2 * (levels[it.first] - level) + 1;
            }
            break;
        }
        for (auto& it : delist) {
            if (working[it] > 0)
            areas.insert(map<int, pair<int, int> >::value_type(it, make_pair(i + 1, working[it] / 2)));
            working.erase(it);
        }
        levels[ i + 1 ] = level;
    }

    vector<int> k;
    auto it = areas.cbegin();
    int next;
    int total = 0;
    while (it != areas.end()) {
        next = it->second.first;
        total += it->second.second;
        k.push_back(it->second.second);
        while (it != areas.end() && it->first < next) advance(it, 1);
    }

    cout << total << endl;
    cout << k.size();
    for (auto& it : k) { cout << ' ' << it; }
    cout << endl;

    cerr << read_msec << ", " << loop_msec << ", " << arrange_msec << endl;
    return 0;
}

