int main()
{
    // 入力
    string s;
    cin >> s;

    // '\'の位置を保存
    vector<int> v1;

    // 水たまりの面積を保存
    vector<pair<int,int>> v2;

    for(int i = 0; i < s.size(); i++)
    {
        // '\'の位置を保存
        if(s[i] == '\\') v1.push_back(i);

        // '/'と対になる'\'との差から面積を計算
        else if(s[i] == '/' && v1.size() > 0)
        {
            // '/'の位置iと対になる'\'の位置jを取り出す
            int j = v1.back();
            v1.pop_back();

            // '\'から'/'までの面積
            int a = i - j;

            // j～i間にある水たまりの統合
            while(v2.size() > 0 && v2.back().first > j)
            {
                a += v2.back().second;
                v2.pop_back();
            }

            // 一つの水たまりを保存
            v2.push_back(make_pair(j, a));
        }
    }

    // 面積の合計を出力
    int sum = 0;
    for(int i = 0; i < v2.size(); i++) sum += v2[i].second;
    cout << sum << endl;

    // 水たまりの個数を出力
    cout << v2.size();

    // 各水たまりの面積を出力
    for(int i = 0; i < v2.size(); i++)
    {
        cout << " " << v2[i].second;
    }
    cout << endl;
    return 0;
}

