  {
    for (int j=0; j < max; j++) map[j][i] = ' ';
    int j = (height[i] > height[i+1])?height[i+1] : height[i];
    map[j][i] = ground[i];
  }

  for (int i=max-1; i>=0;i--)
  {
    map[i][ground_len] = '\0';
    std::cout<<i<<"\t"<<map[i]<<std::endl;
  }
}

void calc_puddle(void)
{

  for(int i=0; i<ground_len-1; i++)
  {
    int j, sq=0;

    if (mpuddle[i] == -1) continue; //計算済み領域は無視
    if (height[i] <= height[i+1] )  continue;      // いきなり平か上りの場合も無視

    for (j = i+1; height[i] >= height[j] ;j++)
    {
      if (j == ground_len-1 && height[i] > height[j])
      { //画面右端の処理
        sq = -2;
        for (int k = i+1; k < ground_len; k++) mpuddle[k] = 0;
        break;
      }

      sq += height[i]*2 -height[j] - height[j-1];
      if (height[i] == height[j]) break;
      mpuddle[j] = -1;
    }
    mpuddle[i] = sq/2;

  }
}

void print_result(void)
{
  int i, count=0, total=0;

  for (i=0; i<ground_len; i++)
  {
    if (mpuddle[i] >0){
      count++;
      total += mpuddle[i];
    }
  }

  std::cout<<total<<std::endl << count;
  for (i=0; i<ground_len; i++)
    if (mpuddle[i] >0)
      std::cout <<" "<<mpuddle[i];

  std::cout << std::endl;
}

