}

void insert_heighest(vector<pair<int, int>>& vec, vector<pair<int, int>>::iterator st,
                     vector<pair<int, int>>::iterator ed, pair<int, int> p){
    for(auto it = ed-1; it != st; --it){
        if(p.second <= it->second){
            vec.erase(it+1, ed);
            vec.insert(it+1, p);
            return;
        }
    }
    vec.erase(st+1, ed);
    vec.push_back(p);
}

