static const char DOWN = '\\';
static const char EVEN = '_';
static const char UP = '/';

struct AREA {
  int index;
  int area;
  int height;
};

int main() {
  stack<AREA> input;
  vector<AREA> answer;

  string data;
  cin >> data;

  int total =0;
  int height = 0;
  int lastIndex = 0;
  AREA current = {};
  for (int i = 0; i < data.length(); i++) {
    switch (data[i]) {
    case DOWN:
      current.index = i;
      current.area = 0;
      current.height = height;
      height -= 1;
      input.push(current);
      break;
    case EVEN:
      break;
    case UP:
      height += 1;
      if (input.empty()) {
        continue;
      }
      lastIndex = input.top().index; input.pop();
      current.area = i - lastIndex;
      current.index = lastIndex;
      current.height = height;
      total += current.area;
      while (answer.size() > 0 && answer.back().height > height) {
        current.area += answer.back().area;
        answer.pop_back();
      }
      answer.push_back(current);
      break;
    default:
      break;
    }
  }

  cout << total << endl;  
  cout << answer.size();
  for (AREA ans : answer) {
      cout << " " << ans.area;
  }  
  cout << endl;

  return 0;
}

