NodePointer insert(int keydata) {
  NodePointer newnode;

  newnode = malloc(sizeof(struct node));
  newnode->key = keydata;
  newnode->next = nil->next;
  newnode->prev = nil;
  newnode->next->prev = newnode;
  return newnode;
}

NodePointer delete(int keydata) {
  NodePointer delnode;
  delnode = nil->next;

  while (delnode != nil && delnode->key != keydata) {
    delnode = delnode->next;
  }
  if(delnode == nil) return nil;
  else {
    delnode->prev->next = delnode->next;
    delnode->next->prev = delnode->prev;
    free(delnode);
    return delnode;
  }
}

NodePointer deleteFirst(void) {
  NodePointer delnode;

  delnode = nil->next;
  nil->next = delnode->next;
  delnode->next->prev = nil;
  free(delnode);
  return delnode;
}


NodePointer deleteLast(void) {
  NodePointer delnode;

  delnode = nil->prev;
  delnode->prev->next = nil;
  nil->prev = delnode->prev;
  free(delnode);
  return delnode;
}

void listPrint(void) {
  NodePointer n;

  for(n = nil->next; n != nil->prev; n = n->next) {
    printf("%d ", n->key);
  }
  printf("%d\n", n->key);
  free(nil);
}

void init(void) {
  nil->next = nil;
  nil->prev = nil;
}

