int main() {
  char area[20001];
  scanf("%s", area);
  int arealen = strlen(area);

  int start = 0, end = 0;
  bool isdown = false;
  int j = 0;
  vector<double> water_area;
  while(start + 1 < arealen) {
    for(int i = start; i < arealen; i++) {
      int up = 0, down = 0;
      for(int j = i; j < arealen; j++) {
        if(area[j] == '_') {
          if(j == i) {
            break;
          } else if(down == 0) {
            continue;
          }
        }

        if(area[j] == '\\') {
          down++;
          if(!isdown) { isdown = true; }
        } else if(area[j] == '/') {
          if(down == 0) { break; }
          up++;
        }

        if(up != 0 && up == down) {
          end = j;
          break;
        }
      }

      if(up != 0 && up == down) {
        start = i;
        break;
      }
    }

    if(isdown == 0) { break; }

    int height = 0;
    for(int i = start; i <= end; i++) {
      if(area[i] == '\\') {
        if(i == start) { water_area.push_back(0); }
        water_area[j] += height + 0.5;
        height++;
      } else if(area[i] == '/') {
        water_area[j] += height - 0.5;
        height--;
      } else if(area[i] == '_') {
        water_area[j] += height;
      }
    }
    start = end + 1;
    isdown = false;
    j++;
  }

  int total_area = 0;
  for(int i = 0; i < (int)water_area.size(); i++) { total_area += water_area[i]; }

  printf("%d\n", total_area);
  printf("%d ", water_area.size());
  for(int i = 0; i < (int)water_area.size(); i++) {
    if(i == water_area.size() - 1) { printf("%d\n", (int)water_area[i]); } else { printf("%d ", (int)water_area[i]); }
  }

  return 0;
}

