                st.push(make_pair(i,area[i]));
            }
        }
    }

    ll sumare=0;
    int siz=st.size();
    vector<ll> vc;
    for(int i=0;i<siz;i++){
        sumare += st.top().second;
        vc.push_back(st.top().second);
        st.pop();
    }

    cout << sumare << endl;
    cout << siz << (siz!=0?" ":"\n");
    for(int i=vc.size()-1;i>=0;i--){
        cout << vc[i] << (i!=0?" ":"\n");
    }
}

