#include <iostream>
#include <stack>
#include <vector>

using namespace std;

typedef struct 
{
    unsigned int left;
    unsigned int area;
}AreaInfo_t;

#define CalcArea(x,y) ((x) - (y))

stack<unsigned int> ArealeftIdxStack;
vector<AreaInfo_t> AreaInfoStack;

unsigned int Decision(char, unsigned int);
void Fusion(AreaInfo_t);
void PrintArea(void);

int main(void){
    char ch;
    unsigned int idx = 0;
    unsigned int total = 0;

    while(cin >> ch)
    {
        total += Decision(ch, idx);
        idx++;
    }

    cout << total << endl;
    PrintArea();

    return 0;

}

unsigned int Decision(char ch, unsigned int idx)
{
    unsigned int rslt = 0;

    switch(ch)
    {
        case '\\':
            ArealeftIdxStack.push(idx);
            break;
        case '/':
            if(!ArealeftIdxStack.empty())
            {
                AreaInfo_t area;
                area.left = ArealeftIdxStack.top();
                rslt = area.area = CalcArea(idx, ArealeftIdxStack.top());
                ArealeftIdxStack.pop();
                Fusion(area);
            }
            break;
        case '_':
            // pass
            break;
        default:
            // unreachable
            break;
    }

    return rslt;
}

void Fusion(AreaInfo_t tInfo)
{

    while(1)
    {
        if(!AreaInfoStack.empty())
        {
            AreaInfo_t tmp = AreaInfoStack.back();
            if(tmp.left > tInfo.left)
            {
                tInfo.area += tmp.area;
                AreaInfoStack.pop_back();
                continue;
            }
        }

        AreaInfoStack.push_back(tInfo);
        break;
    }

    return;
}

void PrintArea()
{
    cout << AreaInfoStack.size();
    for(vector<AreaInfo_t>::iterator it = AreaInfoStack.begin(); it != AreaInfoStack.end(); it++)
    {
        cout << ' ' <<  it->area;
    }
    cout << endl;

    return;
}

#include <iostream>
