#include <iostream>
#include <stack>
#include <list>

using namespace std;

int main()
{
	stack<int> Pool_L;
	stack<int> Pool_R;
	list<int> List_L;
	list<int> List_R;
	string S;
	cin >> S;
	int counter = 0;
	int top = 0;
	int max = 0;
	int max_index = 0;
	// 分水嶺を求める　一番高い場所で一番右側
	for (unsigned int i = 0; i < S.length(); i++)
	{
		if (S.at(i) == '\\')
		{
			top--;
		}
		if (S.at(i) == '/')
		{
			top++;
		}
		if (top >= max)
		{
			max = top;
			max_index = i;
		}
	}
	// 左側から分水嶺まで調べる
	int wL = 0;
	int tmpL = 0;
	for (int i = 0; i <= max_index; i++)
	{
		if (S.at(i) == '\\') {
			Pool_L.push(i);
		}
		if (S.at(i) == '/' && Pool_L.size() > 0) {
			wL += i - Pool_L.top();
			Pool_L.pop();
		}
		if (Pool_L.size() == 0)
		{
			if (wL != tmpL)
			{
				counter++;
				//cout << "左から　wL=" << wL << endl;
				List_L.push_back(wL);
				tmpL = wL;
			}
		}
	}
	// 右側から分水嶺まで調べる
	int wR = 0;
	int tmpR = 0;
	for (int k = S.length() - 1; k > max_index; k--)
	{
		if (S.at(k) == '/') {
			Pool_R.push(k);
		}
		if (S.at(k) == '\\' && Pool_R.size() > 0) {
			wR += Pool_R.top() - k;
			Pool_R.pop();
		}
		if (Pool_R.size() == 0)
		{
			if (wR != tmpR)
			{
				counter++;
				//cout << "右から　wR=" << wR << endl;
				List_R.push_front(wR);
				tmpR = wR;
			}

		}
	}
	cout << wL + wR << endl;
	cout << counter;
	int size_of_List_L = List_L.size();
	int tmp = 0;
	int q = 0;
	for (int j = 0; j < size_of_List_L; j++)
	{
		q = List_L.front();
		List_L.pop_front();
		if (q != tmp)
		{
			cout <<" "<< q - tmp;
			tmp = q;
		}
	}
	if (List_R.size() > 0)
	{
		int tmp_R = List_R.front();
		//int tmp_R = 0;
		//List_R.pop_front();
		int size_of_List_R = List_R.size();
		int q_R = 0;

		for (int j = 0; j < size_of_List_R; j++)
		{
			q_R = List_R.front();
			List_R.pop_front();
			if (q_R != tmp_R) {
				cout <<" "<< tmp_R - q_R;
				tmp_R = q_R;
			}
			if (j == size_of_List_R - 1)
			{
				cout <<" "<< q_R << endl;
			}
		}
	}
	else {
		cout << endl;
	}
}
