using namespace std;

struct mountain {
	int top = 0; int topn; int dis = 0;
};

string s; mountain m[100]; int area[100] = { 0 }, ff = 1;

int calc(int act, int *num) {
	int begin = *num - 1, lis = 0;
	for (begin; begin >= 0 && act > m[begin].top; begin--) {
		if (act - 1 == m[begin].top) lis++;
	}
	cout << *num << m[begin].topn << " ";
	if (ff || begin == -1) return 1;
	if (m[begin].top < act) return 0;

	int d = m[begin].dis, max = m[begin].top;
	for (int i = m[begin].topn; max >= act; i++) {
		if (s[i] == '\\')max--, d--;
		if (s[i] == '_')d--;
	}
	area[*num - 1] += d + 1;

	for (int i = *num - 1; i > *num - lis - 1; i--) {
		area[*num - 1 - lis] += area[i];
		area[i] = 0;
		m[i].dis = 0;
	}
	*num -= lis;

	//cout << "*" << area[*num - 1] << "* ";

	return 1;
}

int main() {
	int num = 1, act = 0, flag = 0;
	m[0].topn = 0; cin >> s;
	for (int i = 0; i < s.size(); i++) {

		if (s[i] == '/') {
			act++;
			flag = calc(act, &num);
			m[num].top = act;
			m[num].topn = i + 1;
		}
		if (s[i] == '_')m[num].topn = i + 1;
		if (s[i] == '\\') {
			if (flag)num++, flag = 0;
			ff = 0, act--;
		}
		for (int j = 0; j < num;j++)m[j].dis++;
	}

	int aa = 0, fff = 0, j = 0;
	for (int i = 0; i < num; i++)aa += area[i];
	if (!area[0])num--, fff = 1, j++;
	if (!area[num - 1])num--;
	cout << aa << endl << num << " ";
	if (j)num++;
	for (j; j < num; j++) cout << area[j] << " ";
	cout << endl;

	return 0;
}

#include <cstdio>
#include <stack>
#include <queue>

using namespace std;

struct Area {
    int s;
    int e;
    int area;
    Area(int _s, int _e) : s(_s), e(_e), area(_e - _s) {}
};

stack<int> stk;
queue<Area> areas;

int main()
{
    int ch;
    int sum = 0;
    int current_point = 0;
    while ((ch = getchar()) && ch != '\n' && ch != EOF)
    {
        switch (ch)
        {
            case '\\':
                stk.push(current_point);
                break;
            case '/':
                if (!stk.empty())
                {
                    int p = stk.top();
                    stk.pop();
                    Area area(p, current_point);
                    sum += area.area;
                    int size = areas.size();
                    while (size-- > 0)
                    {
                        Area a = areas.front();
                        areas.pop();
                        if (area.s < a.s && a.e < area.e)
                            area.area += a.area;
                        else
                            areas.push(a);
                    }
                    areas.push(area);
                }
                break;
        }
        current_point++;
    }

    printf("%d\n", sum);
    printf("%d", areas.size());
    while (!areas.empty())
    {
        Area a = areas.front();
        areas.pop();
        printf(" %d", a.area);
    }
    putchar('\n');
    return 0;
}

