int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(0);
	string s; cin >> s;
	int N = s.size();
	vector<int> v(N+1, 0);
	REP(i, N) {
		int d = s[i] == '/' ? 1 : s[i] == '_' ? 0 : -1;
		v[i+1] = v[i]+d;
	}
	vector<int> h(N);
	REP(i, N) {
		h[i] = max(v[i], v[i+1]);
	}
	int hm = inf;
	REP(i, N) hm = min(hm, h[i]);
	REP(i, N) h[i] -= hm;
	map<int, set<int> > m;
	REP(i, N) {
		m[h[i]].insert(i);
	}
	vector< pair<P, int> > a;
	REP(i, N) {
		if (s[i] == '\\') {
			set<int>& x = m[h[i]];
			auto it = x.upper_bound(i);
			if (it != x.end()) {
//				cout << i << " " << *it << endl;
				a.pb( pair<P, int>(P(i, *it), *it-i) );
			}
		}
	}
	auto it = a.begin();
	while (it != a.end()) {
		auto nxt = it; ++nxt;
		if (nxt == a.end()) break;
		if (nxt->first.second <= it->first.second) {
			nxt->first = it->first;
			nxt->second += it->second;
			it->second = 0;
		}
		++it;
	}
	ll sum = 0;
	vector<ll> ans;
	EACH(p, a) {
		if (p.second == 0) continue;
		ans.pb( p.second );
		sum += p.second;
	}
	cout << sum << endl;
	cout << ans.size();
	REP(i, ans.size()) {
		cout << " " << ans[i];
	}
	cout << endl;
}

