    float area=0;

    int height=0;
    for(int i=start; i<end; i++){
        switch(input[i]){
            case'/':
                area+=-(height+0.5);
                height++;
                break;
            case'\\':
                area+=-(height-0.5);
				height--;
                break;
            case'_':
                area+=-height;
                ;
        }
    }

    return area;
}

