int cal(int former, int later, string ground)
{
    int s = 0;
    int depth = 0;
    for(int i = former; i < later; i++)
    {
        if(ground[i] == '/')
        {
            depth--;
            s += depth;
        }
        else if(ground[i] == '_')
        {
            s+=depth;
        }
        else
        {
            depth++;
            s += depth;
        }
    }
    return s;
