            int plus = 0;
            depth--;
            if (S.empty() == false) {
                int prevJ = popValue(&S);
                plus = i - prevJ;

                if (S2.empty() == false && S2.top().depth > depth) {
                    depthAndAmount daa = S2.top();
                    int amount = 0;
                    do {
                        //                    cout << "/1 " << S2.top().depth << ", " << S2.top().amount << endl;
                        S2.pop();
                        amount += daa.amount;


                        if (S2.empty() == false) {
                            daa = S2.top();
                        } else {
                            break;
                        }
                    } while (daa.depth > depth);
                    daa.depth = depth;
                    daa.amount = amount + plus;
                    S2.push(daa);
                } else {
                    depthAndAmount daa;
                    daa.depth = depth;
                    daa.amount = plus;
