#define INF 0x3f3f3f3f
struct node
{
    int id;
    char c;
} a[20005];

struct st
{
    int val;
    int h;
} sum;

char s[20005];
int ans[20005];
int main()
{
    scanf("%s", s);
    int len=strlen(s);
    for(int i=0; i<len; i++)
    {
        a[i].c=s[i];
        a[i].id=i;
    }
    stack<node> Q;
    stack<st> T;
    int res=0, h=0, s=0;

    for(int i=0; i<len; i++)
    {
        if(a[i].c=='\\' || a[i].c=='_')
        {
            if(a[i].c=='\\') h--;
            Q.push(a[i]);
        }
        else
        {
            h++;
            while(!Q.empty())
            {
                node temp;
                temp=Q.top();
                Q.pop();
                if(temp.c=='\\')
                {
                    sum.val+=a[i].id-temp.id;
                    sum.h=h;
                    break;
                }
            }
        }

        if(sum.val!=0)
        {
            while(!T.empty())
            {
                st temp;
                temp=T.top();
                if(temp.h!=INF && temp.h+1==sum.h)
                {
                    T.pop();
                    sum.val+=temp.val;
                }
                else break;
            }
            if(Q.empty()) sum.h=INF;
            T.push(sum);
        }
        sum.val=0;

    }
    while(!T.empty())
    {
        st temp;
        temp=T.top();
        T.pop();
        ans[res++]=temp.val;
        s+=temp.val;
    }
    printf("%d\n", s);
    printf("%d", res);
    for(int i=res-1; i>=0; i--) printf(" %d", ans[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

#define STRING_DATA 20000
#define LAKE 1000

int stack_index[STRING_DATA];
int stack_area[STRING_DATA];
int stack_lake[LAKE];
int l = 0, pop_flag;

void push(int i) {
  stack_index[l] = i;
  l++;
}

int pop() {
  if(l != 0) {
    pop_flag = 0;
    l--;
    return stack_index[l];
  }
  else {
    pop_flag = 1;
    return 0;
  }
}

int main(void) {
  int k = 0, t, i, j = 0, max = 0;
  long int max_lake = 0;
  char in;

  for(i = 0 ; i < STRING_DATA ; i++) {
    stack_area[i] = 0;
  }

  while((in = getchar()) != EOF) {
    if(in == '\\') {
      push(k);
      max = k;
    }
    else if(in == '/') {
      t = pop();
      if(pop_flag != 1) {
	stack_area[t] = k - t;
	for(i = t + 1 ; i <= max ; i++) {
	  stack_area[t] += stack_area[i];
	  stack_area[i] = 0;
	}
      }
    }
    k++;
  }

  for(i = 0 ; i < k ; i++) {
    if(stack_area[i] != 0) {
      max_lake += stack_area[i];
      stack_lake[j] = stack_area[i];
      j++;
    }
  }

  printf("%ld\n", max_lake);
  printf("%d", j);
  for(i = 0 ; i < j ; i++) {
    printf(" %d", stack_lake[i]);
  }
  printf("\n");
  return 0;
}

