struct Region {
  size_t begin_;
  size_t end_;
  int height;

  size_t begin() { return begin_; }
  size_t end() { return end_; }
};

int main() {
  vector<pair<size_t, int>> tops;
  // height, half
  vector<float> heights;

  char prev = '/';
  int height = 0;

  string line;
  cin >> line;

  for (size_t i = 0; i < line.size(); ++i) {
    auto cur = line[i];
    if (prev == '/' && cur != '/') {
      DLOG("top: " << i << " " << height);
      tops.push_back(make_pair(i, height));
    } else if (i + 1 == line.size() && cur == '/') {
      DLOG("top: " << (i + 1) << " " << height + 1);
      tops.push_back(make_pair(i + 1, height + 1));
    }
    if (cur == '/') {
      heights.push_back(height + .5f);
      ++height;
    } else if (cur == '\\') {
      heights.push_back(height - .5f);
      --height;
    } else {
      heights.push_back(height);
    }
    prev = cur;
  }

  auto cmp = [](pair<size_t, int> lhs, pair<size_t, int> rhs) {
    return lhs.second > rhs.second;
  };
  // To the right
  sort(tops.begin(), tops.end(), cmp);

  vector<Region> right_regions;
  bool first = true;
  size_t left = 0;
  for (size_t i = 0; i < tops.size(); ++i) {
    auto t = tops[i];
    if (first && (tops.size() <= i + 1 || tops[i + 1].second == t.second)) {
      continue;
    }
    DLOG("r_top " << t.first << " " << t.second);
    if (first || t.first > left) {
      if (!first) {
        DLOG("Region " << left << " " << t.first);
        Region r{left, t.first, t.second};
        right_regions.push_back(r);
      }
      first = false;
      left = t.first;
    }
  }

  // To the left
  reverse(tops.begin(), tops.end());
  sort(tops.begin(), tops.end(), cmp);

  stack<Region> left_regions;
  auto limit = heights.size() + 1;
  size_t right = limit;
  for (auto&& t : tops) {
    if (t.first < right) {
      if (right < limit) {
        Region r{t.first, right, t.second};
        left_regions.push(r);
      }
      right = t.first;
    }
  }

  vector<float> areas;
  for (; !left_regions.empty(); left_regions.pop()) {
    auto r = left_regions.top();
    float area = 0.f;
    bool found = false;
    for (auto i = r.begin(); i != r.end(); ++i) {
      auto area0 = r.height - heights[i];
      if (area0 > 0) {
        found = true;
        area += area0;
      }
    }
    DLOG("AREA L " << area);
    if (found)
      areas.push_back(area);
  }
  for (auto&& r : right_regions) {
    float area = 0.f;
    auto found = false;
    for (auto i = r.begin(); i != r.end(); ++i) {
      auto area0 = r.height - heights[i];
      if (area0 > 0.f) {
        found = true;
        area += area0;
      }
    }
    DLOG("AREA R " << area);
    if (found)
      areas.push_back(area);
  }
  auto sum = accumulate(areas.begin(), areas.end(), 0);
  cout << sum << endl;
  cout << areas.size();
  for (auto&& a : areas) {
    cout << " ";
    first = false;
    cout << a;
  }
  cout << endl;
}

