};

int inte(mountain m[], int act, int *num, int ga[]) {
	int begin, lis = 0;
	for (int i = *num - 1; i >= 0 && act > m[i].top; i--) {
		begin = i - 1;
		if (act - 1 == m[i].top)lis++;
	}
	if (begin == -1)begin = 100;
	int max = m[begin].top;
	if (max < act) return 0;
	int d = m[begin].dis;
	for (int i = m[begin].topn; max >= act; i++) {
		if (s[i] == '\\')max--,d--;
		if (s[i] == '_')d--;
	}
	if (ff = s.size())d -= dd;
	ga[*num] += d + 1;
	//cout << "*" << ga[*num] << " " << dd << "*";
	//??±?????????
	for (int i = *num; i > *num - lis; i--) {
		ga[*num - lis] += ga[i];
		ga[i] = 0;
		m[i].dis = 0;
	}
	*num -= lis;

	return lis;
}

int calc(int max, int min, int a[], int n) {
	int area = (max - min) * (max - min);
	for (int i = 0; i < n; i++) 
		if(min <= a[i] && a[i] < max)area += max - a[i];
	return area;
}

