string ike(string s, int* t)
{
    string c;
    int i = *t, d = *t;
    while (i < s.size())
    {
        int down = 0, up = 0;
        while (i < s.size())
        {
            if (s[i] == '\\') {
                down++;
            }
            else if (s[i] == '/') {
                break;
            }
            i++;
        }
        while (i < s.size())
        {
            if (s[i] == '/') {
                up++;
            }
            else if (s[i] == '\\')
            {
                up--;
            }
            if (down == up) {
                for (int j = d; j < i+1; j++)
                {
                    c += s[j];
                }
                *t = i;
                return c;
            }
            i++;
        }
        i = ++d;
    }
    return "";
}

