    {
        while (i < s.size() && s[i] != '\\')
            i++;

        c = ike(s, &i);
        if (c == "")
            break;

        b = 0;
        a++;
        while (b < c.size())
        {
            if (c[b] == '\\')
            {
                sum[a-1] += 0.5 + (h * 1);
                h++;
            }
            else if (c[b] == '/')
            {
                if(0 < h){
                    sum[a - 1] += 0.5 + ((h-1)*1);
                    h--;
                }
            }
            else {
                sum[a - 1] += (h * 1);
            }
            b++;
        }
        sums += sum[a - 1];
    }

    cout << sums << "\n";
    cout << a << " ";
    if (sums == 0) 
        cout << "0" << "\n";
    else 
        for (i = 0; i < a; i++)
            cout << sum[i] << (i < a - 1 ? " " : "\n");
}

