        hmax[i-1] =  height[i-1] < hmax[i] ? hmax[i]: height[i-1];
    }
    p = 0;
    for (i = 0, p = 0, s = 0, k = 0, A = 0;
         i < len; i++) {
        switch (data[i]) {
            case '\\':
            pos[p++] = i;
            break;
            case '/':
            if (p > 0) {
                s += i - pos[--p];
                if (p == 0 || hmax[i+1] == height[i+1]) {
                    l[k++] = s;
                    A += s;
                    s = 0;
                }
            }
            break;
            default: break;
        }
    }
    cout << A << endl << k;
    for (i = 0; i < k; i++) {
        cout << " " << l[i];
    }
    cout << endl;

    return 0;
}

