typedef std::vector<int> IntVector;

namespace
{
enum GroundShape
{
	gsUp,
	gsFlat,
	gsDown
};

typedef std::vector<GroundShape> GroundShapes;

GroundShape CharToShape(char Shape)
{
	if(Shape == '/') return gsUp;
	if(Shape == '_') return gsFlat;
	return gsDown;
}	




void Input(GroundShapes& ShapeList)
{
	std::string GroundString;
	std::cin >> GroundString;

	for(unsigned int i=0;i<GroundString.length();i++)
	{
		ShapeList.push_back(CharToShape(GroundString[i]));
	}
}

void CreateHeightList(IntVector& HeightList,const GroundShapes& ShapeList)
{
	int Height = 0;
	HeightList.push_back(Height);

	for(unsigned int i=0;i<ShapeList.size();i++)
	{
		switch(ShapeList[i])
		{
			case gsUp   : Height++;break;
			case gsDown : Height--;break;
			default     : break;
		}
		HeightList.push_back(Height);
	}
}
};//namespace

struct TMountain
{
	int Position;
	int Height;

public:
	TMountain(int APosition,int AHeight);
};

TMountain::TMountain(int APosition,int AHeight)
{
	Position = APosition;
	Height   = AHeight;
}

typedef std::vector<TMountain> TMountains;

void CreateMountains(TMountains& MountainList,const GroundShapes& ShapeList,const IntVector& HeightList)
{
	bool IsClimbing = true;
	for(unsigned int i=0;i<ShapeList.size();i++)
	{
		switch(ShapeList[i])
		{
			case gsUp   : IsClimbing = true;break;
			case gsDown : if(IsClimbing) MountainList.push_back(TMountain(i,HeightList[i] ));
			              IsClimbing = false;break;
			default     : break;
		}
	}
	if(IsClimbing) MountainList.push_back(TMountain(ShapeList.size(),HeightList[ShapeList.size()]));
}

TMountains::const_iterator GetHighest(const TMountains& Mountains,TMountains::const_iterator Left,TMountains::const_iterator Right)
{
	TMountains::const_iterator It = Left;
	TMountains::const_iterator Highest = It;
	for(It = Left;It != Mountains.end() && It != Right;It++)
	{
		if((*It).Height > (*Highest).Height) Highest = It;
	}
	return Highest;
}

enum MeasureDirection
{
	mdFront,
	mdBack
};

int MeasureLake(const IntVector& HeightList,int Edge,MeasureDirection Direction)
{
	int Vector = Direction == mdFront ? 1 : -1;
	const int LakesideHeight = HeightList[Edge];
	int Position = Edge + Vector;
	int Size = 0;
	while(Size == 0 || HeightList[Position] < LakesideHeight)
	{
		Size += 2 * LakesideHeight - HeightList[Position] - HeightList[Position - Vector];
		Position += Vector;
	}
	return (Size + 1)/2;
}

typedef std::deque<int> TLakes;

int GetTotal(const TLakes& ALakes)
{
	TLakes Lakes = ALakes;
	int Size = 0;
	for(unsigned int i= 0;i<ALakes.size();i++)
	{
		Size += Lakes.front();
		Lakes.pop_front();
	}
	return Size;
}

int main()
{
	GroundShapes ShapeList;
	Input(ShapeList);
	IntVector HeightList;
	CreateHeightList(HeightList,ShapeList);

	TMountains MountainList;
	CreateMountains(MountainList,ShapeList,HeightList);

	TMountains::const_iterator Highest = GetHighest(MountainList,MountainList.begin(),MountainList.end());

	TLakes Lakes;
	TMountains::const_iterator HighestLeft = Highest;
	while(HighestLeft != MountainList.end() - 1)
	{
		HighestLeft = GetHighest(MountainList,HighestLeft + 1,MountainList.end());
		Lakes.push_back(MeasureLake(HeightList,(*HighestLeft).Position,mdBack));
	}

	while(Highest != MountainList.begin())
	{
		Highest = GetHighest(MountainList,MountainList.begin(),Highest - 1);
		Lakes.push_front(MeasureLake(HeightList,(*Highest).Position,mdFront));
	}

	std::cout << GetTotal(Lakes) << std::endl;
	int LakeCount = Lakes.size();
	std::cout << LakeCount << std::flush;
	for(int i=0;i<LakeCount;i++)
	{
		std::cout << " " << std::flush;
		std::cout << Lakes.front() << std::flush;
		Lakes.pop_front();
		if(i < LakeCount - 1)
		{
			std::cout << std::flush;
		}else{
			std::cout << std::endl;
		}
	}

	return 0;
}

