#define NONE -1

int checkLength(int index,string str){
    int height = 1;
    for(int i = index;i < str.length();++i){
        switch(str.at(i)){
            case '\\':
                height++;
                break;
            case '_':
                break;
            case '/':
                height--;
                if(height == 0){
                    return i;
                }
                break;
        }
    }
    return NONE;
}

float checkArea(int index1,int index2,string s){
    int height = 1;
    float area = 0.5;

    for(int i = index1;i <= index2;++i){
        switch(s.at(i)){
            case '\\':
                area += 0.5 + height;
                height++;
                break;
            case '_':
                area += height;
                break;
            case '/':
                height--;
                area += 0.5 + height;
                break;
        }
    }
    return area;
}


