     * ?????????????????? hmax ????±?????????????????????????????????????hmin ??????????????????
     * ?§????
     */
}

void solve(const vector<Column>& cols, int hmax, int hmin)
{
    int width = cols.size();

    // ????????¨????????¢???????±???????(????????????????????\???????§?)
    int area_total = 2 * (width * (hmax-hmin));

    // ??°??¢?????¢???????±???????
    int area_ground = 0;
    for(auto col : cols) {
        area_ground += 2 * (col.height - hmin);
        switch(col.grad) {
        case Grad::UP:   ++area_ground; break;
        case Grad::DOWN: --area_ground; break;
        case Grad::FLAT:                break;
        }
    }

    // ??????????°´??????
    int area_air_left = 0;
    for(int h = cols[0].height; h <= hmax; ++h) {
        for(int x = 0; x < width; ++x) {
            Column col = cols[x];
            if(col.height == h && col.grad == Grad::UP) {
                area_air_left += 2*x + 1;
                break;
            }
        }
    }

    // ??????????°´??????
    int area_air_right = 0;
    int h = cols[width-1].height;
    if(cols[width-1].grad == Grad::UP)
        ++h;
    else if(cols[width-1].grad == Grad::DOWN)
        --h;
    for(; h <= hmax; ++h) {
        for(int x = width-1; x >= 0; --x) {
            Column col = cols[x];
            if(col.height == h+1 && col.grad == Grad::DOWN) {
                area_air_right += 2*(width-1-x) + 1;
                break;
            }
        }
    }

    int result = (area_total - area_ground - area_air_left - area_air_right) / 2;
    printf("%d\n", result);
    if(result) printf("%d\n", result);
}

