bool asc2(const pair<int, int>& left, const pair<int, int>& right)
{
    return left.second == right.second ? left.first > right.first : left.second < right.second;
}

int cal(int former, int later, string ground)
{
    int s = 0;
    int depth = 0;
    for(int i = former; i < later; i++)
    {
        if(ground[i] == '/')
        {
            depth--;
            s += depth;
        }
        else if(ground[i] == '_')
        {
            s+=depth;
        }
        else
        {
            depth++;
            s += depth;
        }
    }
    return s;
}

