using namespace std;

struct Water {
    int b;
    int e;
    int area;
};

class PredFunctor {
  public:
    int b;
    int* area_ptr;
  public:
    PredFunctor(int b, int *area_ptr) : b(b), area_ptr(area_ptr) { }
    bool operator()(const Water& water) {
        if (water.b > this->b) {
            *area_ptr += water.area;
            return true;
        }
        return false;
    }
};

int main(void) {

    string map;
    cin >> map;

    int total_area = 0;
    list<Water> waters;
    stack<int> geo;
    for (int i = 0; i < map.size(); ++i) {
        switch (map[i]) {
            case '\\':
                geo.push(i);
                break;
            case '_':
                // do nothing
                break;
            case '/':
                if ( ! geo.empty()) {
                    int this_area = i - geo.top();
                    total_area += this_area;
                    PredFunctor pred(geo.top(), &this_area);
                    waters.remove_if(pred);
                    waters.push_back({ geo.top(), i, this_area });
                    geo.pop();
                }
                break;
            default:
                fprintf(stderr, "unknown character: %c\n", map[i]);
                return 1;
        }
    }

    printf("%d\n", total_area);
    printf("%lld", waters.size());
    for (list<Water>::iterator it = waters.begin();
            it != waters.end(); ++it) {
        printf(" %d", it->area);
    }
    printf("\n");

    return 0;
}

#include <iostream>
#include <string>
#include <stack>
using namespace std;

class Water {
public:
	int size;
	int position;
	Water(int _size, int _position) {
		size = _size;
		position = _position;
	}
	void fill(int addition) {
		size += addition;
	}
	void merge(Water* water) {
		if (water) {
			size += water->size;
			delete water;
		}
	}
};

// it returns false if no action is committed
bool mergeWaters(int position, stack<Water*>& waters) {
	Water* accum = NULL;
	Water* water;
	while (! waters.empty() && (water = waters.top())->position >= position) {
		waters.pop();
		water->merge(accum);
		accum = water;
	}
	if (accum) {
		waters.push(accum);
		return true;
	} else {
		return false;
	}
}

int main() {
	string pattern;
	stack<Water*> waters;
	stack<int> positions;
	int total = 0;

	cin >> pattern;

	for (int pos = 0, len = pattern.length(); pos < len; pos++) {
		switch (pattern[pos]) {
		case '\\':
			positions.push(pos);
			break;
		case '/':
			if (! positions.empty()) {
				int top = positions.top(); positions.pop();
				int addition = pos - top;
				if (mergeWaters(top, waters))
					waters.top()->fill(addition);
				else
					waters.push(new Water(addition, top));
				total += addition;
			}
			break;
		case '_':
			break;
		}
	}

	cout << total << endl;
	cout << waters.size();
	while (! waters.empty()) {
		Water* water = waters.top(); waters.pop();
		cout << ' ' << water->size;
	}
	cout << endl;
}

