//				cout << "including : " <<  sub.first << "(" << sub.second << ")" <<endl;
			}
//			cout << "subarea is : " <<subarea << endl;
			area += (i-l);
			st2.push(make_pair(l,subarea));
			break;
		case '\\':
			st1.push(i);
			break;
		}
	}
	println(area);
