  int fstart;
  for(size_t i=0; i<hts.size()-1; ++i) {
    if(min(lmaxes[i],rmaxes[i+1])>min(hts[i], hts[i+1])) {
      if (not flood) {
        flood = true;
        fstart = hts[i];
      }
      if(hts[i]!=hts[i+1]) current_vol += 0.5;
      current_vol += min(lmaxes[i], rmaxes[i+1]) - max(hts[i], hts[i+1]);
    } 
    if (hts[i+1]==fstart and current_vol) {
      vols.push_back(current_vol);
      current_vol=0;
      flood=false;
    }
  }
  if (current_vol) vols.push_back(current_vol);

  cout << accumulate(vols.begin(), vols.end(), 0) << endl;  // total volume
  cout << vols.size(); // number of floods
  for (auto v : vols) cout << " " << v;  // print volume of each flood
  cout << endl;
}

