using namespace std;

class stack
{
	public:
	int s[10000];
	int t;

public:
	void initialize();
	void push(int x);
	int pop();
	int size();
};

void stack::initialize()
{
	t = 0;
}

void stack::push(int x)
{
	t++;
	s[t] = x;
}

int stack::pop()
{
	t--;
	return s[t];
}
int stack::size()
{
	return t;
}



int main()
{
	stack slash;
	stack backslash;
	queue<int>  Lake;
	stack  Lake2;
