			//cout << slash.size();

			countslash++;

			//cout << "lake = " << lake << endl;
		}
		else if (str[i] == '/')
		{
			countbackslash++;

			if (slash.size() != 0)
			{
				//cout << "/" << endl;
				backslash.push(i);
				lake += (slash.size() - backslash.size() + 0.5);
				//cout << "lake = " << lake << endl;
			}
