void read_problem(vector<Column>& cols, int& hmax, int& hmin)
{
    int height = 30000; // ????????????
    hmax = hmin = height;

    int c;
    while((c = getchar()) != EOF) {
        if(c == '\n') break;

        if(c == '\\') {
            cols.push_back(Column(height, Grad::DOWN));
            --height;
        }
        else if(c == '/') {
            cols.push_back(Column(height, Grad::UP));
            ++height;
        }
        else if(c == '_') {
            cols.push_back(Column(height, Grad::FLAT));
        }
        else {
            assert(false);
        }

        if(hmax < height) hmax = height;
        if(height < hmin) hmin = height;
    }

    /**
