int tobasu(int from) {
	int i = from;
	while (i < length && s[i] != '\\') {
		++i;
	}
	return i;
}

int reverse_tobasu(int from, int to) {
	int i = from;
	while (to <= i && s[i] != '/') {
		--i;
	}
	return i;
}

int calc_area(int from, int to) {
	int d = 0;
	int a = 0;
	for (int l = from; l <= to; ++l) {
		if (s[l] == '\\') {
			a += (d + 1);
			d += 2;
		}
		else if (s[l] == '_') {
			a += d;
		}
		else {
			a += (d - 1);
			d -= 2;
		}
	}
	return a / 2;
}

