using namespace std;
int main()
{
    stack<int> S1;
    stack<pair<int,int>> S2;
    char Sdata;
    int sum=0;//计算积水总面积
    for(int i=0;cin>>Sdata;i++)
    {
       // cout<<"cs:"<<i<<endl;
        if(Sdata=='\\')
        S1.push(i);
        else if(Sdata=='/'&&S1.size()>0)
        {
            int j=S1.top();
            int distance=i-j;
            sum+=distance;
            //cout<<"cs: "<<sum<<endl;
            S1.pop();
            //下面对该积水处所在S2中代表的数据进行更新
            while(S2.size()>0&&S2.top().first>j)
            {
                distance+=S2.top().second;
                S2.pop();
            }
            S2.push(make_pair(j,distance));
        }

    }
    //数据处理完毕,next
    cout<<sum<<endl;
    cout<<S2.size();
    vector<int> areas;
    while(S2.size()>0)
    {
        areas.push_back(S2.top().second);
       // cout<<"cs:"<<S2.top().second;
        S2.pop();
    }
    //cout<<endl;
    reverse(areas.begin(),areas.end());
    for(int i=0;i<areas.size();i++)
    {
        cout<<" "<<areas[i];
    }

    cout<<endl;
  //  cout<<*(areas.end()-1)<<endl;
    return 0;
}

