  while (start + 1 < arealen) {
    int up = 0, down = 0;
    for (int i = start; i < arealen; i++) {
      if (area[i] == '\\') {
        if (!down && i != start) {
          start = i;
          up = 0, down = 1;
          continue;
        }
        down++;
      } else if (area[i] == '/') { up++; }

      if (up && up == down) {
        end = i;
        break;
      }

      if (i == arealen - 1 && up != down) { end = start; }
    }

    int height = 0;
    for (int i = start; i <= end; i++) {
      if (start != end) {
        if (area[i] == '\\') {
          if (i == start) { water_area.push_back(0); }
          water_area[j] += height + 0.5;
          height++;
        } else if (area[i] == '/') {
          water_area[j] += height - 0.5;
          height--;
        } else if (area[i] == '_') {
          water_area[j] += height;
        }
      }
    }

    if (start != end) { j++; }
    start = end + 1;
  }

