#include <bits/stdc++.h>

using namespace std;

typedef long long  ll;

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    string s;
    cin >> s;
    const int n = s.size() + 1;
    vector<int> h(n);
    h[0] = 0;
    for (int i = 1; i < n; ++i) {
        if (s[i - 1] == '\\')
            h[i] = 1;
        else if (s[i - 1] == '/')
            h[i] = -1;
        else if (s[i - 1] == '_')
            h[i] = 0;
    }
    for (int i = 1; i < n; ++i)
        h[i] += h[i - 1];

    double area = 0.0;
    vector<double> L;
    int left = 0, right = 0;

    while (left < n) {

        right = left + 1;
        if (n <= right)
            break;
        if (h[left] == h[right] || h[left] > h[right]) {
            ++left;
            continue;
        }

        while (right < n && h[left] != h[right])
            ++right;
        if (right == n) {
            ++left;
            continue;
        }

        double tmp = 0.0;
        int p = 0;
        for (int i = left; i < right; ++i) {
            if (s[i] == '\\') {
                tmp += p + 0.5;
                ++p;
            }
            else if (s[i] == '/') {
                tmp += (p - 1) + 0.5;
                --p;
            }
            else
                tmp += p;
        }

        L.emplace_back(tmp);
        area += tmp;
        left = right;
    }

    cout << area << endl;
    cout << L.size();
    for (int i = 0, size = L.size(); i < size; ++i)
        cout << " " << L[i];
    cout << endl;

    return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <sstream>
#include <stack>
#include <vector>

std::stack<int> merge(
    std::stack<int>& merged,
    const int left_end,
    std::stack<std::pair<int, int>>& ponds)
{
    if (ponds.empty()) {
        return merged;
    }

    const auto& pond = ponds.top();
    if (left_end >= pond.first) {
        merged.push(0);
    }
    merged.top() += pond.second;
    ponds.pop();

    return merge(
        merged,
        std::min(left_end, pond.first),
        ponds);
}

std::stack<int> merge(std::stack<std::pair<int, int>>& ponds)
{
    std::stack<int> merged;
    if (ponds.empty()) {
        return merged;
    }
    return merge(
        merged,
        ponds.top().first,
        ponds);
}

int aggregate(std::stringstream& stream, std::stack<int>& merged) {
    if (merged.empty()) {
        return 0;
    }

    if (merged.size() == 1) {
        stream << merged.top();
        return merged.top();
    }

    const int t = merged.top();
    merged.pop();
    stream << t << " ";
    return t + aggregate(stream, merged);
}

void solve(const std::string& input) {
    std::stack<int> slope;
    std::stack<std::pair<int, int>> ponds;
    for (std::size_t i = 0; i < input.size(); ++i) {
        if ('\\' == input[i]) {
            slope.emplace(i);
        }
        if ('/' == input[i] && !slope.empty()) {
            ponds.emplace(slope.top(), i - slope.top());
            slope.pop();
        }
    }

    std::stack<int> merged = merge(ponds);
    const std::size_t size = merged.size();
    std::stringstream stream;
    std::cout << aggregate(stream, merged) << std::endl;
    std::cout << size;
    if (size > 0) {
        std::cout << " " << stream.str()
    }
    std::cout << std::endl;

    return;
}
int main()
{
    std::string input;
    getline(std::cin, input);
    solve(input);

    return 0;
}

