int l = 0, pop_flag;

void push(int i) {
  stack_index[l] = i;
  l++;
}

int pop() {
  if(l != 0) {
    pop_flag = 0;
    l--;
    return stack_index[l];
  }
  else {
    pop_flag = 1;
    return 0;
  }
}

int main(void) {
