      t = pop();
      if(pop_flag != 1) {
	stack_area[t] = k - t;
	for(i = t + 1 ; i <= k ; i++) {
	  stack_area[t] += stack_area[i];
	  stack_area[i] = 0;
	}
      }
    }
    k++;
  }

  for(i = 0 ; i < k ; i++) {
    if(stack_area[i] != 0) {
