void input(string *command) {
	cin >> *command;
}

void area(string *command) {
	int i = 0;
	int bottom = 0;
	double water = 0;
	int length = 0;
	bool flag = false;
	bool use = false;

	while (command[0][i] != '\0') {
		if (command[0][i] == '\\') {
			bottom++;
			length++;
			water += 0.5 + (bottom - 1);
			flag = true;
		}
		else if (command[0][i] == '/') {
			if (0 == bottom) {
				break;
			}
			water += 0.5 + (bottom - 1);
			length++;
			bottom--;
		}
		else if (command[0][i] == '_') {
			if (0 == bottom) {
				break;
			}
			water += bottom;
			length++;
		}

		// 出力
		if (0 == bottom && true == flag) {
			cout << water << " ";
			water = 0;
			length = 0;
			flag = false;
			use = true;
		}
		i++;
	}
	if (0 != bottom) {
		cout << water - (2 * (0.5 * bottom) + (length - bottom) * bottom) << " ";
	}

	if (false == use) {
		cout << water;
	}

	cout << endl;
}

