class Area
{
public:
	Area()
	: m_area(0)
	, m_left(0)
	{}

	~Area()
	{}

	void setArea(int area, int left) {
		m_area = area;
		m_left = left;
	}

	int getArea() {
		return m_area;
	}

	int getLeft() {
		return m_left;
	}
private:
	int m_area;
	int m_left;
};

class AreaList
{
public:
	AreaList()
	: m_list()
	{}

	~AreaList()
	{}

	void addArea(Area& point) {
		Area* q = &point;
		while (!m_list.empty()) {
			Area* p = m_list.back();
			if (p->getLeft() < q->getLeft()) {
				break;
			}
			m_list.pop_back();
		}
		m_list.push_back(q);
	}

	std::string toString() {
		std::ostringstream os1, os2;
		int total = 0;
		os2 << m_list.size();
		std::vector<Area*>::iterator itr;
		for (itr = m_list.begin(); itr != m_list.end(); itr++) {
			total += (*itr)->getArea() / 2;
			os2 << " " << ((*itr)->getArea() / 2);
		}
		os1 << total;
		std::string output = os1.str() + "\n" + os2.str();
		return output;
	}

private:
	std::vector<Area*> m_list;
};

int main() {
	std::string str;
	std::cin >> str;

	int h[str.size() + 1];
	int max, min;
	h[0] = max = min = 0;
	for (int i = 0; i < str.size(); i++) {
		switch (str[i]) {
		case '_' :
			h[i + 1] = h[i];
			break;
		case '/' :
			h[i + 1] = h[i] + 1;
			if (h[i + 1] > max) {
				max = h[i + 1];
			}
			break;
		// case '\\' :
		default :
			h[i + 1] = h[i] - 1;
			if (h[i + 1] < min) {
				min = h[i + 1];
			}
			break;
		}
	}

	AreaList list;
	Area point[str.size() + 1][max - min + 1];
	for (int j = 0; j < max - min + 1; j++) {
		point[0][j].setArea(0, 0);
	}
	for (int i = 1; i < str.size() + 1; i++) {
		for (int j = 0; j < max - min + 1; j++) {
			if (j > h[i] - min) {
				if (j == h[i - 1] - min) {
					point[i][j].setArea(1, i - 1);
				} else if (point[i - 1][j].getArea() == 0) {
					point[i][j].setArea(0, 0);
				} else {
					point[i][j].setArea(point[i - 1][j].getArea() + (j - (h[i - 1] - min)) + (j - (h[i] - min)), point[i - 1][j].getLeft());
				}
			} else if (j == h[i] - min) {
				if (j > h[i - 1] - min && point[i - 1][j].getArea() > 0) {
					point[i][j].setArea(point[i - 1][j].getArea() + 1, point[i - 1][j].getLeft());
					list.addArea(point[i][j]);
				} else {
					point[i][j].setArea(0, 0);
				}
			} else {
				point[i][j].setArea(0, 0);
			}
		}
	}

	std::cout << list.toString() << std::endl;

	return 0;
}

