typedef pair<int, int> P;

class stack{
  public:
  P v[22222];
  int t;
  stack(){
    t = 0;
    v[0] = P(-1, -1);
  }
  stack(P zero){
    t = 0;
    v[0] = zero;
  }
  void push(P a){
    t++;
    v[t] = a;
  }
  void pop(){
    t--;
  }
  P top(){
    return v[t];
  }
  void pr(){
    for(int i = 1; i <= t; i++){
      cout << v[i].second << " ";
    }
    cout << endl;
  }
  bool empty(){
    return t == 0;
  }
};

