    std::stack<int> down_indices;               // 下り斜面の位置
    std::stack<std::pair<int, int>> floods;     // 水たまりの左の位置、水たまりの面積

    int total_area = 0;
    for (int i = 0; i < slopes.size(); i ++) {
        if (slopes[i] == '\\') {
            down_indices.push(i);
        } else if (slopes[i] == '/' && !down_indices.empty()) {
            int left = down_indices.top();
            down_indices.pop();
            total_area += i - left;
            int current_area = i - left;
            while (!floods.empty() && floods.top().first > left) {
                current_area += floods.top().second;
                floods.pop();
            }
            floods.push({left, current_area});
        }
    }

    // 出力用に面積の値を並べ替える。
    std::list<int> areas;
    while (!floods.empty()) {
        areas.push_front(floods.top().second);
        floods.pop();
    }

    std::cout << total_area << std::endl;
    std::cout << areas.size();
    for (int area : areas) {
        std::cout << " " << area;
    }
    std::cout << std::endl;
}

