};

struct Column {
    int height; // ???????????????
    Grad grad;
    Column(int h, Grad g) : height(h), grad(g) {}
};

void read_problem(vector<Column>& cols)
{
    int height = 30000; // ????????????

    int c;
    while((c = getchar()) != EOF) {
        if(c == '\n') break;

        if(c == '\\') {
            cols.push_back(Column(height, Grad::DOWN));
            --height;
        }
        else if(c == '/') {
            cols.push_back(Column(height, Grad::UP));
            ++height;
        }
        else if(c == '_') {
            cols.push_back(Column(height, Grad::FLAT));
        }
        else {
            assert(false);
        }
    }
}

// 1???????°´??????????????¢????????????(???????????????)
int area_pool(const vector<Column>& cols, int l, int r)
{
    int height_pool = cols[l].height;
    int area = 0;

    FOR(i, l, r+1) {
        Column col = cols[i];
        area += 2 * (height_pool - col.height);
        if(col.grad == Grad::DOWN)
            ++area;
        else if(col.grad == Grad::UP)
            --area;
    }

    return area;
}

vector<int> solve(const vector<Column>& cols)
{
    vector<int> pools;

    int width = cols.size();

    REP(i, width) {
        // ????????????????????¢?????????????????????
        Column left = cols[i];
        if(left.grad != Grad::DOWN) continue;

        // ?????????????????£??????????????¢?????¶????????£?????????????????????1???????°´?????????
        FOR(j, i+1, width) {
            Column right = cols[j];
            if(right.height == left.height-1 && right.grad == Grad::UP) {
                pools.push_back(area_pool(cols, i, j));
                i = j;
                break;
            }
        }
    }

    return pools;
}

