using namespace std;

#define MAX_LETTERS 20000

typedef struct tagDown
{
	int startPos;
	int lakeNum;
}DOWN;

DOWN downInfo[MAX_LETTERS];
int pos = 0;

void push(int p, int lake)
{
	pos++;
	downInfo[pos].startPos = p;
	downInfo[pos].lakeNum = lake;
}

DOWN pop(void)
{
	DOWN ret = downInfo[pos];
	pos--;
	return ret;
}

bool checkStack()
{
	if (pos <= 0)
		return false;
	else
		return true;
}

int main()
{
	char inputString[MAX_LETTERS] = { 0 };
	cin >> inputString;
	int ln = strlen(inputString);

	int allWater = 0;
	int water[10000] = { 0 };

	int sum = 0;
	int lake = 0;
	int prev = 0;

	for (int i = 0; i < ln; i++)
	{
		int line;
		int now = inputString[i];
		DOWN s;

		switch (now)
		{
		case '\\':
			if (now != prev)
			{
				lake++;
			}
			push(i, lake);
			break;
		case '/':
			if (checkStack())
			{
				s = pop();
				line = i - s.startPos;
				water[s.lakeNum] += line;
				allWater += line;
			}
			else
			{
				break;
			}
			if (s.lakeNum < lake)
			{
				int max = lake;
				for (int j = s.lakeNum+1; j <= max; j++)
				{
					water[s.lakeNum] += water[j];
					water[j] = 0;
					lake--;
				}
			}
			break;
		case '_':
			break;
		default:
			cout << "???" << endl;
		}
		prev = inputString[i];
	}

	cout << allWater << endl;
	int numberOfLake = 0;
	for (int i = 1; i <= lake; i++)
	{
		if (water[i])
			numberOfLake++;
	}
	cout << numberOfLake;
	for (int i = 1; i <= lake; i++)
	{
		if(water[i])
			cout << " " << water[i];
	}
	cout << endl;

    return 0;
}

