#include <cstdio>
#include <iostream>
#include <stack>
using namespace std;

int Calc(char *pArea, int *pSize, int *pCnt)
{
    stack<int> point;
    int tmp;
    int cnt = 0;
    int ret = 0;

    *pCnt = 0;

    while (pArea[cnt] != '\0') {
        switch (pArea[cnt]) {
        case '\\' :
            point.push(cnt);
            break;
        case '/' :
            tmp = point.top();
            point.pop();
            pSize[*pCnt] = cnt - tmp;
            ret += pSize[*pCnt];
            ++(*pCnt);
            break;
        default :
            break;
        }
        ++cnt;
    }

    return ret;
}

int main(void)
{
    char input[20000];
    int  hoge[100];
    int  cnt;
    int  ret;

    scanf("%s", input);

    ret = Calc(input, hoge, &cnt);

    printf("%d\n%d", ret, cnt);
    for (int i = 0; i < cnt; i++) {
        printf(" %d", hoge[i]);
    }
    printf("\n");

    return 0;
}

