            for(int j = n+1; j <= m; j++){
                w.push_back(v[n]);
            }
            q1.push(m);
            n = m;
        }

    }
    number = q1.size()-1;
    queue<int> q2;
    int ss = 0;
    for(int j = 0; j < v.size()-1; j++){
        ss += (w[j]-v[j]+w[j+1]-v[j+1]);
        if(j+1 == q1.front()){
            q2.push(ss);
            s += ss;
            ss = 0;
            q1.pop();
        }
    }
    if(q2.empty()){
        cout << 0 << "\n" << 0 << endl;
    }
    else {
        cout << s/2 << endl << number << " ";
        for(int j = 0; j < number; j++){
            cout << (q2.front())/2 << " ";
            q2.pop();
        }
    }

    return 0;
}

