using namespace std;

std::vector<int> ys;
std::vector<int> floodAreas;

void floodArea(int begin, int end) {
  if ((end - begin) <= 2) {
    return;
  }

  int maxi = begin + 1;
  for (int i = begin + 1; i < end - 1; ++i) {
    if (ys[maxi] < ys[i]) {
      maxi = i;
    }
  }
  int maxy = ys[maxi];
  int level = min(ys[begin], ys[end - 1]);
  if (maxy < level) {
    int area = 0;
    for (int i = begin + 1; i < end; ++i) {
      int a = 2 * level - ys[i] - ys[i-1];
      if (a > 0) {
        area += a;
      }
    }
    floodAreas.push_back(area / 2);
    return;
  }
  floodArea(begin, maxi + 1);
  floodArea(maxi, end);
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  string map;
  cin >> map;

  int level = 0;
  ys.push_back(0);

  for (char c : map) {
    if (c == '/') {
      ++level;
    } else if (c == '\\') {
      --level;
    }
    ys.push_back(level);
  }
  floodArea(0, ys.size());

  int areaSum = 0;
  for (int a : floodAreas) {
    areaSum += a;
  }
  cout << areaSum << endl;

  cout << floodAreas.size() << " ";
  for (int i = 0; i < floodAreas.size(); ++i) {
    if (i != 0) {
      cout << " ";
    }
    cout << floodAreas[i];
  }
  cout << endl;
}

#include<iostream>
#include<string>
using namespace std;

typedef struct geoBlock {
	int rHeight, lHeight;
	bool isFlooded = false;
	int incl; // '/'=1, '\'=-1, '_'=0
	int puddleHeight;
};

int main() {
	string geoShape;
	cin >> geoShape;
	geoBlock* mBlock = new geoBlock[geoShape.length()];
	int minHeight, maxHeight;
	for (int i = 0; i < geoShape.length(); i++) {

		if (geoShape[i] == '/') {
			mBlock[i].incl = 1;
		}
		else if (geoShape[i] == '\\') {
			mBlock[i].incl = -1;
		}
		else if (geoShape[i] == '_') {
			mBlock[i].incl = 0;
		}
		if (i == 0) {
			mBlock[i].lHeight = 0;
			mBlock[i].rHeight = mBlock[i].lHeight + mBlock[i].incl;
		}
		else {
			mBlock[i].lHeight = mBlock[i - 1].rHeight;
			mBlock[i].rHeight = mBlock[i].lHeight + mBlock[i].incl;
		}
		int min = (mBlock[i].lHeight > mBlock[i].rHeight ? mBlock[i].rHeight : mBlock[i].lHeight);
		int max = (mBlock[i].lHeight > mBlock[i].rHeight ? mBlock[i].lHeight : mBlock[i].rHeight);
		if (i == 0) {
			minHeight = min;
			maxHeight = max;
			continue;
		}

		if (minHeight > min) {
			minHeight = min;
		}
		else if (maxHeight < max) {
			maxHeight = max;
		}
	}
	int puddleCount = 0;
	for (int i = maxHeight; i > minHeight - 1; i--) {
		bool isInPuddle = false;
		int puddleStart;
		for (int j = 0; j < geoShape.length(); j++) {
			if (mBlock[j].isFlooded)continue;
			if ((isInPuddle == false) && (mBlock[j].lHeight == i) && (mBlock[j].incl == -1)) {
				isInPuddle = true;
				puddleStart = j;
			}
			else if ((isInPuddle == true) && (mBlock[j].rHeight == i) && (mBlock[j].incl == 1)) {
				isInPuddle = false;
				puddleCount++;
				for (int k = puddleStart; k < j + 1; k++) {
					mBlock[k].isFlooded = true;
					mBlock[k].puddleHeight = i;
				}
			}
		}
	}
	int* area = new int[puddleCount];
	int marker = 0;
	int sumArea = 0;
	for (int i = 0; i < puddleCount; i++) {
		area[i] = 0.0f;
		while (marker < (geoShape.length() + 1)) {
			if (mBlock[marker].isFlooded) {
				while (mBlock[marker].isFlooded) {
					area[i] += (mBlock[marker].puddleHeight) - (mBlock[marker].lHeight > mBlock[marker].rHeight ? mBlock[marker].lHeight : mBlock[marker].rHeight) + (mBlock[marker].incl == -1 ? 1 : 0);
					if (mBlock[marker].rHeight == mBlock[marker].puddleHeight) {
						marker++;
						break;
					}
					marker++;
				}
				break;
			}
			else {
				marker++;
			}
		}
		sumArea += area[i];
	}
	cout << sumArea << endl << puddleCount;
	for (int i = 0; i < puddleCount; i++) {
		cout << " " << area[i];
	}
	cout << endl;
	delete[] area;
	delete[] mBlock;
	return 0;
}

