bool searchEdge(const int a[][2], int n, int edge[])
{	
	edge[0] = edge[1] + 1;
	int i;
	for (i = edge[0]; i < n; i++) {
		if (a[i][1] - a[i][0] == -1) {
			edge[0] = i;
			break;
		}
	}	
	if (i >= n) return false;

	int height = a[edge[0]][0];
	edge[1] = edge[0];
	int j;
	for (j = edge[1]; j < n; j++) {
		if (a[j][1] == height) {
			edge[1] = j;
			break;
		}
	}
	if (j >= n) return false;

	return true;
}

int calcArea(const int a[][2], const int edge[])
{
	int max = a[edge[0][0]];
	int area = 0;
	for (int i = edge[0]; i <= edge[1]; i++) {
		if (a[i][0] < max || a[i][1] < max) {
			area += (-(a[i][0] - max));
			area += (-(a[i][1] -a[i][0]) / 2);
		}
	}

	return area;
}

#include <iostream>
#include <utility>

using namespace std;

void search_lakes(char input[], int lake_areas[],
	int *total_lake_area, int *lakes_num,
	int search_direction, int start_index, int last_index,
	char uphill_char, char flat_char, char downhill_char)
{
	int i = start_index;
	int depth = 0,
		lake_size = 0;
	bool is_inside_lake = false;

	if (search_direction == 1) {
		// start < last : i++
		for (int i = start_index; i < last_index;) {
			if (is_inside_lake)
			{
				// inside lake
				if (input[i] == uphill_char) {
					depth -= 2;
					lake_size += depth + 1;
					if (depth == 0)
					{
						// leave lake
						is_inside_lake = false;
						lake_areas[*lakes_num] = lake_size / 2;
						(*lakes_num)++;
					}
				}
				else if (input[i] == flat_char) {
					lake_size += depth;
				}
				else if (input[i] == downhill_char) {
					lake_size += depth + 1;
					depth += 2;
				}
				i++;
			}
			else
			{
				// outside lake
				if (input[i] == uphill_char || input[i] == flat_char) {
					i++;
				}
				else if (input[i] == downhill_char) {
					// enter lake
					is_inside_lake = true;
				}
			}
		}
	}
	else
	{
		// start > last : i--
		for (int i = start_index - 1; i >= last_index;) {
			if (is_inside_lake)
			{
				// inside lake
				if (input[i] == uphill_char) {
					depth -= 2;
					lake_size += depth + 1;
					if (depth == 0)
					{
						// leave lake
						is_inside_lake = false;
						lake_areas[*lakes_num] = lake_size / 2;
						*total_lake_area += lake_areas[*lakes_num];
						(*lakes_num)++;
						lake_size = 0;
					}
				}
				else if (input[i] == flat_char) {
					lake_size += depth;
				}
				else if (input[i] == downhill_char) {
					lake_size += depth + 1;
					depth += 2;
				}
				i--;
			}
			else
			{
				// outside lake
				if (input[i] == uphill_char || input[i] == flat_char) {
					i--;
				}
				else if (input[i] == downhill_char) {
					// enter lake
					is_inside_lake = true;
				}
			}
		}
	}
}

void land_survey(char input[], int *top_index, int *last_index)
{
	int max_height = -20001, now_height = 0, i = 0;
	*top_index = -20001; *last_index = 0;

	for (; input[i] != '\0'; i++) {
		switch (input[i])
		{
		case '/':
			now_height++;
			if (now_height > max_height) {
				*top_index = i + 1;
				max_height = now_height;
			}
			break;
		case '\\':
			now_height--;
			break;
		case '_':
			break;
		}
	}
	*last_index = i;
}

void simulate_flood(char input[], int lake_areas[], int *total_lake_area, int *lakes_num)
{
	*total_lake_area = 0;
	*lakes_num = 0;
	int top_index, last_index, center_index;
	land_survey(input, &top_index, &last_index);

	// search 0 ==> top_index (up'/' down'\\')
	search_lakes(
		input, lake_areas, total_lake_area, lakes_num,
		1, 0, top_index, '/', '_', '\\');
	center_index = *lakes_num;
	// search last ==> top_index (up'\\' down'/')
	search_lakes(
		input, lake_areas, total_lake_area, lakes_num,
		-1, last_index, top_index, '\\', '_', '/');
	reverse(&lake_areas[center_index], &lake_areas[*lakes_num]);
}


