{
	ios::sync_with_stdio(false);
	cin.tie(0);

	int total_lake_area, lake_num;
	char input[20001];
	int lake_areas[10001];

	cin >> input;

	simulate_flood(input, lake_areas, &total_lake_area, &lake_num);

	cout << total_lake_area << endl
		<< lake_num;
	for (int i = 0; i < lake_num; i++) {
		cout << ' ' << lake_areas[i];
	}
	cout << endl;

	return 0;
}

