main()
{
    ios_base::sync_with_stdio(false);

    string line;
    getline(cin, line);

    int level = 0;
    vector<int> levels(line.length() + 1); // level at the point
    levels[0] = level;
    map<int, pair<int, int> > areas; // start, end, area
    map<int, int> working; // start, workarea
    for (int i = 0; i < line.length(); i++) {
        working.insert(map<int, int>::value_type(i, 0));

        set<int> delist;
        switch (line[i]) {
          case '\\':
            level--;
            for (auto& it : working) {
                working[it.first] += 2 * (levels[it.first] - level) - 1;
            }
            break;
          case '_':
            for (auto& it : working) {
                if (levels[it.first] == level) { delist.insert(it.first); }
                working[it.first] += 2 * (levels[it.first] - level);
            }
            break;
          case '/':
            level++;
            for (auto& it : working) {
                if (levels[it.first] <= level) { delist.insert(it.first); }
                if (levels[it.first] < level) break;
                working[it.first] += 2 * (levels[it.first] - level) + 1;
            }
            break;
        }
        for (auto& it : delist) {
            if (working[it] > 0)
            areas.insert(map<int, pair<int, int> >::value_type(it, make_pair(i + 1, working[it] / 2)));
            working.erase(it);
        }
        levels[ i + 1 ] = level;
    }

    vector<int> k;
