struct pairs {
    int left, area;
};
int main()
{
    string input;
    cin >> input;
    int sum = 0, j;
    stack<int> left;
    stack<pairs> areas;
    pairs ini;
    ini.left = ini.area = 0;
    areas.push(ini);
    for (unsigned i = 0; i < input.size(); i++) {
        if ('\\' == input[i]) {
            left.push(i);
        }
        else if ('/' == input[i] && !left.empty()) {
            j = left.top();
            left.pop();
            sum += i - j;
            int temp;
            while(j < areas.top().left) {
                temp += areas.top().area;
                j = areas.top().left;
                areas.pop();
            }
            pairs x;
            x.area = i - j;
            x.left = j;
            areas.push(x);
        }
    }
    cout << sum << endl;
    stack<int> output;
    while(!areas.empty()) {
        int temp = areas.top().area;
        output.push(temp);
        areas.pop();
    }
    output.pop();
    if (!output.empty()) {
        cout << output.top();
        output.pop();
    }
    while(!output.empty()) {
        cout << " " << output.top();
        output.pop();
    }
    cout << endl;
}

