void findPeaks2(scenery& list, scenery& peaks) {
    bool climb = true;
    for(int i = 1; i < list.size(); i++) {
       if(list[i].second>list[i-1].second) {
           if(i==list.size()-1) {
               peaks.push_back(list[i]);
           }
           climb=true;
       } else if(list[i].second<=list[i-1].second){
           if(climb == true) {
                peaks.push_back(list[i-1]);
           }
           climb=false;
        }
    }
