    scenery::iterator highestMount= std::max_element(peaks.begin(),peaks.end(),mount);
    if(highestMount!=peaks.begin()) {
        int toto = computeSurface2(list, peaks.begin()->first, highestMount->first);
        if (toto>0) {
            surfaces.push_back(toto);
        }
