#include <iostream>
#include <stack>
#include <vector>

using namespace std;

typedef struct
{   
    /* 水溜りの面積を求めるために必要なデータ */
    unsigned int uiLeft;    /* 水溜りの左端のインデックス */
    unsigned int uiArea;    /* 水溜りの面積 */
}AreaInfo_t;

#define CALC_AREA(x,y) ((x) - (y))          /* 水溜りの面積の計算 */

stack<unsigned int> stuiArealeftIdx;        /* 水溜りの左端を保持するstack */
vector<AreaInfo_t> vectAreaInfo;            /* 水溜りの情報を持つvector */

unsigned int DetectionPuddle(char, unsigned int);   /* 水溜り検出 */
void UnionPuddle(AreaInfo_t);                       /* 水溜り合成 */

/*
水溜りの面積が連続で入力されため、水溜りが構成できる場合、
'\', '_', '/' の順に入力される
*/
int main(void){
    char ch = '\0';                 /* 入力を受け取るバッファ */
    unsigned int uiIdx = 0;         /* 何番目かの入力かをカウントする変数 */
    unsigned int uiTotal = 0;       /* 水溜りの総面積を表す変数 */

    /* 入力される文字列を一文字ずつ処理するループ */
    while(cin >> ch)
    {
        /* '\'と'/'で構成される水溜りの一部を計算 */
        uiTotal += DetectionPuddle(ch, uiIdx);
        uiIdx++;
    }

    /* 水溜り情報の出力 */
    cout << uiTotal << endl;
    cout << vectAreaInfo.size();

    /* 各水たまりの面積を左側から順に表示 */
    for(vector<AreaInfo_t>::iterator it = vectAreaInfo.begin(); it != vectAreaInfo.end(); it++)
    {
        cout << ' ' <<  it->uiArea;
    }
    cout << endl;

    return 0;

}

/*
入力された文字によって、構成できる水溜りの一部の面積を計算する
'\'と'/'の一組で水たまりの一部とする
ch      [in] 水溜りを構成する文字
uiIdx   [in] 何番目の文字か
return 水たまりの一部の面積
*/
unsigned int DetectionPuddle(char ch, unsigned int uiIdx)
{
    unsigned int rslt = 0;  /* 水溜りの一部の面積*/

    /*水溜りの面積を構成する文字を判定  */
    switch(ch)
    {
        case '\\':
            /* 入力された最新を取り出すため、水溜りの左端はstackに保存 */
            stuiArealeftIdx.push(uiIdx);
            break;
        case '/':
            /* 水溜りの左端が入力されている場合、左端を取り出し計算 */
            if(!stuiArealeftIdx.empty())
            {
                /* 水溜りの一部の面積の計算と合成の準備 */
                AreaInfo_t tInfo;
                tInfo.uiArea = CALC_AREA(uiIdx, stuiArealeftIdx.top());
                tInfo.uiLeft = stuiArealeftIdx.top();
                /* 水溜りの一部を対応した水溜りに合成 */
                UnionPuddle(tInfo);
                /* 水溜りとして処理出来た左端をスタックから除く */
                stuiArealeftIdx.pop();
                /* 面積の結果を戻り値として保存 */
                rslt =  tInfo.uiArea;
            }
            break;
        case '_':
            // pass
            break;
        default:
            // unreachable
            exit(1);
    }

    return rslt;
}
/*
水溜りの面積の一部同士を合体させ、一つの水たまりとして保存する
tInfo   [in]    最新の水たまりの情報
return  なし
*/
void UnionPuddle(AreaInfo_t tInfo)
{
    /* 水たまりが合成できなくなるまでのループ（一つ前の水溜りの面積が保存されている場合） */
    while(!vectAreaInfo.empty())
    {
        /* 最新の水たまりが一つの水たまりよりも内側(入力的には右側)にある場合、 */
        AreaInfo_t tmp = vectAreaInfo.back();
        if(tmp.uiLeft > tInfo.uiLeft)
        {
            /* 最新の水たまりの面積を更新（一つ前の水たまりと合算） */
            tInfo.uiArea += tmp.uiArea;
            vectAreaInfo.pop_back();
        }
        else
        {
            break;
        }
    }
    /* 最新の水たまりを保存 */
    vectAreaInfo.push_back(tInfo);

    return;
}

