  int level = 0;
  ys.push_back(0);

  for (char c : map) {
    if (c == '/') {
      ++level;
    } else if (c == '\\') {
      --level;
    }
    ys.push_back(level);
  }
  floodArea(0, ys.size());

  int areaSum = 0;
  for (int a : floodAreas) {
    areaSum += a;
  }
  cout << areaSum << endl;

  cout << floodAreas.size();
  for (int a : floodAreas) {
    cout << a << " ";
  }
  cout << endl;
}

