  cout << cnrvStSum.size();
  if (cnrvStSum.size() > 0)
  {
    cout << " ";
    for (auto itvStSum = begin(cnrvStSum); itvStSum != end(cnrvStSum); ++itvStSum)
    {
      if (itvStSum != begin(cnrvStSum)) cout << " ";
      cout << itvStSum->m_nArea;
    }
  }
  cout << endl;
}

