    int w = 0;
    int h = 0;
    string slopes;
    cin >> slopes;
    stack<Pos> heights;
    heights.push(Pos{-1, 100000});
    heights.push(Pos{0, 0});
    vector<Pos> ponds;
    for (auto ch : slopes){
        ++w;
        if (ch == '\\'){
            --h;
            heights.push(Pos{w, h});
