            if (heights.top().y == h){
                auto dif = w - heights.top().x - 1;
                cum += dif;
                while (!ponds.empty() && ponds.back().x > heights.top().x){
                    dif += ponds.back().y;
                    ponds.pop_back();
                }
                ponds.push_back(Pos{heights.top().x, dif});
                heights.top().x = w;
            }else{
                heights.push(Pos{w, h});
            }

        }else if (ch == '_'){
            heights.top().x = w;
        }
    }
    cout << cum << endl;
    cout << ponds.size();
