using namespace std;

class Water {
public:
	int size;
	int position;
	Water(int _size, int _position) {
		size = _size;
		position = _position;
	}
	void fill(int addition) {
		size += addition;
	}
	void merge(Water* water) {
		if (water) {
			size += water->size;
			delete water;
		}
	}
};

// it returns false if no action is committed
bool mergeWaters(int position, stack<Water*>& waters) {
	Water* accum = NULL;
	Water* water;
	while (! waters.empty() && (water = waters.top())->position >= position) {
		waters.pop();
		water->merge(accum);
		accum = water;
	}
	if (accum) {
		waters.push(accum);
		return true;
	} else {
		return false;
	}
}

int main() {
	string pattern;
	stack<Water*> waters;
	stack<int> positions;
	int total = 0;

	cin >> pattern;

	for (int pos = 0, len = pattern.length(); pos < len; pos++) {
		switch (pattern[pos]) {
		case '\\':
			positions.push(pos);
			break;
		case '/':
			if (! positions.empty()) {
				int top = positions.top(); positions.pop();
				int addition = pos - top;
				if (mergeWaters(top, waters))
					waters.top()->fill(addition);
				else
					waters.push(new Water(addition, top));
				total += addition;
			}
			break;
		case '_':
			break;
		}
	}

	cout << total << endl;
	cout << waters.size();
	while (! waters.empty()) {
		Water* water = waters.top(); waters.pop();
		cout << ' ' << water->size();
	}
	cout << endl;
}

