int Area::solve( string s )
{
  stack<int> st;
  stack<pair <int, int> > ans;
  vector<int> fa;

  int sum = 0;

  for (int i = 0; i < (int)s.size(); i++)
    {
      if (s[i] == '\\')
        {
          st.push(i);
        }
      else if (s[i] == '/')
        {
          if (!st.empty())
            {
              int b = st.top();
              int ss = (i - b);
              sum += (i - b);
              pair<int, int> t = ans.top();

              while (!ans.empty() && t.first > b)
                {
                  ss += t.second;
                  ans.pop();
                  t = ans.top();
                }

              ans.push(make_pair(b, ss));
              st.pop();
            }
        }
    }

  while(!ans.empty())
    {
      pair<int, int> t = ans.top();
      fa.push_back(t.second);
      ans.pop();
    }

  reverse(fa.begin(), fa.end());

  cout << sum << endl;
  cout << fa.size();

  for(vector<int>::iterator i = fa.begin(); i != fa.end(); i++)
    {
      cout << " " << *i;
    }

  cout << endl;

  return 0;
}

