typedef struct{int pos,size;}Lake;

void Push(Lake* s, int x, int y){
	int top;
	s[0].size++;
	top=s[0].size;

	s[top].pos=x;
	s[top].size=y;
}
void Pop(Lake* s){
	s[0].size--;
}
Lake Top(Lake* s){
	int top=s[0].size;
	return s[top];
}


