int main(){
	string inp;
	cin >> inp;
	int inp_size = inp.size();
	int hight[20000] = {0};
	int area[10000] = {0};
	for (int i = 0; i < inp_size; i++){
		if (inp[i] == '/'){
			hight[i+1] = hight[i] + 1;
		}
		else if (inp[i] == '_'){
			hight[i+1] = hight[i];
		}
		else {
			hight[i+1] = hight[i] - 1;
		}
	}

	// calc areas
	int x = inp_size;
	int num = 0;
	int sum = 0;
	while(x > 0){
		if (hight[x] > hight[x-1]){
			int y = x;
			for (int j = x-1; j >= 0; j--){
				if (hight[x] == hight[j]) {
					y = j;
					// calc area
					for (int i = y; i < x; i++){
						if (hight[i] > hight[i+1]){
							area[num] += (hight[y] - hight[i+1] - 1) * 2 + 1;
						}
						else if  (hight[i] == hight[i+1]){
							area[num] += hight[y] - hight[i+1];
						}
					}
					num++;
					sum += area[num];
					x = y;
					break;
				}
				if (j == 0) x = -1;
			}
		}
		else {
			x--;
		}
	}
	cout << sum << endl;
	cout << num;
	for (int i = 0; i < num; i++) cout << " " << area[i];
}

#include <iostream>
#include <string>
using namespace std;

string ike(string s, int* t)
{
    string c;
    int i = *t, d = *t;
    while (i < s.size())
    {
        int down = 0, up = 0;
        while (i < s.size())
        {
            if (s[i] == '\\') {
                down++;
            }
            else if (s[i] == '/') {
                break;
            }
            i++;
        }
        while (i < s.size())
        {
            if (s[i] == '/') {
                up++;
            }
            else if (s[i] == '\\')
            {
                up--;
            }
            if (down == up) {
                for (int j = d; j < i+1; j++)
                {
                    c += s[j];
                }
                *t = i;
                return c;
            }
            i++;
        }
        i = ++d;
    }
    return "";
}

int main()
{
    string s, c;
    cin >> s;

    int a = 0, b = 0, h = 0, i = 0;
    double sum[10000] = {}, sums=0;
    while (i < s.size())
    {
        while (i < s.size() && s[i] != '\\')
            i++;

        c = ike(s, &i);
        if (c == "")
            break;

        b = 0;
        a++;
        while (b < c.size())
        {
            if (c[b] == '\\')
            {
                sum[a-1] += 0.5 + (h * 1);
                h++;
            }
            else if (c[b] == '/')
            {
                if(0 < h){
                    sum[a - 1] += 0.5 + ((h-1)*1);
                    h--;
                }
            }
            else {
                sum[a - 1] += (h * 1);
            }
            b++;
        }
        sums += sum[a - 1];
    }

    cout << sums << "\n";
    cout << a << " ";
    for (i = 0; i < a; i++)
    {
        cout << sum[i] << (i < a-1 ? " ":"\n");
    }
    cin >> a;
}

