{
  cin.tie(0);
  ios::sync_with_stdio(false);

  stack<StDtl> skStDtl;
  vector<StSum> voSum;
  int iTtlAra = 0;

  fnCroSecSet(skStDtl, voSum, iTtlAra);
  fnCroSecGet(voSum, iTtlAra);

  return 0;
}

