int main() {
  std::string str;
  std::cin >> str;
  std::stack<int> stack;
  std::stack<std::pair<int, int>> stack2;

  for (int i = 0; i < str.size(); i++) {
    auto c = str[i];
    if (c == '\\') {
      stack.push(i);
    } else if (c == '/' && !stack.empty()) {
      int x = stack.top();
      stack.pop();

      auto current = std::make_pair(x, i - x);
      while (!stack2.empty()) {
        auto before = stack2.top();
        if (current.first > before.first) break;
        current.second += before.second;
        stack2.pop();
      }
      stack2.push(current);
    }
  }

  int total = 0;
  int count = 0;
  std::string areas = "";
  while (!stack2.empty()) {
    auto s = stack2.top();
    stack2.pop();
    total += s.second;
    count++;
    areas = " " + std::to_string(s.second) + areas;
  }

  std::cout << total << std::endl;
  std::cout << count++;
  std::cout << areas;
  std::cout << std::endl;
  return 0;
}

