#define PAIR		pair< char, int >

struct SResult
{
	int begin;
	int end;
	int val;

	SResult(){ Init(); }

	void Init()
	{
		begin	= -1;
		end		= -1;
		val		= -1;
	}

	bool operator < ( const SResult& e) const
	{
		return begin < e.begin;
	}
	bool operator > (const SResult& e) const
	{
		return begin > e.begin;
	}
	bool IsValid() const
	{
		return ( begin >= 0 ) && ( end >= 0 ) && ( val >= 0 );
	}
};

using namespace std;

int main()
{
	stack< PAIR > s;
	priority_queue< SResult, vector< SResult >, greater< SResult > >	res;

	// ??\???.
	string input;
	cin >> input;

	//??\?????????????????§?????¢????¨?????????§.
	int allRegion = 0;
	for( int i = 0; i < input.size(); ++i ){
		PAIR factor = make_pair( input[i], i );

		if( cin.eof() ){
			break;
		}

		if( factor.first == '\\' ){
			// ?????????????????????.
			s.push( factor );
		}
		else if( factor.first == '/' ){
			// ?????????????????????????????¨????????????????????¢???????¨??????????.
			if( s.empty() ){
				// ?????????????????????????????????????????§????????????????????????.
				continue;
			}

			PAIR top = s.top();	s.pop();

			// ?§?????????????????°´??????????????¢?????????????????????.
			SResult tmp;
			tmp.begin	= top.second;
			tmp.end		= factor.second;
			tmp.val		= tmp.end - tmp.begin;
			res.push(tmp);

			// ????????§?????¨??¢??????????¨?????????¨???.
			allRegion += tmp.val;
		}
	}

	// ???????????¢????????±???????????????.
	vector< SResult > output;
	SResult root;
	while( res.size() > 0 ){
		SResult tmp = res.top();	res.pop();
		if( root.IsValid() ){
			if( root.begin < tmp.begin && tmp.end < root.end ){
				// ???????????\??£??????????????§??±???.
				root.val += tmp.val;
			}
			else{
				// ?????????????????????????????§????????£.
				output.push_back( root );
				root = tmp;
			}
		}
		else{
			root = tmp;
		}
	}
	// ???????????\????????????????????£??????????????§??\??????.
	if( root.IsValid() ){
