struct Sq
{
	unsigned int xmax;
	unsigned long li;
};

int main()
{
	string st;
	long a = 0, hmax = 0;
	vector<long> h = { 0 };
	vector<Sq> S = { Sq{0, 0} };

	cin >> st;

	for (unsigned int i = 0; i < st.size(); i++) {

		switch (st[i]) {
			case '/':
				if (h[i] == hmax)
					hmax++;
				else {
					for (unsigned long j = 0; j < h.size(); j++) {
						if (h[h.size() - j - 1] == h[i] + 1) {
							if (S.back().xmax !=0 && (S.back().xmax < h.size() - j))
								S.push_back(Sq{ h.size() - 1 , j});
							else if (S.size() > 1 && (S[S.size() - 2].xmax > h.size() - j)) {
								while (S.size() > 1 && (S[S.size() - 2].xmax > h.size() - j)) {
									S[S.size() - 2].li += j + S.back().li;
									S.pop_back();
								}
							}
							else{
								S.back().li += j;
								S.back().xmax = h.size() - 1;
							}
							break;
						}
					}
				}
				h.push_back(h[i] + 1);
				break;
			case '\\':
				h.push_back(h[i] - 1);
				break;
			case '_':
				h.push_back(h[i]);
				break;
		}
	}

	for (unsigned int i = 0; i < S.size(); i++)
		a += S[i].li;

	cout << a << endl;

	if (a > 0) {
		cout << S.size();
		for (unsigned int i = 0; i < S.size(); i++)
			cout << " " << S[i].li;
	}
	else
		cout << "0";

	cout << endl;

	return 0;
}

#include <iostream>
#include <vector>
#include <string>

using namespace std;

int main()
{
	string line;
	cin >> line;
	vector<int> stack;
	vector<int> lakes;
	int all =0;
	int lake = 0;

	for (int i=0; i<line.length(); i++)
	{
		char c = line[i];
		if (c=='\\')
		{
			stack.push_back(i);
		}
		else if (c=='/')
		{
			if (stack.size() == 0) continue;
			auto end = stack.end() -1;
			lake += i - *end;
			stack.erase(end);
			if (stack.size() == 0)
			{
				all += lake;
				lakes.push_back(lake);
				lake = 0;
			}
		}
	}

	int mid = lakes.size();
	lake = 0;

	if (stack.size())
	{
		int end = stack[0];
		stack.clear();
		for (int i = line.length()-1; i >= end; i--)
		{
			char c = line[i];
			if (c=='/')
			{
				stack.push_back(i);
			}
			else if (c=='\\')
			{
				if (stack.size() == 0) continue;
				auto end = stack.end() -1;
				lake += *end - i;
				stack.erase(end);
				if (stack.size() == 0)
				{
					all += lake;
					lakes.push_back(lake);
					lake = 0;
				}
			}
		}
	}

	cout << all << endl;
	cout << lakes.size();
	for (int i=0; i<mid; i++)
	{
		cout << ' ' << lakes[i];
	}
	for (int i=lakes.size()-1; i>=mid;i--)
	{
		cout << ' ' << lakes[i];
	}
	cout << endl;

	return 0;
}

