typedef std::vector<int> TList;
typedef TList::iterator TIt;
struct TPeak
{
    int Pos;
    int Alt;
    TPeak(int APos, int AAlt) : Pos(APos), Alt(AAlt) {}
};
typedef std::vector<TPeak> TPeakList;
bool CompareAlt(const TPeak& Left, const TPeak& Right)
{
    return Left.Alt < Right.Alt;
}

void Output(const TList& List)
{
    TList::const_iterator It = List.begin();
    std::cout << *(It++);
    for(; It != List.end(); ++It){
        std::cout << " " << *It;
    }
    std::cout << std::endl;
}
TList GetAltitude(const std::string Diagram)
{
    TList AltList;
    AltList.reserve(Diagram.size()+1);
    int Alt = 0;
    AltList.push_back(Alt);
    for(int i = 0; i < Diagram.size(); ++i){
        if(Diagram[i] == '\\'){
            --Alt;
        }else
        if(Diagram[i] == '/'){
            ++Alt;
        }
        AltList.push_back(Alt);
    }
    return AltList;
}
TPeakList GetPeakList(const TList& AltList)
{
    TPeakList PeakList;
    bool IsUpped = true;
    int Pos;
    for(Pos = 0; Pos < AltList.size() - 1; ++Pos){
        if(IsUpped && AltList[Pos+1] < AltList[Pos]){
            PeakList.push_back(TPeak(Pos, AltList[Pos]));
            IsUpped = false;
        }
        if(AltList[Pos+1] > AltList[Pos]){
            IsUpped = true;
        }
    }
    if(IsUpped){
        PeakList.push_back(TPeak(Pos, AltList[Pos]));
    }
    return PeakList;
}
int GetArea(const TList& AltList, int TopPos, int SecondPos)
{
    dprintf("TopPos:%d, SecondPos:%d\n", TopPos, SecondPos);
    int way = TopPos < SecondPos ? -1 : 1;
    int Depth = 0;
    int Area = 0;
    for(int i = SecondPos + way; i != TopPos + way; i += way){
        dprintf("%2d:%d\n", i, AltList[i]);
        switch(AltList.at(i) - AltList.at(i - way)){
        case 1:
            --Depth;
            Area += Depth * 2 + 1;
            if(Depth == 0){
                dprintf("Area:%d\n", Area/2);
                return Area/2;
            }    
            break;
        case 0:
            Area += Depth * 2;
            break;
        case -1:
            Area += Depth * 2 + 1;
            ++Depth;
            break;
        default:
            assert(false);
        }
    }
    assert(false);   
}
TList SimulateFlood(const TList& AltList, TPeakList::const_iterator begin, TPeakList::const_iterator end)
{
    TList List;
    TPeakList::const_iterator Top = begin;
    while(Top+1 != end){
        TPeakList::const_iterator Second = std::max_element(Top+1, end, CompareAlt);
        int Area = GetArea(AltList, Top->Pos, Second->Pos);
        List.push_back(Area);
        Top = Second;
    }
    return List;
}
