TList SimulateFlood(const std::string Diagram)
{
    TList AltList = GetAltitude(Diagram);
    TPeakList PeakList = GetPeakList(AltList);
    if(PeakList.size() < 2){
        return TList();
    }

    // ShowPeakList(PeakList); // debug
    TPeakList::iterator TopPeak = std::max_element(PeakList.begin(), PeakList.end(), CompareAlt);
    dprintf("TopPeakPos:%d\n", TopPeak->Pos);
    dprintf("TopPeakAlt:%d\n", TopPeak->Pos);
    TList RightAreaList = SimulateFlood(AltList, TopPeak, PeakList.end());

    int D = std::distance(PeakList.begin(), TopPeak);
