    if(D == 0) return RightAreaList;
    TPeakList LeftPeakList(PeakList.begin(), TopPeak+1);
    std::reverse(LeftPeakList.begin(), LeftPeakList.end());
    TList LeftAreaList = SimulateFlood(AltList, LeftPeakList.begin(), LeftPeakList.end());
    std::reverse(LeftAreaList.begin(), LeftAreaList.end());

    LeftAreaList.insert(LeftAreaList.end(), RightAreaList.begin(), RightAreaList.end());
    return LeftAreaList;
}

