	int h = 0,oldh = 0,res = 0;
	while(true) {
		char c = q.front();
		h += (c == '\\');
		h -= (c == '/');

		res += h + oldh;

		if(h == 0) {
			break;
		}

		q2.push(c);
		q.pop();
		if(q.empty()) {
			q2.pop();
			q = q2;
			return f();
		}

		oldh = h;
	}
	return res;
}

