int main(){
    string str;
    cin >> str;

    //出力記憶用
    int sum=0;
    stack<int> output;

    stack<int> slopes; //坂の開始位置を格納する
    stack<pair<int,int> > lakes; //水たまりを格納する first:位置,second:面積

    for(int i=0;i<str.length();++i){
        if(str[i]=='\\'){
            slopes.push(i);
        }else if(str[i]=='/' && !slopes.empty()){
            int s=slopes.top();slopes.pop();
            lakes.push(pair<int,int>(s,i-s));
            sum+=i-s;
        }
    }

    //包含関係にある水たまりのうち，小さい方の方が後から出てくることを利用
    vector<bool> islake(str.length(),false); //湖かどうか記憶しておく
    while(!lakes.empty()){
        if(islake[lakes.top().first]){
            //すでに水面下であった場合
            output.top()+=lakes.top().second;
        }else{
            for(int i=lakes.top().first;i<lakes.top().first+lakes.top().second;++i){
                islake[i]=true;
            }
            output.push(lakes.top().second);
        }
        lakes.pop();
    }

    //出力するだけ
    cout << sum << endl;
    cout << output.size();
    while(!output.empty()){
        cout << ' ' << output.top();
        output.pop();
    }
    cout << endl;
}

