#include <stdio.h>
#include <vector>
#include <algorithm>

using namespace std;

// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=ALDS1_3_D

const int maxi = 20000;
const char UP = '/';
const char DOWN = '\\';
const char FLAT = '_';

template<typename I, typename F>
void for_each2(I begin, I end, F fnc){
    if (begin == end) return;
    fnc(true, begin == end - 1, *begin);
    while(++begin <= end - 1) fnc(false, begin == end - 1, *begin);
}

class Area {
    public:
        int start;
        int end;
        int area;
        Area(int start, int end, int area) : start(start), end(end), area(area) {};
        Area() = default;
        inline bool contains(const Area &a){
            return start <= a.start && a.end <= end;
        }
};

vector<Area> areas;
vector<int> starts;
const int max_s = 20000;

int main(int argc, char const* argv[])
{
    starts.reserve(max_s/2);

    int c;
    int i = 0;
    while ((c = getchar()) != EOF) {
        if(starts.empty() && c != DOWN){
            // nop
        }else if(c == DOWN){
            starts.push_back(i);
        }else if(c == UP){
            int s;
            s = starts.back();
            Area a(s, i, i-s);
            while (!areas.empty()) {
                auto p = areas.back();
                if(a.contains(p)){
                    a.area += p.area;
                    areas.pop_back();
                } else {
                    break;
                }
            }
            areas.push_back(a);
            starts.pop_back();
        }
        i++;
    }

    int sum = 0;
    for_each(areas.begin(), areas.end(), [&sum](Area &x)
        { sum += x.area; });
    printf("%d\n", sum);
    if(areas.size() > 0){
        printf("%d ", areas.size());
        for_each2(areas.begin(), areas.end(), [](bool is_first, bool is_last, Area &v)
            { printf(!is_last ? "%d " : "%d\n", v.area); });
    }else{
        puts("0");
    }

    return 0;
}

