            }
            else if (s[i] == '/') {
                break;
            }
            i++;
        }
        while (i < s.size())
        {
            if (s[i] == '/') {
                up++;
            }
            else if (s[i] == '\\')
            {
                up--;
            }
            if (down == up) {
                for (int j = d; j < i+1; j++)
                {
                    c += s[j];
                }
                *t = i;
                return c;
            }
            i++;
        }
        i = ++d;
    }
    return "";
}

