template <typename T> constexpr T INF = numeric_limits<T>::max() / 2;

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  stack<int> left;
  stack<int> right;
  stack<int> pool;
  char c;
  int i = 0;
  while (cin >> c) {
    if (c == '/' and not left.empty()) {
      int l = left.top();
      left.pop();

      pool.push(i - l);

      while (not right.empty()) {
        int r_prev = right.top();
        if (l < r_prev) {
          // merge
          int pool_prev1 = pool.top();
          pool.pop();
          int pool_prev2 = pool.top();
          pool.pop();
          pool.push(pool_prev1 + pool_prev2);
          right.pop();
        } else {
          break;
        }
      }

      right.push(i);
    } else if (c == '\\') {
      left.push(i);
    }
    i++;
  }

  vector<int> vec;
  while (not pool.empty()) {
    vec.push_back(pool.top());
    pool.pop();
  }
  reverse(ALL(vec));
  int ans = 0;
  REP(i, SZ(vec)) { ans += vec.at(i); }
  cout << ans << endl;
  cout << SZ(vec);
  REP(i, SZ(vec)) { cout << " " << vec.at(i); }
  cout << endl;

  return 0;
}

