using namespace std;

int main() {
    stack<double> s;
    vector<double> S;
    int m = 0, n = 0, w = 0, maxd = 0;
    char map[20001];
    scanf("%s", map);

    while (1){
        if (s.empty()){
            maxd = 0;
            w = 0;
            if (map[n] == '\\'){
                s.push(0.5);
                S.push_back(0.5);
                w++;
                maxd = max(maxd, int(s.size()));
            }
        }

        else if (not s.empty()){
            if (map[n] == '\\'){
                s.push(0.5+s.size());
                S[m] += s.top();
                w++;
                maxd = max(maxd, int(s.size()));
            }
            else if (map[n] == '_'){
                S[m] += s.size();
                w++;
            }
            else if (map[n] == '/'){
                S[m] += s.top();
                s.pop();
                w++;
                if (s.empty()){
                    m++;
                }
            }
        }
        n++;
        if (n == strlen(map)) break;
    }
    if (not s.empty()){
        S[m] -= min(maxd, int(s.size())) * (w + w - s.size()) / 2;
        if (S[m] > 0) m++;
    }

    double Sum = 0;
    for (int i = 0; i < m; i++){
        Sum += S[i];
    }

    printf("%d", int(Sum));
    printf("\n");
    printf("%d", m);
    for (int i = 0; i < m; i++){
        printf(" ");
        printf("%d", int(S[i]));
    }
    printf("\n");

    return 0;

}

