int main() {
    string S;
    cin >> S;
    int n = S.size();
    vector<int> h(n+1), max_l(n+1), max_r(n+1);
    h[0] = 0;
    for ( int i = 1; i <= n ; i++ ) {
        char s = S[i-1];
        h[i] = h[i-1];
        if ( s == '\\' ) h[i]--;
        if ( s == '/' ) h[i]++;
    }
    max_l[0] = h[0];
    for ( int i = 1; i <= n; i++ ) {
        max_l[i] = max(max_l[i-1] , h[i]);
    }
    max_r[n] = h[n];
    for ( int i = n-1; i >= 0; i-- ) {
        max_r[i] = max(max_r[i+1], h[i]);        
    }
    vector<int> L;
    int x2 = 0, d1, d2;
    for ( int i = 0; i < n; i++ ) {
        d1 = min(max_r[i], max_l[i]) - h[i];
        d2 = min(max_r[i+1], max_l[i+1]) - h[i+1];
        if (d1 < 0) d1 = 0;
        if (d2 < 0) d2 = 0;
        if ( (d1 == 0 || d2 == 0) && x2 > 0 ) {
            x2 += d1 + d2;
            L.push_back(x2/2);
            x2 = 0;
        } else {
            x2 += d1 + d2;
        }
    }
    if ( x2 > 0 ) {
        L.push_back(x2/2);
        x2 = 0;
    }

    int A = 0;
    for ( int i = 0; i < L.size(); i++ ) {
        A += L[i];
    }

    cout << A << '\n';
    cout << L.size();
    for ( int i = 0; i < L.size(); i++ ) {
        cout << " " << L[i];
    }
    cout << '\n';
    return 0;
}

