int main() {
    string s;
    cin >> s;
    int A[10010], ans = 0, n = 0;

    for (int i = 0; i < s.size();) {
        if (s[i] == '\\') {
            int dl = 0, hl = 0, ul = 0;
            for (int j = i; s[j] == '\\'; ++j) {
                ++dl;
            }
            if (s[i + dl] == '_') {
                for (int j = i + dl; s[j] == '_'; ++j) {
                    ++hl;
                }
            }
            else if (s[i + dl] == '/') {
                for (int j = i + dl; s[j] == '/'; ++j) {
                    ++ul;
                }
            }
            if (s[i + dl + hl] == '/') {
                for (int j = i + dl + hl; s[j] == '/'; ++j) {
                    ++ul;
                }
            }
            if (dl > ul) {
                A[n] = ul * ul + hl * ul;
                ans += A[n];
            }
            else {
                A[n] = dl * dl + hl * dl;
                ans += A[n];
            }
            ++n;
            i += dl + hl + ul;
        }
    }

    cout << ans << endl << n;
    for (int i = 0; i < n; ++i) {
        cout << ' ' << A[i];
    }
    cout << endl;

