class CrossSectionDiagram {
public:
    CrossSectionDiagram(string diagram) : diagram_(diagram), totalArea(0) {}
    void solve() {
        size_t current = 0;
        while (current < diagram_.size()) {
            current = findStart(current);
            if (current == string::npos) {
                break;
            }
            size_t end = findEnd(current);
            if (end != string::npos) {
                int area = getArea(current, end);
                areas.push_back(area);
                totalArea += area;
                current = end + 1;
            }
            else {
                ++current;
            }
        }

        cout << totalArea << endl;
        cout << areas.size();
        for (int i : areas) {
            cout << " " << i;
        }
        cout << endl;
    };
private:
    size_t findEnd(int start) {
        int depth = 0;
        size_t current = start;
        while (current < diagram_.size()) {
            switch (diagram_[current]) {
            case '\\':
                ++depth;
                break;
            case '/':
                --depth;
                break;
            default:
                break;
            }
            if (depth == 0) {
                return current;
            }
            ++current;
        }
        return string::npos;
    }
    size_t findStart(int start) {
        size_t current = start;
        while (current < diagram_.size()) {
            if (diagram_[current] == '\\') {
                return current;
            }
            ++current;
        }
        return string::npos;
    }
    int getArea(size_t start, size_t end) {
        int depth = 0;
        int area = 0;
        for (size_t i = start; i <= end; ++i) {
            switch (diagram_[i]) {
            case '\\':
                ++area;   // 2倍の値とする
                area += (depth * 2);
                ++depth;
                break;
            case '/':
                ++area;
                --depth;
                area += (depth * 2);
                break;
            case '_':
                area += (depth * 2);
                break;
            default:
                break;
            }
        }
        return area/2;
    }
    string diagram_;
    vector<int> areas;
    int totalArea;
};

