    //string str{ "\\\\///\\_/\\/\\\\\\\\/_/\\\\///__\\\\\\_\\\\/_\\/_/\\" };

    CrossSectionDiagram aCrossSectionDiagram(str);
    aCrossSectionDiagram.solve();
}

