  {
    cout << " ";
    for (auto itvoSum = begin(a_cnrvoSum); itvoSum != end(a_cnrvoSum); ++itvoSum)
    {
      if (itvoSum != begin(a_cnrvoSum)) cout << " ";
      cout << itvoSum->m_iArea;
    }
  }
  cout << endl;
}

