#include    <utility>

using namespace std;

int main() {
    using uint = unsigned int;

    string in;
    stack<uint> downPoint;              // 下り坂の地点を覚える
    deque<pair<uint, uint> > puddles;   // 水たまりの始点位置と面積の組 stackとqueueを使いたいため，dequeで実装
    uint sum = 0;

    // 入力
    cin >> in;

    // 計算
    for(uint i = 0; i < in.size(); i++) {
        if(in[i] == '\\') {
            downPoint.push(i);
        }
        // のぼり坂の場合，総面積の更新と水たまりの更新(結合)を行う．
        // ただし，対応する下り坂がない場合はこの計算を行わない．
        else if(in[i] == '/' && !downPoint.empty()) {
            // 対応する坂との間の部分面積を求める．
            uint j = downPoint.top(), p = i - j;
            downPoint.pop();
            // 総面積に加算する．
            sum += p;

            // 水たまりをまとめる．
            while(!puddles.empty() && puddles.front().first > j) {
                p += puddles.front().second;
                puddles.pop_front();
            }
            puddles.push_front(make_pair(j, p));
        }
    }

    // 出力
    cout << sum << endl;
    cout << puddles.size();
    while(!puddles.empty()) {
        cout << ' ' << puddles.back().second;
        puddles.pop_back();
    }
    cout << endl;

    return 0;
}

