#include<iostream>
#include<stack>

using namespace std;

int main() {
	int slope[20000];
	int n = 0;
	int maxH = 0;
	int nowH = 0;
	stack<int> tops;
	stack<int> topInds;
	bool nextTop = true;
	char s;
	while(cin >> s) {
		if(s == '-') {
			slope[n] = 0;
		}
		else if(s == '/') {
			slope[n] = 1;
			nextTop = true;
			nowH++;
			while(!tops.empty() && nowH > tops.top() && maxH > tops.top()) {
				tops.pop();
				topInds.pop();
			}
			maxH = (nowH > maxH) ? nowH : maxH;
		}
		else {
			slope[n] = -1;
			if(nextTop) {
				tops.push(nowH);
				topInds.push(n);
				nextTop = false;
			}
			nowH--;
		}
		n++;
	}
	if(nextTop) {
		tops.push(nowH);
		topInds.push(n);
	}

	int sumR = 0;
	int count = 0;
	int rains[20000];
	int tpR = tops.top(); tops.pop();
	int tpRInd = topInds.top(); topInds.pop();
	while(!tops.empty()) {
		int tpL = tops.top();
		int depth = 0;
		int rain = 0;
		int slC = 0;
		if(tpL > tpR) {
			do {
				tpRInd--;
				int sl = slope[tpRInd];
				slC += sl*sl;
				rain += depth;
				depth -= sl;
				if(sl == 1) rain--;
			} while(depth != 0 || slC == 0);
		}
		else {
			int tpLInd = topInds.top();
			do {
				int sl = slope[tpLInd];
				slC += sl*sl;
				rain += depth;
				depth -= sl;
				tpLInd++;
				if(sl == 1) rain--;
			} while(depth != 0 || slC == 0);
		}
		rain += slC / 2;
		sumR += rain;
		rains[count] = rain;
		count++;
		tpR = tops.top(); tops.pop();
		tpRInd = topInds.top(); topInds.pop();
	}

	cout << sumR << endl;
	cout << count;
	for(int i=0; i<count; i++) {
		cout << " " << rains[count-1-i];
	}
	cout << endl;
}

