#include <stdio.h>
#include <deque>
#include <map>

struct PoolInfoEntry
{
	int position;
	int capacity;
};
typedef std::deque<PoolInfoEntry> PoolInfo;

typedef std::deque<int> PositionInfo;

int main( int argc , char** argv )
{
	int total_capacity = 0;
	int position = 0;
	PoolInfo pool_info;
	PositionInfo position_info;

	while( 1 )
	{
		int c = getchar();
		if( c == EOF )
		{
			break;
		}
		if( c == '\\' )
		{
			position_info.push_back( position );
		}
		if( c == '/' )
		{
			if( !position_info.empty() )
			{
				int start_position = position_info.back();
				int capacity = position - start_position;

				total_capacity += capacity;

				while( ( !pool_info.empty() ) && ( start_position < pool_info.back().position ) )
				{
					capacity += pool_info.back().capacity;
					pool_info.pop_back();
				}
				PoolInfoEntry entry;
				entry.position = start_position;
				entry.capacity = capacity;
				pool_info.push_back( entry );

				position_info.pop_back();
			}
		}
		position++;
	}

	printf( "%d\n" , total_capacity );
	printf( "%d" , pool_info.size() );
	for( PoolInfo::const_iterator itr = pool_info.begin() ; itr != pool_info.end() ; itr++ )
	{
		printf( " %d" , itr->capacity );
	}
	printf( "\n" );
	return 0;
}

#include<deque>
#include<iostream>
#include<string>

int main()
{
	std::string str;
	std::cin >> str;

	int heightRight = 0;
	for (char c : str)
	{
		if ('\\' == c)
		{
			heightRight -= 1;
		}
		else if ('/' == c)
		{
			heightRight += 1;
		}
	}
	int heightLeft = 0;

	auto searchDown = [&str, &heightLeft, &heightRight](int& targetPosition, int& targetHeight)
	{
		const char characterDown = &heightLeft == &targetHeight ? '\\' : '/';
		const char characterUp = &heightLeft == &targetHeight ? '/' : '\\';
		const int direction = &targetHeight == &heightLeft ? 1 : -1;
		for (; 0 <= targetPosition && str.size() > targetPosition && characterDown != str[targetPosition]; targetPosition += direction)
		{
			if (characterUp == str[targetPosition])
			{
				targetHeight += 1;
			}
		}
	};
	auto researchFlood = [&str, &heightLeft, &heightRight](int& targetPosition, int& targetHeight)
	{
		const char characterDown = &heightLeft == &targetHeight ? '\\' : '/';
		const char characterUp = &heightLeft == &targetHeight ? '/' : '\\';
		const int direction = &targetHeight == &heightLeft ? 1 : -1;
		const int startHeight = targetHeight;
		int area = 0;
		targetPosition += direction;
		targetHeight -= 1;
		while (startHeight > targetHeight)
		{
			area += startHeight - targetHeight;
			if (characterDown == str[targetPosition])
			{
				targetHeight -= 1;
			}
			else if (characterUp == str[targetPosition])
			{
				targetHeight += 1;
			}
			targetPosition += direction;
		}
		return area;
	};

	int positionLeft = 0;
	int positionRight = static_cast<int>(str.size()) - 1;
	std::deque<int> areaLeft;
	std::deque<int> areaRight;
	int areaSum = 0;
	searchDown(positionLeft, heightLeft);
	searchDown(positionRight, heightRight);
	while (positionLeft < positionRight)
	{
		if (heightLeft < heightRight)
		{
			areaLeft.emplace_back(researchFlood(positionLeft, heightLeft));
			areaSum += areaLeft.back();
			if (positionLeft >= positionRight)
			{
				break;
			}
			searchDown(positionLeft, heightLeft);
		}
		else
		{
			areaRight.emplace_front(researchFlood(positionRight, heightRight));
			areaSum += areaRight.front();
			if (positionLeft >= positionRight)
			{
				break;
			}
			searchDown(positionRight, heightRight);
		}
	}

	std::cout << areaSum << std::endl;
	std::cout << (areaLeft.size() + areaRight.size());
	if (!areaLeft.empty())
	{
		std::cout << ' ';
	}
	for (int index = 0; static_cast<int>(areaLeft.size()) - 1 > index; ++index)
	{
		std::cout << areaLeft[index] << ' ';
	}
	if (!areaLeft.empty())
	{
		std::cout << areaLeft.back();
	}
	if (!areaRight.empty())
	{
		std::cout << ' ';
	}
	for (int index = 0; static_cast<int>(areaRight.size()) - 1 > index; ++index)
	{
		std::cout << areaRight[index] << ' ';
	}
	if (!areaRight.empty())
	{
		std::cout << areaRight.back();
	}
	std::cout << std::endl;
}

