stack<unsigned> sam;
stack<unsigned> sam2;
vector<unsigned> pool;
unsigned sum = 0;
unsigned p_sum = 0;
void all_add(){
    for (int i = 0; i < sam.size(); i++) {
        sam2.push(sam.top() + 1);
        sam.pop();
    }
    for (int i = 0; i < sam2.size(); i++) {
        sam.push(sam2.top());
        sam2.pop();
    }
}

void pair_sum(){
    all_add();
    unsigned a = sam.top();
    sam.pop();
    p_sum += a;
}

int main(){

    char ch;

    for(int i = 0;(cin >> ch);i++){

        if(p_sum > 0 && sam.empty()){
            sum += p_sum;
            pool.push_back(p_sum);
            p_sum = 0;
        }

        if (ch == '\\') {
            if (sam.empty() == true) {
                sam.push(0);
            }else{
                all_add();
                sam.push(0);
            }
        }else if(ch == '/'){
            if (sam.empty() != true) {
                pair_sum();
            }
        }else{
            if (sam.empty() != true) {
                all_add();
            }
        }
    }

    cout<<sum<<endl;
    cout<<pool.size();
    for (int i = 0; i < pool.size(); i++) {
