list<int> rec(int start){
	list<int> areas;
	int area = 0;
	bool downed = false;
	for(i=start; i<size; i++){
		switch(s[i]){
		case '\\':
			if(downed)
				for(int tmp : rec(i))
					areas.push_back(tmp);
			downed = true;
			break;
		case '_':
			break;
		case '/':
			if(downed){
				area = i - start;
				for(int tmp : areas)
					area += tmp;
				areas.clear();
				areas.push_back(area);
				downed = false;
			}
			return areas;
		}
	}
	return areas;
}


