#include <iostream>
#include <string>
#include <map>
#include <set>

using namespace std;

typedef multimap<int, int> MMII;
typedef map<int, int> MII;

void readline(const string line, set<int>* keys, MMII* levels, MII* heights)
{
    int level = 0;
    levels->insert(MMII::value_type(0, level));
    heights->insert(MII::value_type(0, level));
    for (int i = 0; i < line.length(); i++) {
        switch (line[i]) {
          case '\\':
            level++;
            break;
          case '/':
            level--;
            break;
          case '_':
            break;
        }
        if (keys->find(level) == keys->end()) { keys->insert(level); }
        levels->insert(MMII::value_type(level, i + 1));
        heights->insert(MII::value_type(i + 1, level));
    }
}

int
getarea(const int a, const int b, const MII heights)
{
    int area = 0;
    int depth = 0;
    for (int i = a + 1; i <= b; i++) {
        if (heights.find(i) == heights.end()) { return 0;}
        switch (heights.at(i) - heights.at( i - 1 )) {
          case -1:
            depth -= 2;
            area += depth + 1;
            break;
          case 1:
            depth += 2;
            area += depth - 1;
            break;
          default:
            area += depth;
        }
        if (depth < 0) { return 0; }
    }

    return area / 2;
}

int
main()
{
    ios_base::sync_with_stdio(false);

    string line;
    getline(cin, line);

    MMII levels;
    MII heights;
    set<int> keys;
    readline(line, &keys, &levels, &heights);

    MII areas;
    int total = 0;
    for (auto& it : keys) {
        pair<decltype(levels)::const_iterator, MMII::const_iterator> p = levels.equal_range(it);
        for (auto kit = p.first; kit != p.second; kit++) {
            if (heights.find(kit->second) == heights.end()) { continue; }
            auto nit = next(kit);
            while (nit != p.second && heights.find(nit->second) == heights.end()) { nit = next(nit); }
            if (nit == p.second) { continue; }
            int a = getarea(kit->second, nit->second, heights);
            if (a > 0) {
                areas.insert(MII::value_type(kit->second, a));
                total += a;
            }
            for (int i = kit->second; i < nit->second; i++) {
                heights.erase(i);
            }
        }
    }

    cout << total << endl;
    cout << areas.size();
    for (auto& it : areas) {
        cout << ' ' << it.second;
    }
    cout << endl;

    return 0;
}

