auto bracket_matcher(const string& str){
  vector<int32_t> que;
  vector<tuple<int32_t,int32_t>> ret;
  for(int32_t i=0; i<str.size(); ++i){
    if(str[i]=='\\'){
      que.push_back(i);
    } else if(str[i]=='/'){
      if(!que.empty()){
        int32_t x=que.back(); que.pop_back();
        int32_t tmp_area=0;
        while(!ret.empty() && get<0>(ret.back())>x){
          tmp_area+=get<1>(ret.back()); ret.pop_back();
        }
        ret.emplace_back(x,tmp_area+i-x);
      }
    }
  }
  return ret;
}
int32_t main(){
