int calc_area(int i, int j, const string* input)
{
    int area = 0, d = 0;
    while (i < j) {
	if ((*input)[i] == UP)
	    area += d--;
	else if ((*input)[i] == DOWN)
	    area += d++;
	else
	    area += d;
	i++;
    }
    return area;
}

