stack<int> y;       // 水位を入れる => 最初の水位を0とする
stack<int> leftMax; // 自分よりも左側の最大の水位
stack<int> result;
int allsum = 0;

int deleteRight()
{
    int rightTop = 0;
    // 右端より高い部分は捨てる
    while (y.size() > 1)
    {
        int right = y.top();
        y.pop();
        int leftMaximum = leftMax.top();
        leftMax.pop();
        if (leftMaximum < right)
        {
            // 水位より高い場合
            continue;
        }
        int left = y.top();
        if (left >= right)
        {
            // 左以下の場合
            continue;
        }
        else
        {
            rightTop = right;
            break;
        }
    }
    return rightTop;
}

