    leftMax.push(0);
    string word;
    cin >> word;
    for (char a : word)
    {
        leftMax.push(leftMax.top() >= y.top() ? leftMax.top() : y.top());
        if (a == '\\')
        {
            y.push(y.top() - 1);
        }
        else if (a == '_')
        {
            y.push(y.top());
        }
        else if (a == '/')
        {
            y.push(y.top() + 1);
        }
    }
    while (y.size() > 1)
    {
        int righttop = deleteRight();
        int sum = 0;
