		else a[cnt][1] = a[cnt][0];
		a[cnt+1][0] = a[cnt][1];
		cnt++;
	}

	int edge[2];
	edge[1] = -1;
	int area[10000];
	int k = 0;
	while (1) {
		if (searchEdge(a, cnt, edge)) {
			area[k] = calcArea(a, edge);
			k++;
		}
		if (edge[1] >= cnt - 1) break;
	}

	int sum = 0;
	for (int i = 0; i < k; i++) {
