		cout << " " << area[k];
	}
	cout << endl;

	return 0;
}

bool searchEdge(const int a[][2], int n, int edge[])
{	
	edge[0] = edge[1] = edge[1] + 1;
	for (int i = edge[0]; i < n; i++) {
		if (a[i][1] - a[i][0] == -1) {
			edge[0] = i;
			break;
		}
	}	
	if (edge[0] == edge[1]) {
		edge[1] = n - 1;
		return false;
	}

	int height = a[edge[0]][0];
	edge[1] = edge[0];
	for (int j = edge[1]; j < n; j++) {
		if (a[j][1] == height) {
			edge[1] = j;
			break;
		}
	}
	if (edge[0] == edge[1]) return false;

	return true;
}

int calcArea(const int a[][2], const int edge[])
{
	int max = a[edge[0]][0];
	double area = 0;
	for (int i = edge[0]; i <= edge[1]; i++) {
		area += (-(a[i][0] - max));
		area += (-(a[i][1] -a[i][0]) / 2.0);
	}

	return (int)area;
}

