           climb=true;
       } else if(list[i].second<=list[i-1].second){
           if(climb == true) {
                peaks.push_back(list[i-1]);
           }
           climb=false;
        }
    }
}

int computeSurface(scenery& list,int begin, int end) {
    int surf=0;

    for(int i=begin;i<end;i++) {
        if(list[i].second<=list[end].second) {
            if(list[i].second==list[i+1].second) {
                surf += (list[end].second-list[i+1].second)*2;
            } else if(abs(list[end].second-list[i+1].second)>abs(list[end].second-list[i].second)){
                surf += (abs(list[end].second-list[i+1].second)*2-1);
            } else {
                surf += (abs(list[end].second-list[i].second)*2-1);
            }
        }
     // std::cout << surf << std::endl;
    }
    return surf/2;
}

int computeSurface2(scenery& list,int begin, int end) {
    int surf=0;

    for(int i=begin;i<end;i++) {
        if(list[i].second<=list[begin].second) {
            if(list[i].second==list[i+1].second) {
                surf += (list[begin].second-list[i+1].second)*2;
            } else if(abs(list[begin].second-list[i+1].second)>abs(list[begin].second-list[i].second)){
                surf += (abs(list[begin].second-list[i+1].second)*2-1);
            } else {
                surf += (abs(list[begin].second-list[i].second)*2-1);
            }
        }
      //std::cout << surf << std::endl;
    }
    return surf/2;
}


void highestPeaks(scenery& list, scenery& peaks, scenery::iterator& highestMount, surface& surfaceTot) {
    scenery::iterator secondHighestMount = std::max_element(highestMount+1,peaks.end(),mount);
    surfaceTot.push_back(computeSurface(list, highestMount->first, secondHighestMount->first));
    //std::cout << highestMount->first << ":" << secondHighestMount->first << "::surface" << surfaceTotal(surfaceTot) << std::endl;
    if(secondHighestMount!=peaks.end()-1 && highestMount!=peaks.end()-1) {
       // std::cout << secondHighestMount->first << ":" << peaks.end()->first << std::endl;
        return highestPeaks(list, peaks,secondHighestMount,surfaceTot);
    } 
}

