char s[20005];
int ans1[20005], ans2[20005], ans3[20005];
int ans[20005];
int main()
{
    gets(s);
    int len=strlen(s);
    for(int i=0; i<len; i++)
    {
        a[i].c=s[i];
        a[i].id=i;
    }
    stack<node> Q;
    int sum=0, j=0, res=0;
    for(int i=0; i<len; i++)
    {
        if(a[i].c=='\\' || a[i].c=='_') Q.push(a[i]);
        else
        {
            while(!Q.empty())
            {
                node temp;
                temp=Q.top();
                Q.pop();
                if(temp.c=='\\')
                {
                    sum+=a[i].id-temp.id;
                    break;
                }
            }
        }
        if(sum!=0 && (Q.empty() || i==len-1))
        {
            ans1[j++]=sum;
            res+=sum;
            sum=0;
        }
    }

    stack<node> T;
    sum=0, j=0, res=0;
    for(int i=len-1; i>=0; i--)
    {
        if(a[i].c=='/' || a[i].c=='_') T.push(a[i]);
        else
        {
            while(!T.empty())
            {
                node temp;
                temp=T.top();
                T.pop();
                if(temp.c=='/')
                {
                    sum+=temp.id-a[i].id;
                    break;
                }
            }
        }
        if(sum!=0 && (T.empty() || i==0))
        {
            ans2[j++]=sum;
            res+=sum;
            sum=0;
        }
    }

    for(int i=j-1, k=0; i>=0; i--, k++)
        ans3[k]=ans2[i];
    int k=0;
    for(int i=0, j=0; ans1[i]!=0 && ans3[j]!=0;)
    {
        if(ans1[i]==ans3[j])
        {
            ans[k++]=ans1[i];
            i++, j++;
        }
        else if(ans1[i]>ans3[j])
        {
            ans[k++]=ans3[j];

            ans1[i]-=ans3[j];
            j++;
        }
        else if(ans1[i]<ans3[j])
        {
            ans[k++]=ans1[i];

            ans3[j]-=ans1[i];
            i++;
        }

    }
    printf("%d\n", res);
    printf("%d", k);
    for(int i=0; i<k; i++)
        printf(" %d", ans[i]);
    printf("\n");
    return 0;
}

