int main(int argc, const char * argv[]) {
    string dia;
    cin >> dia;

    int len = (int)dia.size();
    dia = "/" + dia + "\\";

    cout << dia << endl; //

    int s = 0;
    int k = 0;
    vector <int> L;

    for(int i = 1; i <= len; ++i){
        if(dia[i] == '\\' && dia[i + 1] == '/'){
            k++;
            int l = i, r = i + 1;
            int pl = i, pr = i + 1;
            int d = 1;
            while(true){
                while(dia[l - 1] == '_'){
                    l--;
                }
                while(dia[r + 1] == '_'){
                    r++;
                }
                if(dia[l - 1] == '\\' || dia[r + 1] == '/'){
                    l--;
                    r++;
                    pl = l;
                    pr = r;
                    d++;
                    continue;
                }
                if(dia[l - 1] == '/' || dia[r + 1] == '\\'){
                    break;
                }
            }

            int nd = 0;
            int ss = 0;
            for(int i = pl; i <= pr; ++i){
                if(dia[i] == '\\'){
                    ss += 1 + nd;
                    nd++;
                }
                if(dia[i] == '_'){
                    ss += nd;
                }
                if(dia[i] == '/'){
                    nd--;
                    ss += nd;
                }
            }
            L.push_back(ss);
            s += ss;
            i = r + 1;
        }
