    cout << dia << endl;

    int l, r;
    int pl, pr;
    int a;
    vector <int> L;

    for(int i = 1; i < dia.size() - 1; ++i){
        l = i;
        while(dia[l] != '\\'){
            l++;
        }
        r = l + 1;

        while(dia[r] != '/'){
            r++;
            if(r >= dia.size()){
                break;
            }
        }
        if(r >= dia.size()){
            break;
        }

        pr = r;
        pl = r - 1;

        l = pl;
        r = pr;
        while(true){
            while(dia[pl - 1] == '_'){
                pl--;
            }

            while(dia[pr + 1] == '_'){
                pr++;
            }

            if(dia[pl - 1] == '\\' && dia[pr + 1] == '/'){
                pl--;
                pr++;
                continue;
            }

            if(dia[pl - 1] == '/' || dia[pr + 1] == '\\'){
                break;
            }
        }

        int s = 0;
        int d = 0;
        for(int j = pl; j <= pr; ++j){
            if(dia[j] == '\\'){
                d++;
                s += d;
            }
            if(dia[j] == '_'){
                s += d;
            }
            if(dia[j] == '/'){
                d--;
                s += d;
            }
