		case '\\':
			for (int j = s.size(); j > i; --j)
				if (c[i] <= c[j]) { d.push(true); break; }
			break;

		case '/':
			if (!d.empty())
				sum += 2 * d.size() - 1, d.pop();
			break;
		}

		if (d.empty() && sum != 0)
			area.push_back(sum), sum = 0;
	}

	cout << accumulate(area.begin(), area.end(), 0) << endl;
	cout << area.size();
