using namespace std;

class Pair {

public:
	char first;
	int second;

	Pair(char ch, int a) {
		first = ch;
		second = a;
	}
};

int targetsecond;

bool PairCom(const Pair& A) {
	return targetsecond == A.second;
}

int main()
{
	string ground;

	cin >> ground;

	//タイルの種類と高さ 最初のタイルが高さ0
	vector<Pair> data;

	for (int i = 0; i < ground.size(); i++) {

		int y = (i > 0) ? data[i - 1].second : 0;
		char beforetil = (i > 0) ? data[i - 1].first : '/';

		switch (ground[i])
		{
		case '\\':
			if (beforetil == '\\') {
				y--;
			}
			break;

		case '/':
			if (beforetil == '/' || beforetil == '_') {
				y++;
			}
			break;

		case '_':
			if (beforetil == '\\') {
				y--;
			}
		}
		//cout << ground[i] << " " << y << endl;
		data.push_back(Pair(ground[i], y));
	}

	vector<Pair>::iterator front, end;
	front = data.begin();
	end = data.end();

	vector<int> areas;
	float allarea = 0;

	while (front != end)
	{
		if (front->first != '\\') {
			advance(front, 1);
			continue;
		}

		targetsecond = front->second;

		//find_ifでpairをclass化 ==をoperator定義
		vector<Pair>::iterator target = find_if(front + 1, end, PairCom);

		//無い場合はイテレータを一つ進めてもう一度探索
		if (target == end) {
			advance(front, 1);
			continue;
		}

		float area = 0;

		for (; front <= target; front++) {
			//高さの差
			area += abs(front->second - target->second);

			//斜めのとき
			if (front->first != '_') {
				area += 0.5F;
			}
		}
		allarea += area;
		areas.push_back((int)area);
	}

	cout << (int)allarea << endl;
	cout << areas.size();

	for (int i = 0; i < areas.size(); i++) {
		cout << " " << areas[i];
	}

	cout << endl;

	return 0;
}

