    int sum=0, j=0, res=0;
    for(int i=0; i<len; i++)
    {
        if(a[i].c=='\\' || a[i].c=='_') Q.push(a[i]);
        else
        {
            while(!Q.empty())
            {
                node temp;
                temp=Q.top();
                Q.pop();
                if(temp.c=='\\')
                {
                    sum+=a[i].id-temp.id;
                    break;
                }
            }
        }
        if(sum!=0 && (Q.empty() || i==len-1))
        {
            ans1[j++]=sum;
            res+=sum;
            sum=0;
        }
    }

    stack<node> T;
    sum=0, j=0, res=0;
    for(int i=len-1; i>=0; i--)
    {
        if(a[i].c=='/' || a[i].c=='_') T.push(a[i]);
        else
        {
            while(!T.empty())
            {
                node temp;
                temp=T.top();
                T.pop();
                if(temp.c=='/')
                {
                    sum+=temp.id-a[i].id;
                    break;
                }
            }
        }
        if(sum!=0 && (T.empty() || i==0))
        {
            ans2[j++]=sum;
            res+=sum;
            sum=0;
        }
