            i++, j++;
        }
        else if(ans1[i]>ans3[j])
        {
            ans[k++]=ans3[j];

            ans1[i]-=ans3[j];
            j++;
        }
        else if(ans1[i]<ans3[j])
        {
            ans[k++]=ans1[i];

            ans3[j]-=ans1[i];
            i++;
        }

    }
    printf("%d\n", res);
    printf("%d", k);
    for(int i=0; i<k; i++)
        printf(" %d", ans[i]);
