		int st,end,area;
		st = edge.front();
		edge.pop();
		end = edge.front();
		edge.pop();

		area = 0;
		for(int i=st;i<end;++i){
			area += (abs(height[st]-height[i])+abs(height[st]-height[i+1]));
		}
		area /= 2;
		pondArea[n] = area;
		sumArea += area;
		++n;
	}

	cout<<sumArea<<endl;
	cout<<pondNum<<" ";
	for(int i=0;i<pondNum;++i){
		cout<<pondArea[i]<<(i!=pondNum-1?" ":"");
	}
	cout<<endl;

	return 0;
}

