  for(int i = 0; i < S.size(); i++){
    if(S[i] == '\\'){
      alt_near_ind[cur_alt] = i;
      alt_near_ind[cur_alt - 1] = i + 1;
      cur_alt --;
    } else if(S[i] == '/'){
      cur_alt ++;
