      else if (graph.slop(x, x+1) > 0) // '/'
      {
        area += depth - 0.5;
        depth--;
      }
      else // slop(x, x+1) // '_'
      {
        area += depth;
      }
    }
    DPRINTF("AREA %.1f (S %d   E %d)\n", area, itr->x0_, itr->x1_);
    areas.push_back((int)area);
    totalArea += (int)area;
  }

  // print messages
  cout << totalArea << endl;
  cout << intervals.size();
  for (int i = 0; i < areas.size(); i++) {
    cout << " " << areas[i];
  }
  cout << endl;
  return 0;
}

