class stack
{
	public:
	int s[10000];
	int t,temp;

public:
	void initialize();
	void push(int x);
	int pop();
};

void stack::initialize()
{
	t = 0;
}

void stack::push(int x)
{
	t++;
	s[t] = x;
}

int stack::pop()
{
	temp = s[t];
	t--;
	return temp;
}



