static const char DOWN = '\\';
static const char EVEN = '_';
static const char UP = '/';

struct AREA {
  int index;
  int area;
};

int main() {
  stack<int> input;
  vector<AREA> answer;

  string data;
  cin >> data;

  AREA current = {};
  int total = 0;
  int lastIndex = 0;
  for (int i = 0; i < data.length(); i++) {
    switch (data[i]) {
    case DOWN:
      input.push(i);
      break;
    case EVEN:
      break;
    case UP:
      if (input.empty()) {
        continue;
      }
      lastIndex = input.top();
      input.pop();
      current.area = i - lastIndex;
      current.index = lastIndex;
      total += current.area;
      while (answer.size() > 0 && answer.back().index > lastIndex) {
        current.area += answer.back().area;
        answer.pop_back();
      }
      answer.push_back(current);
      break;
    default:
      break;
    }
  }

  cout << total << endl;  
  cout << answer.size();
  for (AREA ans : answer) {
      cout << " " << ans.area;
  }  
  cout << endl;

  return 0;
}

