int main() {
  char area[20001];
  scanf("%s", area);
  int arealen = strlen(area);

  int start = 0, end = 0;
  int j = 0;
  vector<double> L;
  while (start < arealen) {
    int up = 0, down = 0;
    for (int i = start; i < arealen; i++) {
      if (area[i] == '\\') {
        if (!down && i != start) {
          start = i;
          up = 0, down = 1;
          continue;
        }
        down++;
      } else if (area[i] == '/') { up++; }

      if (up && up == down) {
        end = i;
        break;
      }

      if (i == arealen - 1 && up != down) {
        end = start;
      }
    }

    if (up != down) {
      start++;
      continue;
    }

    int height = 0;
    for (int i = start; i <= end; i++) {
      if (area[i] == '\\') {
        if (i == start) { L.push_back(0); }
        L[j] += height + 0.5;
        height++;
      } else if (area[i] == '/') {
        L[j] += height - 0.5;
        height--;
      } else if (area[i] == '_') {
        L[j] += height;
      }
    }

    if (start != end) { j++; }
    start = end + 1;
  }

  int A = 0;
  for (int i = 0; i < (int)L.size(); i++) { A += L[i]; }

  printf("%d\n", A);
  printf("%d ", L.size());
  for (int i = 0; i < (int)L.size(); i++) {
    if (i == L.size() - 1) { printf("%d\n", (int)L[i]); } else { printf("%d ", (int)L[i]); }
  }

  return 0;
}

