    TList RightAreaList = SimulateFlood(AltList, TopPeak, PeakList.end());

    int D = std::distance(PeakList.begin(), TopPeak);
    dprintf("D:%d\n", D);
    if(D == 0) return RightAreaList;
    TPeakList LeftPeakList(PeakList.begin(), TopPeak+1);
    std::reverse(LeftPeakList.begin(), LeftPeakList.end());
    TList LeftAreaList = SimulateFlood(AltList, LeftPeakList.begin(), LeftPeakList.end());
    std::reverse(LeftAreaList.begin(), LeftAreaList.end());

    LeftAreaList.insert(LeftAreaList.end(), RightAreaList.begin(), RightAreaList.end());
    return LeftAreaList;
}

int main()
{
    std::string Input;
    std::cin >> Input;

    TList AreaList = SimulateFlood(Input);
    int Sum = std::accumulate(AreaList.begin(), AreaList.end(), 0);
    std::cout << Sum << std::endl;
    std::cout << AreaList.size() << " ";
    Output(AreaList);
    return 0;
}

