class stack {
public:
    int a[20000];
    int top = -1;

    void push(int v) {
        top++;
        a[top] = v;
        return;
    }

    int pop() {
        top--;
        return a[top+1];
    }

    bool empty() {
        if(top == -1) return true;
        return false;
    }

    int check() {
        return top;
    }
};

class point {
public:
