string input;
stack< pair<int,int> > top;
stack< pair<int,int> > water;


float getArea(int start, int end){
    float area=0;

    int height=0;
    for(int i=start; i<end; i++){
        switch(input[i]){
            case'/':
                area+=-(height+0.5);
                height++;
                break;
            case'\\':
                area+=-(height-0.5);
				height--;
                break;
            case'_':
                area+=-height;
                ;
        }
    }

    return area;
}

int main() {
    ios_base::sync_with_stdio(0);

    cin >> input;

    int length = (int)(input.length());
