#include<iostream>
#include<stack>
using namespace std;

stack<int> order;
stack<pair<int, int> > area;

void pool(){
	while(1){
		pair<int ,int> x = area.top(); area.pop();
		if(area.empty()) {
			area.push(x);	
			break;
		}
		pair<int ,int> y = area.top();
		if(x.first > y.first){
			area.push(x);
			break;
		}
		else{
			int s = x.second + y.second;
			area.pop(); // pop(y)
			area.push(make_pair(x.first, s)); //new area
		}	
	}	
}

