using namespace std;

int main()
{
  vector<int> hts;
  hts.push_back(0);  // left endpoint is height 0
  int ht = 0;
  string map;
  cin >> map;
  for(char c : map) {
    if (c == '/') hts.push_back(++ht);
    else if (c == '\\') hts.push_back(--ht);
    else if (c == '_') hts.push_back(ht);
  }

  vector<int> lmaxes = hts;
  int lmax=hts.front();
  for (size_t i=0; i<lmaxes.size(); ++i) {
    lmax = max(lmax, hts[i]);
    lmaxes[i] = lmax;
  }

  vector<int> rmaxes = hts;
  int rmax=hts.back();
  for (int i=(int)lmaxes.size()-1; i>=0; --i) {
    rmax = max(rmax, hts[i]);
    rmaxes[i] = rmax;
  }

//  cout << "Heights: ";
//  for (auto hi = hts.begin(); hi!=hts.end(); ++hi) cout << *hi << " ";
//  cout << endl;

  vector<double> vols;
  double current_vol=0;
  bool flood=false;
  int fstart;
  for(size_t i=0; i<hts.size()-1; ++i) {
    if(min(lmaxes[i],rmaxes[i+1])>min(hts[i], hts[i+1])) {
      if (not flood) {
        flood = true;
        fstart = hts[i];
      }
      if(hts[i]!=hts[i+1]) current_vol += 0.5;
      current_vol += min(lmaxes[i], rmaxes[i+1]) - max(hts[i], hts[i+1]);
    } 
    if (hts[i+1]==fstart and current_vol) {
      vols.push_back(current_vol);
      current_vol=0;
      flood=false;
    }
  }
  if (current_vol) vols.push_back(current_vol);

  cout << setprecision(0) << fixed << endl;
  cout << accumulate(vols.begin(), vols.end(), 0) << endl;  // total volume
  cout << vols.size(); // number of floods
  for (auto v : vols) cout << " " << v;  // print volume of each flood
}

