                     }
                     break;
                 case '/':
                     area += 0.5 + depth;
                     depth += 1;
                     break;
                 case '_':
                     if (depth > 0)
                         area += depth;

                     break;
                 default:
                     break;
             }
         }
     END:
         return area;
     }
}


int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    string line;
    getline(cin, line);

    vector<double> pools;
    int depth = 0;


    vector<char> stack;
    char prev = 0;

    for(const char& c : line) {
        switch(c) {
            case '\\':
                if (prev == '_') {
                    pools.push_back(calculate_area(stack));
                    stack.clear();
                    depth = 0;
                }
                stack.push_back('\\');
                depth += 1;
                break;
            case '/':
                stack.push_back('/');
                if (depth > 0) {
                    depth -= 1;
                    if (depth == 0) {
                        pools.push_back(calculate_area(stack));
                        stack.clear();
                    }
                }
                break;
            case '_':
                stack.push_back('_');
                break;
            default:
                break;
        }
        prev = c;
    }
    if (depth > 0) {
        double area = calculate_area(stack);
        if (area > 0)
            pools.push_back(area);
    }

    double total = 0;
    for(const auto& p : pools) { total += p; };

    cout << total << endl;
    cout << pools.size() << " ";
    print_vector(pools);
    return 0;
}

