int solve(vector<char> que){
  int h=0;
  int f[que.size()];
  f[0]=1;
  for(int i=1;i<que.size();i++){
    if(que[i]=='\\') f[i]=f[i-1]+1;
    else if(que[i]=='/' && que[i-1]=='/') f[i]=f[i-1]-1;
    else if(que[i]=='/' && que[i-1]=='\\') f[i]=f[i-1];
    else if(que[i]=='_' && que[i-1]=='/') f[i]=2*(f[i-1]-1);
    else if(que[i]=='_' && que[i-1]=='\\') f[i]=2*f[i-1];
  }

  int yu=0;
  for(int i=0;i<que.size();i++)
    yu+=f[i]/2;

  return yu;
}


