typedef struct D{int h,p,s;}D;

#define ML 20005
char S[ML];
int i,A,nh=0,np,r=0,k,R[ML],mh=0;
stack<D>ST;
int main()
{
	gets(S);
	for(i=np=0;S[i];i++)
	{
		if(S[i]=='\\')
		{
			D tmp={nh--,i,0};
			mh=max(mh,tmp.h);
			ST.push(tmp);
		}
		else if(S[i]=='/')
		{
			int ts=0;
