void solve() {
    std::stack<int64_t> S1;
    std::stack<std::pair<int64_t, int64_t> > S2;
    char ch;
    int64_t sum = 0;
    for (int64_t i = 0; std::cin >> ch; i++) {
        if (ch == '\\')
            S1.push(i);
        else if (ch == '/' && S1.size() > 0) {
            int64_t j = S1.top();
            S1.pop();
            sum += i - j;
            int64_t a = i - j;
            while (S2.size() > 0 && S2.top().first > j) {
                a += S2.top().second;
                S2.pop();
            }
            S2.push(std::make_pair(j, a));
        }
    }

    std::vector<int64_t> ans;
    while (S2.size() > 0) {
        ans.push_back(S2.top().second);
        S2.pop();
    }
    std::reverse(ans.begin(), ans.end());

    std::cout << sum << std::endl;
    std::cout << ans.size();
    for (int64_t i = 0; i < ans.size(); i++) {
        std::cout << " " << ans[i];
    }
    std::cout << std::endl;

    return;
}

int main() {
    std::cin.tie(0);
    std::ios_base::sync_with_stdio(false);
    std::cout << std::fixed << std::setprecision(15);
    solve();
}

