int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	string s;
    cin >> s;
    stack<int> field;
    stack<pair<int, int>> pond;
    int count = 0;
    for(auto&& c : s){
        if(c == '\\'){
            field.push(count);
        }else if(!field.empty() && c == '/'){
            int f_top = field.top();
            field.pop();
            int a = count - f_top;
            while(!pond.empty() && pond.top().first > f_top){
                a += pond.top().second;
                pond.pop();
            }
            pond.push(make_pair(f_top, a));
        }
        ++count;
    }
    list<int> sq;
    while(!pond.empty()){
        sq.emplace_front(pond.top().second);
        pond.pop();
    }
    cout << accumulate(sq.begin(), sq.end(), 0) << "\n";
    cout << sq.size();
    for(auto i = sq.begin(), end = sq.end(); i != end; ++i){
        cout << " ";
        cout << *i;
    }
    cout << "\n";
    return 0;
}

