#define cube(x) (x) * (x) * (x)

const int INF = 1e9;

using namespace std;

stack<tuple<int, int, int> > area;
stack<int> res;
stack<int> downs;

int integrate(int i, int j){
    int value = j-i;
    while(!area.empty() && get<1>(area.top()) >= i && get<2>(area.top()) <= j){
        value += get<0>(area.top());
        area.pop();
    }
    return value;
}

