using namespace std;

class cFlood
{
	string tb;
	int A;
	int k;
	vector<int> vL;
	vector<int> vLrev;

	void output();

public:
	cFlood(){}
	cFlood(const string &c)
	{
		tb = c;
	}

	void calcflood();
};

void cFlood::calcflood()
{
	string::iterator it = tb.begin();

	int hstd = 0;
	vector<int> vheight;

	int th = hstd;
	vheight.push_back(th);
	int stdIndex = 0;
	for (int i = 0; i < tb.size(); ++i)
	{
		if (tb[i] == '\\')
		{
			th -= 1;
		}
		else if (tb[i] == '_')
		{
			th = th;
		}
		else if (tb[i] == '/')
		{
			th += 1;
		}

		vheight.push_back(th);
	}

	int tsum;
	for (int i = 1; i < vheight.size(); ++i)
	{
		if (hstd == vheight[i])
		{
			tsum = 0;

			for (int j = stdIndex; j <= i; ++j)
			{
				tsum += hstd - vheight[j];
			}
			if (tsum)
				vL.push_back(tsum);
		}

		if (hstd <= vheight[i])
		{
			hstd = vheight[i];
			stdIndex = i;
		}
	}
	int hstd_rev = vheight[vheight.size() - 1];
	stdIndex = vheight.size() - 1;
	for (int i = vheight.size() - 2; hstd != vheight[i]; --i)
	{
		if (hstd_rev == vheight[i])
		{
			tsum = 0;

			for (int j = stdIndex; j >= i; --j)
			{
				tsum += hstd_rev - vheight[j];
			}
			if (tsum)
				vLrev.push_back(tsum);
		}
		if (hstd_rev <= vheight[i])
		{
			hstd_rev = vheight[i];
			stdIndex = i;
		}
	}

	for (int i = vLrev.size() - 1; i >= 0 ; --i)
	{
		vL.push_back(vLrev[i]);
	}

	A = accumulate(vL.begin(), vL.end(), 0);

	output();
}

void cFlood::output()
{
	ostringstream oss;
	oss << vL.size() << " ";
	for (int i = 0; i < vL.size(); ++i)
	{
		oss << vL[i] << " ";
	}
	string ans(oss.str());
	ans.rfind(" ");
	ans.replace(ans.rfind(" "),ans.size(), "");
	cout << A << endl;
	cout << ans << endl;
}

