#include <vector>
#define INT_MIN -200000
using namespace std;

int nextHeighest(int *heightArray,int n,int index){		//index 以降で最も高い標高を返す(indexは含まない)
	int maxHeight = INT_MIN;
	for(int i = index + 1; i < n; i++){
		if( heightArray[i] > maxHeight) maxHeight = heightArray[i];
	}
	return maxHeight;
}

double pondArea(int *heightArray,int n,int start,int goal){		//start,goal の標高を基準にして、池の面積を求める
	double waterSurface = heightArray[start];
	double area = 0;
	for(int i = start ; i < goal; i++){
		area += waterSurface - ((double)(heightArray[i]) + (double)(heightArray[i+1]))/2;
	}
	return area;
}

int nextHeightIndex(int *heightArray,int n,int index,int height){	//次の標高がheightになる場所のindexを返す
	for(int i = index + 1; i < n; i++){
		if(heightArray[i] == height) return i;
	}
	return -1;
}

int nextStartIndex(int *heightArray,int n,int index){
	if(index == n) return n;  //右端の場合
	int currentHeight = heightArray[index];
	if(currentHeight > heightArray[index + 1] && nextHeightIndex(heightArray,n,index,currentHeight) != -1){
		return index;
	}else{
		return nextStartIndex(heightArray,n,index + 1);
	}
}


int main()
{
	string str;
	getline(cin,str);
	int n = str.size();
	int *heightArray = new int[n+1];
	heightArray[0] = 0;
	for(int i = 1; i <= n; i++){
		if(str[i-1] == '\\'){
			heightArray[i] = heightArray[i-1] - 1;
		}else if(str[i-1] == '/'){
			heightArray[i] = heightArray[i-1] + 1;
		}else if(str[i-1] == '_'){
			heightArray[i] = heightArray[i-1];
		}
	}
	vector<double> pondAreaVector;
	double totalPondArea = 0;
	int i = nextStartIndex(heightArray,n+1,0);
	while(i <= n ){
		int currentHeight = heightArray[i];
		int nextGoalIndex = nextHeightIndex(heightArray,n+1,i,currentHeight);
		double localPondArea = pondArea(heightArray,n+1,i,nextGoalIndex);
		totalPondArea += localPondArea;
		pondAreaVector.push_back(localPondArea);
		i = nextStartIndex(heightArray,n+1,nextGoalIndex);
	}
	cout<<(int)totalPondArea<<endl;
	cout<<pondAreaVector.size();
	for(int i = 0; i < pondAreaVector.size(); i++){
		cout <<" "<<(int)pondAreaVector[i];
	}
	cout << endl;

	return 0;
}

