        while (S[i]=='/' || S[i]=='_') {
            if(S[i]=='/'){
                check[hight[i]]--;
                st++;
                i++;
            }else if(S[i]=='_'){
                i++;
                check[hight[i]]--;
            }
        }
        if (i>S.length()) {
            break;
        }
        while (check[st]<=1) {
            i++;
            st--;
            while (S[i]=='_') {
                check[hight[i]]--;
                i++;
            }
            if (i>S.length()) {
                break;
            }
        }
        if (i>S.length()) {
            break;
        }
        int ff=0;
        double count=0;
        check[hight[i]]--;
        for (int j=i+1; j<=S.length(); j++) {
            if (hight[j] == st and ff) {
                if (count == 0) {
                    break;
                }
