                Q.push_back(count);
                ans += count;
                i = j-1;
                //cout << j<<"|"<<count<<endl;
                count =0;
                break;
            }else{
                double hoge = (2*st-hight[j-1]-hight[j])/2.0;
                count += hoge;
                check[hight[j]]--;
                ff=1;
                //cout << "|"<<count<<"("<<hoge<<")" << "|"<<endl;
            }
        }
        i++;
    }
