                st.push_back(make_pair(s[i], i));
                break;
            case '_':
                current += depth * 2;
                break;
            case '/':
                depth -= 1;
                current += depth * 2 + 1;
                if (st.empty()) {
                    depth = 0;
                    current = 0;
                }
                else {
                    st.pop_back();
                    if (st.empty()) {
                        v.push_back(current / 2);
                        depth = 0;
                        current = 0;
                    }
                }
                break;
            }
            // printf("stacksize: %ld, depth: %d, current: %d\n", st.size(),
            // depth,
            //       current);
        }
        if (st.empty()) {
            return make_pair(v, -2);
        }
        else {
            return make_pair(v, st[0].second);
        }
    };
    vector<int> v;
    int start = 0;
    do {
        auto r = f(start);
        v.insert(end(v), begin(r.first), end(r.first));
        start = r.second + 1;
    } while (start != -1);
    //    for (auto&& i : st) {
    //        printf("%c %d ", i.first, i.second);
    //    }
    // putchar('\n');
    // putchar('\n');
    printf("%d\n", accumulate(begin(v), end(v), 0));
    printf("%ld ", v.size());
    for (size_t i = 0; i < v.size(); ++i) {
        if (i != v.size() - 1) {
            printf("%d ", v[i]);
        }
        else {
            printf("%d\n", v[i]);
        }
    }
}

