using namespace std;

int Calc(char *pArea, int *pSize, int *pCnt)
{
    stack<int> point;
    int tmp;
    int tmp2;
    int cnt = 0;
    int ret = 0;

    *pCnt = 0;
    tmp2  = 0;

    while (pArea[cnt] != '\0') {
        switch (pArea[cnt]) {
        case '\\' :
            point.push(cnt);
            break;
        case '/' :
            if (point.empty() == false) {
                tmp = point.top();
                point.pop();
                tmp = cnt - tmp;
                tmp2 += tmp;
                ret += tmp;
            }
            break;
        default :
            if (tmp2 > 0) {
                pSize[*pCnt] = tmp2;
                ++(*pCnt);
                tmp2 = 0;
            }
            break;
        }
        ++cnt;
    }

    if (tmp2 > 0) {
        pSize[*pCnt] = tmp2;
        ++(*pCnt);
    }

    return ret;
}

int main(void)
{
    char input[20000];
    int  hoge[100];
    int  cnt;
    int  ret;

    scanf("%s", input);

    ret = Calc(input, hoge, &cnt);

    printf("%d\n%d", ret, cnt);
    for (int i = 0; i < cnt; i++) {
        printf(" %d", hoge[i]);
    }
    printf("\n");

    return 0;
}

