	for(int i=0;i<str.size();i++){
		if(str[i]=='\\'){
			st.push(i);
		}else if(str[i]=='/' && !st.empty()){
				idx = st.top();
				sum += i - idx;
				area = i-idx;
				st.pop();

			while(!s2.empty() && s2.top().first > idx){
				area += s2.top().second; s2.pop();
			}
			s2.push(make_pair(idx,area));
		}
	}
	return sum;
}

