            ll a = i - j;
            while (!s2.empty() && j < s2.top().first) {
                a += s2.top().second;
                s2.pop();
            }

            s2.push(P(j, a));
        }
    }

    vector<ll> ans;
    while (!s2.empty()) {
        ans.push_back(s2.top().second);
        s2.pop();
    }
    reverse(ans.begin(), ans.end());

    cout << sum << endl;
    if(ans.size() == 0) {
        cout << 0 << endl;
        return 0;
    }
    cout << ans.size() << ' ';
    print_line(ans);
}

