using namespace std;

int main(void) {
	string str;
	cin >> str;
	int now = 0;
	int len = str.length();
	vector<int> h(len);
	for (int i = 0; i < len; ++i) {
		if (str[i] == '\\') {
			--now;
		}
		else if (str[i] == '/') {
			++now;
		}
		h[i] = now;
	}

	vector<int> a(len);
	a[len-1] = h[len-1];
	for (int i = 1; i < len; ++i) {
		a[len-i-1] = max(a[len-i],h[len-i-1]);
	}

	int nop = 0;
	int sum = 0;
	int ind = 0;
	queue<int> q;
	bool end = false;
	while (!end) {
		if (str[ind] == '\\') {
			int hs = h[ind]+1;
			if (hs <= a[ind]) {
				int na = 0;
				bool find = false;
				for (int i = ind; !find && i < len; ++i) {
					na += hs - h[i];
					if (str[i] == '\\') {
						--na;
					}
					else if (str[i] == '/') {
						++na;
						if (hs == h[i]) {
							find = true;
						}
					}
					++ind;
				}
				++nop;
				sum += na;
				q.push(na);
				--ind;
			}
		}
		++ind;
		if (ind >= len) {
			end = true;
		}
	}
	cout << sum << endl;
	cout << nop;
	while (!q.empty()) {
		cout << " " << q.front();
		q.pop();
	}
	cout << endl;
	return 0;
}

