void get_result(stack< pair<int, int> > *st) {
	int i, st_size, num = 0, area = 0;
	int empty_flag  = 0;
	int area_each_puddle[MAX_STR_LEN / 2] = {0};

	st_size = st->size();
	for (i = 0; i < st_size && empty_flag != 1; i++) {
		while (st->size() > 0) {
			if (st->top().second == 0) {
				st->pop();
				if (st->size() == 0) {
					empty_flag = 1;
					break;
				}
			}
			else {
				break;
			}
		}

		if (empty_flag == 1) {
			break;
		}
		else {
			area_each_puddle[i] = st->top().second;
			area += area_each_puddle[i];
			num++;
			st->pop();
			if (st->size() == 0) {
				empty_flag = 1;
				break;
			}
		}
	}

	//print result
	cout << area << endl;
	if (area == 0) {
		cout << 0 << endl;
	}
	else {
		// print num of puddle
		cout << num;

		//print each area of puddles
		for (i = num - 1; i >= 0; i--)
			cout << ' ' << area_each_puddle[i];

		cout << endl;
	}
}

