            surfaces.push_back(leftSurfaces[g]);
        }
    }
    if(highestMount!=peaks.end()-1) {
        highestPeaks(list,peaks,highestMount,surfaces);
    }
    std::cout << surfaceTotal(surfaces) << std::endl;
    std::cout << surfaces.size();
    print_surface(surfaces);
    return 0;
}

