struct slope {
  int type;
  int height;
};

int main() {
  string input;
  cin >> input;
  int n = input.length();

  list<slope> shape;
  slope tmp;
  int current_height = 0;
  for (int i = 0; i < n; i++) {
    switch (input[i]) {
    case DOWN:
      tmp.type = DOWN;
      tmp.height = current_height--;
      break;
    case UP:
      tmp.type = UP;
      tmp.height = ++current_height;
      break;
    case FLAT:
      tmp.type = FLAT;
      tmp.height = current_height;
      break;
    }
    shape.push_back(tmp);
  }

  //for (list<slope>::iterator i = shape.begin(); i != shape.end(); i++) {
  //  cout << i->type << " " << i->height << endl;
  //}

  list<float> area_all;
  float area_total = 0;
  while (1) {
    if (shape.size() == 0) {
      break;
    }

    if (shape.begin()->type == UP || shape.begin()->type == FLAT) {
      shape.pop_front();
      continue;
    }

    float area = 0.5;
    int start_height = shape.begin()->height;
    int delete_num = 0;
    shape.pop_front();
    for (list<slope>::iterator i = shape.begin(); i != shape.end(); i++) {
      delete_num++;
      int current_height = i->height - start_height;
      switch (i->type) {
      case DOWN:
        area += abs(current_height) + 0.5;
        break;
      case UP:
        area += abs(current_height) + 0.5;
        break;
      case FLAT:
        area += abs(current_height);
        break;
      }
      //cout << current_height << " " << start_height << endl;
      if (i->height == start_height) {
        for (int j = 0; j < delete_num; j++) {
          shape.pop_front();
        }
        area_all.push_back(area);
        area_total += area;
        break;
      }
    }

    //cout << shape.size() << endl;
  }

  //cout << area_all.size() << endl;
  cout << int(area_total) << endl;
  cout << area_all.size();
  for (list<float>::iterator i = area_all.begin(); i != area_all.end(); i++) {
    cout << " " << int(*i);
  }
  cout << endl;

  return 0;
}

#include <iostream>
#include <sstream>
#include <stack>
using namespace std;

int main()
{
  string str;
  cin >> str;

  stack<int> bs_index;          // Index of backslash(\)
  stack<pair<int, int>> puddle; // (index, area)

  int total_area = 0;
  for (int i = 0; i < (int)str.length(); ++i)
  {
    switch (str[i])
    {
      case '\\':
      {
        bs_index.push(i);
        break;
      }
      case '/':
      {
        if (!bs_index.empty()) // Corresponding backslach(\) is found
        {
          int j = bs_index.top();
          int area = i - j;
          bs_index.pop();

          while (!puddle.empty() && j < puddle.top().first) // Integratable puddle is found
          {
            area += puddle.top().second; // Integrate the puddle
            puddle.pop();
          }

          puddle.push(pair<int, int>(j, area)); // Add new puddle
          total_area += (i - j);                 // Add to total area
        }
        break;
      }
      default:
        break;
    }
  }

  cout << total_area << endl;

  int num_of_puddles = puddle.size();

  string result;
  for (int i = 0; i < num_of_puddles; ++i)
  {
    result = ' ' + to_string(puddle.top().second) + result;
    puddle.pop();
  }
  cout << num_of_puddles << result << endl;

  return 0;
}

