    if (form.empty()) return 0;
    int rain = 0;
    while (form.top() != '/') {
        form.pop();
        if (form.empty()) return 0;
    }
    form.pop();
    int cnt = 1;
    int rain_tmp = 0;
    while (form.top() != '\\') {
        if (form.top() == '/') {
            rain += calc();
        }
        rain_tmp++;
        form.pop();
        if (form.empty()) return rain;
        cnt++;
    }
   form.pop();
    cnt++;
    rain += rain_tmp + 1;
    for (int i = 0; i < cnt; i++) {
        form.push('_');
    }
    return rain;
}


int main()
{
    char c;
    while (cin >> c) {
        form.push(c);
    }
    int total_rain = 0;
    stack<int> tamari;
