int main() {
  string area;
  cin >> area;


  int start = 0, end = 0;
  int j = 0;
  vector<double> water_area;
  while(start + 1 < (int)area.size()) {
    for(int i = start; i < (int)area.size(); i++) {
      int up = 0, down = 0;
      for(int j = i; j < (int)area.size(); j++) {
        if(area[j] == '_') {
          if(j == i) {
            break;
          } else if(down == 0) {
            continue;
          }
        }

        if(area[j] == '\\') {
          down++;
        } else if(area[j] == '/') {
          if(down == 0) { break; }
          up++;
        }

        if(up != 0 && up == down) {
          end = j;
          break;
        }
      }

      if(up != 0 && up == down) {
        start = i;
        break;
      }
    }

    int height = 0;
    for(int i = start; i <= end; i++) {
      if(area[i] == '\\') {
        if(i == start) { water_area.push_back(0); }
        water_area[j] += height + 0.5;
        height++;
      } else if(area[i] == '/') {
        water_area[j] += height - 0.5;
        height--;
      } else if(area[i] == '_') {
        water_area[j] += height;
      }
    }
    start = end + 1;
    j++;
  }

  int total_area = 0;
  for(int i = 0; i < (int)water_area.size(); i++) { total_area += water_area[i]; }

  cout << total_area << endl;
  cout << water_area.size() << " ";
  for(int i = 0; i < (int)water_area.size(); i++) {
    if(i == water_area.size() - 1) { cout << water_area[i] << endl; } else { cout << water_area[i] << " "; }
  }

  return 0;
}

