#include <stack>
#include <cstdio>

using namespace std;

static const char DOWN = '\\';
static const char EVEN = '_';
static const char UP = '/';

struct AREA {
  int index;
  int area;
};

int main() {
  stack<int> input;
  vector<AREA> answer;

  int total = 0;
  string data;
  cin >> data;
  AREA current = {};
  int lastIndex = 0;
  for (int i = 0; i < data.length(); i++) {
    switch (data[i]) {
    case DOWN:
      input.push(i);
      break;
    case EVEN:
      break;
    case UP:
      if (input.empty()) {
        continue;
      }
      lastIndex = input.top();
      input.pop();
      current.area = i - lastIndex;
      current.index = lastIndex;
      total += current.area;
      while (answer.size() > 0 && answer[answer.size() - 1].index > lastIndex) {
        current.area += answer[answer.size() - 1].area;
        answer.pop_back();
      }
      answer.push_back(current);
      break;
    default:
      break;
    }
  }

  cout << total << endl;  
  cout << answer.size() << " ";
  bool first = true;
  for (AREA ans : answer) {
    if (first) {
      cout << ans.area;
      first = false;
    } else {
      cout << " " << ans.area;
    }
  }  
  cout << endl;

  return 0;
}

#include <iostream>
#include <vector>

using namespace std;

namespace {
    template<typename T>
    void print_vector(vector<T> &v) {
        for (auto it = v.begin(); it != v.end(); it++) {
            cout << *it;
            if (it + 1 != v.end())
                cout << " ";
        }
        cout << endl;
    }

     double calculate_area(vector<char>& stack) {
         double area = 0;
         int depth = 0;
         while(!stack.empty()) {
             const char c = stack.back();
             stack.pop_back();
             switch(c) {
                 case '\\':
                     if (depth > 0) {
                         area += 0.5 + depth - 1;
                         depth -= 1;

                         if (depth == 0) {
                             break;
                         }
                     }
                     break;
                 case '/':
                     area += 0.5 + depth;
                     depth += 1;
                     break;
                 case '_':
                     if (depth > 0)
                         area += depth;

                     break;
                 default:
                     break;
             }
         }
         return area;
     }
}


int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    string line;
    getline(cin, line);

    vector<double> pools;
    int depth = 0;


    vector<char> stack;
    char prev;

    for(const char& c : line) {
        switch(c) {
            case '\\':
                if (prev == '_') {
                    pools.push_back(calculate_area(stack));
                    stack.clear();
                    depth = 0;
                }
                stack.push_back('\\');
                depth += 1;
                break;
            case '/':
                stack.push_back('/');
                if (depth > 0) {
                    depth -= 1;
                    if (depth == 0) {
                        pools.push_back(calculate_area(stack));
                        stack.clear();
                    }
                }
                break;
            case '_':
                stack.push_back('/');
                break;
            default:
                break;
        }
        prev = c;
    }

    double total = 0;
    for(const auto& p : pools) { total += p; };

    cout << total << endl;
    cout << pools.size() << " ";
    print_vector(pools);
    return 0;
}

