bool searchEdge(const int a[][2], int n, int edge[])
{	
	edge[0] = edge[1] = edge[1] + 1;
	for (int i = edge[0]; i < n; i++) {
		if (a[i][1] - a[i][0] == -1) {
			edge[0] = i;
			break;
		}
	}	
	if (edge[0] == edge[1]) {
		edge[1] = n - 1;
		return false;
	}

	int height = a[edge[0]][0];
	edge[1] = edge[0];
	for (int j = edge[1]; j < n; j++) {
		if (a[j][1] == height) {
			edge[1] = j;
			break;
		}
	}
	if (edge[0] == edge[1]) return false;

	return true;
}

int calcArea(const int a[][2], const int edge[])
{
	int max = a[edge[0]][0];
	int area = 0;
	for (int i = edge[0]; i <= edge[1]; i++) {
		area += (-(a[i][0] - max));
		area += (-(a[i][1] -a[i][0]) / 2);
	}

	return area;
}

#include <cstdio>
#include <stack>
#include <list>
using namespace std;

typedef struct{
    int left_edge;
    int area;
}part;

list<part> calc(list<part> parts){
    int num = parts.size() - 1;
    part tmp;
    parts.push_front(parts.back());
    parts.pop_back();
    for(int i=0;i<num;i++){
        if(parts.back().left_edge < parts.front().left_edge)
            parts.push_front(parts.back());
        else
            parts.front().area += parts.back().area;
        parts.pop_back();
    }
    return parts;
}

int main(){
    list<part> parts;
    stack<int> s;
    char str[20001];
    int i=0;
    int sum=0;
    part tmp;

    scanf("%s",str);

    while(str[i]!='\0'){
        switch(str[i]){
        case '\\':
            s.push(i);
            break;
        case '_':
            break;
        case '/':
            if(s.empty())
                break;
            tmp.left_edge = s.top();
            tmp.area = i - tmp.left_edge;
            sum += tmp.area;
            parts.push_back(tmp);
            s.pop();
            break;
        default:
            return -1;
        }
        i++;
    }

    printf("%d\n",sum);

    parts = calc(parts);

    printf("%lu",parts.size());

    while(parts.size()){
        printf(" %d", parts.front().area);
        parts.pop_front();
    }

    printf("\n");

    return 0;
}

