#include<stdio.h>

#define MAX 1000


int EACH_AREA_Calculation(int e_area[], int e_e_idx)//各水溜まりの面積を求める
{
	int e_number = 0,
		each_area = 0,
		w_cnt = 0;

	while (e_area[e_number] != 0) {
		each_area += e_area[e_number];
		e_number++;
	}

	while (e_area[w_cnt] != 0) {
		e_area[w_cnt] = 0;
		w_cnt++;
	}


	return each_area;
}

int EACH_AREA_Decision(int snd_stk[], int each_area[], int s_idx)//各水溜まりの面積を求めた時点で、それ以前にその水溜まりより高い水溜まりがないかを確認する。
{
	int share_count = 0,
		number = 0,
		pool_number = 0,
		pool_count = 0,
		f_cnt = 0,
		TOP = 0;

	while (1) {
		pool_number++;
		if (each_area[pool_number] == 0) {
			pool_number--;
			break;
		}
	}

	share_count = 1;
	s_idx -= 1;

	while ((pool_number - share_count) != -1) { 

		if (snd_stk[s_idx] < snd_stk[s_idx - share_count]) {//判定した水溜まりとそれ以前の水溜まりが同じ以下の高さであれば（※数値上では高ければ）その間にある水溜まりを結合する。
			each_area[pool_number - share_count] += each_area[pool_number - pool_count];//判定されたほうに入れていく
			each_area[pool_number] = 0;//初期化
			snd_stk[s_idx] = 0;//snd_stk[]の結合した部分を初期化
		}
		else if (snd_stk[s_idx] >= snd_stk[s_idx - share_count]) {//
			break;
		}

		share_count++;//判定したところから結合した部分の終わりまで
		pool_count++;
	}

	return share_count - 1;
}


int main(void)
{

	int fst_stk[MAX] = { 0 }, f_idx = 0,
		snd_stk[MAX] = { 0 }, s_idx = 0,
		each_area[MAX] = { 0 }, e_idx = 0,
		ALL_area = 0;

	int i_idx = 0,
		d_count = 0,
		f_cnt,
		distance = 0;


	char input[MAX];

	fgets(input, MAX, stdin);


	while (input[i_idx] != '\n') {

		switch (input[i_idx]) {
		case '\\':
			if (s_idx == 0) {
				snd_stk[s_idx] = 1;
				s_idx++;
			}
			d_count++;
			fst_stk[f_idx] = d_count;
			f_idx++;
			i_idx++;
			break;


		case '/':
			if (d_count == 0) {
				i_idx++;
				break;
			}
			fst_stk[f_idx] = d_count;

			for (f_cnt = f_idx - 1; f_cnt >= 0; f_cnt--) {//Ｘ軸の面積を求める
				distance++;
				if (fst_stk[f_idx] == fst_stk[f_cnt]) {
					each_area[e_idx] = distance;
					e_idx++;
					snd_stk[s_idx] = d_count;//水溜まりの深さを一時的に格納
					s_idx++;
					distance = 0;//次に使うために初期化

					f_cnt = EACH_AREA_Decision(snd_stk, each_area, s_idx);//水溜まりを結合していた場合、帳尻を合わせる
					s_idx -= f_cnt;
					e_idx -= f_cnt;//結合した分の帳尻を合わせる
					break;
				}
			}

			d_count--;
			f_idx++;
			i_idx++;

			break;


		case '_':
			if (d_count == 0) {
				i_idx++;
				break;
			}
			fst_stk[f_idx] = -1;
			f_idx++;
			i_idx++;
			break;

		}
	}

	for (f_cnt = 0; f_cnt < e_idx; f_cnt++) {
		ALL_area += each_area[f_cnt];
	}

	printf("%d\n", ALL_area);
	printf("%d", e_idx);

	for (f_cnt = 0; f_cnt < e_idx; f_cnt++) {
		printf(" %d", each_area[f_cnt]);
	}
	putchar('\n');

	return 0;

}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stack>
#include <queue>
using namespace std;

stack<int> S;
queue<char> Q;
stack<char> Slast;

void calc_area(int *total, bool last) {
    int sum = 0;
    int depth = 0;
    while (!S.empty()) {
        bool end = false;
        switch (S.top()) {
            case '\\':
                if (depth > 0) {
                    depth--;
                    sum += depth * 2 + 1;
                    if (depth == 0) {
                        if (last) {
                            Slast.push(sum);
                        }
                        else {
                            Q.push(sum);
                        }
//                        printf("Push sum %d\n", sum);
                        *total += sum;
                        sum = 0;
                    }
                }
                break;
            case '/':
                depth++;
                sum += depth * 2 - 1;
                break;
            case '_':
                if (depth > 0) {
                    sum += depth * 2;
                }
                break;
        }
        S.pop();
//        printf("Depth %d sum %d\n", depth, sum);
    }

}

int main (void) {

    char c;
    int depth = 0;
    int total = 0;
    int sum = 0;

    while (scanf("%c", &c) != EOF) {
        switch (c) {
            case '/':
                if (depth > 0) {
                    depth--;
                    S.push(c);
                    if (depth == 0) {
                        calc_area(&total, false);
                    }
                }
                break;
            case '\\':
                depth++;
                S.push(c);
                break;
            case '_':
                if (depth > 0) {
                    S.push(c);
                }
                break;
            case '\n':
                if (depth != 0) {
                    calc_area(&total, true);
                }
                printf("%d\n", total/2);
                printf("%d", int(Q.size()));
                while (!Q.empty()) {
                    printf(" %d", Q.front()/2);
                    Q.pop();
                }
                while (!Slast.empty()) {
                    printf(" %d", Slast.top()/2);
                    Slast.pop();
                }
                printf("\n");
                return 0;
            default:
                printf("Invalid charactor!!\n");
                return 1;
        }
//        printf("depth %d\n", depth);
    }
}

