#define FOR(i, a, b) for (int i = (a); i < (b); ++i)
#define REP(i, n) for (int i = 0; i < (n); ++i)

using namespace std;

int main()
{
    string s;
    cin >> s;

    stack<int> S1;
    stack<pair<int, int> > S2;

    int sum = 0;
    REP(i, (int)s.length())
    {
        char c = s[i];

        if (c == '\\')
        {
            S1.push(i);
        }
        else if (c == '/' && S1.size() > 0)
        {
            int j = S1.top();
            S1.pop();
            int a = i - j;
            sum += a;
            while (S2.size() && S2.top().first > j)
            {
                a += S2.top().second;
                S2.pop();
            }
            S2.push(make_pair(j, a));
        }
    }

    vector<int> ans;
    while(S2.size() > 0)
    {
        ans.push_back(S2.top().second);
        S2.pop();
    }
    reverse(ans.begin(), ans.end());
    cout << sum << endl;
    cout << ans.size();
    REP(i, (int)ans.size())
    {
        cout << " ";
        cout << ans[i];
    }
