#include <iostream>

#define K_MAX 10000

using namespace std;

int main(void) {
	int list[K_MAX];
	int k = 0;
	int depth = 0;
	int width = 0;
	int area2 = 0;
	int sum = 0;
	char c;
	bool exist = false;


	while (cin >> c) {

		if (c == '\\') {
			area2 += depth * 2 + 1;
			depth++;
			width++;
		}
		else if (c == '_' && depth > 0) {
			area2 += depth * 2;
			width++;
		}
		else if (c == '/') {
			if (depth > 0) {
				exist = true;
				width++;
			}
			if (depth > 1) {
				area2 += depth * 2 - 1;
				depth--;
			}
			else if(depth == 1){
				area2 += 1;
				list[k] = area2 / 2;
				sum += area2 / 2;
				k++;
				area2 = 0;
				depth = 0;
				width = 0;
				exist = false;
			}
		}
	}
	if (exist) {
		list[k] = (area2 - (2 * (width - depth)*depth + 1)) / 2;
		sum += (area2 - (2 * (width - depth)*depth + 1)) / 2;
		k++;
	}

	cout << sum << "\n";
	cout << k;
	for (int i = 0; i < k; i++) {
		cout << " " << list[i];
	}
	cout << "\n";





	int n;
	cin >> n;
	return 0;
}

