int main(){
    int P = 0, p = 0, h = 0;
    string str;
    cin >> str;
    int a = str.length();

    int Area[a], Left[a+1], Right[a+1], Puddle[a/2+1];
    Left[0] = 0; Right[a] = 0; Puddle[0] = 0;
    int l = 1, L = 0, r = a-1, R = 0;
    for (int i = 0; i < a; i++) {
        if (str[i] == '/') { if (L < 0) L++; }
        else if (str[i] != '_') L--;
        if (L < 0) Left[l] = 1;
        else Left[l] = 0;
        l++;
    }
    for (int i = a-1; i >= 0; i--) {
        if (str[i] == '/') R--;
        else if (R < 0 && str[i] != '_') R++;
        if (R < 0) Right[r] = 1;
        else Right[r] = 0;
        r--;
    }
    for (int j = 0; j <= a; j++) {
        if (Left[j] == 0 || Right[j] == 0) {
            if (P != 0) { P++; Puddle[0] += P; Puddle[p+1] = P; p++; P = 0; h = 0; }
        }
        else {
            if (str[j-1] == '/') { P += 2*(h-1) + 1; h--; }
            else if (str[j-1] == '_') { P += 2*h; }
            else { P += 2*h + 1; h++; }
        }
    }

    cout << Puddle[0]/2 << endl;
    if (p == 0) cout << p << endl;
    else {
        cout << p << " ";
        for (int i = 1; i <= p; i++) {
            cout << Puddle[i]/2;
            if (i == p) cout << endl;
            else cout << " ";
        }
    }
    return 0;
}

#include <stdio.h>

#define STRING_DATA 20000
#define LAKE 500

int stack_index[STRING_DATA];
int stack_area[STRING_DATA];
int stack_lake[LAKE];
int l = 0, pop_flag;

void push(int i) {
  stack_index[l] = i;
  l++;
}

int pop() {
  if(l != 0) {
    pop_flag = 0;
    l--;
    return stack_index[l];
  }
  else {
    pop_flag = 1;
    return 0;
  }
}

int main(void) {
  int k = 0, t, i, j = 0;
  long int max_lake = 0;
  char in;

  for(i = 0 ; i < STRING_DATA ; i++) {
    stack_area[i] = 0;
  }

  while((in = getchar()) != EOF) {
    if(in == '\\') {
      push(k);

    }
    else if(in == '/') {
      t = pop();
      if(pop_flag != 1) {
	stack_area[t] = k - t;
	for(i = t + 1 ; i <= k ; i++) {
	  stack_area[t] += stack_area[i];
	  stack_area[i] = 0;
	}
      }
    }
    k++;
  }

  for(i = 0 ; i < k ; i++) {
    if(stack_area[i] != 0) {
      max_lake += stack_area[i];
      stack_lake[j] = stack_area[i];
      j++;
    }
  }

  printf("%ld\n", max_lake);
  printf("%d", j);
  for(i = 0 ; i < j ; i++) {
    printf(" ");
    printf("%d", stack_lake[i]);
  }
  printf("\n");
  return 0;
}

#include <cstdio>
#include <cstdlib>
#include <cstring>
struct Node{
	int x;
	int y;
	int type;
	int S;
	Node *next, *prev;
};


Node *nil;

Node *listSearch(int key_y, int type) {
	Node *cur = nil->prev;
	while (cur != nil && ((cur->y != key_y || cur->type != type))){
		cur = cur->prev;
	}
	return cur;
}

int puddleCount(){
	Node *cur = nil->prev->prev;
	int count=0;
	bool puddle_flag = false;
	nil->prev->y ++;

	while (cur != nil && cur->y != 0){
		cur->y += 1;
		cur = cur->prev;
	}
	cur = cur->next->next;
	while (cur != nil){
		if (cur->y ==-1){
			puddle_flag = true;
		}
		if (puddle_flag && cur->y==0){
			count +=1;
			puddle_flag = false;
		}
		cur = cur->next;
	}
	return count;
}

void init(){
	nil = (Node *)malloc(sizeof(Node));
	nil->next = nil;
	nil->prev = nil;
	nil->x = -1;
	nil->y = 0;
	nil->type=0;
	nil->S = 0;
}

void insert(int x, int y, int type, int S){
	Node *n  = (Node *)malloc(sizeof(Node));
	n->x = x;
	n->y = y;
	n->type = type;
	n->S = S;
	n->prev = nil->prev;
	n->next = nil;
	nil->prev->next = n;
	nil->prev = n;

}

int main(){
	char str[20000];
	int i, k, S, y;
	bool puddle_flag = false;
	Node *puddle_end, *cur;
	scanf("%s", str);
	i=k=S=0;
	init();

	while(str[i]!='\0'){
		if(str[i]=='\\'){
			y = nil->prev->y;
			insert(i, y-1, -1, S);
			if(!puddle_flag) puddle_flag=true;
		}
		if(puddle_flag && str[i]=='/'){
			y = nil->prev->y;
			S += i-listSearch(y, -1)->x;
			insert(i, y+1, 1, S);
			if(nil->prev->y == 0){
				k++;
				puddle_flag = false;
			}
		}
		i++;
	}

	puddle_end = nil->prev;
	while(puddle_end->type != 1 && puddle_end != nil){
		puddle_end = puddle_end->prev;
	}
	nil->prev = puddle_end;
	puddle_end->next = nil;
	while(nil->prev->y!=0){
		k += puddleCount();
	}
	printf("%d\n", S);
	printf("%d", k);

	cur = nil->next->next;
	S=0;
	for(i=0;i<k;i++){
		while(cur->y != 0 || cur->type != 1){
			cur = cur->next;
		}
		printf(" %d",cur->S - S);
		S = cur->S;
		cur = cur->next;
	}
	printf("\n");
	return 0;
}

