using namespace std;

stack<int> S;
queue<char> Q;
stack<char> Slast;

void calc_area(int *total, bool last) {
    int sum = 0;
    int depth = 0;
    while (!S.empty()) {
        bool end = false;
        switch (S.top()) {
            case '\\':
                if (depth > 0) {
                    depth--;
                    sum += depth * 2 + 1;
                    if (depth == 0) {
                        if (last) {
                            Slast.push(sum);
                        }
                        else {
                            Q.push(sum);
                        }
//                        printf("Push sum %d\n", sum);
                        *total += sum;
                        sum = 0;
                    }
                }
                break;
            case '/':
                depth++;
                sum += depth * 2 - 1;
                break;
            case '_':
                if (depth > 0) {
                    sum += depth * 2;
                }
                break;
        }
        S.pop();
//        printf("Depth %d sum %d\n", depth, sum);
    }

}

int main (void) {

    char c;
