    int total = 0;
    int sum = 0;

    while (scanf("%c", &c) != EOF) {
        switch (c) {
            case '/':
                if (depth > 0) {
                    depth--;
                    S.push(c);
                    if (depth == 0) {
                        calc_area(&total, false);
                    }
                }
                break;
            case '\\':
                depth++;
                S.push(c);
                break;
            case '_':
                if (depth > 0) {
                    S.push(c);
                }
