#include <iostream>
#include <string>
#include <stack>
#define S_LEN_MAX 20000
#define WATER true
using namespace std;

bool chkRightHeighest(string s, int start) {
    int diff = 0;
    for (int i=start; i<s.size(); i++) {
        if ( s[i] == '\\' ) {
            diff--;
        } else if ( s[i] == '/' ) {
            diff++;
        }
        if ( diff == 0 ) {
            return false;
        }
    }
    return true;
}

// half is 1
void solve (string s, int *a, int *L, int *n) {
    int idxl = 0;
    stack<bool> lake;
    for (int i=0; i<s.size(); i++) {
        if ( s[i] == '\\' ) {
            if ( !chkRightHeighest(s, i) ) {
                L[idxl] += 1 + 2 * lake.size();
                lake.push(WATER);
            }
        } else if ( s[i] == '_' ) {
            L[idxl] += 2 * lake.size();
        } else if ( s[i] == '/' ) {
            if ( !lake.empty() ) {
                L[idxl] += 2 * lake.size() - 1;
                lake.pop();
                if ( lake.empty() ) {
                    *a += L[idxl] / 2;
                    idxl++;
                }
            }
        }
    }
    *n = idxl;
}

int main () {
    // input
    string s;
    cin >> s;
    // solve
    int a = 0;
    int L[S_LEN_MAX/2] = {};
    int n = 0;
    solve(s, &a, L, &n);
    // output
    cout << a << endl;
    if (n == 0) {
        cout << n << endl;
    } else {
        cout << n << " ";
        for (int i=0; i<n; i++) {
            cout << L[i] / 2;
            if (i == n-1) {
                cout << endl;
            } else {
                cout << " ";
            }
        }
    }
}

