void fnCrossSectAreaSet(stack<StDtl> &a_rskoDtl, vector<StSum> &a_rvoSum, int &a_riTotalArea)
{
  string sCrossSect;
  cin >> sCrossSect;

  for (int i = 0; i < sCrossSect.size(); i++)
  {
    if (sCrossSect[i] == '\\')
    {
      StDtl oDtl(i);
      a_rskoDtl.push(oDtl);
    }
    else if (sCrossSect[i] == '/')
    {
      if (a_rskoDtl.size() > 0)
      {
        int iLeft = a_rskoDtl.top().m_iLeft; a_rskoDtl.pop();
        int iSum = i - iLeft; 
        a_riTotalArea += iSum;

        while (a_rvoSum.size()  &&
               iLeft < a_rvoSum.back().m_iLeft  &&
               a_rvoSum.back().m_iRight < i       )
        {
          iSum += a_rvoSum.back().m_iArea;
          a_rvoSum.pop_back();
        }
        StSum oSum(iLeft, i, iSum);
        a_rvoSum.push_back(oSum);
      }
      else;
    }
  }
}

