int searchPuddle(int start, string s) {
	double a = 0, h = 0;
	for (int i = start; i < s.size(); i++) {
		switch (s[i]) {
			case '\\':
				a += h + 0.5;
				h++;
				break;
			case '/':
				h--;
				a += h + 0.5;
				if (h == 0) {
					A += a;
					L.push_back((int)a);
					return i;
				}
				break;
			case '_':
				a += h;
				break;
			default:
				break;
		}
	}
	return start;
}

