template <typename T>
class stack{
public :
	const static int MAX = 30000;
	stack<T> (){
		pos = 0;
	}

	void empty(){
		pos = 0;
	}

	bool isEmpty(){
		return (pos == 0);
	}

	bool isFull(){
		return (pos == MAX);
	}

	T pop(){
		if(isEmpty()){
			throw exception();
		}
		return body[--pos];
	}

	void push(T el){
		if(isFull()){
			throw exception();
		}
		body[pos++] = el;
	}

	T top(){
		if(isEmpty()){
			throw exception();
		}
		return body[pos-1];
	}

	T body[MAX];
	int pos;
};


