        if (area[i] == '\\') {
          if (i == start) { water_area.push_back(0); }
          water_area[j] += height + 0.5;
          height++;
        } else if (area[i] == '/') {
          water_area[j] += height - 0.5;
          height--;
        } else if (area[i] == '_') {
          water_area[j] += height;
        }
      }
    }

    if (start != end) { j++; }
    start = end + 1;
