using namespace std;
int result[10];
void init(){
    for (int j=0; j<=10;j++){
        result[j]=0;
    }
}
#define STACK_MAX 10

int S[STACK_MAX];

int stack_top = 0;

void push(int val){
    if (stack_top==STACK_MAX) {
        return;
    }else{
        S[stack_top++]=val;
    }
}

int pop(){
    if (stack_top==0) {
        return(0);
    }else{
        return S[--stack_top];
    }
}
void pops(){
    if (stack_top==0) {
        return;
    }else{
        --stack_top;
        S[stack_top]=0;    }
}


int main(){
    init();
    string word;
    int p=0;
    while (cin >> word){
        if (word!="\") {
            continue;
        }else{
        if (word == "\"){
            int i=0,sum=0;
            push(1);
            i+=1;
            sum+=1;
            while (stack_top!=0){
                if (word=="\") {
                    push(1);
                    i+=1;
                    sum=sum + 2*i -1;
                }else{
                if (word=="/") {
                    pops();
                    sum=sum+ 2*i -1;
                    i-=1;
                }else{
                    continue;
                }
            }
            }
            result[p]=sum;
            p++;
        }
        }
    }
    int sumsum=0;
