#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>

int main()
{
    struct Point
    {
        int height{};
        char lean{};
    };
    std::string geo_signs;
    std::cin >> geo_signs;
    geo_signs.insert(0, 1, '_');
    std::vector<Point> geo_points(geo_signs.length());
    geo_points[0].lean = '_';
    for (auto i = 1; i < geo_signs.length(); ++i)
    {
        int adjuster{};
        char cc{geo_signs[i]}, pc{geo_signs[i - 1]};
        switch (cc)
        {
        case '_':
            adjuster = (pc == '\\') ? -1 : 0;
            break;
        case '\\':
            adjuster = (pc == '\\') ? -1 : 0;
            break;
        case '/':
            adjuster = (pc == '\\') ? 0 : 1;
            break;
        default:
            adjuster = 0;
            break;
        }
        geo_points[i].height = geo_points[i - 1].height + adjuster;
        geo_points[i].lean = cc;
    }

    std::vector<std::vector<Point>> lakes;
    for (auto first_it = geo_points.begin(); first_it != geo_points.end();)
    {
        auto second_it = (first_it->lean != '\\') ? geo_points.end() : std::find_if(first_it + 1, geo_points.end(), [first_it](Point &p) { return p.height == first_it->height; });
        if (second_it == geo_points.end())
        {
            ++first_it;
            continue;
        }
        lakes.emplace_back(first_it, second_it + 1);
        first_it = second_it + 1;
    }

    std::vector<int> lake_areas;
    for (auto it = lakes.begin(); it != lakes.end(); ++it)
    {
        auto mmpair{std::minmax_element(it->begin(), it->end(), [](Point &p1, Point &p2) { return p1.height < p2.height; })};
        int lake_height{mmpair.second->height - mmpair.first->height + 1};
        int lake_width{static_cast<int>(it->size())};
        double area{static_cast<double>(lake_height * lake_width)};
        for (auto i = it->begin(); i != it->end(); ++i)
        {
            area -= (i->height - mmpair.first->height + (i->lean == '_' ? 1 : 0.5));
        }
        lake_areas.push_back(static_cast<int>(area));
    }
    std::cout << std::accumulate(lake_areas.begin(), lake_areas.end(), 0) << std::endl;
    std::cout << lake_areas.size();
    for (auto area : lake_areas)
    {
        std::cout << " " << area;
    }
    std::cout << std::endl;
    return 0;
}

