class Flood{
private:
	int x_;
	int y_;
	int w_;
	int h_;
	int area_;

public:
	Flood(int x, int y, int w, int h) : x_(x), y_(y), w_(w), h_(h), area_(0){}

	virtual ~Flood(){}

	void search(int x, int y, const std::vector<char> &diagram, std::vector<bool> &is_checked){
		if(x >= w_ || y >= h_ || y < y_){ return; }
		int cidx = y * w_ + x;
		if(is_checked[cidx]){ return; }

		is_checked[cidx] = true;
		if(diagram[cidx] == '\\'){
			area_++;
			search(x + 1, y, diagram, is_checked);
		}
		else if(diagram[cidx] == '_'){
			area_ += 2;
			search(x + 1, y, diagram, is_checked);
		}
		else if(diagram[cidx] == '/'){
			area_++;
		}
		else{
			area_ += 2;
			search(x + 1, y, diagram, is_checked);
			search(x, y + 1, diagram, is_checked);
		}
		return;
	}

	void create_flood(const std::vector<char> &diagram, std::vector<bool> &is_checked){
		search(x_, y_, diagram, is_checked);
	}

	int get_area(){
		return area_ / 2;
	}

	bool operator < (Flood & r){ return this->x_ < r.x_; }
};

