	multimap<int, int> m;
	int max = 0, min = 0, v[20010];
	v[0] = 0;
	m.insert(make_pair(0, 0));
	rep(i,str.size()) {
		if(str[i] == '\\') {
			v[i+1] = v[i] - 1;
			m.insert(make_pair(v[i+1], i+1));
			if(min > v[i+1]) min = v[i+1];
		} else if(str[i] == '/') {
			v[i+1] = v[i] + 1;
			m.insert(make_pair(v[i+1], i+1));
			if(max < v[i+1]) max = v[i+1];
		} else {
			v[i+1] = v[i];
			m.insert(make_pair(v[i+1], i+1));
		}
	}
	int f[20010];
	bool b[20010];
	rep(i,str.size()+1) {
		b[i] = true;
	}
	for(int i = max; i >= min; --i) {
		int c = m.count(i);
		int e[2];
		auto begin = m.find(i);
		e[0] = begin->second;
		if(c < 2) {
			f[e[0]] = 0;
			b[e[0]] = false;
			continue;
		}
		auto end = m.upper_bound(i);
		end--;
		e[1] = end->second;
		rep2(j,e[0],e[1]+1) {
			if(b[j]) f[j] = i - v[j];
			b[j] = false;
		}
	}
	vector<int> ret;
	int pre = 0, count = 0;
	rep(i,str.size()+1) {
		if(f[i]) {
			count += f[i];
			pre = f[i];
		} else {
			if(pre) {
				ret.push_back(count);
				count = pre = 0;
			}
		}
	}

	int total = 0;
	rep(i,ret.size()) {
		total += ret[i];
	}
	cout << total << endl;
	cout << ret.size();
	rep(i,ret.size()) {
		cout << " " << ret[i];
	}
	cout << endl;
	return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define MAX 20000
typedef struct {
  int maxi;
  int maxj;
  double area;
}INF;

int main()
{
  int i,j,n,m=0,sum_p=0,sum_m=0,min=0,Area[MAX+1],k=0,sum=0;
  char word[MAX];
  INF L[MAX/2];

  scanf("%s",word);

  n=strlen(word);
  Area[0]=0;

  for(i=0;i<n;i++){
    if(word[i]=='/') sum_p++;
    if(word[i]=='\\') sum_m--;
    Area[i+1]=sum_p+sum_m;
    if(min>Area[i+1]){
      min=Area[i+1];
    }
  }

  for(i=0;i<n+1;i++){
    Area[i]=Area[i]-min;
  }

  for(i=0;i<n+1;i++){
    if(word[i]=='\\'){
      j=i+1;
      while(1){
	if(Area[i]==Area[j]){
	  L[m].maxi=i;
	  L[m].maxj=j;
	  m++;
	  i=j-1;
	  break;
	};
	j++;
	if(j==n+1) break;
      }
    }
  }

  for(i=0;i<m;i++){
    for(j=L[i].maxi;j<L[i].maxj;j++){
      if(word[j]=='\\'||word[j]=='/'){
	L[i].area+=(1/2+abs(Area[L[i].maxi]-Area[j]));
      }
      if(word[j]=='_') L[i].area+=Area[L[i].maxi]-Area[j];
    }
  }

  for(i=0;i<m;i++){
    sum=sum+L[i].area;
  }

  printf("%d\n%d",sum,m);

  for(i=0;i<m;i++){
    printf(" %d",(int)L[i].area);
  }

  printf("\n");

  return 0;
}

