int main() {
	struct slayer {
		int S;				//S=ri-li
		int Li;
	};
	char ch;
	stack<int> cal;
	stack<slayer> area;
	int sum = 0;
	for (int i = 0; ch=getchar(); i++) {
		if (ch == '\\') {
			cal.push(i);
		}
		else if (ch == '/') {
			if (cal.empty())
				continue;				//找不到对应 continue

			int temp = cal.top();		//找到对应，读取上一个"\"				

			slayer s{0,temp};

			while (!area.empty() && area.top().Li > cal.top()) {
				s.S += area.top().S;
				area.pop();
			}
			cal.pop();
			s.S += (i - temp);
			sum += (i - temp);
			area.push(s);
