          while (slope_up.size() > 0 && slope_up.top().first > left) {
            puddle_area += slope_up.top().second;
            slope_up.pop();
          }
          slope_up.push(make_pair(left, puddle_area));
        }

        break;
      case '_':
        break;
      default:
        break;
