    //const int max_ground_level_x2 = 2*max(height[i], height[i+1]);
    //cout << water_level_x2 << ' ' << ave_ground_level_x2 << endl;

    water_volume_x2 += max(0, water_level_x2 - ave_ground_level_x2);

    if(water_level_x2 == 2*height[i+1] && 
       water_volume_x2 > 0){
      ponds_x2.push_back(water_volume_x2);
      water_volume_x2 = 0;
    }
    //cout << "?:" << water_volume_x2 << endl;
  }

  if(water_volume_x2 > 0) {
    ponds_x2.push_back(water_volume_x2);
  }

  // //output 
  // cout << "---" << endl
  //      << "answer" << endl;
  cout << accumulate(ponds_x2.begin(), ponds_x2.end(), 0)/2 << endl;
  cout << ponds_x2.size();
  for(auto vol_x2 : ponds_x2){
    cout << ' ' << vol_x2/2;
  }
  cout << endl;
  //water_volume_x2/2 <<endl; 

  return 0;
}

