	Data d = pq.top();
	pq.pop();
	T[d.index] = H[d.index];

	int i_min = d.index,
		i_max = d.index;

	while(!pq.empty())
	{
		Data d = pq.top();
		pq.pop();
		if(T[d.index] == 0){
			h = H[d.index];
			T[d.index] = h;
			if( d.index < i_min ){
				i = d.index + 1;
				while( (H[i] <= h) && (T[i] == 0) && ( i <= i_max )) {
					T[i] = h;
					++i;
				}
				i_min = d.index;
			}else if( d.index > i_max ){
				i = d.index - 1;
				while ((H[i] <= h) && (T[i] == 0) && (i >= i_min)){
					T[i] = h;
					if (H[i] == h) break;
					--i;
				}
				i_max = d.index;
			}
		}
	}

	int A = 0;
	int t = -1;
	vector<int> v(s, 0);
	for(i = 1; i <= b; ++i){
		if( T[i] == 0 || T[i-1] == 0 )
			continue;
		if( T[i-1] == H[i-1] && T[i] > H[i] )
			++t;
		if(-1 == t)
			continue;
		v[t] += (T[i] - H[i]) + (T[i-1] - H[i-1]);
	}

	for(i = 0; i <= t; ++i)
		A += v[i];
	++t;

	cout << A / 2 << "\n" << t;
	for(i = 0; i < t; ++i)
		cout << " " << v[i] / 2;
	cout << "\n";

	return 0;
}

