	Slope	slope;

	slope.input();

	slope.simulate();

	slope.print();

	return	0;
}

Slope::Slope(): allAreas{0}, level{0}, slopes{}, floods{}
{
}

void Slope::input()
{
	char	c		{'\0'};

	while((c = getchar()) != '\n'){
		slope	s	{};
		switch(c){
		case '/':
			s	= std::make_tuple(c, level, level - 1);
			--level;
			break;

		case '_':
			s	= std::make_tuple(c, level, level);
			break;

		case '\\':
			s	= std::make_tuple(c, level, level + 1);
			++level;
			break;

		default:
			break;
		}

		slopes.push_back(s);
	}
}

void Slope::simulate()
{
	bool	isStart	{false};

	unsigned int	num	= slopes.size();
	int				startLevel	{0};

	unsigned int	i = 0;
	for(;;){
		auto	s	= slopes[i];
		auto	c	= std::get<0>(s);

		if(c == '\\'){
			startLevel	= std::get<1>(s);
			auto	start	= i;
			for(auto j = i + 1; j < num; ++j){
				auto	se	= slopes[j];
				auto	ce	= std::get<0>(se);

				if((ce == '/') && (std::get<2>(se) == startLevel)){
					auto	area	= flood(start, j);
					floods.push_back(area);
					allAreas	+= area;
					i	= j;
					break;
				}
			}
			++i;
		}
		else{
			++i;
		}

		if(i >= num){
			break;
		}
	}
}

unsigned int	Slope::flood(const unsigned int	start,
							 const unsigned int	end)
{
	unsigned int	a	{0};
	auto			startLevel	= std::get<1>(slopes[start]);

	for(auto i= start; i < end + 1; i++){
		auto	s	= slopes[i];
		auto	c	= std::get<0>(s);
		switch(c){
		case '\\':
			a	+= 1 + ((std::get<1>(s) - startLevel) * 2);
			break;

		case '_':
			a	+= (std::get<1>(s) - startLevel) * 2;
			break;

		case '/':
		default:
			a	+= 1 + ((std::get<2>(s) - startLevel) * 2);
			break;
		}
	}

	return	a / 2;
}

void Slope::print()
{
	std::cout << allAreas << '\n';
	std::cout << floods.size();

	for(auto area :floods){
		std::cout << ' ' << area;
	}

	std::cout << '\n';
}

