using namespace std;

std::vector<int> ys;
std::vector<int> floodAreas;

void floodArea(int begin, int end) {
  if ((end - begin) <= 2) {
    return;
  }

  int maxi = begin + 1;
  for (int i = begin + 1; i < end - 1; ++i) {
    if (ys[maxi] < ys[i]) {
      maxi = i;
    }
  }
  int maxy = ys[maxi];
  int level = min(ys[begin], ys[end - 1]);
  if (maxy < level) {
    int area = 0;
    for (int i = begin + 1; i < end; ++i) {
      int a = 2 * level - ys[i] - ys[i-1];
      if (a > 0) {
        area += a;
      }
    }
    floodAreas.push_back(area / 2);
    return;
  }
  floodArea(begin, maxi + 1);
  floodArea(maxi, end);
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  string map;
  cin >> map;

  int level = 0;
  ys.push_back(0);

  for (char c : map) {
    if (c == '/') {
      ++level;
    } else if (c == '\\') {
      --level;
    }
    ys.push_back(level);
  }
  floodArea(0, ys.size());

  int areaSum = 0;
  for (int a : floodAreas) {
    areaSum += a;
  }
  cout << areaSum << endl;

  cout << floodAreas.size() << " ";
  for (int i = 0; i < floodAreas.size(); ++i) {
    if (i != 0) {
      cout << " ";
    }
    cout << floodAreas[i];
  }
  cout << endl;
}

