	int startStep;
	int volume;
};

int main()
{
	vector<Flood> floods;
	Flood flood;
	int memo[50000];

	string input;
	cin >> input;

	int nowFloor;
	int nowStep;

	nowFloor = 25000;
	nowStep = 0;

	for (int i = 0; i < 50000; i++)
	{
		memo[i] = -1;
	}

	memo[nowFloor] = nowStep;
	flood.startStep = nowStep;
	flood.volume = 0;

