}

#include "bits/stdc++.h"

using namespace std;
using ll = long long;
using pll = pair<ll, ll>;

/*********** Constants ***********/
const auto INF = static_cast<ll>(1e15);
const auto MOD = static_cast<ll>(1e9 + 7);

/************* Utils *************/

/*********** Variables ***********/
string S;
ll A, K;
stack<ll> S1;
stack<pair<ll, ll>> S2;
vector<ll> ANS;

/*********** Functions ***********/
bool init() {
    cin >> S;
    return true;
}

void solve() {
    for (ll i = 0; i < S.length(); i++) {
        if (S[i] == '_') {
            continue;
        }
        if (S[i] == '\\') {
            S1.push(i);
        }
        if (S[i] == '/') {
            if (S1.empty()) {
                continue;
            }
            ll j = S1.top(); S1.pop();
            A += i - j;
            ll a = i - j;
            while (!S2.empty() && S2.top().first > j) {
                a += S2.top().second; S2.pop();
            }
            S2.emplace(j, a);
        }
    }
    K = S2.size();
    while (!S2.empty()) {
        ANS.push_back(S2.top().second);
        S2.pop();
    }
    reverse(ANS.begin(), ANS.end());
}

void output() {
    cout << A << endl;
    cout << K;
    for (const auto& LAKE: ANS) {
        cout << " " << LAKE;
    }
    cout << endl;
}

int main() {
    init();
    solve();
    output();
    return 0;
}

