int GetArea(string str, vector<TArea>& AreaList)
{
    int TotalArea = 0;
    TArea Temp;
    vector<int> List;
    List.clear();
    AreaList.clear();

    for(int i = 0; i < str.size(); i++){
        if(str[i] == '\\')  List.push_back(i);
        if(str[i] == '/' && !List.empty()){
            Temp.Area = i - List[List.size() - 1];
            Temp.Point = List[List.size() - 1];
