            for(int j = AreaList.size() - 1; j >= 0; j--){
                if(Temp.Point < AreaList[j].Point){
                    Temp.Area += AreaList[j].Area;
                    AreaList.pop_back();
                }
            }
            AreaList.push_back(Temp);
            List.pop_back();
        }
    }
    return TotalArea;
}

