		pour cur = parts[i];
		sum += cur.sz;
		if (cur.stt > stt && cur.end < ed) {
			int pick = out.back(); out.pop_back();
			out.push_back(pick + cur.sz);
		}
		else {
			stt = cur.stt;
			ed = cur.end;
