    area += ((r-l+1)+(r-l-1))*1/2;
  }
  V.push_back(area);
  cout << accumulate(V.begin(), V.end(), 0) << endl;
  cout << V.size() << ' ';
  for (int i = 0; i < V.size(); i++) {
    cout << V[i] << (i == V.size()-1 ? '\n' : ' ');
  }
}

#include <iostream>
