int convert_geom(char g){
  switch(g){
  case '/':
    return +1;
  case '\\':
    return -1;
  case '_':
    return 0;
  default:
    assert(false);
  }
}

int main(){
  string geom;
  cin >> geom;
  const int N = geom.size();

  vector<int> height(N+1);
  vector<int> max_lefthand_height(N+1);
  vector<int> max_righthand_height(N+1);
  vector<int> water_level(N);

  //set height
  height[0] = 0;
  for(int i = 0; i<N; ++i){
    height[i+1] = height[i] + convert_geom(geom[i]);
  }

  //set max_lefthand_height
  max_lefthand_height[0] = height[0];
  for(int i = 0; i<N; ++i){
    max_lefthand_height[i+1] = max(max_lefthand_height[i], height[i+1]);
  }

  //set max_righthand_height
  max_righthand_height[N] = height[N];
  for(int i = N-1; i>-1; --i){
    max_righthand_height[i] = max(max_righthand_height[i+1], height[i]);
  }

  //set water_level
  for(int i = 0; i<N; ++i){
    water_level[i] = min(max_lefthand_height[i], 
			 max_righthand_height[i+1]);
  }


  int water_volume_x2 = 0;
  vector<int> ponds_x2;
  //cout << "w g" << endl;
  for(int i = 0; i<N; ++i){
    const int water_level_x2 = 2*water_level[i];
    const int ground_level_x2 = height[i]+height[i+1];
    //cout << water_level_x2 << ' ' << ground_level_x2 << endl;

    water_volume_x2 += max(0, water_level_x2 - ground_level_x2);

    if(water_level_x2 == ground_level_x2 && 
       water_volume_x2 > 0){
      ponds_x2.push_back(water_volume_x2);
      water_volume_x2 = 0;
    }
    //cout << "?:" << water_volume_x2 << endl;
  }

  if(water_volume_x2 > 0) {
    ponds_x2.push_back(water_volume_x2);
  }

  // //output 
  // cout << "---" << endl
  //      << "answer" << endl;
  cout << accumulate(ponds_x2.begin(), ponds_x2.end(), 0)/2 << endl;
  cout << ponds_x2.size();
  for(auto vol_x2 : ponds_x2){
    cout << ' ' << vol_x2/2;
  }
  cout << endl;
  //water_volume_x2/2 <<endl; 

  return 0;
}

