int main() {
    stack<int> S1;
    stack<pair<int, int> > S2;
    int total = 0;
    string S; cin >> S;

    for(int i = 0; i < S.size(); i++){
        if(S[i] == '/' && S1.size() > 0){
            int a = S1.top(); S1.pop();
            int b = i - a;
            total += b;
            int men = 0;
            while(!S2.empty() && S2.top().first > a){
                men += S2.top().second;
                S2.pop();
            }
            men += b;
