typedef std::vector<int> TList;
typedef TList::iterator TIt;
struct TPeak
{
    int Pos;
    int Alt;
    TPeak(int APos, int AAlt) : Pos(APos), Alt(AAlt) {}
};
typedef std::vector<TPeak> TPeakList;
bool CompareAlt(const TPeak& Left, const TPeak& Right)
{
    return Left.Alt < Right.Alt;
}

void Output(const TList& List)
{
    TList::const_iterator It = List.begin();
    std::cout << *(It++);
    for(; It != List.end(); ++It){
        std::cout << " " << *It;
    }
    std::cout << std::endl;
}
TList GetAltitude(const std::string Diagram)
{
    TList AltList(Diagram.size());
    int Alt = 0;
    for(int i = 0; i < Diagram.size(); ++i){
        if(Diagram[i] == '\\'){
            --Alt;
        }else
        if(Diagram[i] == '/'){
            ++Alt;
        }
        AltList.push_back(Alt);
    }
    return AltList;
}
TPeakList GetPeakList(const std::string Diagram)
{
    TPeakList PeakList;
    int Alt = 0;
    bool IsUpped = true;
    for(int Pos = 0; Pos < Diagram.size(); ++Pos){
        if(Diagram[Pos] == '\\'){
            if(IsUpped){
                PeakList.push_back(TPeak(Pos, Alt));
                IsUpped = false;
            }
            --Alt;
        }else
        if(Diagram[Pos] == '/'){
            IsUpped = true;
            ++Alt;
        }
    }
    if(IsUpped){
        PeakList.push_back(TPeak(Diagram.size(), Alt));
    }
    return PeakList;
}
int GetArea(const std::string& Diagram, int LeftPos, int RightPos)
{
    // ?????´?????????????????´??????????????¢?????????????????????????????????????????£??????????????????
    // std::cout << "Left:" << LeftPos << ", Right:" << RightPos << std::endl; // debug
    int Depth = 0;
    int Area = 0;
    for(int i = RightPos; i >= LeftPos; --i){
        // std::cout << Diagram.at(i) << std::endl; // debug
        switch(Diagram.at(i)){
        case '\\':
            --Depth;
            Area += Depth * 2 + 1;
            if(Depth == 0){
                // std::cout << ", Area:" << Area << std::endl; // debug
                return Area/2;
            }    
            break;
        case '_':
            Area += Depth * 2;
            break;
        case '/':
            Area += Depth * 2 + 1;
            ++Depth;
            break;
        default:
            assert(false);
        }
    }
    assert(false);
}
TList SimulateFlood(const std::string Diagram, TPeakList::const_iterator begin, TPeakList::const_iterator end)
{
    TList List;
    TPeakList::const_iterator Top = begin;
    while(Top+1 != end){
        TPeakList::const_iterator Second = std::max_element(Top+1, end, CompareAlt);
        int Area = GetArea(Diagram, Top->Pos, Second->Pos-1);
        List.push_back(Area);
        Top = Second;
    }
    return List;
}
