int main(){
	char com[20002];
	scanf("%s", com);
	vector<int> h;
	h.push_back(0);
	h.push_back(0);
	for (int i = 0; i < (int)strlen(com); i++){
		switch (com[i]){
		case '_':
			h.push_back(h[i + 1]);
			break;
		case '\\':
			h.push_back(h[i + 1] - 1);
			break;
		case '/':
			h.push_back(h[i + 1] + 1);
			break;
		default:
			break;
		}
	}

	int min = h[1];
	int max = h[1];
	for (int i = 2; i < (int)h.size(); i++){
		if (min > h[i]) min = h[i];
		if (max < h[i]) max = h[i];
	}
	h[0] = min;
	h.push_back(min);

	vector<int> smoothed(h.size(), max);
	int curmax = h[0];
	for (int i = 0; i < (int)h.size(); i++){
		if (h[i] > curmax) curmax = h[i];
		smoothed[i] = curmax;
		if (curmax == max) break;
	}
	curmax = h[h.size() - 1];
	for (int i = h.size() - 1; i >= 0; i--){
		if (h[i] > curmax) curmax = h[i];
		smoothed[i] = curmax;
		if (curmax == max) break;
	}

	int water = 0;
	int sum = 0;
	bool ispond = false;
	vector<int> ponds;
	for (int i = 0; i < h.size(); i++){
		if (smoothed[i] > h[i]){
			ispond = true;
		}
		if (ispond) water += ((smoothed[i] - h[i]) + (smoothed[i - 1] - h[i - 1]));
		if (ispond && smoothed[i] == h[i]){
			ispond = false;
			ponds.push_back(water/2);
			sum += water / 2;
			water = 0;
		}
	}

	cout << sum << endl << ponds.size();
	for (int i = 0; i < ponds.size(); i++){
		cout << " " << ponds[i];
	}
	cout << endl;

	return 0;
}

