    long stacksize =sumstack.size();
    int a[sumstack.size()];
    for (int i = 0; i<stacksize; i++) {
        allsum += sumstack.top().sum;
        a[i] = sumstack.top().sum;
        sumstack.pop();
    }
    cout << allsum << endl;
     cout << stacksize<< " ";
