        cout << a[i];
        if (i != 0) {
            cout << " ";
        }
    }
    cout << endl;
}
void calTotalSum(int position, int sum)
{
    si sumtop =sumstack.top();;
    si newtop =sumtop;
    if(sumstack.empty()||position>sumtop.position){
        si* sinfo = (si*)malloc(sizeof(si));
        sinfo->sum = sum;
        sinfo->position = position;
        sumstack.push(*sinfo);
        return;
    }
    while (position < sumtop.position) {
        sumstack.pop();
        newtop.sum += sum;
        if(sumstack.empty()){
            break;
        }
        sumtop = sumstack.top();
        sum = sumtop.sum;
    }
    sumstack.push(newtop);

}
void solve(char c[20000])
{

    int N = strlen(c);
    int depth = 0;
    for (int i = 0; i < N; i++) {
        if ('\\' == c[i]) {
            depth++;
            ci* cinfo = (ci*)malloc(sizeof(ci));
            cinfo->depth = depth;
            cinfo->position = i;
            contour.push(*cinfo);
            //	    sum += depth - 0.5;
        }
        if ('/' == c[i]) {
            if(contour.empty()){
                continue;
            }
            int sum = 0;
            ci ctop = contour.top();
            if (ctop.depth == depth) {
                contour.pop();
                if (c[i - 1] == '\\') {
                    sum = 1;
                    si* sinfo = (si*)malloc(sizeof(si));
                    sinfo->sum = sum;
                    sinfo->position = ctop.position;
                    sumstack.push(*sinfo);
                } else {
                    sum = i-ctop.position;
                    calTotalSum(ctop.position, sum);
                }
            }
            depth--;
        }
        if ('_' == c[i]) {
        }
    }
    print();
}

