			maxHeightTable[i] = maxHeightTable[i-1];
		}

		if(maxHeight <= height && ((history == '/' && current == '\\')
				|| (history == '_' && current == '\\') || (history == '/' && current== '\n'))){
			maxHeightTable[i] = i;
			maxHeight = height;
		}
