int getPondarea(Mount summit, vector<int> heightList)
{
	int pond = 0;
	int i = summit.ichi;

	//???????§??????¨???
	int depth = 0;
	bool upward = false;

	while( summit.height >= heightList[i] ){

		if( heightList[i] > heightList[i-1]){
			pond += 1 +(depth*2) ;
			depth++ ;
		}
		else if( heightList[i] < heightList[i-1] ){
			depth-- ;
			pond += 1 + (depth*2) ;
			upward = true;
		    if(depth == 0){
		        break;
		    }
		}
		else{
			//??????????????????????????¨?????±???????????????????¶????
			pond += (depth*2);
		}
		i--;
	}
	return pond /2 ;	//2??????????????§???????????????
}

