bool asc1(const pair<int, int>& left, const pair<int, int>& right)
{
     return left.first == right.first ? left.second < right.second : left.first > right.first;
}

bool asc2(const pair<int, int>& left, const pair<int, int>& right)
{
    return left.second == right.second ? left.first > right.first : left.second < right.second;
}

int cal(int former, int later, string ground)
{
    int s = 0;
    int depth = 0;
    for(int i = former; i < later; i++)
    {
        if(ground[i] == '/')
        {
            depth--;
            s += depth;
        }
        else if(ground[i] == '_')
        {
            s+=depth;
        }
        else
        {
            depth++;
            s += depth;
        }
    }
    return s;
}

bool is_not_flat(int start, int end, vector<pair<int, int> > xs) //?????????????????£????????????
{
    if(end + 1 > start)
    {
        if(xs[start].first - xs[start+1].first > 0)
            return true;
    }
    return false;
}

void part(int start, int end, vector<pair<int,int> > xs, int size)
{
    if(end > start + 1)
    {
        vector<pair<int, int> > rem;
        for(int i =start ; i < end; i++)
        {
            rem.push_back(xs[i]);
        }
        sort(rem.begin(), rem.end(),asc1);
        int index = -1;
        int index2 = -1;
        for(int i = 0; i < rem.size(); i++)
        {
            if(rem[i+1].second > -1 && rem[i].second > -1 && rem[i].first == rem[i+1].first)
            {
                index = rem[i].second;
                index2 = rem[i+1].second;
                break;
            }
        }

        if(index >= 0)
        {
            if(index > start + 1)
                part(start,index,xs,size);//?????????
            if(end > index2 + 1)
                part(index2,end,xs,size);//????????????
            if(index2 - index > 1 && is_not_flat(index, index2, xs))
            {
                location.push_back({index,index2});//?°´??????????????????????¨???¶
                number++;
            }
        }
    }
}

