using namespace std;

int H[20005];

int main()
{
	string str;
	cin >> str;

	H[0] = (str[0] == '\\' ? -1 : (str[0] == '/' ? 1 : 0));
	int len = str.length();
	for(int i = 1; i < len; ++i)
	{
		H[i] = H[i - 1] + (str[i] == '\\' ? -1 : (str[i] == '/' ? 1 : 0));
	}

	int total = 0, count = 0, pool[10000];
	for(int i = 0; i < len; ++i)
	{
		if(str[i] == '\\')
		{
			int idx = -1, mh = -100000;
			for(int j = i + 1; j < len; ++j)
			{
				if(str[j] == '/' && H[j] > mh)
				{
					idx = j;
					mh = H[j];

					if(H[j] == H[i] + 1)
					{
						break;
					}
				}
			}

			if(idx >= 0)
			{
				int sum = 0;
				for(int j = i; j <= idx; ++j)
				{
					if((str[j] == '/' && H[j] <= mh) || H[j] < mh)
					{
						sum += (str[j] == '\\' ? (mh - H[j]) * 2 - 1 : (str[j] == '/' ? (mh - H[j]) * 2 + 1 : (mh - H[j]) * 2));
					}
				}

				pool[count] = sum / 2;
				total += pool[count++];
				i = idx - 1;
			}
			else
			{
				break;
			}
		}
	}

	cout << total << endl;
	cout << count;
	for(int i = 0 ; i < count; ++i)
	{
		cout << " " << pool[i];
	}
	cout << endl;

    return 0;
}

