      lakes.push_back(make_pair(state.top(), ls));
      state.pop();
    }
  }

  cout << lsum << "\n"
       << lakes.size();
  for (auto itr = lakes.begin(); itr != lakes.end(); ++itr)
  {
    cout << " " << (*itr).second;
  }
  cout << endl;
}

