int rain() {
	int i=0, left, right = 0, k;
	while (i < len && s[i] != '\\')i++;
	while (i < len && s[i] != '/')i++;
	if (i == len) return 0;
	right = i;
	while (i >= 0 && s[i] != '\\')i--;
	if (i < 0)return 0;
	left = i;
	depth[left] = 1;
	for (k = left + 1; k < right; k++)depth[k] += 2;
	depth[right] = 1;
	s[left] = '_';
	s[right] = '_';
	return right - left;
}
