		} else if(inp[i] == '/'){
			int b = pop1();
			if(b != -1){
				sum += i-b;
				push2(newP(b, i, i-b));
				st();
			}
		}
	}
	printf("%d\n%d", sum, end2);
	if(end2 != 0){
		printf(" ");
		for(int i=0;i<end2;i++){
			printf("%d", stack2[i].qty);
			if(i != end2-1) printf(" ");
		}
	}
	printf("\n");
	return 0;
}

