template <typename Iter, typename C>
inline decltype(auto) getIndexfromIter(const Iter &i, const C &container) {
  return i - begin(container);
}

int main() {
  string str;
  cin >> str;
  deque<int> index;
  deque<pair<int, int>> puddle;
  for (auto i = str.begin(), e = str.end(); i != e; i++) {
    if ('\\' == *i) {
      index.push_back(getIndexfromIter(i, str));
    } else if ('/' == *i && !index.empty()) {
      auto j = index.back();
      auto area = getIndexfromIter(i, str) - j;
      index.pop_back();
      while (!puddle.empty() && puddle.back().first > j) {
        area += puddle.back().second;
        puddle.pop_back();
      }
      puddle.emplace_back(j, area);
    }
  }

  auto sum = 0;
  for (auto &&var : puddle) {
    sum += var.second;
  }
  cout << sum << '\n';
  cout << puddle.size();
  for (auto &&var : puddle) {
    cout << ' ' << var.second;
  }
  cout << '\n';

  return 0;
}

