		if (s[i] == '/') {
			act++;
			flag = calc(act, &num);
			m[num].top = act;
			m[num].topn = i + 1;
			wind = 1;
		}
		if (s[i] == '_')m[num].topn = i + 1;
		if (s[i] == '\\') {
			if (flag)num++, flag = 0;
			ff = 0, act--, wind = 1;
		}
		if (i == s.size() - 1 && !wind)num++;
		for (int j = 0; j < num;j++)m[j].dis++;
	}

	int aa = 0, fff = 0, j = 0;
	for (int i = 0; i < num; i++)aa += area[i];
	//cout << num << "   ";
	if (!area[num - 1])num--;
	if (!area[0])num--, fff = 1, j++;
	if (num <= 0) num = 0;
	cout << aa << endl << num;
	if(0 < num) {
		if (j)num++;
		for (j; j < num; j++) cout << " " << area[j];
	}
	cout << endl;

	return 0;
}

