struct TMountain
{
	int Position;
	int Height;

public:
	TMountain(int APosition,int AHeight);
};

TMountain::TMountain(int APosition,int AHeight)
{
	Position = APosition;
	Height   = AHeight;
}

typedef std::vector<TMountain> TMountains;

void CreateMountains(TMountains& MountainList,const GroundShapes& ShapeList,const IntVector& HeightList)
{
	bool IsClimbing = true;
	for(unsigned int i=0;i<ShapeList.size();i++)
	{
		switch(ShapeList[i])
		{
			case gsUp   : IsClimbing = true;break;
			case gsDown : if(IsClimbing) MountainList.push_back(TMountain(i,HeightList[i] ));
			              IsClimbing = false;break;
			default     : break;
		}
	}
	if(IsClimbing) MountainList.push_back(TMountain(ShapeList.size(),HeightList[ShapeList.size()]));
}

enum ScanDirection
{
	sdFront,
	sdBack
};

TMountains::const_iterator GetHighest(const TMountains& Mountains,TMountains::const_iterator Left,TMountains::const_iterator Right,ScanDirection Direction)
{
	int Vector = Direction == sdFront ? 1 : -1;
	TMountains::const_iterator Start = Direction == sdFront ? Left : Right;
	const TMountains::const_iterator End = Direction == sdFront ? Right : Left;
	const TMountains::const_iterator Boundary = Direction == sdFront ? Mountains.end() - 1 : Mountains.begin();

	TMountains::const_iterator Highest = Start;

	for(TMountains::const_iterator It = Start; It != End;It += Vector)
	{
		if((*It).Height > (*Highest).Height) Highest = It;
	}
	return Highest;
}

int MeasureLake(const IntVector& HeightList,int Edge,ScanDirection Direction)
{
	int Vector = Direction == sdFront ? 1 : -1;
	const int LakesideHeight = HeightList[Edge];
	int Position = Edge + Vector;
	int Size = 0;
	while(Size == 0 || HeightList[Position] < LakesideHeight)
	{
		Size += 2 * LakesideHeight - HeightList[Position] - HeightList[Position - Vector];
		Position += Vector;
	}
	return (Size + 1)/2;
}

typedef std::deque<int> TLakes;

int GetTotal(const TLakes& ALakes)
{
	TLakes Lakes = ALakes;
	int Size = 0;
	for(unsigned int i= 0;i<ALakes.size();i++)
	{
		Size += Lakes.front();
		Lakes.pop_front();
	}
	return Size;
}

int main()
{
	GroundShapes ShapeList;
	Input(ShapeList);
	IntVector HeightList;
	CreateHeightList(HeightList,ShapeList);

	TMountains MountainList;
	CreateMountains(MountainList,ShapeList,HeightList);

	TMountains::const_iterator Highest = GetHighest(MountainList,MountainList.begin(),MountainList.end(),sdFront);
	std::cout << "step1" << std::endl;

	TLakes Lakes;
	TMountains::const_iterator HighestLeft = Highest;
	while(HighestLeft != MountainList.end() - 1)
	{
		HighestLeft = GetHighest(MountainList,HighestLeft + 1,MountainList.end(),sdFront);
		Lakes.push_back(MeasureLake(HeightList,(*HighestLeft).Position,sdBack));
	}
	std::cout << "step2" << std::endl;

	while(Highest != MountainList.begin())
	{
		Highest = GetHighest(MountainList,MountainList.begin(),Highest - 1,sdBack);
		Lakes.push_front(MeasureLake(HeightList,(*Highest).Position,sdFront));
	}

	std::cout << GetTotal(Lakes) << std::endl;
	int LakeCount = Lakes.size();
	std::cout << LakeCount << std::flush;
	for(int i=0;i<LakeCount;i++)
	{
		std::cout << " " << std::flush;
		std::cout << Lakes.front() << std::flush;
		Lakes.pop_front();
	}

	std::cout << std::endl;

	return 0;
}

