int Terrain(char* ascii, int len, int p, int q){
  int depth = 0, i;
  double b = 0;

  for(i = p; i < q; i++){
    if(ascii[i] == '/'){
      b += (double)depth - 0.5;
      depth--;
    }
    if(ascii[i] == '\\'){
      b += (double)depth + 0.5;
      depth++;
    }
    if(ascii[i] == '_'){
      b += depth;
    }
  }
  return b;
}

