{
	d->next = *p;
	*p = d;
}

ST_FOUNTAIN *pop(ST_FOUNTAIN **p)
{
	ST_FOUNTAIN *d = *p;
	if(d != NULL)
	{
		*p = (*p)->next;
	}

	return d;
}

int main()
{
	char ch;
	int area;
	int plane;
	int total;
	int count;
	int loop;
