	{
		if(ch == '\\')
		{
			d = (ST_FOUNTAIN*)malloc(sizeof(ST_FOUNTAIN));
			d->area = 0;
			d->plane = 0;
			push(&w1, d);
		}
		else if(ch == '_')
		{
			d = pop(&w1);
			if (d != NULL)
			{
				d->plane++;
				push(&w1, d);
			}
			else
			{
				/* error process */
			}
		}
		else if(ch == '/')
		{
			area = plane = 0;
