			{
				while((d = pop(&w2)) != NULL) push(&w1, d);
			}
		}
		else
		{
		}
	}

	total = count = 0;
	while((d = pop(&w1)) != NULL)
	{
		if(d->area == 0)
		{
			free(d);
			continue;
		}

		total += d->area;
		count++;
		push(&w2, d);
	}

	printf("%d\n", total);
