    int index;
    int subtotal;
} Stack2;

Stack1 stack1[STACK_SIZE];
Stack2 stack2[STACK_SIZE];
Stack2 subtotal[STACK_SIZE];
int top1, top2, subtotal_top;

void push1(int _index, char _slope){
    stack1[++top1].index = _index;
    stack1[top1].slope = _slope;
}

void push2(int _index, int _subtotal){
    stack2[++top2].index = _index;
    stack2[top2].subtotal = _subtotal;
}

void push_subtotal(int _index, int _subtotal) {
    subtotal[++subtotal_top].index = _index;
    subtotal[subtotal_top].subtotal = _subtotal;
}

Stack1 pop1(){
    top1--;
    return stack1[top1 + 1];
}

Stack2 pop2(){
    top2--;
    return stack2[top2 + 1];
}

Stack2 pop_subtotal(){
    subtotal_top--;
    return subtotal[subtotal_top + 1];
}

