{
    int i, sum, subtotal;
    top1 = -1;
    top2 = -1;
    subtotal_top = -1;
    char input[STACK_SIZE];

    i = 0;
    sum = 0;
    subtotal = 0;

    scanf("%s", input);

    while(input[i] != '\0'){
        if (input[i] == '\\'){
            push1(i, input[i]); // stack1にiをpush
        } else if (input[i] == '/') {
            while(top1 >= 0) {
                Stack1 stack1_top = pop1();
                if (stack1_top.slope == '\\') {
                    sum += (i - stack1_top.index);
                    push2(stack1_top.index, i - stack1_top.index);

                    break;
                }

            }
        }
        i++;
    }

    int j = 0;

    if (top2 >= 0) {
        Stack2 tmp = pop2();
        int min_index = tmp.index;
        subtotal = tmp.subtotal;

        while (top2 >= 0) {
            Stack2 stack2 = pop2();

            if (min_index > stack2.index) {
                push_subtotal(min_index, subtotal);
                subtotal = 0;
                min_index = stack2.index;
                subtotal = stack2.subtotal;
            } else if (min_index < stack2.index) {
                subtotal += stack2.subtotal;
            }
        }
        push_subtotal(min_index, subtotal);
    }

    printf("%d\n", sum);
    printf("%d", subtotal_top + 1);
     while (subtotal_top >= 0) {
        if (subtotal_top >= 0) printf(" ");
        Stack2 output_subtotal = pop_subtotal();
        printf("%d", output_subtotal.subtotal);
    }
    printf("\n");

    return 0;
}

