			sum += i-j;
			// st2_j と st2_a を用いて水たまりの水量を更新
			int a = i - j;   // 更新する水たまりの水量を a に格納していく
			while (!isEmpty(&st2_j) && st2_j.S[st2_j.top] > j) {  // 最も左の '\' の位置が j よりも大きい場合，以下を繰り返す
				// 水たまりの水量を求めていく (write your code)
