int chLake(int staMap, int endMap, const struct _map* stMap, int nDepth){
  int a=0;
  int m;
  for(m=staMap;m<=endMap;m++){
    if(stMap[m].chMap=='\\'){
      a = a + 1 + (nDepth - stMap[m].nDepth) * 2;
    }
    else if(stMap[m].chMap=='_'){
      a = a + 2 + (nDepth - stMap[m].nDepth) * 2;
    }
    else if(stMap[m].chMap=='/'){
      a = a + 1 + (nDepth - stMap[m].nDepth) * 2;
    }
  }
  return (a);
}

#include<stdio.h>
#include<stdlib.h>
#define MAX 20000  // スタックの最大値

typedef struct{
  int top;         // スタックポインタ(一番上の位置)
  int S[MAX];
}Stack;


// スタック st の初期化
void initialize(Stack *st)
{
  st->top = 0;
  st->S[st->top] = 0;
}

// スタック st が空かどうかを確認
int isEmpty(Stack *st)
{
  return st->top == 0;
}

// スタック st が一杯かどうかを確認
int isFull(Stack *st)
{  
  return st->top >= MAX - 1;
}

// スタック st に要素 x をプッシュ(一番上に要素を追加)
void push(int x, Stack *st)
{
  if (isFull(st)) 
    exit(1);

  st->top++;
  st->S[st->top] = x;
}

// スタック st から要素をポップ(一番上の要素を取り出す)
int pop(Stack *st) {
  if (isEmpty(st)) 
    exit(1);

  st->top--;
  return st->S[st->top+1];
}


