typedef struct {
	int location;
	int size;
} pool;

int top_s2;
pool S2[MAXLEN];

void initialize();
int isEmpty();
int isFull();
void push(int x);
int pop();

void initializeS2();
int isEmptyS2();
int isFullS2();
void pushS2(pool S2);
pool popS2();


int main() {
	int i, j;
	int sum, tmp;
	pool s2, tmp_s2;
	scanf("%s", AREA);
	sum = 0;
	initialize();
	initializeS2();
	for (i = 0; AREA[i] != '\0'; ++i) {
		switch(AREA[i]) {
		case '\\':
			push(i);
			break;
		case '/':
			if (isEmpty()) continue;
			j = pop();
			tmp = (i - j);
			sum += tmp;
			if (isEmptyS2()) {
				s2.location = j;
				s2.size = tmp;
				pushS2(s2);
			} else {
				tmp_s2 = popS2();
				while (tmp_s2.location > j ) {
					tmp += tmp_s2.size;
					if (isEmptyS2()) break;
					tmp_s2 = popS2();
				}
				if (tmp_s2.location < j) {
					pushS2(tmp_s2);
				}
				s2.location = j;
				s2.size =  tmp;
				pushS2(s2);
			}
			break;
		case '_':
			break;
		}
	}
	printf("%d\n", sum);
	j = 1;
	s2 = popS2();
	S[0] = s2.size;
	while (!isEmptyS2()) {
		s2 = popS2();
		S[j] = s2.size;
		++j;
	}
	printf("%d ", j);
	for (i = 0; i < j; ++i) {
		if (i != j - 1) {
			printf("%d ", S[j-1-i]);
		} else {
			printf("%d\n", S[j - 1 - i]);
		}
	}
	return 0;
}

void initialize() {
	top = 0;
	return;
}

int isEmpty() {
	return top == 0;
}

int isFull() {
	return top >= MAXLEN - 1;
}

void push(int x) {
	if (isFull()) {
		printf("Over Flow\n");
		exit(-1);
	}

	top++;
	S[top] = x;
}

int pop() {
	if (isEmpty()) {
		exit(-1);
	}
	top--;
	return S[top+1];
}


void initializeS2() {
	top_s2 = 0;
	return;
}

int isEmptyS2() {
	return top_s2 == 0;
}

int isFullS2() {
	return top_s2 >= MAXLEN - 1;
}

void pushS2(pool new) {
	if (isFullS2()) {
		printf("Over Flow S2\n");
		exit(-1);
	}
//	printf("new %d %d %d\n", new.location, new.size, top_s2);
	top_s2++;
	S2[top_s2] = new;
}

pool popS2() {
	if (isEmptyS2()) {
		printf("Under Flow S2\n");
	}
	top_s2--;
	return S2[top_s2+1];
}

#include<stdio.h>

#define MAXLEN 20000

int area, areas[(MAXLEN/2)+1],cnt;

int getArea( char *areastr, int start, int maxh )
{
	int i;
	int ravine,squre;
	int up,down;

	up=down=0;
	areas[cnt]=squre=ravine=0;
	for( i=start; '\0'!=*(areastr+i); i++ ) {
		if( '\\'== *(areastr+i) ) {
			ravine++;
			if( 0 < up ) {
				down++;		
			}		
		} else if( 0 < ravine && '/' == *(areastr+i) ) {
			if( 0 < down ) {
				areas[cnt]-=(down*down);
				areas[cnt]-=(down*2)*(maxh-ravine);
				up=down=0;
			}
			ravine--;		
			up++;
			if( 0 == ravine ) {
				squre=(i-start+1)*maxh;
				areas[cnt]+=squre;
				areas[cnt]-=(maxh*maxh);
				break;
			}			
		} else {
			areas[cnt]-=(maxh-ravine);
		}
	}
	return areas[cnt];
}


int checkRavine( char *checkstr, int start )
{
	int i,j;
	int ravine,maxh;

	ravine=maxh=0;
	for( i=start, j=0; '\0'!=*(checkstr+i) &&  j<100; i++, j++ ) {
		if( '\\'== *(checkstr+i) ) {
			ravine++;
		} else if( 0 < ravine && '/' == *(checkstr+i) ) {
			if( maxh < ravine ) { maxh=ravine; }		
			ravine--;
			if( 0 == ravine ) {
				area+=getArea( checkstr, start, maxh );
				cnt++;
				return j;
			}			
		}
	}

	return 0;
}

void getAreas( char *inputs )
{
	int i,next;

	next=cnt=0;
	for( i=0; '\0'!=inputs[i]; i++ ) {
		next=checkRavine( inputs, i );
		i+=next;
	}

	return;
}

