  char s[20000];

  scanf("%s",s);
  for(i=0;s[i]!='\0';i++){
    if(stack_size<=0 && s[i]=='/'){
      continue;
    }
    else if(s[i]==92){
      push(i);
    }
    else if(s[i]=='/'){
      n=pop();
      if(n>k1[k_size-1] || k_size==0){
	k1[k_size]=n;
	k2[k_size]=i-n;
	k_size++;
      }
      else{
	k1[k_size-1]=n;
	k2[k_size-1]=i-n+k2[k_size-1];
	while(k1[k_size-1]<k1[k_size-2] && k_size>=2){
	  k1[k_size-2]=k1[k_size-1];
	  k2[k_size-2]=k2[k_size-1]+k2[k_size-2];
	  k_size--;
	}
      }
    }
  }
  for(i=0;i<k_size;i++){
    res[i]=k2[i];
    total+=k2[i];
  }
  printf("%d\n",total);
  printf("%d ",k_size);
  for(i=0;i<k_size;i++){
    if(i==k_size-1) printf("%d \n",res[i]);
    else printf("%d ",res[i]);
  }

  return 0;
}
int pop(){
  if(stack_size<=0) return 0;
  return stack[--stack_size];
}
void push(int i){
  stack[stack_size]=i;
  stack_size++;
}

