			    //printf("aaaaa\n");
			    break;

			case '_':
			    mountain.data[mountain.point] = -1;
			    mountain.point++;
			    break;

			case '/':
			    location_downhill = whereDownHill(&mountain);
			    if ( location_downhill >= 0 ) {
			        calculateWater(&mountain, &width);
			    }
