   for(i = 0 ; i < top2 - 1 ; i++) printf("%d ", Stack2[i].S);
   printf("%d\n", Stack2[top2-1].S);
 }

return 0;
}

#define LENGTH 25000

int mennseki(char *ascii,int length,int p,int q) {
	int hukami = 0,i;
	double a =0;

	for(i = p; i < q; i++) {
		if(ascii[i] == '/') {
			a += (double)hukami - 0.5;
			hukami--;
		} else if (ascii[i] == '\\') {
			a +=(double)hukami + 0.5;
			hukami++;
		} else if(ascii[i] =='_') {
			a += hukami;
		}
	}
	return a;
}

int main(void) {
	char ascii[LENGTH];
	int i,length,dis;
	int sum=0,num=0,alt=0,j=0;
    int height[LENGTH] = {0};
	int width[LENGTH] = {0};
	scanf("%s",ascii);

	for(length = 0; ascii[length] == '\0'; length++) {
		height[length] = alt;
		if(ascii[length] =='/') {
			alt++;
		} else if(ascii[length] == '\\') {
			alt--;
		} 
	}

	while(num < length) {
		while(ascii[num] != '\\' && num < length) {
			num++;
		}
		dis= num + 1;
		while(dis <= length && height[dis] != height[num]) {
			dis++;
		}
		if(dis <= length) {
			width[j++] = mennseki(ascii,length,num,dis);
			num = dis;
		} else {
			num++;
		}
	}

	printf("%d\n%d", sum, j);

  for(i = 0; i < j; i++){
    printf(" %d", width[i]);
  }
  printf("\n");

  return 0;
}

#include <stdio.h>

#define LEN 25000

int Terrain(char* ascii, int len, int p, int q){
  int depth = 0, i;
  double b = 0;

  for(i = p; i < q; i++){
    if(ascii[i] == 0x2f){
      b += (double)depth - 0.5;
      depth--;
    }
    if(ascii[i] == 0x5c){
      b += (double)depth + 0.5;
      depth++;
    }
    if(ascii[i] == 0x5f){
      b += depth;
    }
  }
  return b;
}

 int main(){
  char ascii[LEN];
  int i, len, det;
  int sum = 0, alt = 0, pl = 0, stk = 0;
