	if(list->root==NULL){
		list->root=input;
		list->last=input;
	}
	else{
		list->root->prev=input;
		input->next=list->root;
		list->root=input;
	}
	list->size++;
	list->csum+=key;
}


void append(dlist *list1,dlist *list2){
	if(list2->size==0){
		return;
	}
	if(list1->last==NULL){
		list1->root=list2->root;
		list1->last=list2->last;
	}
	else{
		list1->last->next=list2->root;
		list2->root->prev=list1->last;
		list1->last=list2->last;
	}
	list1->size+=list2->size;
	list1->csum+=list2->csum;
	list2->root=NULL;
	list2->last=NULL;
}

obj *deleteF(dlist *list){
	obj *output;
	if(list->root==NULL){
		return NULL;
	}
	else{
		output=list->root;
		if(list->root->next==NULL){
			list->root=NULL;
			list->last=NULL;
		}
		else{
			list->root=list->root->next;
			list->root->prev=NULL;
		}
		return output;
	}
}

void reverse(dlist *list,dlist *slist){
	int cumH,sum,c1;
	obj *ob;
	dlist *blist;
	blist=createDlist();
	cumH=0;
	sum=0;
	ob=deleteF(list);
	while(1){
		if(ob==NULL){break;}
		c1=ob->key;
		if(c1==1){
			sum+=2*cumH+1;
			cumH++;
		}else{
		if(c1==0){
			sum+=2*cumH;
		}else{
		if(c1==-1){
			if(cumH!=0){
				sum+=2*cumH-1;
				cumH--;
				if(cumH==0){
					insert(blist,sum/2);
					sum==0;
				}
			}
		}}}
		ob=deleteF(list);
	}
	append(slist,blist);
}



