#define LEN 20001

int Terrain(char* ascii, int len, int p, int q){
  int depth = 0, i;
  double b = 0;

  for(i = p; i < q; i++){
    if(ascii[i] == 0x2f){
      b += (double)depth - 0.5;
      depth--;
    }
    if(ascii[i] == 0x5c){
      b += (double)depth + 0.5;
      depth++;
    }
    if(ascii[i] == 0x5f){
      b += depth;
    }
  }
  return b;
}

