  scanf("%s", ascii);
  for(len = 0; ; len++){
    height[len] = alt;
    if(ascii[len] == 0x2f){
      alt++;
    }
    if(ascii[len] == 0x5c){
      alt--;
    }
    if(ascii[len] == 0x0a){
      break;
    }
  }

  while(pl < len){
    while(ascii[pl] != 0x5c && pl < len){
      pl++;
    }
    det = pl+1;
    while(det <= len && height[det] != height[pl]){
      det++;
    }
    if(det <= len){
