#include<stdio.h>

#define MAXLEN 20000

int garea,gareas[(MAXLEN/2)+1],gcnt;


int getArea( char *inputs, int start )
{
    int i,j;
    int ravine,water;
    int down;

    gareas[gcnt]=water=ravine=down=0;
    for( i=start, j=0; '\0'!=*(inputs+i) &&  j<MAXLEN; i++, j++ ) {
        if( '\\'== *(inputs+i) ) {
            water+=(ravine*2);
            ravine++;
            water++;
        } else if( 0 < ravine && '/' == *(inputs+i) ) {   
            ravine--;
            if( 0 == ravine ) {
                gareas[gcnt]+=water;
                garea+=gareas[gcnt];
                gcnt++;
                return j;
            }           
        } else {
	     	gareas[gcnt]+=ravine;
        }       
    }

    return 0;
}

void getAreas( char *inputs )
{
    int i,next;

    next=0;
    for( i=0; '\0'!=inputs[i]; i++ ) {
        next=getArea( inputs, i );
        i+=next;
    }

    return;
}

