	k1[k_size]=n;
	k2[k_size]=i-n;
	k_size++;
      }
      else{
	k1[k_size-1]=n;
	k2[k_size-1]=i-n+k2[k_size-1];
	while(k1[k_size-1]<k1[k_size-2] && k_size>=2){
	  k1[k_size-2]=k1[k_size-1];
	  k2[k_size-2]=k2[k_size-1]+k2[k_size-2];
	  k_size--;
	}
      }
    }
  }
  for(i=0;i<k_size;i++){
    total+=k2[i];
  }
  printf("%d\n",total);
  if(k_size==0) printf("%d\n",k_size);
