typedef struct{
    int s1;
    int area;
}stack2;
typedef struct{
    stack2 *s2;
    int count2;
    int size2;
}STACK2;
void updateS2(STACK2 *S2,int s,int area){
    if(S2->count2==0){
        S2->s2[0].s1=s;
        S2->s2[0].area=area;
        S2->count2++;
        return;
    }

    if(S2->count2>=S2->size2){
        while(S2->count2>0&&S2->s2[S2->count2-1].s1>s){
            if(S2->s2[S2->count2-1].area==-1)break;
            area=area+S2->s2[S2->count2-1].area;
            S2->s2[S2->count2-1].area=-1;
            S2->count2--;
        }
    }else{
        while(S2->count2>=0&&S2->s2[S2->count2].s1>s){
            if(S2->s2[S2->count2].area==-1)break;
            area=area+S2->s2[S2->count2].area;
            S2->s2[S2->count2].area=-1;
            S2->count2--;
        }
    }

    if(S2->count2>=S2->size2){
        S2->size2++;
        S2->s2=(stack2*)realloc(S2->s2,sizeof(stack2)*S2->size2);
        S2->s2[S2->count2].s1=s;
        S2->s2[S2->count2].area=area;
        S2->count2++;
    }else{
        if(S2->count2<0)S2->count2=0;
        S2->s2[S2->count2].s1=s;
        S2->s2[S2->count2].area=area;
        S2->count2++;
    }
}

