#include<stdio.h>

#define MAXLEN 20000

int area, areas[(MAXLEN/2)+1],cnt;

int getArea( char *areastr, int start, int maxh )
{
    int i;
    int ravine,squre;
    int up,down,preup,predown;

    preup=predown=up=down=0;
    areas[cnt]=squre=ravine=0;
    for( i=start; '\0'!=*(areastr+i); i++ ) {
        if( '\\'== *(areastr+i) ) {
            ravine++;
            if( 0 < up ) {
                down++;
                if( up == down ) {
                    areas[cnt]-=(down*down);
                    areas[cnt]-=(down*2)*(maxh-ravine);
                    up=down=0;
                }
            } else if( up == 0 && 0 < preup ) {
                predown++;
                if( preup == predown ) {
                    areas[cnt]-=(predown*predown);
                    areas[cnt]-=(predown*2)*(maxh-ravine);
                    preup=predown=0;
                }
            } 
        } else if( 0 < ravine && '/' == *(areastr+i) ) {
            if( 0 < down ) {
                areas[cnt]-=(down*down);
                areas[cnt]-=(down*2)*(maxh-ravine);
                 if( preup == 0 ) {
                	preup=up-down;
                }
                up=down=0;
            }
            ravine--;
            up++;
            if( 0 == ravine ) {
                squre=(i-start+1)*maxh;
                areas[cnt]+=squre;
                areas[cnt]-=(maxh*maxh);
                break;
            }           
        } else {
            areas[cnt]-=(maxh-ravine);
        }
    }
    return areas[cnt];
}


