{
    int i,j;
    int ravine,maxh;

    ravine=maxh=0;
    for( i=start, j=0; '\0'!=*(checkstr+i) &&  j<100; i++, j++ ) {
        if( '\\'== *(checkstr+i) ) {

            ravine++;
        } else if( 0 < ravine && '/' == *(checkstr+i) ) {

            if( maxh < ravine ) { maxh=ravine; }     
            ravine--;
            if( 0 == ravine ) {
                area+=getArea( checkstr, start, maxh );
                cnt++;
                return j;
            }           
        }
    }

    return 0;
}

