}
void calcDamage(char *str)
{
  int i;//counter
  int x=0,y=0;//current position
  int p[N];//array of depth
  p[0]=0;
  int mindepth=0;//minimum depth (default: 0)
  damage temp;
  for(x=1;x<=strlen(str);x++)
    {
      switch(str[x])
        {
        case '\\':
          y--;
          p[x]=y;
          #ifdef DEBUG
          printf("(%d,%d)\n",x,y);//debugging
          #endif
          break;
        case '/':
          y++;
          p[x]=y;
          #ifdef DEBUG
          printf("(%d,%d)\n",x,y);//debugging
          #endif
          if(y>mindepth) mindepth=y;
          else
            {
              for(i=x-1;i>=0;i--)
                {
                  if(p[i]==y) break;
                }
              if(i>=0)
                {
                  temp.x[0]=i;
                  temp.x[1]=x;
                  temp.depth=y;
                  temp.area=((x-i)+(x-i-2))/2;
                  #ifdef DEBUG
                  printf("push->%d,%d,%d,%d\n",temp.x[0],temp.x[1],temp.depth,temp.area);//debugging
                  #endif
                  push(temp);
                }
            }
          break;
        case '_':
          p[x]=y;
          #ifdef DEBUG
          printf("(%d,%d)\n",x,y);//debugging
          #endif
          break;
        }
    }
}
void push(damage d)
{
  damage p;//poped element
  while(top>0)
    {
      p=pop();
      if(p.x[0]>d.x[0]&&p.x[1]<d.x[1])
        {
          d.area+=p.area;
          #ifdef DEBUG
          printf(" merged->%d,%d,%d,%d\n",d.x[0],d.x[1],d.depth,d.area);//debugging
          #endif
        }
      else break;
    }
  top++;
  stack[top]=d;
}
damage pop(void)
{
  top--;
  return stack[top+1];
}
void printStack(void)
{
  int i=0;//counter
  int sum=0;//sum of damage
  for(i=1;i<=top;i++) sum+=stack[i].area;
  printf("%d\n",sum);
  printf("%d",top);
  for(i=1;i<=top;i++) printf(" %d",stack[i].area);
  printf("\n");
}

