        int s=0;
        for(int i=first;i<last;i++){
            if(high[i]>high[i+1]){
                s+=((high[first]-high[i+1])*2-1);
            }else if(high[i]==high[i+1]){
                s+=(high[first]-high[i])*2;
            }else{
                s+=((high[first]-high[i])*2-1);
            }
        }
        return s/2;
    }
