    if(ascii[i] == 0x2f){
      b += (double)depth - 0.5;
      depth--;
    }
    if(ascii[i] == 0x5c){
      b += (double)depth + 0.5;
      depth++;
    }
    if(ascii[i] == 0x5f){
      b += depth;
    }
  }
  return b;
}

