  while( (c = s[k++]) != '\0'){
    if(pre == '/'){
      if(c == '\\')j++;
      else{ i--; j++; }
    }

    else if(pre == '\\'){
      if(c == '\\'){ i++; j++; }
      else j++;
    }

    else{
      if(c == '\\'){ i++; j++; }
      else j++;
    }

    map[i][j] = c;
