  for(j = 0; j < last; j++){

    if(map[i][j] == '\\'){
      tmp = existPool(i,j);
      if(tmp > j){
	pool[n] = getArea(i,j,tmp);
	n++;
	k = tmp;
	setNext(&i,&k);
	j = tmp;
      }

      else{
	k = j;
	setNext(&i,&k);
      }
    }

    else{
      k = j;
      setNext(&i,&k);
    }

  }

  //output

