int existPool(int y, int x){
  int j = x, result = 0;

  while(1){
    j++;
    if(map[y][j] == '/'){
      result = 1;
      break;
    }
    if(j >= last-1) break;
  }

  if(result) return j;
  else return x;
}

int getArea(int y, int x0,int xt){
  int i = y, j, k, result = 0, harf = 0;

  for(j = x0; j <= xt; j++){
    if( (map[i][j] == '\\') || (map[i][j] == '/') ){
      result += (i-y);
      harf++;
    }
    else{
      result += (i-y+1);
    }

    k = j;
    setNext(&i,&k);
  }

  result += (harf/2);

  return result;
}

void setNext(int* i, int* j){
  int x, y;

  y = *i;
  x = *j;

    if(map[y][x] == '\\'){
      if(map[y+1][x+1] == '\\'){
	y++;
	x++;
      }
      else x++;
    }

    else if(map[y][x] == '/'){
      if(map[y][x+1] == '\\') x++;
      else{
	y--;
	x++;
      }
    }

    else{
      if(map[y+1][x+1] == '\\'){
	y++;
	x++;
      }
      else x++;
    }

    *i = y;
    *j = x;

}

