            if(size1<=count1){
                size1++;
                stack1=(int*)realloc(stack1,sizeof(int)*size1);
                stack1[count1]=i;
                count1++;
            }else if(size1>count1){
                if(count1<0)count1=0;
                stack1[count1]=i;
                count1++;
            }
        }else if(c=='/'){
            count1--;
            if(count1>=0){  //count1が負のときスタック1は空
                s=stack1[count1];
                area=i-s;
