    else if((isLake==1)&&(stMap[m].chMap=='_')){
      sumArea=sumArea+2;
      while(m!=s)
	sumArea=sumArea+chLake(&s, (m-1), stMap, nDepth-1);
      s = m+1;
    }
    else if((isLake==1)&&(stMap[m].chMap=='/')){
      sumArea=sumArea+1;
