  int S[MAX];
}Stack;

void initialize(Stack *st)
{
  st->top = 0;
  st->S[st->top] = 0;
}

int isEmpty(Stack *st)
{
  return st->top == 0;
}

int isFull(Stack *st)
{  
  return st->top >= MAX - 1;
}

void push(int x, Stack *st)
{
  if (isFull(st)) 
    exit(1);

  st->top++;
  st->S[st->top] = x;
}

int pop(Stack *st) {
  if (isEmpty(st)) exit(1);

  st->top--;
  return st->S[st->top+1];
}


