int isEmpty(){
  return top == 0;
}

int isFull(){
  return MAX - 1 <= top;
}

int push(x){
  if (isFull())
    puts("over flow");
  top++;
  dipth[top] = x;
  return 0;
}

int pop(){
  if (isEmpty())
    puts("under flow");
  top--;
  return dipth[top + 1];
}

int addWidth(){
  for (d = 1; d <= top; d++)
    width[d]++;
  return 0;
}

int calculate(){
  if (width[top] == 2)
    // triangle
    return width[top] * 1 / 2;
  else
    // trapezoid
    return (width[top] + width[top] - 2) * 1 / 2;
}

