      push(1);
      addWidth();
      break;
    case '/':
      if (isEmpty())
	break;
      addWidth();
      tmpArea += calculate();
      width[top] = 0;
      pop();
      if (top == 0) {
	area[i] = tmpArea;
	tmpArea = 0;
	i++;
      }
      break;
    case '_':
      addWidth();
      break;
