      return (sumArea);
    }
    else if((isLake==0)&&(stMap[m].chMap=='_')){
      s = m+1;
    }
    else if((isLake==0)&&(stMap[m].chMap=='/')){
      while(m!=s)
	sumArea = chLake(&s, (m-1), stMap, nDepth-1);
