void push(unsigned int line_area, unsigned int *stack, int *tail)
{
    stack[++(*tail)] = line_area; 
}

unsigned int pop(unsigned int *stack, int *tail)
{
    if(*tail < 0)
        return 0;

    return stack[(*tail)--];
}

