typedef struct stack{
  int f;
  int s;
} Sta;

void push(int S[], int x, int *top){
  S[(*top)++] = x;
}

int pop(int S[], int *top){
  (*top)--;
  return S[*top];
}

void push2(Sta S[], int x, int y, int *top){
  S[*top].f = x;
  S[(*top)++].s = y;
}

void uni(Sta S[], int *top){
  int i;

  for( i = (*top)-1 ; i > 0 ; i-- ){
    if( S[i].f < S[i-1].f ){
      (*top)--;
      S[i-1].f = S[i].f;
      S[i-1].s += S[i].s;
    }
  }
}


