  int i = 0, res = 0, h = 0,  c;

  while((c = s[i++]) != '\n' && c != '\0'){
    switch(c){
    case '\\':
      push_front(&top, i, 0);
      push_front(&sq, 0, h);
      h--;
      break;
    case '_':
      break;
    case '/':
      h++;
      if(!is_empty(top)){
        int tmp = pop_front(&top);
        res += i - tmp;
        int h2;
        tmp = i - tmp;
        while(!is_empty(sq) && (h2 = sq->hight) < h){
          tmp += pop_front(&sq);
          if(h2 == h){
            break;
          }
        }
        push_front(&sq, tmp, h);
      }
      break;
    default:
      break;
    }
  }

  printf("%d\n", res);
  //print_list(sq);
  int ans[MAXN] = {0}, j = 0;
