                                a += S2.area.last -> data;
                                Pop_back(&(S2.pair.head), &(S2.pair.last));
                                Pop_back(&(S2.area.head), &(S2.area.last));
                                count--;
                        }
                        Push_back(&(S2.pair.head), &(S2.pair.last), j);
