void Push_back(stack **head, stack **last, int data)
{
        stack *p;
        if((p = (stack*)malloc(sizeof(stack))) == NULL){
                fprintf(stderr, "Memory cannot allocate\n");
                exit(0);
        }
        p -> data = data;
        p -> next = NULL;
        p -> prev = *last;
        if(*head == NULL){
                        *head = p;
        }else{
                        (*last) -> next = p;
        }
        *last = p;
}
int Pop_back(stack **head, stack **last)
{
        int pop_data;
        stack *p = *last;
        if(*head == NULL){
                return EOF;
        }
        pop_data = (*last) -> data;
        if((*last) -> prev == NULL){
                *head = NULL;
        }else{
                        (*last) -> prev -> next = NULL;
        }
                *last = (*last) -> prev;
        free(p);
        return pop_data;
}

