int min(int x, int y) { return x < y ? x : y; }
int max(int x, int y) { return x > y ? x : y; }

int area_type(char c)
{
	switch(c)
	{
		case '\\':
			return -1;

		case '/':
			return +1;
	}
	return 0;
}

int main()
{
	int  n, m, tmp, ans;
	int  a[10000];
	int  w[20001];
	int  g[20001];
	char s[20001];

	scanf("%s", s);
	n = strlen(s);

	g[0] = 0;
	for(int i = 0; i < n; ++i)
	{
		g[i+1] = g[i] + area_type(s[i]);
	}

	tmp = w[0] = g[0];
	for(int i = 1; i <= n; ++i)
	{
		tmp = max(tmp, g[i]);
		w[i] = tmp;
	}

	tmp = w[n] = g[n];
	for(int i = n-1; i >= 0; --i)
	{
		tmp = max(tmp, g[i]);
		w[i] = min(w[i], tmp);
	}

	tmp = ans = m = 0;
	for(int i = 1; i <= n; ++i)
	{
		tmp += (w[i-1]-g[i-1])+(w[i]-g[i]);
		if((w[i] == g[i]) && tmp)
		{
			tmp /= 2;
			ans += tmp;
			a[m++] = tmp;
			tmp = 0;
		}
	}

	printf("%d\n%d", ans, m);
	for(int i = 0; i < m; ++i)
	{
		printf(" %d", a[i]);
	}
	printf("\n");
}

#include<stdio.h>

#define MAXLEN 20000

int area, areas[(MAXLEN/2)+1],cnt;

int getArea( char *areastr, int start, int maxh )
{
	int i;
	int ravine,squre;
	int up,down;

	up=down=0;
	areas[cnt]=squre=ravine=0;
	for( i=start; '\0'!=*(areastr+i); i++ ) {
		if( '\\'== *(areastr+i) ) {
			ravine++;
			if( 0 < up ) {
				down++;
				if( up == down ) {
					areas[cnt]-=(down*down);
					areas[cnt]-=(down*2)*(maxh-ravine);
					up=down=0;
				}
			}		
		} else if( 0 < ravine && '/' == *(areastr+i) ) {
			if( 0 < down ) {
				areas[cnt]-=(down*down);
				areas[cnt]-=(down*2)*(maxh-ravine);
				up=down=0;
			}
			ravine--;
			up++;
			if( 0 == ravine ) {
				squre=(i-start+1)*maxh;
				areas[cnt]+=squre;
				areas[cnt]-=(maxh*maxh);
				break;
			}			
		} else {
			areas[cnt]-=(maxh-ravine);
		}
	}
	return areas[cnt];
}


int checkRavine( char *checkstr, int start )
{
	int i,j;
	int ravine,maxh;

	ravine=maxh=0;
	for( i=start, j=0; '\0'!=*(checkstr+i) &&  j<100; i++, j++ ) {
		if( '\\'== *(checkstr+i) ) {

			ravine++;
		} else if( 0 < ravine && '/' == *(checkstr+i) ) {

			if( maxh < ravine ) { maxh=ravine; }		
			ravine--;
			if( 0 == ravine ) {
				area+=getArea( checkstr, start, maxh );
				cnt++;
				return j;
			}			
		}
	}

	return 0;
}

void getAreas( char *inputs )
{
	int i,next;

	next=cnt=0;
	for( i=0; '\0'!=inputs[i]; i++ ) {
		next=checkRavine( inputs, i );
		i+=next;
	}

	return;
}

int main( void ) 
{
    char inputs[MAXLEN+1];

	scanf( "%s", inputs );
	area=cnt=0;
	getAreas( inputs );

	printf( "%d\n", area );
	printf( "%d ", cnt );	

	int i;
	for( i=0; i<cnt; i++ ) {
		printf( "%d", areas[i] );
		if( i < (cnt-1) ) { printf( " " ); }
	}
	printf( "\n" );	

	return 0;
}

