int getArea( char *inputs, int start, int end )
{
    int i;
    int ravine,water;

    gareas[gcnt]=ravine=water=0;
    for( i=start; i!=end; i++ ) {
        if( '\\'== *(inputs+i) ) {
            ravine++;
            water++;
           	water+=((ravine-1)*2);
        } else if( 0 != ravine && '/' == *(inputs+i) ) {
        	ravine--;
        } else {
	     	gareas[gcnt]+=ravine;
        }       
    }
	gareas[gcnt]+=water;

    return gareas[gcnt];
}

int checkRavine( char *inputs, int start )
{
    int i;
    int ravine;

    ravine=0;
    for( i=start; '\0'!=*(inputs+i); i++ ) {
        if( '\\'== *(inputs+i) ) {
            ravine++;
        } else if( 0 != ravine && '/' == *(inputs+i) ) {   
            ravine--;
            if( 0 == ravine ) {
            	garea+=getArea( inputs, start, i+1 );
            	gcnt++;
                return i-start;
            }           
        }
    }
    return 0;
}


void getAreas( char *inputs )
{
    int i,next;

    next=0;
    for( i=0; '\0'!=inputs[i]; i++ ) {
        next=checkRavine( inputs, i );
        i+=next;
    }

    return;
}

