  while ((c = fgetc(stdin)) != '\n') {
    switch (c) {
    case '\\':
      low++;
      width++;
      break;
    case '/':
      if (low) {
	up++;
	width++;
      }
      break;
    case '_':
      if (low && !up) {
	trapzoid++;
	width++;
      }
      else if (low && up) {
	low--;
	width--;
      }
      break;
    default:
      puts("Non definition symbol!");
      break;
    }
    // calculate area
    if (low == up && 0 < low ) {
      if(trapzoid)
	area[i] = (width + trapzoid) * low / 2;
      else
	// triangle
	area[i] = width * low / 2;
      i++;
      initilize();
    }
  }

  // output
  for (j = 0; j < i; j++)
    allArea += area[j];
  printf("%d\n", allArea);

  printf("%d ", i);
  for (j = 0; j < i; j++) {
    if(j)
      printf(" ");
    printf("%d", area[j]);
