			push( i, &s1 );
		}
		else if( !isEmpty(&s1) && c == '/' ){
			j = pop(&s1);
			sum += i - j;
			tmp = i - j;

			while( !isEmpty(&s2) && s2.S[s2.top] > j ){
				pop(&s2);
				tmp += pop(&s3);
			}

			push( j, &s2 );
			push( tmp, &s3 );
		}
