void initialize(Stack *s){
	s->top = 0;
	s->S[s->top] = 0;
}

void push( int x, Stack *s ){
	if( isFull(s)){
		exit(1);
	}
	s->S[++s->top] = x;
}

int pop(Stack *s){
	if( isEmpty(s)){
		exit(1);
	}

	s->top--;
	return s->S[s->top+1];
}

int isEmpty(Stack *s){
	return s->top == 0;
}

int isFull(Stack *s){
	return s->top >= MAX+1;
}

