				if (b != k){
					//この谷には1箇所水がたまる
					depth = 0;
					su = 0.0;
					//面積の計算
					for (w = b + 1, h = b; w <= k; w++, h++){
						if (sa[0][h] > sa[0][w]){ su += depth + 0.5; depth++; }
						else if (sa[0][h] < sa[0][w]){ su += depth - 1 + 0.5; depth--; }
						else{ su += depth; }
					}
					seki[c] = (int)su;
					sum += seki[c];
					c++;
				}
				//検索を前の山との差が0になったところから探すようにする
				j = k;
				//前の山との差が0になる場所があったことを示すフラグ
				m = 0;

				//前の山の高さと同じ高さを記録したときに頂点でないときはこれ以降の頂点を探す
				g = k;//kを変更したくないから
				f = k;
				while (1){
					//読み込んだ山と谷の範囲を出ていたら
					if (g >= i)break;
					//上り坂だったら
					if (sa[0][f]<sa[0][g]){
						f++;
					}
					//下り坂だったら
					else if (sa[0][f] > sa[0][g]){
						//検索を次の山の頂点にする
						j = f;
						//頂点を記録
						t = sa[0][f];
						b = j;
						//頂点が見つかったので検索ループを出る
						break;
					}
					//平坦だったら
					else if (g != f && sa[0][g] == sa[0][f]){
						f++;
					}
					g++;
				}
				//前の山との差が0になったので検索を出る
				break;
			}
		}
		//前の山との差が0になる場所がなかったら
		if (m){
			//前の山からの次の場所（jには頂点が記録されているのでそこから1進んだ場所の位置を記録）
			//ただし平坦な場合は1進んでも前の山との差が0になる場所ではないので平坦以外になるまで移動する
			t = sa[0][j];
			b = j;
			//平坦な場合
			for (r = j + 1; r < i - 1; r++){
				//傾き場変化する場所を記録
				if (sa[0][j] != sa[0][r]){
					b = r - 1;
					break;
				}
			}
			m = 0;
		}
	}
	go:
	printf("%d\n%d ", sum, c);
	for (i = 0; i < c; i++){
		printf("%d", seki[i]);
		if (i < c - 1){
			printf(" ");
		}
	}
	printf("\n");
}
	return 0;
}

#include<stdio.h>
#include<stdlib.h>
#define MAX 20000  // スタックの最大値

typedef struct{
  int top;         // スタックポインタ(一番上の位置)
  int S[MAX];
}Stack;


// スタック st の初期化
void initialize(Stack *st)
{
  st->top = 0;
  st->S[st->top] = 0;
}

// スタック st が空かどうかを確認
int isEmpty(Stack *st)
{
  return st->top == 0;
}

// スタック st が一杯かどうかを確認
int isFull(Stack *st)
{  
  return st->top >= MAX - 1;
}

// スタック st に要素 x をプッシュ(一番上に要素を追加)
void push(int x, Stack *st)
{
  if (isFull(st)) 
    exit(1);

  st->top++;
  st->S[st->top] = x;
}

// スタック st から要素をポップ(一番上の要素を取り出す)
int pop(Stack *st) {
  if (isEmpty(st)) 
    exit(1);

  st->top--;
  return st->S[st->top+1];
}


