int mennseki(char *ascii,int length,int p,int q) {
	int hukami = 0,i;
	double a =0;

	for(i = p; i < q; i++) {
		if(ascii[i] == '/') {
			a += (double)hukami - 0.5;
			hukami--;
		} else if (ascii[i] == '\\') {
			a +=(double)hukami + 0.5;
			hukami++;
		} else if(ascii[i] =='_') {
			a += hukami;
		}
	}
	return a;
}

