void calcDamage(char *str)
{
  int i;//counter
  int x=0,y=0;//current position
  int p[N];//array of depth
  p[0]=0;
  int mindepth=0;//minimum depth (default: 0)
  damage temp;
  for(x=1;x<=strlen(str);x++)
    {
      switch(str[x])
        {
        case '\':
          y--;
          p[x]=y;
          #ifdef DEBUG
          printf("(%d,%d)\n",x,y);//debugging
          #endif
          break;
        case '/':
          y++;
          p[x]=y;
          #ifdef DEBUG
          printf("(%d,%d)\n",x,y);//debugging
          #endif
          if(y>mindepth) mindepth=y;
          else
            {
              for(i=x-1;i>=0;i--)
                {
                  if(p[i]==y) break;
                }
              if(i>=0)
                {
                  temp.x[0]=i;
                  temp.x[1]=x;
                  temp.depth=y;
                  temp.area=((x-i)+(x-i-2))/2;
                  #ifdef DEBUG
                  printf("push->%d,%d,%d,%d\n",temp.x[0],temp.x[1],temp.depth,temp.area);//debugging
                  #endif
                  push(temp);
                }
            }
          break;
        case '_':
          p[x]=y;
          #ifdef DEBUG
          printf("(%d,%d)\n",x,y);//debugging
          #endif
          break;
        }
    }
}
