          d.area+=p.area;
          #ifdef DEBUG
          printf(" merged->%d,%d,%d,%d\n",d.x[0],d.x[1],d.depth,d.area);//debugging
          #endif
        }
      else break;
    }
  top++;
  stack[top]=d;
}
