#include <stdio.h>
#include <string.h>

#define STR_MAX_LEN 20000

int main(void)
{
    char            buf[STR_MAX_LEN];
    unsigned short  length[STR_MAX_LEN] = {}, depth;
    unsigned short  ii, jj, kk, field_len, floos[STR_MAX_LEN / 2] = {};
    unsigned short  valley = 1, hill[STR_MAX_LEN / 2] = {}; 
    unsigned int    total = 0;

    fgets(buf, sizeof(buf), stdin);

    field_len = strlen(buf);
    depth = 0;

    for(ii = 0; ii < field_len; ii++){
        switch(buf[ii]){
            case '\\':
                for(jj = 0; jj <= depth; jj++){
                    length[jj]++;
                }
                if(valley == 1){
                    hill[++hill[0]] = depth;
                    floos[0]++;
                    valley = 0;
                }
                depth++;
                break;
            case  '_':
                for(jj = 0; jj <= depth; jj++){
                    length[jj]++;
                }
                break;
            case  '/':
                for(jj = 0; jj <= depth; jj++){
                    length[jj]++;
                }
                if(0 < depth){
                    floos[floos[0]] += length[depth];
                    length[depth] = 0;
                    if(depth == hill[hill[0]]){
                        floos[0]--;
                        floos[floos[0]] += floos[floos[0] + 1];
                        floos[floos[0] + 1] = 0;
                        hill[hill[0]--] = 0;
                    }
                    depth--;
                    valley = 1;
                }
                break;
            default:
                break;
        }
    }

    if(valley == 0){
        floos[0]--;
        floos[floos[0]] += floos[floos[0] + 1];
        floos[floos[0] + 1] = 0;
    }

    for(ii = 1; ii <= floos[0]; ii++){
        total += floos[ii];
    }
    printf("%d\n", total);
    printf("%d", floos[0]);
    for(ii = 1; ii <= floos[0]; ii++){
        printf(" %d", floos[ii]);
    }
    printf("\n");
}

#include <stdio.h>


typedef struct{
	int index;
	int s;
}STACK_T;


int main()
{
	char c;
	char figure[20000];
	int stack[20000];
	STACK_T stack2[20000];
	int sp, sp2;
	int index;
	int count, sum;
	int i;


	// データを入力
	i = count = 0;
	while( (c = fgetc(stdin)) != '\n'){
		figure[i++] = c;
		count++;
	}


	// 面積の計算
	sp = sp2 = sum = 0;
	for(i = 0; i < count; i++){
		// スタックに積んでいく
		if(figure[i] == '\\')
			stack[sp++] = i;
		// スタックから取り出す&面積の計算
		else if(figure[i] == '/' && sp >= 1){
			index = stack2[sp2].index = stack[--sp];
			sum += stack2[sp2].s = i - stack[sp];
			// 結合
			while(sp2 >= 1 && index < stack2[sp2 - 1].index){
				stack2[--sp2].index = index;
				stack2[sp2].s += stack2[sp2 + 1].s;
			}
			sp2++;
		}
	}


	// 表示
	printf("%d\n", sum);
	printf("%d", sp2);
	for(i = 0; i < sp2; i++){
		if(i == 0)
			printf(" ");
		printf("%d", stack2[i].s);
		if(i != sp2 - 1)
			printf(" ");
	}
	printf("\n");

	return 0;
}

#include<stdio.h>

#define MAXLEN 20000

int area, areas[(MAXLEN/2)+1],cnt;

int getArea( char *areastr, int start, int maxh )
{
    int i;
    int ravine,squre;
    int up,down,preup,predown;

    preup=predown=up=down=0;
    areas[cnt]=squre=ravine=0;
    for( i=start; '\0'!=*(areastr+i); i++ ) {
        if( '\\'== *(areastr+i) ) {
            ravine++;
            if( 0 < up ) {
                down++;
                if( up == down ) {
                    areas[cnt]-=(down*down);
                    areas[cnt]-=(down*2)*(maxh-ravine);
                    up=down=0;
                }
            } else if( up == 0 && 0 < preup ) {
                predown++;
                if( preup == predown ) {
                    areas[cnt]-=(predown*predown);
                    areas[cnt]-=(predown*2)*(maxh-ravine);
                    preup=predown=0;
                }
            } 
        } else if( 0 < ravine && '/' == *(areastr+i) ) {
            if( 0 < down ) {
                areas[cnt]-=(down*down);
                areas[cnt]-=(down*2)*(maxh-ravine);
                 if( preup == 0 ) {
                	preup=up-down;
                }
                up=down=0;
            }

            if( 0 <  predown ) {
                areas[cnt]-=(predown*predown);
                areas[cnt]-=(predown*2)*(maxh-ravine);
                preup=predown=0;
            }
            ravine--;
            up++;
            if( 0 == ravine ) {
                squre=(i-start+1)*maxh;
                areas[cnt]+=squre;
                areas[cnt]-=(maxh*maxh);
                break;
            }           
        } else {
            areas[cnt]-=(maxh-ravine);
        }
    }
    return areas[cnt];
}


int checkRavine( char *checkstr, int start )
{
    int i,j;
    int ravine,maxh;

    ravine=maxh=0;
    for( i=start, j=0; '\0'!=*(checkstr+i) &&  j<100; i++, j++ ) {
        if( '\\'== *(checkstr+i) ) {

            ravine++;
        } else if( 0 < ravine && '/' == *(checkstr+i) ) {

            if( maxh < ravine ) { maxh=ravine; }     
            ravine--;
            if( 0 == ravine ) {
                area+=getArea( checkstr, start, maxh );
                cnt++;
                return j;
            }           
        }
    }

    return 0;
}

void getAreas( char *inputs )
{
    int i,next;

    next=cnt=0;
    for( i=0; '\0'!=inputs[i]; i++ ) {
        next=checkRavine( inputs, i );
        i+=next;
    }

    return;
}

int main( void ) 
{
    char inputs[MAXLEN+1];
    int i;

    scanf( "%s", inputs );
    area=cnt=0;
    getAreas( inputs );

    printf( "%d\n", area );
    if( cnt ) {
        printf( "%d ", cnt );
        for( i=0; i<cnt; i++ ) {
            printf( "%d", areas[i] );
            if( i < cnt-1 ) {
                printf( " " );  
            } else {
                printf( "\n" ); 
            }
        }
    } else {
        printf( "0\n" );
    }

    return 0;
}

