int isfinish(int x)
{
	int up=0,down=0,len,i,flag=1;
	len=strlen(map);
	for(i=x;i<=len-1;i++)
	{

		if(map[i]=='\\')
		{
			down++;
			flag=0;
		}
		if(map[i]=='/')
		{
			up++;
			if(flag==1)
				return 0;
		}
		if(up>down)
			return 0;
	}


	return 1;
}
int main()
{
	int stack[20010],i,j=0,len,puddle[10010]={0},total=0,top=0,flag=1;
