	{

		if(map[i]=='\\')
		{
			top++;
			stack[top]=i;
		}
		if(map[i]=='/' && top!=0)
		{
			if(flag==1)
			{
				flag=0;
				j++;
			}
			puddle[j]+=i-stack[top];
			total+=i-stack[top];
			top--;
			if(top==0)
				flag=1;
			if(flag==0)
				flag=isfinish(i+1);
		}

	}
	printf("%d\n%d",total,j);
	for(i=1;i<=j;i++)
