typedef struct _data {
	int val;
	int ceil;
	struct _data *next;
} data;

void push(data **p, data *d)
{
	d->next = *p;
	*p = d;
}

data *pop(data **p)
{
	if (*p == NULL) return NULL;
	data *d = *p;
	*p = (*p)->next;
	return d;
}

int main()
{
	char str[20001], ch;
	int i, val, ceil, total, count;
	data *work, *result, *d;

	scanf("%s", str);
	i = 0;
	work = NULL;
	while ((ch = str[i++]) != '\0')
	{
		if (ch == '\\')
		{
			d = (data*)malloc(sizeof(data));
			d->val = 0;
			d->ceil = 0;
			push(&work, d);
		}
		else if (ch == '_')
		{
			d = pop(&work);
			if (d == NULL) continue;
			d->ceil++;
			push(&work, d);
		}
		else
		{
			val = ceil = 0;
			while ((d = pop(&work)) != NULL)
			{
				val += d->val;
				ceil += d->ceil;
				if (d->val == 0) break;
				free(d);
			}

			if (d != NULL)
			{
				d->val = val + ceil + 1;
				d->ceil = ceil + 2;
				push(&work, d);
			}
			else if (val > 0)
			{
				d = (data*)malloc(sizeof(data));
				d->val = val;
				d->ceil = ceil;
				push(&work, d);
			}
		}
	}

	total = count = 0;
	while ((d = pop(&work)) != NULL)
	{
		if (d->val == 0)
		{
			free(d);
			continue;
		}

		total += d->val;
		count++;
		push(&result, d);
	}

	printf("%d\n", total);
	printf("%d", count);
	if (count)
	{
		printf(" ");
		for (i = 0; i < count; i++)
		{
			d = pop(&result);
			printf("%d", d->val);
			free(d);
			if (i + 1 < count) printf(" ");
		}
	}
	printf("\n");

	return 0;
}

#include<stdio.h>
