// just implement simple stack
typedef struct StkKey {
    int b4;
    int area;
} StkKey;
typedef struct StkDat {
    StkKey key;
    struct StkDat *next;
} StkDat;
typedef struct Stack {
    size_t len;
    StkDat *top;
} Stack;
#define stk_init(s) ((s) ? ((s)->len = 0, (s)->top = NULL) : 0)
#define stk_len(s) ((s) ? (s)->len : 0)
#define stk_top(s) ((s)->top->key)
StkKey stk_pop(Stack *stk_hdr) {
    assert(stk_hdr->len != 0);
    stk_hdr->len--;
    StkKey key = stk_hdr->top->key;
    StkDat *old_head = stk_hdr->top;
    stk_hdr->top = stk_hdr->top->next;
    free(old_head);
    return key;
}
void stk_push(Stack *stk_hdr, const StkKey key) {
    StkDat *new_dat = (StkDat *)malloc(sizeof(StkDat));
    new_dat->key = key;
    new_dat->next = stk_hdr->top;
    stk_hdr->top = new_dat;
    stk_hdr->len++;
}
// <- stack

int main(int argc, char **argv) {
    // stack for '\' index
    Stack stk_index;
    stk_init(&stk_index);
    // stack for area size and its index
    Stack stk_area;
    stk_init(&stk_area);
    char c;
    // StkKey: {index, area size}
    StkKey key;
    for(int i = 0; ~scanf("%c", &c); ++i) {
        switch(c) {
        case '\\':
            stk_push(&stk_index, (StkKey){i, 0});
            break;
        case '/':
            // stack is empty -> do nothing
            if(stk_len(&stk_index) == 0) break;
            key = stk_pop(&stk_index);
            // if larger index exist, combine
            while(stk_len(&stk_area) && key.b4 < stk_top(&stk_area).b4) {
                key.area += stk_pop(&stk_area).area;
            }
            // combined ? key.area has value : key.area is 0
            stk_push(&stk_area, (StkKey){key.b4, i - key.b4 + key.area});
            break;
        default:
            break;
        }
    }
    int rstack[10000];
    int area = 0;
    int stk_len = (int)stk_len(&stk_area);
    for(size_t i = 0; i < stk_len; ++i) {
        rstack[i] = stk_pop(&stk_area).area;
        area += rstack[i];
    }
    printf("%d\n", area);
    printf("%d", stk_len);
    for(int i = stk_len - 1; i >= 0; --i) {
        printf(" %d", rstack[i]);
    }
    printf("\n");
}

#include<stdio.h>

#define MAXLEN 20000

int garea,gareas[(MAXLEN/2)+1],gcnt;


int getArea( char *inputs, int start, int end )
{
    int i;
    int ravine,water;

    gareas[gcnt]=water=ravine=0;
    for( i=start; i<=end && '\0'!=*(inputs+i) ; i++ ) {
        if( '\\'== *(inputs+i) ) {
            water+=(ravine*2);
            ravine++;
            water++;
        } else if( 0 < ravine && '/' == *(inputs+i) ) {   
            ravine--;
            if( 0 == ravine ) {
                gareas[gcnt]+=water;
                break;
            }           
        } else {
	     	gareas[gcnt]+=ravine;
        }       
    }

    return gareas[gcnt];
}

int checkRavine( char *inputs, int start )
{
    int i,j;
    int ravine;

    ravine=0;
    for( i=start, j=0; '\0'!=*(inputs+i) && j<MAXLEN; i++, j++ ) {
        if( '\\'== *(inputs+i) ) {
            ravine++;
        } else if( 0 < ravine && '/' == *(inputs+i) ) {   
            ravine--;
            if( 0 == ravine ) {
            	garea+=getArea( inputs, start, i );
            	gcnt++;
                return j;
            }           
        }
    }
    return 0;
}


void getAreas( char *inputs )
{
    int i,next;

    next=0;
    for( i=0; '\0'!=inputs[i]; i++ ) {
        next=checkRavine( inputs, i );
        i+=next;
    }

    return;
}

int main( void ) 
{
    char inputs[MAXLEN+1];
    int i;

    scanf( "%s", inputs );
    garea=gcnt=0;
    getAreas( inputs );

    printf( "%d\n", garea );

    if( gcnt ) {
        printf( "%d ", gcnt );
        gcnt--;
        for( i=0; i<=gcnt; i++ ) {
            printf( "%d", gareas[i] );
            if( i < gcnt ) {
                printf( " " );  
            } else {
            	printf( "\n" ); 
            }
        }
    } else {
        printf( "0\n" );
    }

    return 0;
}

