//============================================================================
char cmd[20001];
short line[20001];
void process(char *cmd, long len)
{
    long i,ih,fh,d,a;

    for (i=ih=fh=d=a=0; i<len; i++)
    switch(cmd[i]){
        case '\\': a++; a+=d; d+=2; break;
        case '/' : a++; d-=2; a+=d; break;
        case '_' : a+=d;      break;
    }
    a/=2;
    insertlist(a);
    //printf(" Area = %ld\n", a);
}
