  static int xCount = 0;
  static int yCount = 0;
  list *p;
  p = (list*)malloc(sizeof(list));
  p->prev = tail.prev;
  tail.prev->next = p;
  p->next = &tail;
  tail.prev = p;
  xCount++;
  if(c == '\\'){
    yCount--;
  }
  if(c == '/' ){
    yCount++;
  }
  p->x = xCount;
  p->y = yCount;
  p->ground = c;
}

list *FarSide(list *s){
  list *i_p;
  int height;
  height = s->y + 1;
  for(i_p = s->next; i_p != &tail; i_p = i_p->next){
    if(i_p->y == height){
      return i_p;
    }
  }
  return NULL;
}

