#include <stdio.h>

#define STACK_SIZE 20000
#define TOPLINEAREA STACK_SIZE - 1

void push(unsigned int line_area, unsigned int *stack, int *tail)
{
    stack[++(*tail)] = line_area; 
}

unsigned int pop(unsigned int *stack, int *tail)
{
    if(*tail < 0)
        return 0;

    return stack[(*tail)--];
}

int main(void) 
{
    int i, puddles_num = 0, puddle_area = 0, area = 0, tail = -1, line_area;
    int frontLineArea = TOPLINEAREA, backLineArea, puddle_num = 0;
    unsigned int stack[STACK_SIZE], puddles[STACK_SIZE / 2];
    char ch;

    while(scanf("%c", &ch) != EOF) {
        if(ch == '\n')
            continue;
        switch(ch) {
            case '\\':
                push(frontLineArea, stack, &tail);
                backLineArea = frontLineArea - 1;
                frontLineArea--; 
                break;

            case '/':
                if((line_area = pop(stack, &tail)) == 0) {
                    if(puddle_area) {
                        puddles[puddles_num++] = puddle_area; 
                        puddle_area = 0;
                    }
                    backLineArea = frontLineArea - 1;
                    frontLineArea--;
                    break;
                }
                area += (line_area - backLineArea);
                puddle_area += (line_area - backLineArea);
                backLineArea = frontLineArea - 1;
                frontLineArea--;
                break;

            case '_':
                backLineArea = frontLineArea - 1;
                frontLineArea--;
                break;
            default:
                break;
        }
        //printf("ch: %c\nfront: %d\nback: %d\nline_area: %d\narea: %d\n\n", ch, frontLineArea, backLineArea, line_area, area);
    }
    if(puddle_area)
        puddles[puddles_num++] = puddle_area;

    printf("%d\n%d %d", area, puddles_num, puddles[0]);
    for(i = 1; i < puddles_num; i++)
        printf(" %d", puddles[i]);
    printf("\n");

    return 0;
}

#include<stdio.h>

#define MAXLEN 20000

int area, areas[(MAXLEN/2)+1],cnt;

int getArea( char *areastr, int start, int maxh )
{
	int i;
	int ravine,squre;
	int up,down;

	up=down=0;
	areas[cnt]=squre=ravine=0;
	for( i=start; '\0'!=*(areastr+i); i++ ) {
		if( '\\'== *(areastr+i) ) {
			ravine++;
			if( 0 < up ) {
				down++;		
			}		
		} else if( 0 < ravine && '/' == *(areastr+i) ) {
			ravine--;		
			if( 0 < down ) {
				areas[cnt]-=(down*down);
				up=down=0;
			}
			up++;
			if( 0 == ravine ) {
				squre=(i-start+1)*maxh;
				areas[cnt]+=squre;
				areas[cnt]-=(maxh*maxh);
				break;
			}			
		} else {
			areas[cnt]-=(maxh-ravine);
		}
	}
	return areas[cnt];
}


int checkRavine( char *checkstr, int start )
{
	int i,j;
	int ravine,maxh;

	ravine=maxh=0;
	for( i=start, j=0; '\0'!=*(checkstr+i) &&  j<100; i++, j++ ) {
		if( '\\'== *(checkstr+i) ) {
			ravine++;
		} else if( 0 < ravine && '/' == *(checkstr+i) ) {
			if( maxh < ravine ) { maxh=ravine; }		
			ravine--;
			if( 0 == ravine ) {
				area+=getArea( checkstr, start, maxh );
				cnt++;
				return j;
			}			
		}
	}

	return 0;
}

void getAreas( char *inputs )
{
	int i,next;

	next=cnt=0;
	for( i=0; '\0'!=inputs[i]; i++ ) {
		next=checkRavine( inputs, i );
		i+=next;
	}

	return;
}

int main( void ) 
{
    char inputs[MAXLEN+1];

	scanf( "%s", inputs );
	area=cnt=0;
	getAreas( inputs );

	printf( "%d\n", area );
	printf( "%d ", cnt );	

	int i;
	for( i=0; i<cnt; i++ ) {
		printf( "%d", areas[i] );
		if( i < cnt ) { printf( " " ); }
	}
	printf( "\n" );	

	return 0;
}

