public class Main{
	public static void main(String[] args){
		Scanner scan = new Scanner(System.in);
		String ground = scan.next();
		int[] height = new int[ground.length()+1];
		height[0] = 0;
		int now = 0;
		int[] valley = new int[(ground.length()/2)+1];
		int status = 0;
		int j = 0;
		int cnt = 0;
		for(int i = 0; i < ground.length(); i++){
			char c = ground.charAt(i);
			switch(c){
			case '\\':
				if(cnt == 0){
					valley[j] = i;
					status = -(i + 1);
					j++;
					cnt++;
				}else if(status > 0){
					if(j != 0){
						if(height[valley[j - 1]] < now && j > 1){
							int k = j - 2;
							int max = height[valley[j - 1]];
							int maxk = j - 1;
							while(k >= 0){
								if(height[valley[k]] > max){
									max = height[valley[k]];
									maxk = k;
									if(max >= now){
										break;
									}
								}
								k--;
							}
							valley[maxk + 1] = status;
							j = maxk + 2;
						}else{
							valley[j] = status;
							j++;
						}
						status = -(i + 1);
					}else{
						valley[j] = status;
						status = -(i + 1);
						j++;
					}
				}
				now--;
				height[i+1] = now;
				break;
				case '/':
				if(cnt == 0){
					status = i + 1;
					cnt++;
				}else if(i == ground.length() - 1 && j != 0){
					if(height[valley[j - 1]] < now + 1 && j > 1){
						int k = j - 2;
						int max = height[valley[j - 1]];
						int maxk = j - 1;
						while(k >= 0){
							if(height[valley[k]] > max){
								max = height[valley[k]];
								maxk = k;
								if(max >= now){
									break;
								}
							}
							k--;
						}
						valley[maxk + 1] = i + 1;
						j = maxk + 2;
					}else{
						valley[j] = i + 1;
						j++;
					}
					status = i + 1;
				}else{
					status = i + 1;
				}
				now++;
				height[i+1] = now;
				break;
				case '_':
				if(i == ground.length() - 1 && status > 0 && j > 0){
					if(height[valley[j - 1]] < now && j > 1){
						int k = j - 2;
						int max = height[valley[j - 1]];
						int maxk = j - 1;
						while(k >= 0){
							if(height[valley[k]] > max){
								max = height[valley[k]];
								maxk = k;
								if(max >= now){
									break;
								}
							}
							k--;
						}
						valley[maxk + 1] = status;
						j = maxk + 2;
					}else{
						valley[j] = status;
						j++;
					}
				}
				height[i+1] = now;
				break;
			}
		}

		int A = 0;
		int k = 0;
		if(j > 1){
			k = j - 1;
			int[] L = new int[k];
			for(int i = 0; i < k; i++){
				L[i] = 0;
			}
			int lower;
			int i = 1;
			while(i < j){
				if(height[valley[i - 1]] > height[valley[i]]){
					lower = height[valley[i]];
				}else{
					lower = height[valley[i - 1]];
				}

				for(int l = valley[i - 1]; l < valley[i]; l++){
					if(height[l] >= lower && height[l + 1] >= lower){
						continue;
					}else{
						L[i - 1] += ((lower - height[l]) + (lower - height[l + 1]));
					}
				}
				L[i - 1] /= 2;
				A += L[i - 1];
				i++;
			}

			System.out.println(A);
			System.out.print(k);
			for( i = 0; i < k; i++){
				System.out.print(" "+L[i]);
			}
			System.out.println("");
		}else{
			System.out.println(A);
			System.out.println(k);
		}
	}
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    // 現在のx座標
    public int lineNumber;

    // 現在の 層別未確定水たまりスタック
    public ArrayList<Short> stack;
    // 未確定水たまり層の始点
    public ArrayList<Short> stackStart;
    // 確定水たまりリスト
    public ArrayList<Short> puddles;
    // 確定水たまり層の始点
    public ArrayList<Short> puddleStart;
    // 現在の確定水たまりIdx
    public int puddleNumber = 0;
    // 現在の深さ
    public int currentDepth = 0;
    // 前回の水たまり水面高
    public int prevPuddleHeight = -1;

    public int sum = 0;

    /**
     * 指定の層へ水を追加する
     *
     * @param idx       追加する層Idx
     * @param n         追加量
     * @param isConfirm 層確定操作を行うかどうか
     */
    public void add(int idx, int n, boolean isConfirm) {
        // 初出層の場合はstackに追加
        if (this.stack.size() - 1 < idx) {
            this.stack.add(idx, (short) 0);
            this.stackStart.add(idx, (short) lineNumber);
        }
        // 追加動作
        this.stack.set(idx, (short) (this.stack.get(idx) + n));
        // 層確定操作
        if (isConfirm) {
            this.sum += this.stack.get(idx);
            // 現在の未確定水たまり層を、確定水たまりリストに移す
            this.puddles.add(puddleNumber, this.stack.get(idx));
            // 追加した確定水たまりの始点も設置
            this.puddleStart.add(puddleNumber, (short) this.stackStart.get(idx));
            // 初回の層確定操作でない && 前回の層確定操作の1つ上位層の場合
            if ((prevPuddleHeight != -1) && ((prevPuddleHeight - 1) == idx)) {
                // 繰り上がり動作を行う
                // 各確定水たまりについて、初めて (現在の水たまりの始点) < (ある水たまり始点) となるものを探す
                int start = this.puddleStart.get(puddleNumber);
                for (int i = 0; i <= puddleNumber; i++) {
                    // (現在の水たまりの始点) < (ある水たまり始点) Hit!!
                    if (start < this.puddleStart.get(i)) {
                        // ある地点の水たまりを吸収
                        // はじめに始点を更新
                        this.puddleStart.set(i, (short) start);
                        // 次に、その間の水たまり量をすべて吸収
                        for (int j = i + 1; j <= puddleNumber; j++) {
                            this.puddles.set(i, (short) (this.puddles.get(i) + this.puddles.get(j)));
                        }
                        for (int j = puddleNumber; j >= i + 1; j--) {
                            this.puddles.remove(j);
                            this.puddleStart.remove(j);
                        }
                        puddleNumber = i + 1;
                        break;
                    }
                }
            } else { // 繰り上がり動作を行わない場合
                puddleNumber++;
            }
            prevPuddleHeight = idx;
            this.stack.remove(idx);
            this.stackStart.remove(idx);
        }
    }

    public void up() {
        if (currentDepth == 0) {
            return;
        }
        currentDepth--;
        this.add(currentDepth, 1, true);
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void hori() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void down() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
        this.add(currentDepth, 1, false);
        currentDepth++;
    }

    public void print() {
        System.out.println(sum / 2);
        System.out.print(this.puddles.size());
        int len = this.puddles.size();
        for (int i = 0; i < len; i++) {
            System.out.print(" " + (this.puddles.get(i) / 2));
        }
        System.out.println();
    }

    public void go() {
        this.stack = new ArrayList<Short>();
        this.stackStart = new ArrayList<Short>();
        this.puddles = new ArrayList<Short>();
        this.puddleStart = new ArrayList<Short>();
        Scanner sc = new Scanner(System.in);
        String line = sc.next();
        String[] strings = line.split("");
        for (int i = 0; i < strings.length; i++) {
            String s = strings[i];
            this.lineNumber = i;
            switch (s) {
            case "\\":
                this.down();
                break;
            case "_":
                this.hori();
                break;
            case "/":
                this.up();
                break;
            }
        }
        print();
    }

    public static void main(String[] args) {
        Main cui = new Main();
        cui.go();
    }
}

