					xs[i+1] = 0;
					cs[i] = '_';
				}
			} else {
				xs[i+1] = xs[i];
			}
		}
		xs[xs.length - 1] = 0;
		for (int i = cs.length - 1; i >= 0; i--) {
			if (cs[i] == '\\') {
				xs[i] = xs[i+1] + 1;
				if (xs[i] > 0) {
					xs[i] = 0;
					cs[i] = '_';
				}
			} else if (cs[i] == '/') {
				xs[i] = xs[i+1] - 1;
			} else {
				xs[i] = xs[i+1];
			}
		}
		xs[0] = 0;
		int k = 0;
