public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		String[] str = sc.nextLine().split("");
		Deque<Integer> que = new ArrayDeque<>();
		Deque<List<Integer>> puddle = new ArrayDeque<>();
		for (int i = 0; i < str.length; i++) {
			if (str[i].equals("\\")) {
				que.add(i);
			} else if(str[i].equals("/")) {
				if (que.size() == 0) {
					continue;
				} else {
					int l = que.pollLast();
					int s = i - l;
					if(puddle.size() == 0) {
						puddle.addLast(new ArrayList<>());
						puddle.getLast().add(0, l);
						puddle.getLast().add(1, s);
					} else {
						if(l > puddle.getLast().get(0)) {
							puddle.addLast(new ArrayList<>());
							puddle.getLast().add(0, l);
							puddle.getLast().add(1, s);
						} else {
							List<Integer> list = puddle.pollLast();
							while (true) {
								s += list.get(1);
								if (puddle.size() == 0) {
									break;
								} else if(puddle.getLast().get(0) < l) {
									break;
								} else {
									list = puddle.pollLast();
								}
							}
							puddle.add(new ArrayList<>());
							puddle.getLast().add(0, l);
							puddle.getLast().add(1, s);
						}
					}
				}
			}
		}
		int sum = 0;
		Iterator<List<Integer>> it = puddle.iterator();
		while (it.hasNext()) {
			List<Integer> next = it.next();
			sum += next.get(1);
		}
		System.out.println(sum);
		if (puddle.size() == 0) {
			System.out.print(puddle.size());
		} else {
			System.out.print(puddle.size() + " ");
			it = puddle.iterator();
			while (it.hasNext()) {
				List<Integer> next = it.next();
				if(!it.hasNext()) {
					System.out.println(next.get(1));
				} else {
					System.out.print(next.get(1) + " ");
				}
			}
		}
	}
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {

	static Deque<Integer> mapStack;
	static Deque<Mizutamari> waterStack;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		String[] graph = sc.nextLine().split("");
		sc.close();
		mapStack = new ArrayDeque<>();
		waterStack = new ArrayDeque<>();

		for (int i = 0; i < graph.length; i++) {
			switch (graph[i]) {
			case "\\":
				mapStack.offerLast(i);
				break;
			case "/":
				if (mapStack.isEmpty()) continue;
				int start = mapStack.pollLast();
				int tmpArea = i - start;
				while (!waterStack.isEmpty() && waterStack.peekLast().getStartIdx() > start) {
					tmpArea += waterStack.pollLast().getArea();
				}
				waterStack.offerLast(new Mizutamari(start, tmpArea));
				break;
			case "_":
				continue;
			}

		}

		System.out.println(waterStack.stream().map(m -> m.getArea()).reduce(0, (x, y) -> x + y));
		System.out.print(waterStack.size());
		int len = waterStack.size();
		for (int i = 0; i < len; i++) {
			System.out.print(" ");
			System.out.print(waterStack.pollFirst());
		}
	}

}

class Mizutamari {
	private int startIdx;
	private int area;
	public Mizutamari(int start, int area) {
		this.startIdx = start;
		this.area = area;
	}
	public int getStartIdx() {
		return startIdx;
	}
	public int getArea() {
		return area;
	}
	public void addArea(int area) {
		this.area += area;
	}

	@Override
	public String toString() {
		return String.valueOf(area);
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) throws IOException {
        final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        final char[] line = reader.readLine().toCharArray();
        reader.close();

        final Deque<Integer> stack = new ArrayDeque<Integer>(line.length);
        final StringBuilder answer = new StringBuilder();

        int sum = 0;
        int count = 0;
        int indexLastZero = 0;
        final int[] process = new int[line.length];
        final int[] graph = new int[line.length];
        for (int i = 0; i < line.length; ++i) {
            if (stack.isEmpty()) indexLastZero = i;

            switch (line[i]) {
                case '\\':
                    stack.push(i);
                    break;
                case '/':
                    if (!stack.isEmpty()) {
                        sum += i - stack.pop();
                        if (stack.isEmpty()) {
                            ++count;
                            answer.append(" ").append(sum - process[indexLastZero]);
                        }
                    }
                    break;
                default:
            }
            graph[i] = stack.size();
            process[i] = sum;
        }

        for (int i = indexLastZero + 1; i < line.length; ++i) {
            for (int j = line.length - 1; i < j; --j) {
                if (graph[i] == graph[j]) {
                    ++count;
                    answer.append(" ").append(process[j] - process[i]);
                    i = j;
                    break;
                }
            }
        }
        System.out.println(sum);
        System.out.println(count + answer.toString());
    }
}

