/**
 * 境界部分には気をつける(そこだけ別で処理するというのもあり)
 * 逆再生することで簡単になることもある
 */
public class Main {
    public Main() {
    }

    public static void main(String[] args ) {
    		Main main = new Main();
    		main.exec();
    }

    public void exec() {
        BufferedReader bf = null;
        try{
            bf = new BufferedReader(new InputStreamReader(System.in));
            exec_body(bf);
        } catch (IOException e) {
			e.printStackTrace();
		}
        finally{
            if( bf != null ) {
                try {
					bf.close();
				} catch (IOException e) {
					e.printStackTrace();
				}
            }
        }
    }

    public class CalcResult {
    		private LinkedList<String> _strList = null;
    		private ArrayList<Integer> _dimensionList = null;
    }

    public int countPosition( LinkedList<String> strList ) {
    		int position = 0;
    		while( !strList.isEmpty() ) {
    			String s = strList.peekFirst();
    			if( "/".equals(s)) {
    				position++;
    			} else if( "\\".equals(s)) {
    				position--;
    			}
    		}

    		return position;
    }

    public void calc( CalcResult result ) {
    		LinkedList<String> strList = result._strList;
    		boolean fromFirst = countPosition(strList) >= 0;
    		int dimension = 0;
    		int position = 0;
    		while( !strList.isEmpty() ) {
    			String s = ( fromFirst ) ? strList.pollFirst() : strList.pollLast();
    			if( "_".equals(s)) {
    				dimension = dimension + 2 * position;
    			} else if( ( fromFirst && "\\".equals(s) ) || ( !fromFirst && "/".equals(s)) ) {
    				position--;
    				dimension = 1 + dimension + 2 * position;
    			} else {
    				dimension = 1 + dimension + 2 * position;
    				position++;
    				if( position != 0 ) {
    					continue;
    				}

    				result._dimensionList.add(dimension);
    			}
    		}
    }

    public LinkedList<String> omitString( LinkedList<String> strList ) {
    		LinkedList<String> charList = new LinkedList<>();
		// 計算に不要な部分を最初に除く
		boolean isFirst = true;
		while( !strList.isEmpty() ) {
			String s = strList.pollFirst();
			if( isFirst && ( "/".equals(s) || "_".equals(s) ) ) {
				continue;
			}

			isFirst = false;
			charList.add(String.valueOf(s));
		}

		LinkedList<String> charList2 = new LinkedList<>();
		// 計算に不要な部分を最初に除く
		isFirst = true;
		while( !charList.isEmpty() ) {
			String s = charList.pollLast();
			if( isFirst && ( "\\".equals(s) || "_".equals(s) ) ) {
				continue;
			}

			isFirst = false;
			charList2.add(String.valueOf(s));
		}

		return charList2;
    }

    public LinkedList<String> toList( String str ) {
    		LinkedList<String> list = new LinkedList<>();
    		for( int ii = 0; ii < str.length(); ii++ ) {
    			char ch = str.charAt(ii);
    			list.add(String.valueOf(ch));
    		}

    		return list;
    }

    public void exec_body( BufferedReader bf ) throws IOException {
    		String line = bf.readLine();
    		LinkedList<String> strList = toList(line);
    		CalcResult result = new CalcResult();
    		result._strList = strList;
    		result._dimensionList = new ArrayList<>();

    		while( !result._strList.isEmpty() ) {
    			result._strList = omitString(result._strList);
    			calc(result);
    		}

    		int sum = 0;
    		for( int i = 0; i < result._dimensionList.size(); i++ ) {
    			sum = sum + result._dimensionList.get(i);
    		}
    		System.out.println(sum/2);

    		// 結果を出力する
    		StringBuilder bd = new StringBuilder();
    		bd.append(result._dimensionList.size());
    		for( int i = 0; i < result._dimensionList.size(); i++ ) {
    			bd.append(" ");
    			bd.append(result._dimensionList.get(i)/2);
    		}
    		System.out.println(bd.toString());
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    static class LinkElement {
        LinkElement prev;
        LinkElement next;
        Object value;

        public LinkElement(Object value) {
            this.value = value;
        }

        public void insertAfter(LinkElement newElement) {
            newElement.prev = this;
            newElement.next = this.next;
            this.next.prev = newElement;
            this.next = newElement;
        }

        public void delete() {
            if (prev != null) {
                prev.next = next;
            }
            if (next != null) {
                next.prev = prev;
            }
        }
    }

    static class DoubleLinkedList {
        LinkElement first;
        LinkElement last;

        public DoubleLinkedList() {
            first = new LinkElement(null);
            last = new LinkElement(null);
            first.next = last;
            last.prev = first;
        }

        public void insert(Object x) {
            first.insertAfter(new LinkElement(x));
        }

        public void delete(Object x) {
            LinkElement it = first.next;
            while (it != last) {
                if (it.value.equals(x)) {
                    it.delete();
                    break;
                }
                it = it.next;
            }
        }

        public void deleteFirst() {
            if (first.next != last) {
                first.next.delete();
            }
        }

        public void deleteLast() {
            if (first.next != last) {
                last.prev.delete();
            }
        }

        public String toString() {
            StringBuilder builder = new StringBuilder();
            LinkElement it = first.next;
            while (it != last) {
                if (builder.length() > 0) {
                    builder.append(" ");
                }
                builder.append(it.value);
                it = it.next;
            }
            return builder.toString();
        }
    }

    public static class Shape {
        final int leftHeight;
        final int rightHeight;
        final char type;

        public Shape(int leftHeight, char type) {
            this.leftHeight = leftHeight;
            switch(type) {
            case '\\':
                this.rightHeight = leftHeight - 1;
                break;
            case '/':
                this.rightHeight = leftHeight + 1;
                break;
            case '_':
                this.rightHeight = leftHeight;
                break;
            default:
                this.rightHeight = -99999;
                break;
            }
            this.type = type;
        }

        public int bottomHeight() {
            switch(type) {
            case '\\':
                return rightHeight;
            case '/':
                return leftHeight;
            case '_':
                return leftHeight;
            default:
                return -99999;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader r = new BufferedReader(new InputStreamReader(System.in));
        String area = r.readLine();
        Shape[] heights = new Shape[area.length()];
        int[] waterAreas = new int[heights.length];

        int height = 0;
        int maxHeight = 0;
        for (int i = 0;i < area.length();i++) {
            heights[i] = new Shape(height, area.charAt(i));
            maxHeight = Math.max(maxHeight, height);
            height = heights[i].rightHeight;
        }

        int foundIndex = 0;
        int totalAreaSize = 0;

        Shape left, right;
        for (int i = 0;i < heights.length;i++) {
            left = heights[i];
            if (left.type != '\\') {
                continue;
            }
            int angleCount = 0;
            int regularCount = 0;
            for (int k = i + 1;k < heights.length;k++) {
                right = heights[k];
                if (right.type == '/' && right.rightHeight == left.leftHeight) {
                    angleCount++;
                    int areaSize = angleCount + regularCount;
                    waterAreas[foundIndex++] = areaSize;
                    totalAreaSize += areaSize;
                    i = k;
                    break;
                } else if (right.type == '/') {
                    angleCount++;
                    regularCount += left.leftHeight - right.rightHeight;
                } else if (right.type == '_') {
                    regularCount += left.leftHeight - right.leftHeight;
                } else if (right.type == '\\') {
                    regularCount += left.leftHeight - right.leftHeight;
                }
            }
        }

        System.out.println(totalAreaSize);
        StringBuilder builder = new StringBuilder();
        for (int i = 0;i < foundIndex;i++) {
            if (i != 0) {
                builder.append(" ");
            }
            builder.append(waterAreas[i]);
        }
        System.out.println(("" + foundIndex + " " + builder).trim());
    }
}

import java.io.UnsupportedEncodingException;
import java.lang.reflect.UndeclaredThrowableException;
import java.util.Scanner;


class Main {
	public static void main(String args[]) {
		Scanner scanner = new Scanner(System.in);
		String mark = scanner.next();
		int num = mark.length();

		SectionDiagram(mark, num, scanner);

	}
	//enum宣言
	public static enum Operate{
		back(92),
		slush(47),
		under(95);

		private final int mark;

		private Operate(final int mark) {
			this.mark = mark;
		}

		public int getInt(){
			return this.mark;
		}
	}
	public static Operate getOperate(final int id) {
		Operate[] marks = Operate.values();
		for (Operate type : marks) {
			if (type.getInt() == id) {
				return type;
			}
		}
		return null;
	}
	//治水シミュレーション
	public static void SectionDiagram(String mark, int num, Scanner scanner){
		int[] count_puddle = new int[num+5];	//"￥"が来たらそいつをカウント開始
		int[] puddle = new int[num+5];			//各水たまりの面積
		int sum_puddle_now = 0;						//今の水溜りの面積
		int sum_puddle = 0;						//水溜りの面積の合計
		int num_puddle = 0;						//水たまりの数
		int count = 0;							//Whileの周回
		int back_num = 0;							//カウントする￥の数
		int sla_num = 0;							//深さ
		int i;
		byte[] mark_num = new byte[num];		//switch用格納庫
		boolean flap = false;

		try {
			mark_num = mark.getBytes("US-ASCII");
		} catch (UnsupportedEncodingException e) {
			// TODO 自動生成された catch ブロック
			e.printStackTrace();
		}

		while( num > count ){										//文字数文処理


			switch( getOperate(mark_num[count]) ){					//
			case back:
				back_num ++;											//￥の数カウント
				flap = true;
				break;
			case slush:
				back_num --;											//￥の数マイナス
				if(flap) {
					sla_num ++;	
				}
				flap = false;
				//補正
				if( back_num < 0 ) {
					back_num = 0;
					sla_num = 0;
					break;
				}

				sum_puddle_now += count_puddle[back_num + 1];			//消した￥の面積を今の水たまりにする
				count_puddle[back_num + 1] = 0;						//その場所のカウントを初期化

				if ((back_num == 0) || ( count == num - 1)){			//今回の水たまりが確定
					sum_puddle += sum_puddle_now;					//今回の水たまりを全体に足す
					puddle[num_puddle] = sum_puddle_now;			//今回の水たまりを配列に入れる
					sum_puddle_now = 0;								//水たまり初期化
					sum_puddle_now = 0;								//水たまり初期化
					sla_num = 0;
					num_puddle ++;									//全体の水たまりの数を足す
				}
				break;
			case under:
				break;
			}
			//￥の数だけカウント
			for( i = 1; i <= back_num; i ++ ){
				count_puddle[i] += 1;
			}
			count ++;
		}
		/*//向かいの山が足りないときの処理
		if(  sla_num != 0 ) {
			for( i = 1 ; i <= sla_num; i ++ ) {
				puddle[num_puddle] = count_puddle[back_num + i] + 1;
				sum_puddle += count_puddle[back_num + i] + 1;
				num_puddle ++;
			}
		}*/
		//向かいの山が足りないときの処理
		if( sum_puddle_now > 0) {
			sum_puddle += sum_puddle_now;
			puddle[num_puddle] = sum_puddle_now;
			num_puddle ++;
		}

		//出力処理
		System.out.println(sum_puddle);	
		System.out.print(num_puddle);
		for( i = 0; i < num_puddle; i ++ ) {
			System.out.print(" " + puddle[i]);
		}
		System.out.println();
	}
}

import java.util.Arrays;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

class Main {

  class Node {

    int val;
    Node next;

    public Node(int val) {
      this.val = val;
      this.next = null;
    }

  }

  class Stack {

    Node top;

    public Stack() {
      this.top = null;
    }

    public List<Integer> toArrayList() {
      List<Integer> l = new ArrayList<Integer>();
      Node curr = this.top;
      while (curr != null) {
        l.add(curr.val);
        curr = curr.next;
      }
      return l;
    }

    public boolean isEmpty() {
      return this.top == null;
    }

    public void push(int val) {
      Node newElem = new Node(val);
      newElem.next = this.top;
      this.top = newElem;
    }

    public Integer peek() {
      Node top = this.top;
      if (this.top == null)
        return null;
      return top.val;
    }

    public Integer pop() {
      Node top = this.top;
      if (this.top == null)
        return null;
      this.top = this.top.next;
      return top.val;
    }

    public Integer sum() {
      Node top = this.top;
      int sum = 0;
      while (top != null) {
        sum += top.val;
        top = top.next;
      }
      return sum;
    }

    public void display() {
      Node curr = this.top;
      StringBuilder s = new StringBuilder("");
      while (curr != null) {
        s.append(curr.val + " -> ");
        curr = curr.next;
      }
      s.append("null");
      System.out.println(s);
    }

  }

  int totalArea = 0;
  Stack areas = new Stack();
  Stack areas_far_left = new Stack();
  String[] gradients;

  public Main(String[] gradients) {
    this.gradients = gradients;
  }

  public void merge(int left, int right) {
    int new_area = right - left;
    while (this.areas_far_left.peek() != null && left < this.areas_far_left.peek()) {
      new_area += this.areas.pop();
      this.areas_far_left.pop();
    }
    this.areas.push(new_area);
    this.areas_far_left.push(left);
  }

  public void handleDown(Stack s, int i) {
    s.push(i);
  }

  public void handleUp(Stack s, int right) {
    Integer left = s.pop();
    if (left != null)
      this.merge(left, right);
  }

  public void calculateFloods() {
    Stack s = new Stack();
    for (int i = 0; i < gradients.length; i++) {
      switch(gradients[i]) {
        case "/":
          handleUp(s, i);
          break;
        case "\\":
          handleDown(s, i);
          break;
        default:
          break;
      }
    }
  }

  public void displayOutput() {
    int totalArea = this.areas.sum();
    List<Integer> areas = this.areas.toArrayList();
    Collections.reverse(areas);
    StringBuilder s = new StringBuilder(Integer.toString(areas.size()));
    for (int area : areas) {
      s.append(" " + area);
    }
    System.out.println(totalArea);
    System.out.println(s);
  }

  public static void main(String[] args) {
    Scanner s = new Scanner(System.in);
    String[] gradients = s.nextLine().split("");
    Main x = new Main(gradients);
    x.calculateFloods();
    x.displayOutput();
    s.close();
  }
}

import java.io.*;

class Main {
	static int fieldlen = 0;
	static int fieldstart = 0;
    public static void main(String[] args) {
        BufferedReader kb = new BufferedReader( new InputStreamReader( System.in ) );
        try {

			char[] field = kb.readLine().toCharArray();
			fieldlen = field.length;
			int[] areas = new int[10000];
			int cnt, found, total;

			cnt = total = found  = 0;
            for( int i=0; i<fieldlen; i++ ) {
            	if( '/' != field[i] || '_' != field[i] ) {
	            	found = getArea( field, i );
	            	if( 0 < found ) {
	            		areas[cnt] = found;
	            		total += areas [cnt++];
	            		found = 0;
	            		i = fieldstart;
	            	}
            	}
            }

            StringBuilder output = new  StringBuilder( );
            output.append( total ).append( "\n" );
            output.append( cnt ).append( " " );
           	for( int i=0; i<cnt; i++ ) {
           		output.append( areas[i] ).append( " " );
         	}
         	output.deleteCharAt( output.lastIndexOf( " " ) );
         	System.out.println( output );

	    } catch( IOException e ) {
	        System.err.println( e );
	    }
	}
	public static int getArea( char[] field, int start )
	{
		int i, area, cnt, s, t;
		area = cnt = s = t = 0;
		for( i=start; i<fieldlen; i++ ) {
            if( '\\'== field[i] ) {
            	cnt++;
            	t++;
            	area += cnt;
            } else if( 0 < cnt && '/' == field[i] ) {
            	area += cnt;
            	cnt--;
            	if( 0 == cnt ) { break; }
            } else if( '_' == field[i]  ) {
            	s += cnt;
            }
		}
		if( fieldlen == i ) { 
			area = 0;
		} else {
			area = ( area - t + s );
			fieldstart = i;
		}
		return area;
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.NoSuchElementException;

public class Main {

	public static void main(String[] args) throws NumberFormatException, IOException {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		char[] ch = br.readLine().toCharArray();

		int fuchi = 0;
		int water = 0;

		Deque<Integer> left = new ArrayDeque<Integer>();
		List<Integer> areasL = new ArrayList<Integer>();
		for(int i = 0; i < ch.length; i++){
			switch(ch[i]){
			case '\\':
				left.addFirst(i);
				break;

			case '_':
				break;

			case '/':
				try{
					water += i - left.removeFirst();
					if(left.isEmpty()){
						areasL.add(water);
						water = 0;
						fuchi = i;
					}
				} catch(NoSuchElementException e){
				}
				break;
			}
		}

		water = 0;

		Deque<Integer> right = new ArrayDeque<Integer>();
		List<Integer> areasR = new ArrayList<Integer>();
		for(int i = ch.length - 1; i > fuchi; i--){
			switch(ch[i]){
			case '/':
				right.addFirst(i);
				break;

			case '_':
				break;

			case '\\':
				try{
					water += right.removeFirst() - i;

					if(right.isEmpty()){
						areasR.add(water);
						water = 0;
					}

				} catch(NoSuchElementException e){
				}
				break;
			}
		}

		int sum = 0;
		for(int i : areasL) sum += i;
		for(int i : areasR) sum += i;

		System.out.println(sum);
		System.out.print(areasL.size() + areasR.size() + " ");

		for(int i = 0; i < areasL.size(); i++){
			System.out.print(areasL.get(i) + " ");
		}
		for(int i = areasR.size() - 1; i >= 0; i--){
			System.out.print(areasR.get(i));
			if(i == 0){
				System.out.print("\n");
			} else {
				System.out.print(" ");
			}
		}
	}
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Stack;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
        List<Long> res = new ArrayList<>();
        long depth = 0;
        int last = 0;
        long tmp = 0;
        long sum = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '/') {
                if (depth > 0) {
                    depth--;
                }
                tmp += depth;
                if (depth == 0 && tmp != 0) {
                    last = i;
                    sum += tmp;
                    res.add(tmp);
                    tmp = 0;
                }
            } else if (c == '_') {
                tmp += depth;
            } else { // '\'
                depth++;
                tmp += depth;
            }
        }
        depth = 0;
        tmp = 0;
        Stack<Long> stack = new Stack<>();
        for (int i = s.length() - 1; i > last; i--) {
            char c = s.charAt(i);
            if (c == '/') {
                depth++;
                tmp += depth;
            } else if (c == '_') {
                tmp += depth;
            } else { // '\'
                if (depth > 0) {
                    depth--;
                }
                tmp += depth;
                if (depth == 0 && tmp != 0) {
                    sum += tmp;
                    stack.push(tmp);
                    tmp = 0;
                }
            }
        }
        while (!stack.isEmpty()) {
            res.add(stack.pop());
        }
        System.out.println(sum);
        System.out.print(res.size());
        printList(res);
        System.out.println();
    }

    private static <T> void printList(List<T> list) {
        if (list.isEmpty()) {
            return;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < list.size(); i++) {
            sb.append(" ");
            sb.append(list.get(i));
        }
        System.out.print(sb);
    }
}

