import java.util.*;

class Lake {
	int rpos, lpos, area;
	Lake(int lpos, int rpos, int areaOfChilds) {
		this.rpos = rpos;
		this.lpos = lpos;
		this.area = rpos - lpos - 1 + areaOfChilds;
	}
	void print() {
		System.out.println("lpos:" + lpos + ", rpos:" + rpos + ", area:" + area);
	}
}
public class Main {

	void printArray(int[] a) {
		for (int i = 0; i < a.length; i++) {
			System.out.print(a[i] + " ");
		}
		System.out.println();
	}

	void update(LinkedList<Lake> lakes, int l, int r) {
		LinkedList<Lake> childs = new LinkedList<Lake>();
		int areaOfChilds = 0;
		int i = 0, idx = -1;
		for (Lake lake : lakes) {
			if (l < lake.lpos && lake.rpos < r) {
				childs.addLast(lake);
				areaOfChilds += lake.area;
				if (idx == -1) idx = i;
			} else if (idx == -1 && r <= lake.lpos) {
				idx = i;
			}
			i++;
		}
		lakes.removeAll(childs);
		lakes.add((idx == -1 ? lakes.size() : idx), new Lake(l, r, areaOfChilds));
	}

	void debugPrint(LinkedList<Lake> lakes) {
		for (Lake lake : lakes) {
			lake.print();
		}
		System.out.println();
	}

	void solve(int[] a, int level, int cap, LinkedList<Lake> lakes) {
		for (int i = 0; i < a.length;) {
			int l = -1, r = -1;
			if (a[i] == level && i+1 < a.length && a[i+1] == (level-1)) {
				l = i;
				for (i += 2; i < a.length; i++) {
					if (a[i] == level && a[i-1] == (level-1)) {
						r = i;
						break;
					}
				}
				if (r != -1) {
					update(lakes, l, r);
				}
			}
			if (r == -1) i++;
		}
		//System.out.println(level);
		//debugPrint(lakes);
		if (cap == level) return;
		solve(a, level+1, cap, lakes);
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		String line = sc.nextLine();
		char[] chars = line.toCharArray();
		int[] heights = new int[chars.length + 1];
		heights[0] = 0;  // 基準にする
		int bottom = 0;
		int top = 0;
		for (int i = 1; i < heights.length; i++) {
			int diff = 0;
			switch (chars[i-1]) {
			case '\\':
				diff = -1;
				break;
			case '/':
				diff = +1;
				break;
			case '_':
				diff = 0;
				break;
			}
			heights[i] = heights[i-1] + diff;
			bottom = Math.min(heights[i], bottom);
			top = Math.max(heights[i], top);
		}
		//printArray(heights);
		LinkedList<Lake> lakes = new LinkedList<Lake>();
		solve(heights, bottom+1, top, lakes);

		int sum = 0;
		for (Lake lake : lakes) {
			sum += lake.area;
		}

		System.out.println(sum);
		System.out.println(lakes.size());
		for (Lake lake : lakes) {
			System.out.println(lake.area);
		}
	}

	public static void main(String[] args) {
		new Main().run();
	}

}

import java.util.*;

class Main {
	public static void main(String[] args) {
		Scanner stdIn = new Scanner(System.in);
		String str = stdIn.next();
		int len = str.length();
		int[] level = new int[len+1];
		int top = 0;
		int bottom = 0;
		int nowLevel = 0;

		for (int i=0; i<len; i++) {
			char c = str.charAt(i);
			level[i] = nowLevel;
			if (c == '\') {
				nowLevel--;
			}else if(c == '/'){
				nowLevel++;
			}
			top = Math.max(top,nowLevel);
			bottom = Math.min(bottom,nowLevel);
		}
		level[len] = nowLevel;
		top = Math.max(top,nowLevel);
		bottom = Math.min(bottom,nowLevel);

		boolean[] water = new boolean[len];
		List<Integer> list = new ArrayList<Integer>();
		int sum = 0;

		for (int i=top; i>bottom; i--) {//高さ
			int start = -1;
			for (int j=0; j<len; j++) {//幅
				if (!water[j]) {//水は入っているか
					if ((start==-1?level[j]:level[j+1]) == i) {//levelの一致
						if (start == -1 && level[j]>level[j+1]) {//startが設定されているか '\'であるか
							start = j;
						}else if(start != -1){
							int count = 0;//傾斜数
							int vol = 0;
							for (int k=start; k<j+1; k++) {//面積計算
								vol += Math.abs(level[start] - Math.max(level[k],level[k+1]));
								if(Math.abs(level[k] - level[k+1]) > 0)
									count++;
								water[k] = true;//水を入れる
							}
							vol += count/2;
							sum += vol;//総面積に足す
							list.add(vol);
							start = -1;
						}
					}
				}
			}
		}

		System.out.println(sum);
		System.out.print(list.size());
		for (int i=0; i<list.size(); i++) {
			System.out.print(" "+list.get(i));
		}
		System.out.println();
	}
}

