import java.util.Scanner;
public class Main{
    public static void main(String[] args){
        Scanner s=new Scanner(System.in);
        String po=s.nextLine();
        char a[]=po.toCharArray();
        int high[]=new int[20001];
        int mizu[]=new int[10001];
        int i=0;
        for(char a1 : a){
            i++;
            if(a1=='/') high[i]=high[i-1]+1;
            else if(a1=='_') high[i]=high[i-1];
            else high[i]=high[i-1]-1;
        }
        int j=0,tmp=0,cnt=0;
        while(j<i){
            if(high[j]>high[j+1]){
                int m=j;
                while(m<i){
                    m++;
                    if(high[j]==high[m]){
                        mizu[cnt]=menseki(high,j,m);
                        tmp+=mizu[cnt];
                        cnt++;
                        j=m-1;
                        break;
                    }
                }
            }
            j++;
        }
        System.out.println(tmp);
        System.out.print(cnt);
        for(i=0;i<cnt;i++){
            System.out.print(" "+mizu[i]);
        }
        System.out.println("");

    }
    public static int menseki(int[] high,int first,int last){
        int s=0;
        for(int i=first;i<last;i++){
            if(high[i]>high[i+1]){
                s+=((high[first]-high[i+1])*2-1);
            }else if(high[i]==high[i+1]){
                s+=(high[first]-high[i])*2;
            }else{
                s+=((high[first]-high[i])*2-1);
            }
        }
        return s/2;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) throws IOException {
        final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        final char[] line = reader.readLine().toCharArray();
        reader.close();

        final Deque<Integer> stack = new ArrayDeque<Integer>(line.length);
        final StringBuilder answer = new StringBuilder();

        int sum = 0;
        int count = 0;
        int indexLastZero = 0;
        final int[] process = new int[line.length + 1];
        final int[] graph = new int[line.length + 1];
        for (int i = 0; i < line.length; ++i) {
            if (stack.isEmpty()) indexLastZero = i;
            graph[i] = stack.size();
            process[i] = sum;
            switch (line[i]) {
                case '\\':
                    stack.push(i);
                    break;
                case '/':
                    if (!stack.isEmpty()) {
                        sum += i - stack.pop();
                        if (stack.isEmpty()) {
                            ++count;
                            answer.append(" ").append(sum - process[indexLastZero]);
                        }
                    }
                    break;
            }
        }
        if (stack.isEmpty()) indexLastZero = line.length;
        graph[line.length] = stack.size();
        process[line.length] = sum;

        for (int i = indexLastZero + 1, min; i < graph.length; ++i) {
            min = i;
            for (int j = i + 1; j < graph.length; ++j) {
                if (graph[i] == graph[j] && process[i] != process[j]) {
                    min = j;
                    break;
                }
            }
            if (min != i) {
                ++count;
                answer.append(" ").append(process[min] - process[i]);
                i = min - 1;
            }
        }
        System.out.println(sum);
        System.out.println(count + answer.toString());
    }
}

import java.util.Scanner;

public class Main {
	public static int sumarea(String str, int sdepth, int edepth) {
		int i, len, start = sdepth, end = edepth, depth = 0;
		double area = 0;
		len = str.length();
		for (i = 0; i < len; i++) {
			if (start > end && str.charAt(i) == '\\') {
				start--;
			} else {
				switch (str.charAt(i)) {
					case '\\':
						area += depth - 0.5;
						depth -= 1;
						break;
					case '/':
						area += depth + 0.5;
						depth += 1;
						break;
					case '_':
						area += depth;
						break;
					default:
						continue;
				}
			}
		}
		return (int) -area;
	}

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int i = 0, j = 0, len, start = -1, end = -1, depth = 0, sdepth = 0, edepth = 0, count = 0, memo = 0;
		int sum = 0;
		String str;
		str = scan.next();
		len = str.length();
		j = len / 2 + 1;
		int[] area = new int[j];
		j = 0;
		while (i < len) {
			for (i = memo; i < len; i++) {
				if (start == -1 && str.charAt(i) == '\\') {
					start = i;
					depth = 0;
					sdepth = 0;
				}
				if (start != -1) {
					switch (str.charAt(i)) {
						case '\\':
							depth -= 1;
							break;
						case '/':
							if (end == -1) {
								end = i;
								edepth = depth;
							}
							depth += 1;
							if (depth > edepth) {
								end = i;
								edepth = depth;
							}
							if (edepth == 0) {
								area[j] = sumarea(str.substring(start, end + 1), sdepth, edepth);
								sum += area[j];
								count++;
								j++;
								start = -1;
								end = -1;
							}
							break;
						default:
							continue;
					}
				}
			}
			if (start < end  && sdepth > edepth) {
				area[j] = sumarea(str.substring(start, end + 1), sdepth, edepth);
				sum += area[j];
				count++;
				i = end + 1;
				j++;
				memo = end;
				start = -1;
				end = -1;
			}
			if (i >= len)
				break;
		}
		System.out.print(sum + "\n" + count + " ");
		for (i = 0; i < count; i++) {
			if (i < count - 1) {
				System.out.print(area[i] + " ");
			} else {
				System.out.println(area[i] + "");
			}
		}
		scan.close();
	}
}

import java.util.ArrayList;
import java.util.Scanner;


public class Main {
	static Slope[] data;
	static int[] height;
	static boolean[] mount;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		String input = sc.next();
//		System.out.println(input);
		data = new Slope[input.length()];
		for (int i = 0; i < data.length; i++) {
			char temp = input.charAt(i);
			switch (temp) {
				case '\\':
					data[i] = Slope.DOWN;
					break;
				case '/':
					data[i] = Slope.UP;
					break;
				case '_':
					data[i] = Slope.FLAT;
					break;
				default:
					assert true;
			}
		}

		height = new int[data.length + 1];
		height[0] = 0;
		mount = new boolean [data.length + 1];
		Slope prev = Slope.UP;
		for (int i = 0; i < data.length; i++) {
			height[i + 1] = height[i] + data[i].height;
			if (prev == Slope.UP && data[i] == Slope.DOWN) {
				mount[i] = true;
			}
			if (data[i] != Slope.FLAT) {
				prev = data[i];
			}
		}
		if ( prev == Slope.UP) {
			mount[data.length] = true;
		}

//		for (int i = 0; i < height.length; i++) {
//			System.out.println(height[i] + ":" + mount[i]);
//		}

		ArrayList<Integer> result = new ArrayList<Integer>();
		for (int i = 0; i < height.length; ) {
			int from = nextMount(i);
			int to = nextMount(from + 1);
			if (from == -1) {
				break;
			}
			if (to == -1) {
				i++;
				continue;
			}
			result.add(getSquare(from, to));
			i = to;
		}

		int sum = 0;
		StringBuffer str = new StringBuffer();
		str.append(result.size());
		for (int i = 0; i < result.size(); i++) {
			sum += result.get(i);
			str.append(" ");
			str.append(result.get(i));
		}
		System.out.println(sum);
		System.out.println(str);

		sc.close();
	}

	private static int nextMount(int start) {
		for (int i = start; i < mount.length; i++) {
			if (mount[i] == true) {
				return i;
			}
		}

		return -1;
	}

	private static int getSquare(int from, int to) {
		int min = Math.min(height[from], height[to]);
		int square = 0;
		for (int i = from; i < to; i++) {
			if (height[i] > min || height[i + 1] > min) {
				continue;
			}
			square += (min - height[i] + min - height[i + 1]);
		}
		return square / 2;
	}

	private static enum Slope {
		DOWN(-1), UP(1), FLAT(0);

		int height;
		Slope(int height) {
			this.height = height;
		}
	}
}

