import java.util.LinkedList;
import java.util.Scanner;
public class Main {
	static int anotherSide(int[] map,int x){//baseと同じ高さを持つ一番近いｘ座標を返す
		for(int i=x+1;i<map.length;i++){
			if(map[x]==map[i]) return i;
		}
		return -1;
	}
	static double crossProduct(int x1,int y1,int x2,int y2){
		return x1*y2-y1*x2;
	}
	public static void main(String[] args){
		Scanner scan=new Scanner(System.in);
		String data=scan.next();
		int N=data.length()+1;
		int[] map=new int[N];
		int height=0;
		for(int i=0;i<N;i++ ){
			map[i]=height;
			if(i==N-1){
				break;
			}else{
				if(data.charAt(i)=='\\'){
					height--;
				}else if(data.charAt(i)=='/'){
					height++;
				}else{
					//何もしない。高さが変わらない。
				}
			}
		}
		int base=0;
		int area=0;
		int All=0;
		int nextbase;
		LinkedList<Integer> answer=new LinkedList<Integer>();
		while(true){
			if(base==N-1) break;
			while(!(map[base]>map[base+1])){
				base++;
				if(base==N-1) break;
			}
			nextbase=anotherSide(map,base);
			if(nextbase==-1){//見つからなかった。
				base++;
				continue;
			}else{//水たまりができる。
				//外積
				for(int i=base;i<nextbase;i++){
					area+=crossProduct(i,map[i],i+1,map[i+1]);
				}
				area+=crossProduct(nextbase,map[nextbase],base,map[base]);//面積が求まった
				area/=2;
				area=Math.abs(area);
				All+=area;
				answer.addLast(area);
				area=0;
				base=nextbase;
			}
		}
		System.out.println(All);
		System.out.print(answer.size());
		while(!answer.isEmpty()){
			System.out.print(" "+answer.poll());
		}
		System.out.println();
		scan.close();
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;
import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.Deque;

public class Alds1_3_d {
	public static void main(String[] args) {
		FS r = new FS();
		String str = r.next();
		Deque<Integer> stack = new ArrayDeque<Integer>();
		int tmpsum = 0;
		int sum = 0;
		Deque<int[]> pond = new ArrayDeque<int[]>();
		for(int i=0; i<str.length(); i++) {
			switch(str.charAt(i)) {
				case '\\':
					stack.addLast(i);
					break;
				case '/':
					if(!stack.isEmpty()) {
						int t = stack.pollLast();
						sum += i-t;
						if(pond.isEmpty()) {
							int[] data = {i, t, i-t};
							pond.addLast(data);
						} else {
							int tmppond = i-t;
							while(!pond.isEmpty()) {
								int[] tmp = pond.peekLast();
								if(tmp[0] < t) break;
								tmppond += tmp[2];
								pond.removeLast();
							}
							int[] data = {i, t, tmppond};
							pond.addLast(data);
						}
					}
					break;
				default:
					break;
			}
		}
		System.out.println(sum);
		if(pond.size() == 0) {
			System.out.println(0);
		} else {
			int size = pond.size();
			System.out.print(size + " ");
			for(int i=0; i<size; i++) {
				if(i == size-1) System.out.print(pond.pollFirst()[2]);
				else System.out.print(pond.pollFirst()[2] + " ");
			}
			System.out.println();
		}
	}

	// Read Class
	static class FS {
		private final InputStream in = System.in;
		private final byte[] buffer = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;
		private boolean hasNextByte() {
			if (ptr < buflen) {
				return true;
			} else {
				ptr = 0;
				try {
					buflen = in.read(buffer);
				} catch (IOException e) {
					e.printStackTrace();
				}
				if (buflen <= 0) {
					return false;
				}
			}
			return true;
		}

		private int readByte() { return hasNextByte() ? buffer[ptr++] : -1;}
		private boolean isPrintableChar(int c) {return 33 <= c && c <= 126;}
		private void skipUnprintable() {while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}

		public boolean hasNext() { skipUnprintable(); return hasNextByte();}
		public String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while(isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}
		public int nextInt() {
			return (int)nextLong();
		}
		public long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (b < '0' || '9' < b) {
				throw new NumberFormatException();
			}
			while(true) {
				if ('0' <= b && b <= '9') {
					n *= 10;
					n += b - '0';
				} else if(b == -1 || !isPrintableChar(b)) {
					return minus ? -n : n;
				} else {
					throw new NumberFormatException();
				}
				b = readByte();
			}
		}
	}
}

