class NScanner {

	private BufferedReader br;
	private StringTokenizer tok;

	public NScanner(InputStream is) throws IOException{
		br = new BufferedReader(new InputStreamReader(is));
		getLine();
	}

	private void getLine() throws IOException{
		while(tok == null || !hasNext()){
			tok = new StringTokenizer(br.readLine());
		}
	}

	private boolean hasNext(){
		return tok.hasMoreTokens();
	}

	public String next() throws IOException{
		if(hasNext()){
			return tok.nextToken();
		}else{
			getLine();
			return tok.nextToken();
		}
	}

	public int nextInt() throws IOException{
		if(hasNext()){
			return Integer.parseInt(tok.nextToken());
		}else{
			getLine();
			return Integer.parseInt(tok.nextToken());
		}
	}

	public long nextLong() throws IOException{
		if(hasNext()){
			return Long.parseLong(tok.nextToken());
		}else{
			getLine();
			return Long.parseLong(tok.nextToken());
		}
	}

	public double nextDouble() throws IOException{
		if(hasNext()){
			return Double.parseDouble(tok.nextToken());
		}else{
			getLine();
			return Double.parseDouble(tok.nextToken());
		}
	}
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String str = sc.next();
        int len = str.length();

        Deque<Integer> downPos = new ArrayDeque<>();
        Deque<IntPair> downPosPool = new ArrayDeque<>();

        int totalPool = 0;
        for (int i = 0; i < len; i++) {
            char ch = str.charAt(i);
            if (ch == '\\') {
                downPos.push(i);
            } else if (ch == '/' && !downPos.isEmpty()) {
                int j = downPos.pop();
                int a = i - j;
                totalPool += a;
                while (!downPosPool.isEmpty() && downPosPool.peek().int1 > j) {
                    a += downPosPool.pop().int2;
                }
                downPosPool.push(new IntPair(j, a));
            }
        }
        System.out.println(totalPool);

        int size = downPosPool.size();
        System.out.print(size);
        for (int i = 0; i < size; i++) {
            System.out.print((i == size-1) ? "" : " ");
            System.out.print(downPosPool.pollLast().int2);
        }
        System.out.println();
    }

    static class IntPair {
        int int1;
        int int2;
        IntPair(int i1, int i2) {
            int1 = i1;
            int2 = i2;
        }
    }
}

import java.util.Scanner;
import java.util.ArrayDeque;
public class Main {
    static int LIMIT = 200001;
    public static int[] sectionDiagrams = new int[LIMIT];
    public static void main (String[] args) {
	Scanner scan = new Scanner(System.in);
	char[] section = scan.nextLine().toCharArray();
	calculateDiagrams(section, 1);
	for (int i = 0; i < section.length; i++) {
	    if (section[i] == '\\') {
		section[i] = '/';
	    } else if (section[i] == '/') {
		section[i] = '\\';
	    }
	}
	calculateDiagrams(section, -1);
	ArrayDeque<Integer> diagrams = new ArrayDeque<Integer>();
	int sum = 0;
	for (int i = 0; i < LIMIT; i++) {
	    if (sectionDiagrams[i] != 0) {
		diagrams.add(sectionDiagrams[i]);
		sum += sectionDiagrams[i];
	    }
	}
	System.out.println(sum);
	System.out.print(diagrams.size());
	while (diagrams.size() != 0) {
	    System.out.print(" " + diagrams.poll());
	}
	System.out.println();
    }
    static void calculateDiagrams (char[] section, int direction) {
	boolean isIn = false;
	int outH = 0, nowH = 0;
	int sum = 0, inP = 0;
	int sp = 0;
	if (direction == -1) {
	    sp = section.length - 1;
	}
	for (int i = sp; i >=0 && i < section.length; i += direction) {
	    if (isIn == false) {
		if (section[i] == '\\') {
		    isIn = true;
		    outH = nowH;
		    nowH--;
		    inP = i;
		    sum = 1;
		} else if (section[i] == '/') {
		    nowH++;
		}
	    } else {
		if (section[i] == '\\') {
		    sum += outH - nowH + 1;
		    nowH--;
		} else if (section[i] == '/') {
		    nowH++;
		    sum += outH - nowH;
		} else if (section[i] == '_') {
		    sum += outH - nowH;
		}
		if (nowH == outH) {
		    if (direction == 1 && sectionDiagrams[inP] < sum) {
			sectionDiagrams[inP] = sum;
		    } else if (direction == -1 && sectionDiagrams[i] < sum){
			sectionDiagrams[i] = sum;
		    }
		    isIn = false;
		}
	    }
	}
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		String[] str = sc.nextLine().split("");
		Deque<Integer> que = new ArrayDeque<>();
		Deque<List<Integer>> puddle = new ArrayDeque<>();
		for (int i = 0; i < str.length; i++) {
			if (str[i].equals("\\")) {
				que.add(i);
			} else if(str[i].equals("/")) {
				if (que.size() == 0) {
					continue;
				} else {
					int l = que.pollLast();
					int s = i - l;
					if(puddle.size() == 0) {
						puddle.addLast(new ArrayList<>());
						puddle.getLast().add(0, l);
						puddle.getLast().add(1, s);
					} else {
						if(l > puddle.getLast().get(0)) {
							puddle.addLast(new ArrayList<>());
							puddle.getLast().add(0, l);
							puddle.getLast().add(1, s);
						} else {
							List<Integer> list = puddle.pollLast();
							while (true) {
								s += list.get(1);
								if (puddle.size() == 0) {
									break;
								} else if(puddle.getLast().get(0) < l) {
									break;
								} else {
									list = puddle.pollLast();
								}
							}
							puddle.add(new ArrayList<>());
							puddle.getLast().add(0, l);
							puddle.getLast().add(1, s);
						}
					}
				}
			}
		}
		int sum = 0;
		Iterator<List<Integer>> it = puddle.iterator();
		while (it.hasNext()) {
			List<Integer> next = it.next();
			sum += next.get(1);
		}
		System.out.println(sum);
		System.out.print(puddle.size() + " ");
		it = puddle.iterator();
		while (it.hasNext()) {
			List<Integer> next = it.next();
			if(!it.hasNext()) {
				System.out.println(next.get(1));
			} else {
				System.out.print(next.get(1) + " ");
			}
		}
	}
}

