import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;
import java.util.Stack;

/**
 * ZAKIREN第5章 4-6.データ構造の応用
 * 
 * @author tdi5277
 *
 */
public class Main {
	/** 入力用 */
	private static Scanner scan = new Scanner(System.in);

	/** 出力用 */
	private static StringBuilder stringBuilder = new StringBuilder();

	/**
	 * メイン。
	 * 
	 * @param args 未使用
	 */
	public static void main(String[] args) {
		// 読み込み
		String terrain = scan.nextLine();

		// 読み込み終了
		scan.close();
		scan = null;

		// 計算用スタックの宣言
		Stack<Integer> s1 = new Stack<>();
		Stack<Map<Integer, Integer>> s2 = new Stack<>();

		// 文字数分ループ
		int sum = 0;
		for (int i = 0; i < terrain.length(); i++) {
			char target = terrain.charAt(i);
			if (target == '\\') {
				s1.push(i);
			} else if (target == '/' && s1.size() > 0) {
				int j = s1.pop();
				sum += i - j;
				int a = i - j;
				if (s2.size() > 0) {
					Map<Integer, Integer> s2Map = s2.peek();
					Set<Integer> temp = s2Map.keySet();
					Object[] keys = temp.toArray();
					Integer key = (Integer) keys[0];
					while (s2.size() > 0 && key > j) {
						a += s2Map.get(key);
						s2.pop();

						if (s2.size() > 0) {
							s2Map = s2.peek();
							temp = s2Map.keySet();
							keys = temp.toArray();
							key = (Integer) keys[0];
						}
					}
				}
				Map<Integer, Integer> pushS2Map = new HashMap<>();
				pushS2Map.put(j, a);
				s2.push(pushS2Map);
			}
		}

		// 結果出力 合計
		stringBuilder.append(sum + "\n");

		// 結果出力 水たまりの数
		int size = s2.size();
		stringBuilder.append(size);

		// 各面積を逆順に並び替える
		Stack<Integer> reverse = new Stack<>();
		while (s2.size() > 0) {
			Map<Integer, Integer> map = s2.pop();
			Set<Integer> temp = map.keySet();
			Object[] keys = temp.toArray();
			Integer key = (Integer) keys[0];
			reverse.push(map.get(key));
		}
		Collections.reverse(new ArrayList<>(reverse));

		// 結果出力 各面積
		while (reverse.size() > 0) {
			stringBuilder.append(" " + reverse.pop());
		}

		System.out.println(stringBuilder.toString());

	}

}

import java.util.ArrayList;
import java.util.Scanner;

/**
 * ACSD
 */
public class Main {
    // 現在のx座標
    public int lineNumber;

    // 現在の 層別未確定水たまりスタック
    public int[] stack = new int[20000];
    // 未確定水たまり層の始点
    public int[] stackStart = new int[20000];
    // 確定水たまりリスト
    public int[] puddles = new int[10000];
    // 確定水たまり層の始点
    public int[] puddleStart = new int[10000];
    // 現在の確定水たまりIdx
    public int puddleNumber = 0;
    // 現在の深さ
    public int currentDepth = 0;
    // 前回の水たまり水面高
    public int prevPuddleHeight = -1;

    public int sum = 0;

    /**
     * 指定の層へ水を追加する
     *
     * @param idx       追加する層Idx
     * @param n         追加量
     * @param isConfirm 層確定操作を行うかどうか
     */
    public void add(int idx, int n, boolean isConfirm) {
        // 初出層の場合はstackに追加
        if (this.stackStart[idx] == -1) {
            this.stackStart[idx] = lineNumber;
        }
        // 追加動作
        this.stack[idx] += n;
        // 層確定操作
        if (isConfirm) {
            this.sum += this.stack[idx];
            // 現在の未確定水たまり層を、確定水たまりリストに移す
            this.puddles[puddleNumber] = this.stack[idx] / 2;
            // 追加した確定水たまりの始点も設置
            this.puddleStart[puddleNumber] = this.stackStart[idx];
            // 初回の層確定操作でない && 前回の層確定操作の1つ上位層の場合
            if ((prevPuddleHeight != -1) && ((prevPuddleHeight - 1) == idx)) {
                // 繰り上がり動作を行う
                // 各確定水たまりについて、初めて (現在の水たまりの始点) < (ある水たまり始点) となるものを探す
                int start = this.puddleStart[puddleNumber];
                for (int i = 0; i <= puddleNumber; i++) {
                    // (現在の水たまりの始点) < (ある水たまり始点) Hit!!
                    if (start < this.puddleStart[i]) {
                        // ある地点の水たまりを吸収
                        // はじめに始点を更新
                        this.puddleStart[i] = start;
                        // 次に、その間の水たまり量をすべて吸収
                        for (int j = i + 1; j <= puddleNumber; j++) {
                            this.puddles[i] += this.puddles[j];
                        }
                        for (int j = puddleNumber; j >= i + 1; j--) {
                            this.puddles[j] = 0;
                            this.puddleStart[j] = 0;
                        }
                        puddleNumber = i + 1;
                        break;
                    }
                }
            } else { // 繰り上がり動作を行わない場合
                puddleNumber++;
            }
            prevPuddleHeight = idx;
            this.stack[idx] = 0;
            this.stackStart[idx] = -1;
        }
    }

    public void up() {
        if (currentDepth == 0) {
            return;
        }
        currentDepth--;
        this.add(currentDepth, 1, true);
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void hori() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void down() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
        this.add(currentDepth, 1, false);
        currentDepth++;
    }

    public void print() {
        System.out.println(sum / 2);
        int len = puddleNumber;
        System.out.print(len);
        for (int i = 0; i < len; i++) {
            System.out.print(" " + this.puddles[i]);
        }
        System.out.println();
    }

    public void go() {
        for (int i = 0; i < this.stackStart.length; i++) {
            this.stackStart[i] = -1;
        }
        Scanner sc = new Scanner(System.in);
        String line = sc.next();
        String[] strings = line.split("");
        for (int i = 0; i < strings.length; i++) {
            String s = strings[i];
            this.lineNumber = i;
            switch (s) {
            case "\\":
                this.down();
                break;
            case "_":
                this.hori();
                break;
            case "/":
                this.up();
                break;
            }
        }
        print();
    }

    public static void main(String[] args) {
        Main cui = new Main();
        cui.go();
    }
}

