import java.util.Scanner;
import java.util.Stack;

/**
 * ZAKIREN第5章
 *
 * @author K.Yamauchi
 *
 */
public class Main {

	/** 入力用 */
	private static Scanner scan = new Scanner(System.in);

	/** 出力用 */
	private static StringBuilder stringBuilder = new StringBuilder();

	/**
	 * 総合面積を計算します。
	 * @param terrain
	 */
	private static void calcTotalArea(String terrain) {

		Stack<Integer> totalAreaStack = new Stack<>(); // 計算用スタック
		int totalArea = 0;                              // 総合面積

		// 総合面積の計算
		for (int i = 0; i < terrain.length(); i++) {
			if (terrain.charAt(i) == '\\') {
				totalAreaStack.push(i);
			} else if (terrain.charAt(i) == '/' && totalAreaStack.size() > 0) {
				int from = totalAreaStack.pop();
				totalArea += i - from;
			}
		}

		// 結果を保持
		stringBuilder.append(totalArea);
	}

	/**
	 * 各面積を計算します。
	 * @param terrain
	 */
	private static void calcEachArea(String terrain) {

		Stack<Integer> backslashStack = new Stack<>();
		Stack<Integer> slashStack = new Stack<>();
		Stack<Integer> eachAreaStack = new Stack<>();
		int eachArea = 0;

		// 各面積の計算
		for (int i = 0; i < terrain.length(); i++) {
			if (terrain.charAt(i) == '/' && backslashStack.size() > 0) {
				slashStack.push(i);
				int from = backslashStack.pop();
				int to = slashStack.pop();
				eachArea += to - from;
				if (backslashStack.size() <= slashStack.size() || (i == terrain.length() - 1 && eachArea > 0)) {
					eachAreaStack.push(eachArea);
					eachArea = 0;
				}
//			} else if (i == terrain.length() - 1 && backslashStack.size() > 0 && eachArea > 0) {
			} else if (i == terrain.length() - 1 && terrain.charAt(i) == '\\' && eachArea > 0) {
				eachAreaStack.push(eachArea);
				eachArea = 0;
			} else  if (terrain.charAt(i) == '\\') {
				backslashStack.push(i);
			} else if (terrain.charAt(i) == '/') {
				if (backslashStack.size() > 0) {
					slashStack.push(i);
				}
			}
		}

		// 結果出力用
		int size = eachAreaStack.size();
		stringBuilder.append(size);
		if (size != 0) {
			stringBuilder.append(" ");
		}
		for (int i = 0 ; i < size; i++) {
			stringBuilder.append(eachAreaStack.get(i));
			if (i < size - 1) {
				stringBuilder.append(" ");
			}
		}

	}

	/**
	 * メイン。
	 * @param args
	 */
	public static void main(String[] args) {

		// １行目の読み込み
		String terrain = scan.nextLine();

		// 読み込み終了
		scan.close();
		scan = null;

		// 計算
		calcTotalArea(terrain);
		stringBuilder.append("\n");
		calcEachArea(terrain);

		// 結果出力
		System.out.println(stringBuilder.toString());

	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Iterator;
import java.util.Stack;

public class Main {

	public static void main(String[] args) throws IOException {

		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));		
		String profile = reader.readLine();

		Stack<Integer> stackDown = new Stack<Integer>();
		Stack<Integer> stackArea = new Stack<Integer>();
		Stack<Integer> stackEdge = new Stack<Integer>();
		int totalArea = 0;
		int pos = 0;
		int lv = 0;

		for (char c : profile.toCharArray()) {
			if (c == '\\') {
				lv--;
				stackDown.push(pos);
			} else if (c == '/') {
				lv++;
				if (!stackDown.empty()) {
					int start = stackDown.pop();
					int tempArea = pos - start;
					totalArea += tempArea;
					if (stackArea.empty()) {
						stackArea.push(tempArea);
						stackEdge.push(lv);
					} else {
						int lastArea = 0;
						while (!stackEdge.empty() && stackEdge.peek() < lv) {
							lastArea += stackArea.pop();
							stackEdge.pop();
						}
						stackArea.push(lastArea + tempArea);
						stackEdge.push(lv);
					}
				} else {
					if (!stackArea.empty()) {
						stackEdge.pop();
						stackEdge.push(lv);
					}
				}
			}
			pos++;
		}

		System.out.println(totalArea);
		System.out.print(stackArea.size());
		if (stackArea.size() != 0) {
			System.out.print(" ");
		}
		Iterator<Integer> itr = stackArea.iterator();
		while (itr.hasNext()) {
			System.out.print(itr.next());
			if (itr.hasNext()) {
				System.out.print(" ");
			}
		}
		System.out.println("");
	}
}

