					d[i] = depth;
					depth++;
					break;
				case '_':
					d[i] = depth;
					break;
				default:
					continue;
			}
		}
		d[len] = depth;
		if (d[start] > d[end + 1]) {
			horizon = d[end + 1];
		} else {
			horizon = d[start];
		}
		for (i = start; i < end + 1; i++) {
