		int[] mountainH = new int[S.length+1];
		int[] waterH = new int[S.length+1];

		int maxMH = 0;
		for(int i = 0; i < S.length; i++){
			if(S[i] == '\\') mountainH[i+1] = mountainH[i] - 1;
			else if(S[i] == '/') mountainH[i+1] = mountainH[i] + 1;
			else mountainH[i+1] = mountainH[i];
			maxMH = Math.max(maxMH, mountainH[i+1]);
			waterH[i+1] = maxMH;
		}

		maxMH = mountainH[S.length];
		waterH[S.length] = Math.min(waterH[S.length], maxMH);
		for(int i = S.length-1; i >= 0; i--){
			maxMH = Math.max(maxMH, mountainH[i]);
			waterH[i] = Math.min(waterH[i], maxMH);
		}

