import java.util.Scanner;


public class Main {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		String tmp = scanner.nextLine();
		char line[] = tmp.toLowerCase().toCharArray();

		scanner.close();
		int startIndex =0;
		int lastIndex =0;
		//先頭が　\ の番号をチェック
		for(int i = 0; i < line.length; i++) {
			if("\\".equals(String.valueOf(line[i]))) {
				startIndex = i;
				break;
			}
		}
		//最後が　/ の番号をチェック
		for(int i = line.length -1; i >= 0; i--) {
			if("/".equals(String.valueOf(line[i]))) {
				lastIndex = i;
				break;
			}
		}

		//現在は面積計算対象かどうか
		boolean isLake = false;
		int depth = 0;
		//トータル水量
		double floods = 0;
		double flood = 0;
		//水たまり数
		int lakeNumber = 0;
		//各水たまりの面積
		double [] l = new double[3000];
		for (int j = startIndex; j <= lastIndex; j++) {
			String moji = String.valueOf(line[j]);
			//前から断面が変更になった場合 計算開始
			if("\\".equals(moji) && !isLake) {
				//同じ高さがあとから出てくる場合
				if(isSameHight(j,line)) {
 				    isLake = true;
				    //水量0.5+
				    floods += 0.5;
				    flood = 0.5;
				    lakeNumber++;
				    depth++;
				}
			} else if("\\".equals(moji) && isLake) {
				//水量0.5+
				floods += depth + 0.5;
				flood += depth + 0.5;
				depth++;
			} else if ("/".equals(moji) && (depth == 1)) {
			//下り断面と同等の高さになる場合
				isLake = false;
			    //次は0固定
				depth = 0;
				//水量0.5+
				floods += 0.5;
				flood += 0.5;
				l[lakeNumber - 1] = flood;
			} else if ("/".equals(moji) && (depth > 1)) {
				//先に１上昇
				depth--;
				//水量0.5+
				floods += depth + 0.5;
				flood += depth + 0.5;
			} else if ("_".equals(moji) && (depth > 0)) {
				//水量水深分+
				floods += depth;
				flood += depth;
			}

		}
		System.out.println((int)floods);
		System.out.print(lakeNumber);
		for (int x=0; x < lakeNumber; x++){
			System.out.print(" " + (int) l[x]);
		}
		System.out.println();
	}

	static boolean isSameHight(int fromvalue,char line[]) {
		int hight = 0;
		for (int i = fromvalue; i < line.length; i++) {
			String moji2 = String.valueOf(line[i]);
			if("\\".equals(moji2)) {
				hight ++;
			} else if ("/".equals(moji2)) {
				hight --;
				if(hight == 0) {
					return true;
				}
   		    }
		}
		return false;
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        try {
            String line = br.readLine();
            int[] height = new int[line.length() + 1];
            height[0] = 0;
            for (int i = 0; i < line.length(); i++) {
                if (line.charAt(i) == '\\') {
                    height[i + 1] = height[i] - 1;
                } else if (line.charAt(i) == '/') {
                    height[i + 1] = height[i] + 1;
                } else {
                    height[i + 1] = height[i];
                }
            }

            ArrayList<Integer> pondsArea = new ArrayList<>();
            double area = 0.0;
            double areaTotal = 0.0;
            int numberPonds = 0;
            int startPos = 0;
            int maxPos;
            int minHeight;
            int maxHeight;
            int endPos = 0;
            int level = 0;
            boolean hasPond;
            loop : while (startPos < height.length - 1) {
                hasPond = false;
                minHeight = height[startPos];
                maxHeight = -20001;
                maxPos = startPos;

                search: for (int i = startPos + 1; i < height.length; i++) {
                    minHeight = Math.min(minHeight, height[i]);
                    if (height[i] > height[i - 1] && maxHeight < height[i]) {
                        maxPos = i;
                        maxHeight = Math.max(maxHeight, height[i]);

                    }
                    if (height[startPos] <= height[i]) {
                        endPos = i;
                        if (height[startPos] > minHeight && height[endPos] > minHeight) {
                            hasPond = true;
                            numberPonds++;
                            level = height[endPos];
                            break;
                        } else {
                            startPos++;
                            break;
                        }
                    } else if (i == height.length - 1) {
                        for (int j = startPos ; j < maxPos; j++) {
                            if(height[j]==height[maxPos]){
                                level = height[maxPos];
                                hasPond=true;
                                numberPonds++;
                                startPos=j;
                                endPos=maxPos;
                                break search;
                            }
                        }
                        break loop;
                    }
                }

                if (hasPond) {
                    for (int i = startPos; i < endPos; i++) {
                        double a = level > height[i] ? level - height[i] : 0;
                        double b = level > height[i + 1] ? level - height[i + 1] : 0;
                        area += (a + b) / 2;
                    }
                    pondsArea.add((int) area);
                    areaTotal += area;
                    area = 0;
                    startPos = endPos;
                }
            }

            System.out.println((int) areaTotal);
            System.out.print(numberPonds);
            if (pondsArea.size() > 0) {
                for (Integer integer : pondsArea) {
                    System.out.print(" " + integer);
                }
            }
            System.out.println();

        } catch (Exception e) {
            e.printStackTrace();
        }

    }
}

