			cnt++;
		}

		max[map.length - 1] = map[map.length - 1];
		for(int i = map.length - 2; i >= 0; i--){
			max[i] = Math.max(max[i + 1], map[i]);
		}

		LinkedList<Plane> stack = new LinkedList<Plane>();
		LinkedList<Integer> area_list = new LinkedList<Integer>();

		int total_area = 0, cur_area = 0;
		for(int i = 1; i < map.length; i++){
			final int prev_diff = map[i] - map[i - 1];

			if(prev_diff > 0 && !stack.isEmpty()){
				Plane before = stack.removeFirst();
				total_area += (i - before.pos);
				cur_area += (i - before.pos);

				if(stack.isEmpty() || max[i] <= map[i]){
					area_list.add(cur_area);
					cur_area = 0;
				}

			}else if(prev_diff < 0){
				stack.addFirst(new Plane(map[i], i));
			}
		}

		if(cur_area != 0){
			area_list.add(cur_area);
		}

		System.out.println(total_area);
		System.out.print(area_list.size());
		for(int i : area_list){
			System.out.print(" " + i);
		}
		System.out.println();

	}

	public static class Scanner {
	    private BufferedReader br;
	    private StringTokenizer tok;

	    public Scanner(InputStream is) throws IOException {
	        br = new BufferedReader(new InputStreamReader(is));
	    }

	    private void getLine() throws IOException {
	        while (!hasNext()) { tok = new StringTokenizer(br.readLine()); }
	    }

	    private boolean hasNext() {
	        return tok != null && tok.hasMoreTokens();
	    }

	    public String next() throws IOException {
	        getLine(); return tok.nextToken();
	    }

	    public int nextInt() throws IOException {
	        return Integer.parseInt(next());
	    }

	    public long nextLong() throws IOException {
	    	return Long.parseLong(next());
	    }

	    public void close() throws IOException {
	        br.close();
	    }
	}

}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int i, len, start = -1, end = 0, depth = 0, horizon, count = 0;
		double sum = 0;
		String str;
		str = scan.next();
		len = str.length();
		int[] d = new int[len + 1];
		for (i = 0; i < len; i++) {
			switch (str.charAt(i)) {
				case '\\':
					if (start == -1) {
						start = i;
					}
					d[i] = depth;
					depth--;
					break;
				case '/':
					end = i;
					d[i] = depth;
					depth++;
					break;
				case '_':
					d[i] = depth;
					break;
				default:
					continue;
			}
		}
		d[len] = depth;
		if (d[start] > d[end + 1]) {
			horizon = d[end + 1];
		} else {
			horizon = d[start];
		}
		for (i = start; i < end + 1; i++) {
			if (d[i] > d[end + 1]) {
				continue;
			}
			switch (str.charAt(i)) {
				case '\\':
					sum += (horizon - d[i]) * 1 + 0.5;
					break;
				case '/':
					sum += (horizon - d[i + 1]) * 1 + 0.5;
					break;
				case '_':
					sum += (horizon - d[i]) * 1;
					break;
				default:
					continue;
			}
		}
		if (sum > 0) {
			count = 1;
		}
		System.out.printf("%.0f\n%d", sum,count);
		if(count>0) {
			System.out.printf(" %.0f",sum);
		}
		System.out.println("");
		scan.close();
	}
}

