//			switch (mod % 3) {
//			case 0:
//				str2.append('/');
//				break;
//			case 1:
//				str2.append('\\');
//				break;
//			case 2:
//				str2.append('_');
//				break;
//			default:
//				assert true;
//			}
//		}
//		String input = str2.toString();
//		System.out.println(input);

		data = new Slope[input.length()];

		for (int i = 0; i < data.length; i++) {
			char temp = input.charAt(i);
			switch (temp) {
				case '\\':
					data[i] = Slope.DOWN;
					break;
				case '/':
					data[i] = Slope.UP;
					break;
				case '_':
					data[i] = Slope.FLAT;
					break;
				default:
					assert true;
			}
		}

		height = new int[data.length + 1];
		height[0] = 0;
		mount = new boolean [data.length + 1];
		Slope prev = Slope.UP;
		for (int i = 0; i < data.length; i++) {
			height[i + 1] = height[i] + data[i].height;
			if (prev == Slope.UP && data[i] == Slope.DOWN) {
				mount[i] = true;
			}
			if (data[i] != Slope.FLAT) {
				prev = data[i];
			}
		}
		if ( prev == Slope.UP) {
			mount[data.length] = true;
		}

//		for (int i = 0; i < height.length; i++) {
//			System.out.println(height[i] + ":" + mount[i]);
//		}

		ArrayList<Integer> result = new ArrayList<Integer>();
		for (int i = 0; i < height.length - 1; ) {
			int from = nextMount(i);
			if (from == -1) {
				break;
			}
			i = from;
			int to = highestMount(from + 1);
			if (to == -1) {
				i++;
				continue;
			}
			result.add(getSquare(from, to));
			i = to;
		}

		int sum = 0;
		StringBuffer str = new StringBuffer();
		str.append(result.size());
		for (int i = 0; i < result.size(); i++) {
			sum += result.get(i);
			str.append(" ");
			str.append(result.get(i));
		}
		System.out.println(sum);
		System.out.println(str);

		sc.close();
	}

	private static int nextMount(int start) {
		for (int i = start; i < mount.length; i++) {
			if (mount[i] == true) {
				return i;
			}
		}

		return -1;
	}

	private static int highestMount(int start) {
		int maxHeight = Integer.MIN_VALUE;
		int maxIndex = -1;
		for (int i = start; i < mount.length; i++) {
			if (mount[i] == true && maxHeight < height[i]) {
				maxIndex = i;
				maxHeight = height[i];
			}
		}

		return maxIndex;
	}

	private static int getSquare(int from, int to) {
		int min = Math.min(height[from], height[to]);
		int square = 0;
		for (int i = from; i < to; i++) {
			if (height[i] > min || height[i + 1] > min) {
				continue;
			}
			square += (min - height[i] + min - height[i + 1]);
		}
		return square / 2;
	}

	private static enum Slope {
		DOWN(-1), UP(1), FLAT(0);

		int height;
		Slope(int height) {
			this.height = height;
		}
	}
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String str = sc.next();
        int len = str.length();

        Deque<Integer> downPos = new ArrayDeque<>();
        Deque<IntPair> downPosPool = new ArrayDeque<>();

        int totalPool = 0;
        for (int i = 0; i < len; i++) {
            char ch = str.charAt(i);
            if (ch == '\\') {
                downPos.push(i);
            } else if (ch == '/' && !downPos.isEmpty()) {
                int j = downPos.pop();
                int a = i - j;
                totalPool += a;
                while (!downPosPool.isEmpty() && downPosPool.peek().int1 > j) {
                    a += downPosPool.pop().int2;
                }
                downPosPool.push(new IntPair(j, a));
            }
        }
        System.out.println(totalPool);

        int size = downPosPool.size();
        System.out.print(size);
        for (int i = 0; i < size; i++) {
            System.out.print(" ");
            System.out.print(downPosPool.pollLast().int2);
        }
        System.out.println();
    }

    static class IntPair {
        int int1;
        int int2;
        IntPair(int i1, int i2) {
            int1 = i1;
            int2 = i2;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) throws IOException {
        final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        final char[] line = reader.readLine().toCharArray();
        reader.close();

        final Deque<Integer> stack = new ArrayDeque<Integer>(line.length);
        final StringBuilder answer = new StringBuilder();

        int sum = 0;
        int count = 0;
        int indexLastZero = 0;
        final int[] process = new int[line.length + 1];
        final int[] graph = new int[line.length + 1];
        for (int i = 0; i < line.length; ++i) {
            graph[i] = stack.size();
            process[i] = sum;
            switch (line[i]) {
                case '\\':
                    stack.push(i);
                    break;
                case '/':
                    if (!stack.isEmpty()) {
                        sum += i - stack.pop();
                        if (stack.isEmpty()) {
                            ++count;
                            answer.append(" ").append(sum - process[indexLastZero]);
                        }
                    }
                    break;
                default:
            }
            if (stack.isEmpty()) indexLastZero = i;
        }
        graph[line.length] = stack.size();
        process[line.length] = sum;

        for (int i = indexLastZero + 1; i < process.length; ++i) {
            for (int j = graph.length - 1; i < j; --j) {
                if (graph[i] == graph[j] && process[i] != process[j]) {
                    ++count;
                    answer.append(" ").append(process[j] - process[i]);
                    i = j;
                    break;
                }
            }
        }

        System.out.println(sum);
        System.out.println(count + answer.toString());
    }
}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    try (Scanner sc = new Scanner(System.in)) {
      solve(sc);
    }
  }

  static void solve(Scanner sc) {
    ArrayDeque<Integer> idxList = new ArrayDeque<>();
    ArrayDeque<Puddle> areaStuck = new ArrayDeque<>();// 水たまりスタック
    char[] input = sc.next().toCharArray();

    for (int i = 0; i < input.length; i++) {
      if (input[i] == '\\') {
        idxList.push(i);
      } else if (input[i] == '/' && idxList.size() > 0) {
        // 水たまりができたら、対応する\の位置と面積をつど求める
        int j = idxList.pop();
        int tmp = i - j;
        // もっと大きい水たまりができるなら、スタックから取り出して集約する
        while (areaStuck.size() > 0 && areaStuck.peek().beginIndex > j) {
          Puddle stuck = areaStuck.pop();
          tmp += stuck.area;
        }
        areaStuck.push(new Puddle(i, tmp));
      }
    }

    int sum = 0, cnt = areaStuck.size();
    StringBuilder sb = new StringBuilder();
    while (!areaStuck.isEmpty()) {
      int tmp = areaStuck.removeLast().area;
      sb.append(tmp).append(' ');
      sum += tmp;
    }
    System.out.println(sum);
    System.out.print(cnt);
    System.out.println(sb.length() > 0 ? (" " + sb.toString().trim()) : "");
  }
}

class Puddle {
  int beginIndex;
  int area;

  Puddle(int beginIndex, int area) {
    this.beginIndex = beginIndex;
    this.area = area;
  }
}

