/**
 * 境界部分には気をつける(そこだけ別で処理するというのもあり)
 * 逆再生することで簡単になることもある
 */
public class Main {
    public Main() {
    }

    public static void main(String[] args ) {
    		Main main = new Main();
    		main.exec();
    }

    public void exec() {
        BufferedReader bf = null;
        try{
            bf = new BufferedReader(new InputStreamReader(System.in));
            exec_body(bf);
        } catch (IOException e) {
			e.printStackTrace();
		}
        finally{
            if( bf != null ) {
                try {
					bf.close();
				} catch (IOException e) {
					e.printStackTrace();
				}
            }
        }
    }

    public String omitString( String line ) {
		ArrayList<String> charList = new ArrayList<>();
		// 計算に不要な部分を最初に除く
		boolean isFirst = true;
		for( int i = 0; i < line.length(); i++ ) {
			char ch = line.charAt(i);
			if( isFirst && ch == '/' ) {
				continue;
			}

			isFirst = false;
			charList.add(String.valueOf(ch));
		}

		isFirst = true;
		ArrayList<String> charList2 = new ArrayList<>();
		for( int i = charList.size() -1; i >= 0; i-- ) {
			String ch = charList.get(i);
			if( isFirst && ch == "\\" ) {
				continue;
			}

			isFirst = false;
			charList2.add(ch);
		}

		StringBuilder bd = new StringBuilder();
		for( int i = charList2.size() -1; i >= 0; i--  )
		{
			String ch = charList2.get(i);
			bd.append(ch);
		}

		return bd.toString();
    }

    public void exec_body( BufferedReader bf ) throws IOException {
    		String line = bf.readLine();
    		line = omitString(line);

    		Stack<Boolean> charStack = new Stack<>();
    		int dimension = 0;
    		ArrayList<Integer> dimensionList = new ArrayList<>();
    		for( int i = 0; i < line.length(); i++ ) {
    			char ch = line.charAt(i);
    			if( ch == '\\' ) {
    				dimension = dimension + 1 + 2 * charStack.size();
    				charStack.push(Boolean.TRUE);
    			} else if( ch == '_') {
    				dimension = dimension + 2 * charStack.size();
    			} else {
    				if( charStack.size() == 0 ) {
        				continue;
    				}

    				charStack.pop();
    				dimension = dimension + 1 + 2 * charStack.size();
    				if( charStack.size() != 0 ) {
    					continue;
    				}

    				// listに入れて初期化する
    				dimensionList.add(Integer.valueOf(dimension));
    				dimension = 0;
    			}
    		}
    		if( dimension != 0 ) {
    			// 逆から計算し直して、1つめの水たまりでやめる
        		charStack = new Stack<>();
        		dimension = 0;
    			for( int i = line.length() -1; i >= 0; i--) {
        			char ch = line.charAt(i);
        			if( ch == '/' ) {
        				dimension = dimension + 1 + 2 * charStack.size();
        				charStack.push(Boolean.TRUE);
        			} else if( ch == '_') {
        				dimension = dimension + 2 * charStack.size();
        			} else {
        				if( charStack.size() == 0 ) {
            				continue;
        				}

        				charStack.pop();
        				dimension = dimension + 1 + 2 * charStack.size();
        				if( charStack.size() != 0 ) {
        					continue;
        				}

        				break;
        			}
    			}
    			dimensionList.add(Integer.valueOf(dimension));
    		}

    		int sum = 0;
    		for( int i = 0; i < dimensionList.size(); i++ ) {
    			sum = sum + dimensionList.get(i);
    		}
    		System.out.println(sum/2);

    		// 結果を出力する
    		StringBuilder bd = new StringBuilder();
    		bd.append(dimensionList.size());
    		for( int i = 0; i < dimensionList.size(); i++ ) {
    			bd.append(" ");
    			bd.append(dimensionList.get(i)/2);
    		}
    		System.out.println(bd.toString());
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.AbstractMap;
import java.util.AbstractMap.SimpleEntry;
import java.util.LinkedList;
import java.util.ListIterator;

public class Main {
    static final char DOWN = '\\';
    static final char UP = '/';
    static final char FLAT = '_';

    private static class Data {
        public int start;
        public int end;
        public int area;

        public Data(int start, int end, int area) {
            this.start = start;
            this.end = end;
            this.area = area;
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        LinkedList<Integer> resolvedList = new LinkedList();
        LinkedList<Integer> slopeStack = new LinkedList();
        LinkedList<Data> unresolvedStack = new LinkedList();

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String landForm = br.readLine();

        for(int pos = 0; pos < landForm.length(); pos++) {
            if(landForm.charAt(pos) == DOWN) {
                slopeStack.add(pos);
                continue;
            } else if(landForm.charAt(pos) == FLAT) {
                continue;
            }

            // UP
            if(slopeStack.size() == 0) {
                while(unresolvedStack.size() != 0) {
                    Data data = unresolvedStack.removeLast();
                    resolvedList.addFirst(data.area);
                }
                continue;
            }

            int before = slopeStack.removeLast();
            Data data = new Data(before, pos, pos - before);
            while(true) {
                if(unresolvedStack.size() == 0) {
                    unresolvedStack.add(data);
                    break;
                }

                Data beforeData = unresolvedStack.removeLast();
                if(beforeData.start > data.start && beforeData.end < data.end) {
                    data.area += beforeData.area;
                } else {
                    unresolvedStack.add(beforeData);
                    unresolvedStack.add(data);
                    break;
                }
            }
        }

        int sum = 0;
        int count = 0;
        StringBuilder sb = new StringBuilder();

        ListIterator<Integer> itr = resolvedList.listIterator(0);
        while(itr.hasNext()) {
            int l = itr.next().intValue();
            sum += l;
            count++;

            if(sb.length() != 0) {
                sb.append(" ");
            }

            sb.append(l);
        }

        ListIterator<Data> unItr;
        unItr = unresolvedStack.listIterator(0);
        while(unItr.hasNext()) {
            int l = unItr.next().area;
            sum += l;
            count++;

            if(sb.length() != 0) {
                sb.append(" ");
            }

            sb.append(l);
        }
        System.out.println(sum);
        System.out.print(count);
        if(count == 0) {
            System.out.println();
        } else {
            System.out.println(" " + sb.toString());
        }
    }
}

