import java.util.Scanner;
import java.util.Stack;

public class Main {
	String input;
	public static void main(String args[]) {
		new Main().run();
	}
	Main() {
		Scanner scan = new Scanner(System.in);
		input = scan.nextLine();
	}
	void run() {
		int len = input.length();
		Stack<Area> areaStack = new Stack<Area>();
		Stack<Integer> slash = new Stack<Integer>();
		for (int i = 0; i < len; i++) {
			switch(input.charAt(i)) {
			case '\\':
				slash.push(i);
				break;
			case '/':
				if (!slash.isEmpty()) {
					Area v = new Area(slash.pop(),i);
					while (!areaStack.isEmpty()) {
						Area latest = areaStack.pop();
						if (!v.isChild(latest)) {
							areaStack.push(latest);
							break;
						}
						v.addSize(latest.getSize());
					}
					areaStack.push(v);
				}
				break;
			case '_':
				break;
			}
		}
		int[] areaSize = new int[areaStack.size()];
		int sum = 0;
		for (int i = 0; i < areaSize.length; i++) {
			areaSize[i] = areaStack.pop().getSize();
			sum += areaSize[i];
		}
		System.out.println(sum);
		System.out.print(areaSize.length);
		for (int i = areaSize.length - 1; i >= 0; i--) {
			System.out.print(" " + areaSize[i]);
		}
		System.out.println();
	}
	class Area {
		private int left;
		private int right;
		private int size;
		Area() {
			left = 0;
			right = 0;
		}
		Area(int l,int r){
			left = l;
			right = r;
			size = right - left;
		}
		public void addSize(int i) {
			size += i;
		}
		public boolean isChild(Area area) {
			return left < area.getLeft() && right > area.getRight();
		}
		public int getLeft() {
			return left;
		}
		public int getRight() {
			return right;
		}
		public int getSize() {
			return size;
		}
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;
import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
	public static void main(String[] args) {
		FS r = new FS();
		String str = r.next();
		Deque<Integer> stack = new ArrayDeque<Integer>();
		int tmpsum = 0;
		int sum = 0;
		Deque<int[]> pond = new ArrayDeque<int[]>();
		for(int i=0; i<str.length(); i++) {
			switch(str.charAt(i)) {
				case '\\':
					stack.addLast(i);
					break;
				case '/':
					if(!stack.isEmpty()) {
						int t = stack.pollLast();
						sum += i-t;
						if(pond.isEmpty()) {
							int[] data = {i, t, i-t};
							pond.addLast(data);
						} else {
							int tmppond = i-t;
							while(!pond.isEmpty()) {
								int[] tmp = pond.peekLast();
								if(tmp[0] < t) break;
								tmppond += tmp[2];
								pond.removeLast();
							}
							int[] data = {i, t, tmppond};
							pond.addLast(data);
						}
					}
					break;
				default:
					break;
			}
		}
		System.out.println(sum);
		if(pond.size() == 0) {
			System.out.println(0);
		} else {
			int size = pond.size();
			System.out.print(size + " ");
			for(int i=0; i<size; i++) {
				if(i == size-1) System.out.print(pond.pollFirst()[2]);
				else System.out.print(pond.pollFirst()[2] + " ");
			}
			System.out.println();
		}
	}

	// Read Class
	static class FS {
		private final InputStream in = System.in;
		private final byte[] buffer = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;
		private boolean hasNextByte() {
			if (ptr < buflen) {
				return true;
			} else {
				ptr = 0;
				try {
					buflen = in.read(buffer);
				} catch (IOException e) {
					e.printStackTrace();
				}
				if (buflen <= 0) {
					return false;
				}
			}
			return true;
		}

		private int readByte() { return hasNextByte() ? buffer[ptr++] : -1;}
		private boolean isPrintableChar(int c) {return 33 <= c && c <= 126;}
		private void skipUnprintable() {while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}

		public boolean hasNext() { skipUnprintable(); return hasNextByte();}
		public String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while(isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}
		public int nextInt() {
			return (int)nextLong();
		}
		public long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (b < '0' || '9' < b) {
				throw new NumberFormatException();
			}
			while(true) {
				if ('0' <= b && b <= '9') {
					n *= 10;
					n += b - '0';
				} else if(b == -1 || !isPrintableChar(b)) {
					return minus ? -n : n;
				} else {
					throw new NumberFormatException();
				}
				b = readByte();
			}
		}
	}
}

import java.io.IOException;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine(); //文字列を読み込む
        char[] c = s.toCharArray(); //文字単位で配列に詰める
        int sum = 0; //水たまりの面積
        Deque<Integer> stack1 = new ArrayDeque<Integer>();
        Deque<Water> stack2 = new ArrayDeque<Water>();
        for(int i=0; i<c.length; i++) {
            if(c[i]=='\\') {
                stack1.push(i);
            } else if (c[i]=='/' && !stack1.isEmpty()) {
                int n = stack1.pop();
                int a = i-n;
                sum += a;
                while(!stack2.isEmpty() && stack2.peek().index>n) {
                    a += stack2.pop().area;
                }
                Water water = new Water(n,a);
                stack2.push(water);
            }
        }
        System.out.println(sum);
        System.out.print(stack2.size());
        while(!stack2.isEmpty()) {
            System.out.print(" "+stack2.pollLast().area);
        }
        System.out.println();
    }
}
