import java.util.ArrayList;
import java.util.Scanner;

/**
 * ACSD
 */
public class Main {
    // 現在のx座標
    public int lineNumber;

    // 現在の 層別未確定水たまりスタック
    public ArrayList<Integer> stack;
    // 未確定水たまり層の始点
    public ArrayList<Short> stackStart;
    // 確定水たまりリスト
    public ArrayList<Short> puddles;
    // 確定水たまり層の始点
    public ArrayList<Short> puddleStart;
    // 現在の確定水たまりIdx
    public int puddleNumber = 0;
    // 現在の深さ
    public int currentDepth = 0;
    // 前回の水たまり水面高
    public int prevPuddleHeight = -1;

    public int sum = 0;

    /**
     * 指定の層へ水を追加する
     *
     * @param idx       追加する層Idx
     * @param n         追加量
     * @param isConfirm 層確定操作を行うかどうか
     */
    public void add(int idx, int n, boolean isConfirm) {
        // 初出層の場合はstackに追加
        if (this.stack.size() - 1 < idx) {
            this.stack.add(idx, 0);
            this.stackStart.add(idx, (short) lineNumber);
        }
        // 追加動作
        this.stack.set(idx, (this.stack.get(idx) + n));
        // 層確定操作
        if (isConfirm) {
            this.sum += this.stack.get(idx);
            // 現在の未確定水たまり層を、確定水たまりリストに移す
            this.puddles.add(puddleNumber, (short)(int) this.stack.get(idx));
            // 追加した確定水たまりの始点も設置
            this.puddleStart.add(puddleNumber, this.stackStart.get(idx));
            // 初回の層確定操作でない && 前回の層確定操作の1つ上位層の場合
            if ((prevPuddleHeight != -1) && ((prevPuddleHeight - 1) == idx)) {
                // 繰り上がり動作を行う
                // 各確定水たまりについて、初めて (現在の水たまりの始点) < (ある水たまり始点) となるものを探す
                int start = this.puddleStart.get(puddleNumber);
                for (int i = 0; i <= puddleNumber; i++) {
                    // (現在の水たまりの始点) < (ある水たまり始点) Hit!!
                    if (start < this.puddleStart.get(i)) {
                        // ある地点の水たまりを吸収
                        // はじめに始点を更新
                        this.puddleStart.set(i, (short) start);
                        // 次に、その間の水たまり量をすべて吸収
                        for (int j = i + 1; j <= puddleNumber; j++) {
                            this.puddles.set(i, (short) (this.puddles.get(i) + this.puddles.get(j)));
                        }
                        for (int j = puddleNumber; j >= i + 1; j--) {
                            this.puddles.remove(j);
                            this.puddleStart.remove(j);
                        }
                        puddleNumber = i + 1;
                        break;
                    }
                }
            } else { // 繰り上がり動作を行わない場合
                puddleNumber++;
            }
            prevPuddleHeight = idx;
            this.stack.remove(idx);
            this.stackStart.remove(idx);
        }
    }

    public void up() {
        if (currentDepth == 0) {
            return;
        }
        currentDepth--;
        this.add(currentDepth, 1, true);
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void hori() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void down() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
        this.add(currentDepth, 1, false);
        currentDepth++;
    }

    public void print() {
        System.out.println(sum / 2);
        System.out.print(this.puddles.size());
        int len = this.puddles.size();
        for (int i = 0; i < len; i++) {
            System.out.print(" " + (this.puddles.get(i) / 2));
        }
        System.out.println();
    }

    public void go() {
        this.stack = new ArrayList<Integer>();
        this.stackStart = new ArrayList<Short>();
        this.puddles = new ArrayList<Short>();
        this.puddleStart = new ArrayList<Short>();
        Scanner sc = new Scanner(System.in);
        String line = sc.next();
        String[] strings = line.split("");
        for (int i = 0; i < strings.length; i++) {
            String s = strings[i];
            this.lineNumber = i;
            switch (s) {
            case "\\":
                this.down();
                break;
            case "_":
                this.hori();
                break;
            case "/":
                this.up();
                break;
            }
        }
        print();
    }

    public static void main(String[] args) {
        Main cui = new Main();
        cui.go();
    }
}

import java.io.UnsupportedEncodingException;
import java.lang.reflect.UndeclaredThrowableException;
import java.util.Scanner;


class Main {
	public static void main(String args[]) {
		Scanner scanner = new Scanner(System.in);
		String mark = scanner.next();
		int num = mark.length();

		SectionDiagram(mark, num, scanner);

	}
	//enum宣言
	public static enum Operate{
		back(92),
		slush(47),
		under(95);

		private final int mark;

		private Operate(final int mark) {
			this.mark = mark;
		}

		public int getInt(){
			return this.mark;
		}
	}
	public static Operate getOperate(final int id) {
		Operate[] marks = Operate.values();
		for (Operate type : marks) {
			if (type.getInt() == id) {
				return type;
			}
		}
		return null;
	}
	//治水シミュレーション
	public static void SectionDiagram(String mark, int num, Scanner scanner){
		int[] count_puddle = new int[num+5];	//"￥"が来たらそいつをカウント開始
		int[] puddle = new int[num+5];			//各水たまりの面積
		int sum_puddle_now = 0;						//今の水溜りの面積
		int sum_puddle = 0;						//水溜りの面積の合計
		int num_puddle = 0;						//水たまりの数
		int count = 0;							//Whileの周回
		int back_num = 0;							//カウントする￥の数
		int sla_num = 0;							//深さ
		int i;
		byte[] mark_num = new byte[num];		//switch用格納庫
		boolean flap = false;

		try {
			mark_num = mark.getBytes("US-ASCII");
		} catch (UnsupportedEncodingException e) {
			// TODO 自動生成された catch ブロック
			e.printStackTrace();
		}

		while( num > count ){										//文字数文処理


			switch( getOperate(mark_num[count]) ){					//
			case back:
				back_num ++;											//￥の数カウント
				flap = true;
				break;
			case slush:
				back_num --;											//￥の数マイナス
				if(flap) {
					sla_num ++;	
				}
				flap = false;
				//補正
				if( back_num < 0 ) {
					back_num = 0;
					sla_num = 0;
					break;
				}

				sum_puddle_now += count_puddle[back_num + 1];			//消した￥の面積を今の水たまりにする
				count_puddle[back_num + 1] = 0;						//その場所のカウントを初期化

				if ((back_num == 0) || ( count == num - 1)){			//今回の水たまりが確定
					sum_puddle += sum_puddle_now;					//今回の水たまりを全体に足す
					puddle[num_puddle] = sum_puddle_now;			//今回の水たまりを配列に入れる
					sum_puddle_now = 0;								//水たまり初期化
					sum_puddle_now = 0;								//水たまり初期化
					sla_num = 0;
					num_puddle ++;									//全体の水たまりの数を足す
				}
				break;
			case under:
				break;
			}
			//￥の数だけカウント
			for( i = 1; i <= back_num; i ++ ){
				count_puddle[i] += 1;
			}
			count ++;
		}
		//向かいの山が足りないときの処理
		if( sum_puddle_now > 0 && sla_num == 0 ) {
			sum_puddle += sum_puddle_now;
			puddle[num_puddle] = sum_puddle_now;
			num_puddle ++;
		}

		//出力処理
		System.out.println(sum_puddle);	
		System.out.print(num_puddle);
		for( i = 0; i < num_puddle; i ++ ) {
			System.out.print(" " + puddle[i]);
		}
		System.out.println();
	}
}

