	static int lower_bound(int a[],int key) {
		int ok=a.length;
		int ng=-1;
		while(Math.abs(ok-ng)>1) {
			int mid=(ok+ng)/2;
			if(a[mid]>=key)ok=mid;
			else ng=mid;
		}
		return ok;
	}
