import java.util.Deque;
import java.util.LinkedList;
import java.util.Objects;

class Puddle {
    int pos;
    int area;

    Puddle(int pos, int area) {
        this.pos = pos;
        this.area = area;
    }
}

public class Main {
    public static void main(String[] args) {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in))) {
            Deque<Integer> downStack = new LinkedList<>();
            Deque<Puddle> puddleStack = new ArrayDeque<>();

            char[] line = in.readLine().toCharArray();
            int A = 0;
            for (int i = 0; i < line.length; i++) {
                char c = line[i];
                if (c == '\\') {
                    downStack.addFirst(i);
                } else if (c == '/') {
                    if (downStack.isEmpty()) continue;

                    int downPos = downStack.removeFirst();
                    int area = i - downPos;
                    A += area;
                    while (!puddleStack.isEmpty() && puddleStack.peekFirst().pos > downPos) {
                        area += puddleStack.removeFirst().area;
                    }

                    puddleStack.addFirst(new Puddle(downPos, area));
                }
            }

            int k = puddleStack.size();
            String[] L = new String[puddleStack.size()];
            for (int i = 0; i < k; i++) {
                L[i] = String.valueOf(Objects.requireNonNull(puddleStack.pollLast()).area);
            }

            System.out.println(A);

            StringBuilder sb = new StringBuilder();
            sb.append(k);
            if (k > 0) {
                sb.append(" ");
                sb.append(String.join(" ", L));
            }
            System.out.println(sb.toString());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) throws IOException {
        final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        final char[] line = reader.readLine().toCharArray();
        reader.close();

        final Deque<Integer> stack = new ArrayDeque<Integer>(line.length);
        final StringBuilder answer = new StringBuilder();

        int sum = 0;
        int count = 0;
        int indexLastZero = 0;
        final int[] process = new int[line.length];
        final int[] graph = new int[line.length];
        for (int i = 0; i < line.length; ++i) {
            if (stack.isEmpty()) indexLastZero = i;
            graph[i] = stack.size();
            switch (line[i]) {
                case '\\':
                    stack.push(i);
                    break;
                case '/':
                    if (!stack.isEmpty()) {
                        sum += i - stack.pop();
                        if (stack.isEmpty()) {
                            ++count;
                            answer.append(" ").append(sum - process[indexLastZero]);
                        }
                    }
                    break;
                default:
            }
            process[i] = sum;
        }

        for (int i = indexLastZero; i < line.length; ++i) {
            for (int j = line.length - 1; i < j; --j) {
                if (graph[i] == graph[j]) {
                    ++count;
                    answer.append(" ").append(process[j] - process[i]);
                    i = j;
                    break;
                }
            }
        }
        System.out.println(sum);
        System.out.println(count + answer.toString());
    }
}

