import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) throws IOException {
        final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        final char[] line = reader.readLine().toCharArray();
        reader.close();

        final Deque<Integer> stack = new ArrayDeque<Integer>(line.length);
        final StringBuilder answer = new StringBuilder();

        int sum = 0;
        int count = 0;
        int indexLastZero = 0;
        final int[] process = new int[line.length];
        final int[] graph = new int[line.length];
        for (int i = 0; i < line.length; ++i) {
            if (stack.isEmpty()) indexLastZero = i;

            switch (line[i]) {
                case '\\':
                    stack.push(i);
                    break;
                case '/':
                    if (!stack.isEmpty()) {
                        sum += i - stack.pop();
                        if (stack.isEmpty()) {
                            ++count;
                            answer.append(" ").append(sum - process[indexLastZero]);
                        }
                    }
                    break;
                default:
            }
            graph[i] = stack.size();
            process[i] = sum;
        }

        for (int i = indexLastZero + 1; i < line.length; ++i) {
            for (int j = line.length - 1; i < j; --j) {
                if (graph[i] == graph[j]) {
                    ++count;
                    answer.append(" ").append(process[j] - process[i]);
                    i = j;
                    break;
                }
            }
        }
        for (int i = indexLastZero; i < line.length; ++i) {
            System.out.printf("%3d, %3d\n", graph[i], process[i]);
        }

        System.out.println(sum);
        System.out.println(count + answer.toString());
    }
}

import java.io.UnsupportedEncodingException;
import java.lang.reflect.UndeclaredThrowableException;
import java.util.Scanner;


class Main {
	public static void main(String args[]) {
		Scanner scanner = new Scanner(System.in);
		String mark = scanner.next();
		int num = mark.length();

		SectionDiagram(mark, num, scanner);

	}
	//enum宣言
	public static enum Operate{
		back(92),
		slush(47),
		under(95);

		private final int mark;

		private Operate(final int mark) {
			this.mark = mark;
		}

		public int getInt(){
			return this.mark;
		}
	}
	public static Operate getOperate(final int id) {
		Operate[] marks = Operate.values();
		for (Operate type : marks) {
			if (type.getInt() == id) {
				return type;
			}
		}
		return null;
	}
	//治水シミュレーション
	public static void SectionDiagram(String mark, int num, Scanner scanner){
		int[] count_puddle = new int[num+5];	//"￥"が来たらそいつをカウント開始
		int[] puddle = new int[num+5];			//各水たまりの面積
		int sum_puddle_now = 0;						//今の水溜りの面積
		int sum_puddle = 0;						//水溜りの面積の合計
		int num_puddle = 0;						//水たまりの数
		int count = 0;							//Whileの周回
		int back_num = 0;							//カウントする￥の数
		int sla_num = 0;							//深さ
		int i;
		byte[] mark_num = new byte[num];		//switch用格納庫
		boolean flap = false;

		try {
			mark_num = mark.getBytes("US-ASCII");
		} catch (UnsupportedEncodingException e) {
			// TODO 自動生成された catch ブロック
			e.printStackTrace();
		}

		while( num > count ){										//文字数文処理


			switch( getOperate(mark_num[count]) ){					//
			case back:
				back_num ++;											//￥の数カウント
				flap = true;
				break;
			case slush:
				back_num --;											//￥の数マイナス
				if(flap) {
					sla_num ++;	
				}
				flap = false;
				//補正
				if( back_num < 0 ) {
					back_num = 0;
					sla_num = 0;
					break;
				}

				sum_puddle_now += count_puddle[back_num + 1];			//消した￥の面積を今の水たまりにする
				count_puddle[back_num + 1] = 0;						//その場所のカウントを初期化

				if ((back_num == 0) || ( count == num - 1)){			//今回の水たまりが確定
					sum_puddle += sum_puddle_now;					//今回の水たまりを全体に足す
					puddle[num_puddle] = sum_puddle_now;			//今回の水たまりを配列に入れる
					sum_puddle_now = 0;								//水たまり初期化
					sum_puddle_now = 0;								//水たまり初期化
					sla_num = 0;
					num_puddle ++;									//全体の水たまりの数を足す
				}
				break;
			case under:
				break;
			}
			//￥の数だけカウント
			for( i = 1; i <= back_num; i ++ ){
				count_puddle[i] += 1;
			}
			count ++;
		}
		//向かいの山が足りないときの処理
		if(  sla_num != 0 ) {
			for( i = 1 ; i <= sla_num; i ++ ) {
				puddle[num_puddle] = count_puddle[back_num + i] + 1;
				sum_puddle += count_puddle[back_num + i] + 1;
				num_puddle ++;
			}
		}

		//出力処理
		System.out.println(sum_puddle);	
		System.out.print(num_puddle);
		for( i = 0; i < num_puddle; i ++ ) {
			System.out.print(" " + puddle[i]);
		}
		System.out.println();
	}
}

public class Main {
	public static void main(String[] args) throws IOException {
		new Main().run();
	}
	private void run() throws IOException {
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		String input = reader.readLine();
		reader.close();
		int sum = 0;
		Stack<Integer> st1 = new Stack<Integer>();
		Stack<int[]> st2 = new Stack<int[]>();
		for (int i = 0; i < input.length(); i++) {
			char c = input.charAt(i);
			if (c == '\\') {
				st1.add(i);
			} else if (c == '/' && !st1.isEmpty()) {
				int j = st1.pop();
				int area = i - j;
				sum += area;
				int prev = 0;
				while (!st2.isEmpty() && st2.peek()[0] > j) {
					prev += st2.pop()[1];
				}
				st2.add(new int[]{j, area + prev});
			}
		}

		System.out.println(sum);
		System.out.print(st2.size());
		for (int i = 0; i < st2.size(); i++) {
			System.out.print(" " + st2.get(i)[1]);
		}
		System.out.println();
	}
}

import java.io.IOException;
import java.io.InputStream;
