    Scanner sc = new Scanner(System.in);
    final char[] inputs = sc.nextLine().toCharArray();
    int map[] = new int[inputs.length + 1];
    int maps[] = new int[inputs.length + 1];

    int i;
    int total_areas = 0;

    // convert the input to -1 or 0 or 1
    for(i = 0; i < inputs.length; i++){
        map[i] = inputs[i] == '/' ? 1 : inputs[i] == '_' ? 0 : -1;
    }
    for(i = 0; i < inputs.length; i++){
        //System.out.print(map[i] + " ");   
    }
    //System.out.println();

    //maps shows the height
    for(i = 0; i < inputs.length; i++){
        maps[i+1] = map[i];
    }
    for(i = 0; i < inputs.length; i++){
        maps[i+1] += maps[i];
    }
    for(i = 0; i < inputs.length; i++){
        //System.out.print(maps[i] + " ");
    }
    //System.out.println();


    LinkedList<Integer> area_list = new LinkedList<Integer>();

    //check the elements of maos
    for(int cur_pos = 0; cur_pos < inputs.length; cur_pos++){
        int cur_height = maps[cur_pos];

        //check the water area
        int areas = 0;
        boolean ok = false;
        for(int next_pos = cur_pos + 1; next_pos < inputs.length; next_pos++){
            int prev_height = maps[next_pos - 1] - cur_height;
            int next_height = maps[next_pos] - cur_height;
            int max_height = Math.abs(Math.max(prev_height, next_height));

            if(next_height <= 0){
                areas += max_height;
                if(prev_height < next_height){
                    areas += 1;
                }
            }

            if(next_height >= 0){
                cur_pos = next_pos - 1;
                ok = true;
                break;
            }
        }

        if(ok && areas > 0){
            total_areas += areas;
            area_list.add(areas);
        }
    }

    System.out.println(total_areas);
    System.out.print(area_list.size());

    for(int area : area_list){
            System.out.print(" " + area);
        }
        System.out.println();
    }

}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.ListIterator;

public class Main {
    static final char DOWN = '\\';
    static final char UP = '/';
    static final char FLAT = '_';

    private static class Data {
        public int start;
        public int end;
        public int area;

        public Data(int start, int end, int area) {
            this.start = start;
            this.end = end;
            this.area = area;
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        LinkedList<Integer> resolvedList = new LinkedList();
        LinkedList<Integer> slopeStack = new LinkedList();
        LinkedList<Data> unresolvedStack = new LinkedList();

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String landForm = br.readLine();

        for(int pos = 0; pos < landForm.length(); pos++) {
            if(landForm.charAt(pos) == DOWN) {
                slopeStack.add(pos);
                continue;
            } else if(landForm.charAt(pos) == FLAT) {
                continue;
            }

            // UP
            if(slopeStack.size() == 0) {
                while(unresolvedStack.size() != 0) {
                    Data data = unresolvedStack.removeFirst();
                    resolvedList.add(data.area);
                }
                continue;
            }

            int before = slopeStack.removeLast();
            Data data = new Data(before, pos, pos - before);
            while(true) {
                if(unresolvedStack.size() == 0) {
                    unresolvedStack.add(data);
                    break;
                }

                Data beforeData = unresolvedStack.removeLast();
                if(beforeData.start > data.start && beforeData.end < data.end) {
                    data.area += beforeData.area;
                } else {
                    unresolvedStack.add(beforeData);
                    unresolvedStack.add(data);
                    break;
                }
            }
        }

        int sum = 0;
        int count = 0;
        StringBuilder sb = new StringBuilder();

        ListIterator<Integer> itr = resolvedList.listIterator(0);
        while(itr.hasNext()) {
            int l = itr.next().intValue();
            sum += l;
            count++;

            if(sb.length() != 0) {
                sb.append(" ");
            }

            sb.append(l);
        }

        ListIterator<Data> unItr;
        unItr = unresolvedStack.listIterator(0);
        while(unItr.hasNext()) {
            int l = unItr.next().area;
            sum += l;
            count++;

            if(sb.length() != 0) {
                sb.append(" ");
            }

            sb.append(l);
        }
        System.out.println(sum);
        System.out.print(count);
        if(count == 0) {
            System.out.println();
        } else {
            System.out.println(" " + sb.toString());
        }
    }
}

