import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public int lineNumber;

    public ArrayList<Integer> stack;
    public ArrayList<Integer> stackStart;
    public ArrayList<Integer> puddles;
    public ArrayList<Integer> puddleStart;
    public int puddleNumber = 0;
    public int currentDepth = 0;
    public int prevPuddleHeight = -1;

    public int sum = 0;

    public void add(int idx, int n, boolean isConfirm) {
        if (this.stack.size() - 1 < idx) {
            this.stack.add(idx, 0);
            this.stackStart.add(idx, lineNumber);
        }
        this.stack.set(idx, (this.stack.get(idx) + n));
        if (isConfirm) {
            this.sum += this.stack.get(idx);
            this.puddles.add(puddleNumber, this.stack.get(idx));
            this.puddleStart.add(puddleNumber, this.stackStart.get(idx));
            if ((prevPuddleHeight != -1) && ((prevPuddleHeight - 1) == idx)) {
                int start = this.puddleStart.get(puddleNumber);
                for (int i = 0; i <= puddleNumber; i++) {
                    if (start < this.puddleStart.get(i)) {
                        this.puddleStart.set(i, start);
                        for (int j = i + 1; j <= puddleNumber; j++) {
                            this.puddles.set(i, this.puddles.get(i) + this.puddles.get(j));
                        }
                        for (int j = puddleNumber; j >= i + 1; j--) {
                            this.puddles.remove(j);
                            this.puddleStart.remove(j);
                        }
                        puddleNumber = i + 1;
                        break;
                    }
                }
            } else {
                puddleNumber++;
            }
            prevPuddleHeight = idx;
            this.stack.remove(idx);
            this.stackStart.remove(idx);
        }
    }

    public void up() {
        if (currentDepth == 0) {
            return;
        }
        currentDepth--;
        this.add(currentDepth, 1, true);
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void hori() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void down() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
        this.add(currentDepth, 1, false);
        currentDepth++;
    }

    public void print() {
        System.out.println(sum / 2);
        System.out.print(this.puddles.size());
        int len = this.puddles.size();
        for (int i = 0; i < len; i++) {
            System.out.print(" " + (this.puddles.get(i) / 2));
        }
        System.out.println();
    }

    public void go() {
        this.stack = new ArrayList<Integer>();
        this.stackStart = new ArrayList<Integer>();
        this.puddles = new ArrayList<Integer>();
        this.puddleStart = new ArrayList<Integer>();
        Scanner sc = new Scanner(System.in);
        String line = sc.next();
        String[] strings = line.split("");
        for (int i = 0; i < strings.length; i++) {
            String s = strings[i];
            this.lineNumber = i;
            switch (s) {
            case "\\":
                this.down();
                break;
            case "_":
                this.hori();
                break;
            case "/":
                this.up();
                break;
            }
        }
        print();
    }

    public static void main(String[] args) {
        Main cui = new Main();
        cui.go();
    }
}

import java.io.*;
import java.util.Stack;

class Main{
    // -1 : '\' -2: '_' 

    public static void main(String[] args) {
        int MAX = 10000;

        int[] squareOfEachSection = new int[MAX]; 

        int totalSquare = 0;

        for (int i = 0; i < squareOfEachSection.length; i++ ){
            squareOfEachSection[i] = 0;
        }

        // try(BufferedReader reader = new BufferedReader(new FileReader("ALDS1_3_D-in41.txt")))
        try(BufferedReader reader = new BufferedReader(new InputStreamReader(System.in)))
        {

            String inputString = reader.readLine();

            Stack<Integer> stack = new Stack<>();

            int sectionIdentifier = 0;

            int numOfBackSlashInStack = 0;

            for (int i = 0; i < inputString.length(); i++) {
                char currChar = inputString.charAt(i);

                if (currChar != '/'){
                    if (currChar == '\\'){
                        numOfBackSlashInStack ++;
                        stack.push(-1);
                    }else {
                        // '_'
                        stack.push(-2);
                    }

                }else {
                    if (numOfBackSlashInStack > 0) {

                        numOfBackSlashInStack --;
                        // If we are in new section, should increment "sectionIAmIn" by 1
                        boolean isInNewSection = true; 
                        int minSectionId = MAX;
                        // squareOfWaterInthisSection = numGotPop; 
                        // Example : \__/  , 3 item '_' '_' '\' got pop, it is 3. 
                        // '\'+'/' = 1, 0.5 per each. else weight 1. 
                        int numGotPop = 0;
                        int itemPop = -5; // -5 has not special meaning

                        // pop items out of stack until we hit "\"
                        do{
                            itemPop = stack.pop();
                            numGotPop ++;
                            if (itemPop > 0){
                                minSectionId = minSectionId > itemPop ? itemPop : minSectionId;
                                isInNewSection = false;
                            }

                            // while itempop is not -1 ('\')
                        }while(itemPop != -1 );

                        if (isInNewSection) {
                                sectionIdentifier += 1;

                            squareOfEachSection[sectionIdentifier] += numGotPop;
                            totalSquare += numGotPop;

                            for (int j = 0; j <= numGotPop; j++) {
                                stack.push(sectionIdentifier);
                            }
                        }else {
                            if (minSectionId < sectionIdentifier){

                                for (int j = minSectionId + 1; j <= sectionIdentifier; j++){
                                    squareOfEachSection[minSectionId] += squareOfEachSection[j];
                                    squareOfEachSection[j] = 0;
                                }

                                sectionIdentifier = minSectionId;
                            }

                            squareOfEachSection[sectionIdentifier] += numGotPop;
                            totalSquare += numGotPop;

                            for (int j = 0; j <= numGotPop; j++) {
                                    stack.push(sectionIdentifier);

                            }
                        }



                    } 
                } 
            } // end for

            System.out.println(totalSquare+"");
            System.out.print(sectionIdentifier+"");

            for (int i = 1; i <= sectionIdentifier; i++){
                System.out.print(" "+squareOfEachSection[i]);
            }
            System.out.println();

        } catch (Exception e) {
            e.printStackTrace();
        }


    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.AbstractMap;
import java.util.AbstractMap.SimpleEntry;
import java.util.LinkedList;
import java.util.ListIterator;

public class Main {
    static final char DOWN = '\\';
    static final char UP = '/';
    static final char FLAT = '_';

    public static void main(String[] args) throws Exception {
        LinkedList<Integer> resolvedList = new LinkedList<Integer>();
        LinkedList<Integer> slopeStack = new LinkedList<Integer>();
        LinkedList<AbstractMap.SimpleEntry<Integer, Integer>> unresolvedStack
            = new LinkedList<AbstractMap.SimpleEntry<Integer, Integer>>();

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String landForm = br.readLine();

        for(int pos = 0; pos < landForm.length(); pos++) {
            if(landForm.charAt(pos) == DOWN) {
                slopeStack.add(pos);
                continue;
            } else if(landForm.charAt(pos) == FLAT) {
                continue;
            }

            // UP
            if(slopeStack.size() == 0) {
                while(unresolvedStack.size() != 0) {
                    AbstractMap.SimpleEntry<Integer, Integer> data = unresolvedStack.removeLast();
                    resolvedList.addFirst(data.getValue());
                }
                continue;
            }

            int before = slopeStack.removeLast();
            AbstractMap.SimpleEntry<Integer, Integer> data = new AbstractMap.SimpleEntry(before, pos - before);
            while(true) {
                if(unresolvedStack.size() == 0) {
                    unresolvedStack.add(data);
                    break;
                }

                AbstractMap.SimpleEntry<Integer, Integer> beforeData = unresolvedStack.removeLast();
                if(beforeData.getKey() > data.getKey()) {
                    int tmp = beforeData.getValue() + data.getValue();
                    data.setValue(tmp);
                } else {
                    unresolvedStack.add(beforeData);
                    unresolvedStack.add(data);
                    break;
                }
            }
        }

        int sum = 0;
        int count = 0;
        StringBuilder sb = new StringBuilder();

        ListIterator<Integer> itr = resolvedList.listIterator(0);
        while(itr.hasNext()) {
            int l = itr.next().intValue();
            sum += l;
            count++;

            if(sb.length() != 0) {
                sb.append(" ");
            }

            sb.append(l);
        }

        ListIterator<AbstractMap.SimpleEntry<Integer, Integer>> unItr;
        unItr = unresolvedStack.listIterator(0);
        while(unItr.hasNext()) {
            int l = unItr.next().getValue();
            sum += l;
            count++;

            if(sb.length() != 0) {
                sb.append(" ");
            }

            sb.append(l);
        }
        System.out.println(sum);
        System.out.println(count + " " + sb.toString());
    }
}

