//		}
//		String input = str2.toString();
//		System.out.println(input);

		data = new Slope[input.length()];

		for (int i = 0; i < data.length; i++) {
			char temp = input.charAt(i);
			switch (temp) {
				case '\\':
					data[i] = Slope.DOWN;
					break;
				case '/':
					data[i] = Slope.UP;
					break;
				case '_':
					data[i] = Slope.FLAT;
					break;
				default:
					assert true;
			}
		}

		height = new int[data.length + 1];
		height[0] = 0;
		mount = new boolean [data.length + 1];
		Slope prev = Slope.UP;
		for (int i = 0; i < data.length; i++) {
			height[i + 1] = height[i] + data[i].height;
			if (prev == Slope.UP && data[i] == Slope.DOWN) {
				mount[i] = true;
			}
			if (data[i] != Slope.FLAT) {
				prev = data[i];
			}
		}
		if ( prev == Slope.UP) {
			mount[data.length] = true;
		}

//		for (int i = 0; i < height.length; i++) {
//			System.out.println(height[i] + ":" + mount[i]);
//		}

		ArrayList<Integer> result = new ArrayList<Integer>();
		for (int i = 0; i < height.length - 1; ) {
			int from = nextMount(i);
			if (from == -1) {
				break;
			}
			int to = highestMount(from + 1);
			if (to == -1) {
				i++;
				continue;
			}
			result.add(getSquare(from, to));
			i = to;
		}

		int sum = 0;
		StringBuffer str = new StringBuffer();
		str.append(result.size());
		for (int i = 0; i < result.size(); i++) {
			sum += result.get(i);
			str.append(" ");
			str.append(result.get(i));
		}
		System.out.println(sum);
		System.out.println(str);

		sc.close();
	}

	private static int nextMount(int start) {
		for (int i = start; i < mount.length; i++) {
			if (mount[i] == true) {
				return i;
			}
		}

		return -1;
	}

	private static int highestMount(int start) {
		int maxHeight = Integer.MIN_VALUE;
		int maxIndex = -1;
		for (int i = start; i < mount.length; i++) {
			if (mount[i] == true && maxHeight < height[i]) {
				maxIndex = i;
				maxHeight = height[i];
			}
		}

		return maxIndex;
	}

	private static int getSquare(int from, int to) {
		int min = Math.min(height[from], height[to]);
		int square = 0;
		for (int i = from; i < to; i++) {
			if (height[i] > min || height[i + 1] > min) {
				continue;
			}
			square += (min - height[i] + min - height[i + 1]);
		}
		return square / 2;
	}

	private static enum Slope {
		DOWN(-1), UP(1), FLAT(0);

		int height;
		Slope(int height) {
			this.height = height;
		}
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.Stack;

// ALDS1_3_D
public class Main {
	void run() throws IOException {
		Stack<Integer> st = new Stack<Integer>();
		ArrayDeque<Integer> area = new ArrayDeque<Integer>();
		ArrayList<Integer> height = new ArrayList<Integer>();
		int A = 0; int k = 0; int L = 0; int h = 0;
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] str = br.readLine().split("");
		int len = str.length;
		// /の高さを格納
		for (int i = 0; i < len; i++) {
			switch(str[i]) {
			case "\\":
				h--;
				height.add(null);
				break;
			case "/":
				height.add(h);
				h++;
				break;
			default:
				height.add(null);
				break;
			}
		}
		h = 0;
		// \を格納する際に，それ以降に対応する/がない場合は格納しない処理をとる
		for (int i = 0; i < len; i++) {
			switch(str[i]) {
			case "\\":
				h--;
				if (height.subList(i, height.size()).contains(h)) st.push(i);
				break;
			case "/":
				if (!st.empty()) {
					int l = i - st.pop();
					A = A + l;
					L = L + l;
					if (st.empty()) {
						area.addLast(L);
						k += 1;
						L = 0;
					}
				}
				h++;
				break;
			case "_":
				if (i == len) 
				break;
			default:
				break;
			}
		}
		System.out.println(A);
		System.out.print(k);
		for (Integer n : area) {
			System.out.print(" " + n);
		}
		System.out.println();
	}

	public static void main(String[] args) throws IOException {
		new Main().run();
	}
}

