import java.io.InputStreamReader;
import java.util.AbstractMap;
import java.util.AbstractMap.SimpleEntry;
import java.util.LinkedList;
import java.util.ListIterator;

public class Main {
    static final char DOWN = '\\';
    static final char UP = '/';
    static final char FLAT = '_';

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        LinkedList<Integer> resolvedList = new LinkedList();
        LinkedList<Integer> slopeStack = new LinkedList();
        LinkedList<AbstractMap.SimpleEntry<Integer, Integer>> unresolvedStack = new LinkedList();

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String landForm = br.readLine();

        for(int pos = 0; pos < landForm.length(); pos++) {
            if(landForm.charAt(pos) == DOWN) {
                slopeStack.add(pos);
                continue;
            } else if(landForm.charAt(pos) == FLAT) {
                continue;
            }

            // UP
            if(slopeStack.size() == 0) {
                while(unresolvedStack.size() != 0) {
                    AbstractMap.SimpleEntry<Integer, Integer> data = unresolvedStack.removeLast();
                    resolvedList.addFirst(data.getValue());
                }
                continue;
            }

            int before = slopeStack.removeLast();
            AbstractMap.SimpleEntry<Integer, Integer> data = new AbstractMap.SimpleEntry(before, pos - before);
            while(true) {
                if(unresolvedStack.size() == 0) {
                    unresolvedStack.add(data);
                    break;
                }

                AbstractMap.SimpleEntry<Integer, Integer> beforeData = unresolvedStack.removeLast();
                if(beforeData.getKey() > data.getKey()) {
                    int tmp = beforeData.getValue() + data.getValue();
                    data.setValue(tmp);
                } else {
                    unresolvedStack.add(beforeData);
                    unresolvedStack.add(data);
                    break;
                }
            }
        }

        int sum = 0;
        int count = 0;
        StringBuilder sb = new StringBuilder();

        ListIterator<Integer> itr = resolvedList.listIterator(0);
        while(itr.hasNext()) {
            int l = itr.next().intValue();
            sum += l;
            count++;

            if(sb.length() != 0) {
                sb.append(" ");
            }

            sb.append(l);
        }

        ListIterator<AbstractMap.SimpleEntry<Integer, Integer>> unItr;
        unItr = unresolvedStack.listIterator(0);
        while(unItr.hasNext()) {
            int l = unItr.next().getValue();
            sum += l;
            count++;

            if(sb.length() != 0) {
                sb.append(" ");
            }

            sb.append(l);
        }
        System.out.println(sum);
        System.out.println(count + " " + sb.toString());
    }
}

import java.io.UnsupportedEncodingException;
import java.lang.reflect.UndeclaredThrowableException;
import java.util.Scanner;


class Main {
	public static void main(String args[]) {
		Scanner scanner = new Scanner(System.in);
		String mark = scanner.next();
		int num = mark.length();

		SectionDiagram(mark, num, scanner);

	}
	//enum宣言
	public static enum Operate{
		back(92),
		slush(47),
		under(95);

		private final int mark;

		private Operate(final int mark) {
			this.mark = mark;
		}

		public int getInt(){
			return this.mark;
		}
	}
	public static Operate getOperate(final int id) {
		Operate[] marks = Operate.values();
		for (Operate type : marks) {
			if (type.getInt() == id) {
				return type;
			}
		}
		return null;
	}
	//治水シミュレーション
	public static void SectionDiagram(String mark, int num, Scanner scanner){
		int[] count_puddle = new int[num+5];	//"￥"が来たらそいつをカウント開始
		int[] puddle = new int[num+5];			//各水たまりの面積
		int sum_puddle_now = 0;						//今の水溜りの面積
		int sum_puddle = 0;						//水溜りの面積の合計
		int num_puddle = 0;						//水たまりの数
		int count = 0;							//Whileの周回
		int en_num = 0;							//カウントする￥の数
		int en_max = 0;							//深さ
		int i;
		byte[] mark_num = new byte[num];		//switch用格納庫

		try {
			mark_num = mark.getBytes("US-ASCII");
		} catch (UnsupportedEncodingException e) {
			// TODO 自動生成された catch ブロック
			e.printStackTrace();
		}

		while( num > count ){										//文字数文処理


			switch( getOperate(mark_num[count]) ){					//
			case back:
				en_num ++;											//￥の数カウント
				break;
			case slush:
				en_num --;											//￥の数マイナス
				if( en_num < 0 ) {
					en_num = 0;
					break;
				}

				sum_puddle_now += count_puddle[en_num + 1];			//消した￥の面積を今の水たまりにする
				count_puddle[en_num + 1] = 0;						//その場所のカウントを初期化

				if ((en_num == 0) || ( count == num - 1)){			//今回の水たまりが確定
					sum_puddle += sum_puddle_now;					//今回の水たまりを全体に足す
					puddle[num_puddle] = sum_puddle_now;			//今回の水たまりを配列に入れる
					sum_puddle_now = 0;								//水たまり初期化
					sum_puddle_now = 0;								//水たまり初期化
					num_puddle ++;									//全体の水たまりの数を足す
				}
				break;
			case under:
				break;
			}
			//￥の数だけカウント
			for( i = 1; i <= en_num; i ++ ){
				count_puddle[i] += 1;
			}
			count ++;
		}
		//向かいの山が足りないときの処理
		if( sum_puddle_now > 0) {
			sum_puddle += sum_puddle_now;
			puddle[num_puddle] = sum_puddle_now;
			num_puddle ++;
		}

		//出力処理
		System.out.println(sum_puddle);	
		System.out.print(num_puddle);
		for( i = 0; i < num_puddle; i ++ ) {
			System.out.print(" " + puddle[i]);
		}
		System.out.println();
	}
}

import java.util.*;

class Main {
	public static void main(String[] args) {
		Scanner stdIn = new Scanner(System.in);
		String str = stdIn.next();
		int len = str.length();
		int[] level = new int[len+1];
		int top = 0;
		int bottom = 0;
		int nowLevel = 0;

		for (int i=0; i<len; i++) {
			char c = str.charAt(i);
			level[i] = nowLevel;
			if (c == '\' || c == '\\') {
				nowLevel--;
			}else if(c == '/'){
				nowLevel++;
			}
			top = Math.max(top,nowLevel);
			bottom = Math.min(bottom,nowLevel);
		}
		level[len] = nowLevel;
		top = Math.max(top,nowLevel);
		bottom = Math.min(bottom,nowLevel);

		boolean[] water = new boolean[len];
		List<Integer> list = new ArrayList<Integer>();
		int sum = 0;

		for (int i=top; i>bottom; i--) {//高さ
			int start = -1;
			for (int j=0; j<len; j++) {//幅
				if (!water[j]) {//水は入っているか
					if ((start==-1?level[j]:level[j+1]) == i) {//levelの一致
						if (start == -1 && level[j]>level[j+1]) {//startが設定されているか '\'であるか
							start = j;
						}else if(start != -1){
							int count = 0;//傾斜数
							int vol = 0;
							for (int k=start; k<j+1; k++) {//面積計算
								vol += Math.abs(level[start] - Math.max(level[k],level[k+1]));
								if(Math.abs(level[k] - level[k+1]) > 0)
									count++;
								water[k] = true;//水を入れる
							}
							vol += count/2;
							sum += vol;//総面積に足す
							list.add(vol);
							start = -1;
						}
					}
				}
			}
		}

		System.out.println(sum);
		System.out.print(list.size());
		for (int i=0; i<list.size(); i++) {
			System.out.print(" "+list.get(i));
		}
		System.out.println();
	}
}

import java.util.Scanner;

public class Main {
	public static int sumarea(String str, int sdepth, int edepth) {
		int i, len, start = sdepth, end = edepth, depth = 0;
		double area = 0;
		len = str.length();
		for (i = 0; i < len; i++) {
			if (start > end && str.charAt(i) == '\\') {
				start--;
			} else {
				switch (str.charAt(i)) {
					case '\\':
						area += depth - 0.5;
						depth -= 1;
						break;
					case '/':
						area += depth + 0.5;
						depth += 1;
						break;
					case '_':
						area += depth;
						break;
					default:
						continue;
				}
			}
		}
		return (int) -area;
	}

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int i = 0, j = 0, len, start = -1, end = -1, depth = 0, sdepth = 0, edepth = 0, count = 0, memo = 0;
		int sum = 0;
		String str;
		str = scan.next();
		len = str.length();
		j = len / 2 + 1;
		int[] area = new int[j];
		j = 0;
		while (i < len) {
			for (i = memo; i < len; i++) {
				if (start == -1 && str.charAt(i) == '\\') {
					start = i;
					depth = 0;
					sdepth = 0;
				}
				if (start != -1) {
					switch (str.charAt(i)) {
						case '\\':
							depth -= 1;
							break;
						case '/':
							if (end == -1) {
								end = i;
								edepth = depth;
							}
							depth += 1;
							if (depth > edepth) {
								end = i;
								edepth = depth;
							}
							if (edepth == 0) {
								area[j] = sumarea(str.substring(start, end + 1), sdepth, edepth);
								sum += area[j];
								count++;
								j++;
								start = -1;
								end = -1;
							}
							break;
						default:
							continue;
					}
				}
			}
			if (start < end  && sdepth > edepth) {
				area[j] = sumarea(str.substring(start, end + 1), sdepth, edepth);
				sum += area[j];
				count++;
				i = end + 1;
				j++;
				memo = end;
				start = -1;
				end = -1;
			}
			if (i >= len)
				break;
		}
		System.out.print(sum + "\n" + count);
		for (i = 0; i < count; i++) {
				System.out.print(" "+area[i]);
		}
		System.out.println("");
		scan.close();
	}
}

