public class Main {
	public static void main(String[] args) throws IOException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String s = br.readLine();
		ArrayDeque<Integer> left = new ArrayDeque<Integer>();
		ArrayDeque<Integer> areaLeft = new ArrayDeque<Integer>();
		ArrayDeque<Integer> area = new ArrayDeque<Integer>();

		for(int i = 0; i < s.length(); ++i) {
			char c = s.charAt(i);
			if(c == '\\'){
				left.addFirst(i);
			}else if(c == '/'){
				if(!left.isEmpty()) {
					int l = left.removeFirst();
					areaLeft.addFirst(l);
					area.addFirst(i-l);
				}
			}
		}

		int lastl = s.length();
		while(!areaLeft.isEmpty()){
			int l = areaLeft.removeFirst();
			if(l > lastl){
				area.addLast(area.removeFirst() + area.removeLast());
			}else{
				area.addLast(area.removeFirst());
				lastl = l;
			}
		}

		StringBuilder sb = new StringBuilder();
		int sum = 0;
		for(Integer i : area){
			sum += i;
			sb.insert(0, " " + i);
		}
		sb.insert(0, area.size());

		System.out.println(sum);
		System.out.println(sb);
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Main {

	public static void main(String[] args) throws NumberFormatException,
			IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		char[] input = br.readLine().toCharArray();
		int[] level = new int[input.length + 1];
		Map<Integer, Integer> levelMap = new HashMap<Integer, Integer>();
		List<Integer> startIndex = new ArrayList<Integer>();
		List<Integer> endIndex = new ArrayList<Integer>();

		level[0] = 100;
		levelMap.put(100, 1);
		for (int i = 1; i < input.length + 1; i++) {
			char c = input[i - 1];

			switch (c) {
				case '_' :
					level[i] = level[i - 1];
					break;
				case '/' :
					level[i] = level[i - 1] + 1;
					break;
				case '\\' :
					level[i] = level[i - 1] - 1;
					break;
			}

			if (levelMap.containsKey(level[i])) {
				levelMap.put(level[i], levelMap.get(level[i]) + 1);
			} else {
				levelMap.put(level[i], 1);
			}
		}

		// for (Map.Entry<Integer, Integer> entry : levelMap.entrySet()) {
		//	System.out.println(entry.getKey() + ", " + entry.getValue());
		// }

		MAINLOOP : for (int i = 0; i < level.length - 1;) {

			while (input[i] != '\\') {
				levelMap.put(level[i], levelMap.get(level[i]) - 1);
				if (i + 1 < input.length)
					i++;
				else
					break MAINLOOP;
			}

			if (levelMap.get(level[i]) > 1) {
				levelMap.put(level[i], levelMap.get(level[i]) - 1);

				int j;
				for (j = i + 1; j < level.length; j++) {
					if (level[i] == level[j]) {
						break;
					}
					levelMap.put(level[j], levelMap.get(level[j]) - 1);
				}

				startIndex.add(i);
				endIndex.add(j);
				i = j;
			} else {
				boolean existSameLevel = false;
				int targetLevel = 0;
				for (int j = level[i] - 1; levelMap.containsKey(j); j--) {
					if (levelMap.get(j) > 1) {
						existSameLevel = true;
						targetLevel = j;
						break;
					}
				}

				if (existSameLevel) {
					levelMap.put(level[i], levelMap.get(level[i]) - 1);
					int j;
					for (j = i + 1; j < level.length; j++) {
						if (level[j] == targetLevel) {
							break;
						}
						levelMap.put(level[j], levelMap.get(level[j]) - 1);
					}
					startIndex.add(j);

					for (j += 1; j < level.length; j++) {
						levelMap.put(level[j], levelMap.get(level[j]) - 1);
						if (level[j] == targetLevel) {
							break;
						}
					}

					endIndex.add(j);
					i = j;
				} else {
					break;
				}
			}
		}

		int[] water = new int[startIndex.size()];
		int waterNum = 0;
		int allSum = 0;


		for (int i = 0; i < startIndex.size(); i++) {
			int start = startIndex.get(i);
			int end = endIndex.get(i);
			// System.out.println(startIndex.get(i) + " -> " + endIndex.get(i));

			int sum = 0;

			for (int j = start; j <= end; j++) {
				boolean isUp = false;
				boolean isExist = false;

				if (input[j] != '\\')
					continue;

				int length = 0;

				for (int k = j+1; k <= end; k++) {
					length++;
					if (input[k] == '/')
						isUp = true;

					if (level[j] == level[k]) {
						isExist = true;
						break;
					}
				}

				if (isUp && isExist) {
					// System.out.println("length = " + length);
					sum += (length * 2 - 2) / 2;
				}
			}

			if (sum > 0) {
				water[waterNum++] = sum;
				allSum += sum;
			}
		}

		System.out.println(allSum);
		System.out.print(waterNum);

		for (int i = 0; i < waterNum; i++) {
			System.out.print(" " + water[i]);
		}
		System.out.println();

		br.close();
	}

}

import java.util.ArrayList;
import java.util.Scanner;

/**
 * ACSD
 */
public class Main {
    // 現在のx座標
    public int lineNumber;

    // 現在の 層別未確定水たまりスタック
    public int[] stack = new int[20000];
    // 未確定水たまり層の始点
    public int[] stackStart = new int[20000];
    // 確定水たまりリスト
    public int[] puddles = new int[10000];
    // 確定水たまり層の始点
    public int[] puddleStart = new int[10000];
    // 現在の確定水たまりIdx
    public int puddleNumber = 0;
    // 現在の深さ
    public int currentDepth = 0;
    // 前回の水たまり水面高
    public int prevPuddleHeight = -1;

    public int sum = 0;

    /**
     * 指定の層へ水を追加する
     *
     * @param idx       追加する層Idx
     * @param n         追加量
     * @param isConfirm 層確定操作を行うかどうか
     */
    public void add(int idx, int n, boolean isConfirm) {
        // 初出層の場合はstackに追加
        if (this.stackStart[idx] == -1) {
            this.stackStart[idx] = lineNumber;
        }
        // 追加動作
        this.stack[idx] += n;
        // 層確定操作
        if (isConfirm) {
            this.sum += this.stack[idx];
            // 現在の未確定水たまり層を、確定水たまりリストに移す
            this.puddles[puddleNumber] = this.stack[idx] / 2;
            // 追加した確定水たまりの始点も設置
            this.puddleStart[puddleNumber] = this.stackStart[idx];
            // 初回の層確定操作でない && 前回の層確定操作の1つ上位層の場合
            if ((prevPuddleHeight != -1) && ((prevPuddleHeight - 1) == idx)) {
                // 繰り上がり動作を行う
                // 各確定水たまりについて、初めて (現在の水たまりの始点) < (ある水たまり始点) となるものを探す
                int start = this.puddleStart[puddleNumber];
                System.out.println("start=" + start + "/puddleNumber" + puddleNumber);
                for (int i = 0; i <= puddleNumber; i++) {
                    System.out.println("[" + this.puddleStart[i] + "]");
                    // (現在の水たまりの始点) < (ある水たまり始点) Hit!!
                    if (start < this.puddleStart[i]) {
                        // ある地点の水たまりを吸収
                        // はじめに始点を更新
                        this.puddleStart[i] = start;
                        // 次に、その間の水たまり量をすべて吸収
                        for (int j = i + 1; j <= puddleNumber; j++) {
                            this.puddles[i] += this.puddles[j];
                        }
                        for (int j = puddleNumber; j >= i + 1; j--) {
                            this.puddles[j] = 0;
                            this.puddleStart[j] = 0;
                        }
                        puddleNumber = i + 1;
                        break;
                    }
                }
            } else { // 繰り上がり動作を行わない場合
                puddleNumber++;
            }
            prevPuddleHeight = idx;
            this.stack[idx] = 0;
            this.stackStart[idx] = -1;
        }
    }

    public void up() {
        if (currentDepth == 0) {
            return;
        }
        currentDepth--;
        this.add(currentDepth, 1, true);
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void hori() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void down() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
        this.add(currentDepth, 1, false);
        currentDepth++;
    }

    public void print() {
        System.out.println(sum / 2);
        int len = puddleNumber;
        System.out.print(len);
        for (int i = 0; i < len; i++) {
            System.out.print(" " + this.puddles[i]);
        }
        System.out.println();
    }

    public void go() {
        for (int i = 0; i < this.stackStart.length; i++) {
            this.stackStart[i] = -1;
        }
        Scanner sc = new Scanner(System.in);
        String line = sc.next();
        String[] strings = line.split("");
        for (int i = 0; i < strings.length; i++) {
            String s = strings[i];
            this.lineNumber = i;
            switch (s) {
            case "\\":
                this.down();
                break;
            case "_":
                this.hori();
                break;
            case "/":
                this.up();
                break;
            }
            print();
        }
    }

    public static void main(String[] args) {
        Main cui = new Main();
        cui.go();
    }
}

import java.util.Scanner;
import java.util.Stack;
import java.util.Vector;


public class Main {

	public static void main(String arg[]){
		Scanner sc = new Scanner(System.in);
		Stack<Integer> SlopeStack = new Stack<Integer>();
		Stack<Pool> poolStack = new Stack<Pool>();

		String ch;
		int are=0;
		int sum = 0;
		ch = sc.nextLine();
		for (int i=0; i<ch.length(); i++){

			switch(ch.charAt(i)){
			case'\\':
				SlopeStack.push(i);
				break;
			case '/':
				if (!SlopeStack.isEmpty()) {
					Pool v = new Pool(SlopeStack.pop(),i);
					while (!poolStack.isEmpty()) {
						Pool latest = poolStack.pop();
						if (!v.isChild(latest)) {
							poolStack.push(latest);
							break;
						}
						v.addSize(latest.getSize());
					}
					poolStack.push(v);
				}
				break;
			case '_':
				break;
			}
		}

		int[] areaSize = new int[poolStack.size()];
		for (int i = 0; i < areaSize.length; i++) {
			areaSize[i] = poolStack.pop().getSize();
			sum += areaSize[i];
		}
		System.out.println(sum);
		System.out.print(areaSize.length);
		for (int i = areaSize.length - 1; i >= 0; i--) {
			System.out.print(" " + areaSize[i]);
		}
		System.out.println();
	}
}
class Pool {
	int left;
	int right;
	int area;
	Pool(int left, int right) {
		this.left = left;
		this.right = right;
		this.area = right - left;
	}
	void pool(){
		left = 0;
		right = 0;
	}
	public void addSize(int i){
		area += i;
	}
	public boolean isChild(Pool pool) {
		return left < pool.left && right > pool.right;
	}
	public int getSize() {
		return area;
	}
}

