         	System.out.println( output );

	    } catch( IOException e ) {
	        System.err.println( e );
	    }
	}
	public static int getArea( char[] field, int start )
	{
		int i, area, cnt, s, t;
		area = cnt = s = t = 0;
		for( i=start; i<fieldlen; i++ ) {
            if( '\\'== field[i] ) {
            	cnt++;
            	t++;
            	area += cnt;
            } else if( 0 < cnt && '/' == field[i] ) {
            	area += cnt;
            	cnt--;
            	if( 0 == cnt ) { break; }
            } else if( '_' == field[i]  ) {
            	s += cnt;
            }
		}
		if( fieldlen == i ) { 
			area = 0;
		} else {
			area = ( area - t + s );
			fieldstart = i;
		}
		return area;
	}

}

