import java.util.AbstractMap;
import java.util.Iterator;
import java.util.Map.Entry;
import java.util.Scanner;
import java.util.Stack;

public class Main {

	public static Stack<Entry<Integer, Integer>> simulate(String mount){
		Stack<Integer> patches = new Stack<Integer>();
		Stack<Entry<Integer, Integer>> results = new Stack<Entry<Integer, Integer>>();
		int total = 0;
		int i = 0;
		while(i < mount.length()) {
			// the negative slope
			if(mount.charAt(i) == '\\') {
				//push the index
				patches.push(i);
			}else if(mount.charAt(i) == '/') {
				if(!patches.isEmpty()) {
					int s = patches.pop();
					int sum = i - s;
					total += sum;
					while(!results.isEmpty() && results.peek().getKey() >= s) {
						sum += results.pop().getValue(); // include the area
					}

					results.push(new AbstractMap.SimpleEntry<Integer, Integer>(s, sum));
				}
			}


			i++;
		}

		results.push(new AbstractMap.SimpleEntry<Integer, Integer>(total, total));

		return results;

	}


	public static void main(String[] args) {
		Scanner cin = new Scanner(System.in);

		String mount = cin.nextLine();
		Stack<Entry<Integer, Integer>> s = simulate(mount);

		System.out.println(s.pop().getValue());
		System.out.print(s.size()+" ");
		Iterator<Entry<Integer, Integer>> iter = s.iterator(); 


		while(iter.hasNext()) {
			System.out.print(iter.next().getValue());
			if(iter.hasNext()) {
				System.out.print(" ");
			}else {
				System.out.println();
			}

		}


		cin.close();


	}



}

import java.util.Scanner;
import java.util.Stack;

public class Main {
	class Pond {
		int index, ans;
		Pond(int index, int ans) {
			this.index = index;
			this.ans = ans;
		}
	}
	void run() {
		Scanner scan = new Scanner(System.in);
		char[] a = scan.next().toCharArray();
		Stack<Integer> stack = new Stack<Integer>();
		Stack<Pond> ans = new Stack<Pond>();

		for (int i = 0; i < a.length; i++) {
			if (a[i] == '\\')
				stack.push(i);
			else if (a[i] == '/') {
				if (stack.isEmpty())
					continue;
				int n = stack.pop();
				Pond pond = new Pond(n, i - n);
				while (!ans.isEmpty()) {
					Pond p = ans.pop();
					if (p.index < pond.index) {
						ans.push(p);
						break;
					}
					pond = new Pond(pond.index, p.ans + pond.ans);
				}
				ans.push(pond);
			}
		}
		int sum = 0;
		for (int i = 0; i < ans.size(); i++)
			sum += ans.get(i).ans;
		System.out.println(sum);

		System.out.print(ans.size());
		for (int i = 0; i < ans.size(); i++)
			System.out.print(" " + ans.get(i).ans);
		System.out.println();
	}
	public static void main(String[] args) {
		new Main().run();
	}
}

