import java.util.Scanner;
import java.util.ArrayList;
public class Main {
    static int LIMIT = 200001;
    public static int[] sectionDiagrams = new int[LIMIT];
    public static void main (String[] args) {
	Scanner scan = new Scanner(System.in);
	String section = scan.nextLine();
	calculateDiagrams(section, 1);
	String reversedSection = "";
	String tmp = "";
	for (int i = 0; i < section.length(); i++) {
	    tmp = section.substring(i, i + 1);
	    if (tmp.equals("\\")) {
		tmp = "/";
	    } else if (tmp.equals("/")) {
		tmp = "\\";
	    }
	    reversedSection += tmp;
	}
	calculateDiagrams(reversedSection, -1);
	ArrayList<Integer> diagrams = new ArrayList<Integer>();
	int sum = 0;
	for (int i = 0; i < LIMIT; i++) {
	    if (sectionDiagrams[i] != 0) {
		diagrams.add(sectionDiagrams[i]);
		sum += sectionDiagrams[i];
	    }
	}
	System.out.println(sum);
	System.out.print(diagrams.size());
	for (int i = 0; i < diagrams.size(); i++) {
	    System.out.print(" " + diagrams.get(i));
	}
	System.out.println();
    }
    static void calculateDiagrams (String section, int direction) {
	String shape = "";
	boolean isIn = false;
	int outH = 0, nowH = 0;
	int sum = 0, inP = 0;
	int sp = 0;
	if (direction == -1) {
	    sp = section.length() - 1;
	}
	for (int i = sp; i >=0 && i < section.length(); i += direction) {
	    shape = section.substring(i, i+1);
	    if (isIn == false) {
		if (shape.equals("\\")) {
		    isIn = true;
		    outH = nowH;
		    nowH--;
		    inP = i;
		    sum = 1;
		} else if (shape.equals("/")) {
		    nowH++;
		}
	    } else {
		if (shape.equals("\\")) {
		    sum += outH - nowH + 1;
		    nowH--;
		} else if (shape.equals("/")) {
		    nowH++;
		    sum += outH - nowH;
		} else if (shape.equals("_")) {
		    sum += outH - nowH;
		}
		if (nowH == outH) {
		    if (direction == 1 && sectionDiagrams[inP] < sum) {
			sectionDiagrams[inP] = sum;
		    } else if (direction == -1 && sectionDiagrams[i] < sum){
			sectionDiagrams[i] = sum;
		    }
		    isIn = false;
		}
	    }
	}
    }
}

import java.util.ArrayList;
import java.util.Scanner;

/**
 * ACSD
 */
public class Main {
    // 現在のx座標
    public int lineNumber;

    // 現在の 層別未確定水たまりスタック
    public ArrayList<Integer> stack;
    // 未確定水たまり層の始点
    public ArrayList<Integer> stackStart;
    // 確定水たまりリスト
    // public ArrayList<Integer> puddles;
    public int[] puddles = new int[10000];
    // 確定水たまり層の始点
    // public ArrayList<Integer> puddleStart;
    public int[] puddleStart = new int[10000];
    // 現在の確定水たまりIdx
    public int puddleNumber = 0;
    // 現在の深さ
    public int currentDepth = 0;
    // 前回の水たまり水面高
    public int prevPuddleHeight = -1;

    public int sum = 0;

    /**
     * 指定の層へ水を追加する
     *
     * @param idx       追加する層Idx
     * @param n         追加量
     * @param isConfirm 層確定操作を行うかどうか
     */
    public void add(int idx, int n, boolean isConfirm) {
        // 初出層の場合はstackに追加
        if (this.stack.size() - 1 < idx) {
            this.stack.add(idx, 0);
            this.stackStart.add(idx, lineNumber);
        }
        // 追加動作
        this.stack.set(idx, (this.stack.get(idx) + n));
        // 層確定操作
        if (isConfirm) {
            this.sum += this.stack.get(idx);
            // 現在の未確定水たまり層を、確定水たまりリストに移す
            this.puddles[puddleNumber] = this.stack.get(idx) / 2;
            // 追加した確定水たまりの始点も設置
            this.puddleStart[puddleNumber] = this.stackStart.get(idx);
            // 初回の層確定操作でない && 前回の層確定操作の1つ上位層の場合
            if ((prevPuddleHeight != -1) && ((prevPuddleHeight - 1) == idx)) {
                // 繰り上がり動作を行う
                // 各確定水たまりについて、初めて (現在の水たまりの始点) < (ある水たまり始点) となるものを探す
                int start = this.puddleStart[puddleNumber];
                for (int i = 0; i <= puddleNumber; i++) {
                    // (現在の水たまりの始点) < (ある水たまり始点) Hit!!
                    if (start < this.puddleStart[i]) {
                        // ある地点の水たまりを吸収
                        // はじめに始点を更新
                        this.puddleStart[i] = start;
                        // 次に、その間の水たまり量をすべて吸収
                        for (int j = i + 1; j <= puddleNumber; j++) {
                            this.puddles[i] += this.puddles[j];
                        }
                        for (int j = puddleNumber; j >= i + 1; j--) {
                            this.puddles[j] = 0;
                            this.puddleStart[j] = 0;
                        }
                        puddleNumber = i + 1;
                        break;
                    }
                }
            } else { // 繰り上がり動作を行わない場合
                puddleNumber++;
            }
            prevPuddleHeight = idx;
            this.stack.remove(idx);
            this.stackStart.remove(idx);
        }
    }

    public void up() {
        if (currentDepth == 0) {
            return;
        }
        currentDepth--;
        this.add(currentDepth, 1, true);
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void hori() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void down() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
        this.add(currentDepth, 1, false);
        currentDepth++;
    }

    public void print() {
        System.out.println(sum / 2);
        int len = puddleNumber - 1;
        System.out.print(len);
        for (int i = 0; i < len; i++) {
            System.out.print(" " + this.puddles[i]);
        }
        System.out.println();
    }

    public void go() {
        this.stack = new ArrayList<Integer>();
        this.stackStart = new ArrayList<Integer>();
        Scanner sc = new Scanner(System.in);
        String line = sc.next();
        String[] strings = line.split("");
        for (int i = 0; i < strings.length; i++) {
            String s = strings[i];
            this.lineNumber = i;
            switch (s) {
            case "\\":
                this.down();
                break;
            case "_":
                this.hori();
                break;
            case "/":
                this.up();
                break;
            }
        }
        print();
    }

    public static void main(String[] args) {
        Main cui = new Main();
        cui.go();
    }
}

