				//System.out.println(cur_pos + ":" + next_pos + " [" + prev_height + " " + next_height + "]");

				if(next_height <= 0){
					areas += max_height;
					if(prev_height < next_height){
						areas += 1;
					}
				}

				if(next_height >= 0){
					cur_pos = next_pos - 1;
					ok = true;
					break;
				}
			}

			if(ok && areas > 0){
				total_areas += areas;
				area_list.add(areas);
			}
		}

		System.out.println(total_areas);
		System.out.print(area_list.size());
		for(int area : area_list){
			System.out.print(" " + area);
		}
		System.out.println();

