    }

    public void exec_body( BufferedReader bf ) throws IOException {
    		String line = bf.readLine();
    		line = omitString(line);

    		Stack<Boolean> charStack = new Stack<>();
    		int dimension = 0;
    		ArrayList<Integer> dimensionList = new ArrayList<>();
    		for( int i = 0; i < line.length(); i++ ) {
    			char ch = line.charAt(i);
    			if( ch == '\\' ) {
    				dimension = dimension + 1 + 2 * charStack.size();
    				charStack.push(Boolean.TRUE);
    			} else if( ch == '_') {
    				dimension = dimension + 2 * charStack.size();
    			} else {
    				if( charStack.size() == 0 ) {
        				continue;
    				}

    				charStack.pop();
    				dimension = dimension + 1 + 2 * charStack.size();
    				if( charStack.size() != 0 ) {
    					continue;
    				}

    				// listに入れて初期化する
    				dimensionList.add(Integer.valueOf(dimension));
    				dimension = 0;
    			}
    		}
    		if( dimension != 0 ) {
    			// 逆から計算し直して、1つめの水たまりでやめる
        		charStack = new Stack<>();
        		dimension = 0;
    			for( int i = line.length() -1; i >= 0; i--) {
        			char ch = line.charAt(i);
        			if( ch == '/' ) {
        				dimension = dimension + 1 + 2 * charStack.size();
        				charStack.push(Boolean.TRUE);
        			} else if( ch == '_') {
        				dimension = dimension + 2 * charStack.size();
        			} else {
        				if( charStack.size() == 0 ) {
            				continue;
        				}

        				charStack.pop();
        				dimension = dimension + 1 + 2 * charStack.size();
        				if( charStack.size() != 0 ) {
        					continue;
        				}

        				break;
        			}
    			}
    			dimensionList.add(Integer.valueOf(dimension));
    		}

    		int sum = 0;
    		for( int i = 0; i < dimensionList.size(); i++ ) {
    			sum = sum + dimensionList.get(i);
    		}
    		System.out.println(sum/2);

    		// 結果を出力する
    		StringBuilder bd = new StringBuilder();
    		bd.append(dimensionList.size());
    		for( int i = 0; i < dimensionList.size(); i++ ) {
    			bd.append(" ");
    			bd.append(dimensionList.get(i)/2);
    		}
    		System.out.println(bd.toString());
    }
}

import java.io.IOException;
import java.util.*;

class Main {
	public static void main(String args[]) throws IOException {
		Scanner in = new Scanner(System.in);

		Stack<Integer> st = new Stack<>();
		int ch;
		int sum = 0;
		List<Integer> lakes = new ArrayList<>();
		Stack<Pair<Integer, Integer>> lakeStack = new Stack<>(); // first: left's \ pos, right: the lake's size
		for(int i=0; (ch = System.in.read()) != -1; i++) {
			if (ch == '\n' || ch == '\r') {
				break;
			}

			if(ch == '\\') {
				st.push(i);
			} else if(ch == '/') {
				if(st.empty() == true) {
					continue;
				}
				int top = st.pop();
				sum += i - top;

				int lakePoint = i - top;

				while(lakeStack.empty() == false) {
					Pair<Integer, Integer> p = lakeStack.pop();
					if(p.fst >= top) {
						lakePoint += p.snd;
					} else {
						lakeStack.push(p);
						break;
					}
				}
				lakeStack.push(new Pair<>(top, lakePoint));
			}
		}

		while(lakeStack.empty() == false) {
			Pair<Integer, Integer> p = lakeStack.pop();
			lakes.add(p.snd);
		}
		Collections.reverse(lakes);

		System.out.println(sum);
		System.out.print(lakes.size());
		for(int i=0;i<lakes.size();i++) {
			System.out.print(" " + lakes.get(i));
		}

		System.out.println("");
	}
}

