import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) throws IOException {
        final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        final char[] line = reader.readLine().toCharArray();
        reader.close();

        final Deque<Integer> stack = new ArrayDeque<Integer>(line.length);
        final StringBuilder answer = new StringBuilder();

        int sum = 0;
        int count = 0;
        int indexLastZero = 0;
        final int[] process = new int[line.length + 1];
        final int[] graph = new int[line.length + 1];
        for (int i = 0; i < line.length; ++i) {
            graph[i] = stack.size();
            process[i] = sum;
            switch (line[i]) {
                case '\\':
                    stack.push(i);
                    break;
                case '/':
                    if (!stack.isEmpty()) {
                        sum += i - stack.pop();
                        if (stack.isEmpty()) {
                            ++count;
                            answer.append(" ").append(sum - process[indexLastZero + 1]);
                        }
                    }
                    break;
                default:
            }
            if (stack.isEmpty()) indexLastZero = i;
        }
        graph[line.length] = stack.size();
        process[line.length] = sum;

        for (int i = indexLastZero + 1; i < process.length; ++i) {
            for (int j = graph.length - 1; i < j; --j) {
                if (graph[i] == graph[j] && process[i] != process[j]) {
                    ++count;
                    answer.append(" ").append(process[j] - process[i]);
                    i = j;
                    break;
                }
            }
        }
        System.out.println(sum);
        System.out.println(count + answer.toString());
    }
}

import java.io.UnsupportedEncodingException;
import java.lang.reflect.UndeclaredThrowableException;
import java.util.Scanner;


class Main {
	public static void main(String args[]) {
		Scanner scanner = new Scanner(System.in);
		String mark = scanner.next();
		int num = mark.length();

		SectionDiagram(mark, num, scanner);

	}
	//enum宣言
	public static enum Operate{
		back(92),
		slush(47),
		under(95);

		private final int mark;

		private Operate(final int mark) {
			this.mark = mark;
		}

		public int getInt(){
			return this.mark;
		}
	}
	public static Operate getOperate(final int id) {
		Operate[] marks = Operate.values();
		for (Operate type : marks) {
			if (type.getInt() == id) {
				return type;
			}
		}
		return null;
	}
	//治水シミュレーション
	public static void SectionDiagram(String mark, int num, Scanner scanner){
		int[] count_puddle = new int[num+5];	//"￥"が来たらそいつをカウント開始
		int[] puddle = new int[num+5];			//各水たまりの面積
		int sum_puddle_now = 0;						//今の水溜りの面積
		int sum_puddle = 0;						//水溜りの面積の合計
		int num_puddle = 0;						//水たまりの数
		int count = 0;							//Whileの周回
		int en_num = 0;							//カウントする￥の数
		int en_max = 0;							//深さ
		int i;
		byte[] mark_num = new byte[num];		//switch用格納庫

		try {
			mark_num = mark.getBytes("US-ASCII");
		} catch (UnsupportedEncodingException e) {
			// TODO 自動生成された catch ブロック
			e.printStackTrace();
		}

		while( num > count ){										//文字数文処理


			switch( getOperate(mark_num[count]) ){					//
			case back:
				en_num ++;											//￥の数カウント
				break;
			case slush:
				en_num --;											//￥の数マイナス
				if( en_num < 0 ) {
					en_num = 0;
					break;
				}

				sum_puddle_now += count_puddle[en_num + 1];			//消した￥の面積を今の水たまりにする
				count_puddle[en_num + 1] = 0;						//それを初期化

				if ((en_num == 0) || ( count == num - 1)){			//今回の水たまりが確定
					sum_puddle += sum_puddle_now;					//今回の水たまりを全体に足す
					puddle[num_puddle] = sum_puddle_now;			//今回の水たまりを配列に入れる
					sum_puddle_now = 0;								//水たまり初期化
					sum_puddle_now = 0;								//水たまり初期化
					num_puddle ++;									//全体の水たまりの数を足す
				}
				break;
			case under:
				break;
			}
			//￥の数だけカウント
			for( i = 1; i <= en_num; i ++ ){
				count_puddle[i] += 1;
			}
			count ++;
		}
		if( en_num != 0 ) {
			sum_puddle += sum_puddle_now;
			puddle[num_puddle] = sum_puddle_now;
			num_puddle ++;
		}

		//出力処理
		System.out.println(sum_puddle);	
		System.out.print(num_puddle);
		for( i = 0; i < num_puddle; i ++ ) {
			System.out.print(" " + puddle[i]);
		}
		System.out.println();
	}
}

import java.io.*;
import java.util.ArrayList;
import java.util.Deque;
import java.util.ArrayDeque;

class Main {
    public static void main (String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        char[] input = br.readLine().toCharArray();
        Deque<Integer> stack = new ArrayDeque<Integer>();
        ArrayList<int[]> puddles = new ArrayList<int[]>();

        for (int i = 0; i < input.length; i++) {
            if (input[i] == '\\') {
                stack.push(i);
            } else if (input[i] == '/' && !stack.isEmpty()) {
                puddles.add(new int[] {stack.pop(), i});
            }
        }

        ArrayList<Integer> areas = new ArrayList<Integer>();
        int area;
        int totalArea = 0;
        for (int i = 0; i < input.length; i++) {
            for (int[] puddle: puddles) {
                if (puddle[0] == i) {
                    area = puddle[1] - puddle[0] + calcArea(puddle[0] + 1, puddle[1] - 1, puddles);
                    areas.add(area);
                    totalArea += area;
                    i = puddle[1] + 1;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append(totalArea).append("\n").append(areas.size());
        if (areas.size() > 0) {
            sb.append(" ").append(areas.remove(0));
            for (int a: areas) {
                sb.append(" ").append(a);
            }
        }

        System.out.println(sb.toString());
    }

    public static int calcArea(int first, int last, ArrayList<int[]> puddles) {
        int area = 0;
        for (int i = first; i < last; i++) {
            for (int[] puddle: puddles) {
                if (puddle[0] == i) {
                    area += puddle[1] - puddle[0] + calcArea(puddle[0] + 1, puddle[1] - 1, puddles);
                    i = puddle[1] + 1;
                }
            }
        }
        return area;
    }
}

import java.io.IOException;
import java.util.*;

class Main {
	public static void main(String args[]) throws IOException {
		Scanner in = new Scanner(System.in);

		Stack<Integer> st = new Stack<>();
		int ch;
		int sum = 0;
		List<Integer> lakes = new ArrayList<>();
		Stack<Pair<Integer, Integer>> lakeStack = new Stack<>(); // first: left's \ pos, right: the lake's size
		for(int i=0; (ch = System.in.read()) != -1; i++) {
			if (ch == '\n' || ch == '\r') {
				break;
			}

			if(ch == '\\') {
				st.push(i);
			} else if(ch == '/') {
				if(st.empty() == true) {
					continue;
				}
				int top = st.pop();
				sum += i - top;

				int lakePoint = i - top;

				while(lakeStack.empty() == false) {
					Pair<Integer, Integer> p = lakeStack.pop();
					if(p.fst >= top) {
						lakePoint += p.snd;
					} else {
						lakeStack.push(p);
						break;
					}
				}
				lakeStack.push(new Pair<>(top, lakePoint));
			}
		}

		while(lakeStack.empty() == false) {
			Pair<Integer, Integer> p = lakeStack.pop();
			lakes.add(p.fst);
		}
		Collections.reverse(lakes);

		System.out.println(sum);
		System.out.print(lakes.size()+ " ");
		for(int i=0;i<lakes.size();i++) {
			System.out.print(lakes.get(i) + " ");
		}
		System.out.println("");
	}
}

