import java.util.*;

class Lake {
	int rpos, lpos, area;
	Lake(int lpos, int rpos, int areaOfChilds) {
		this.rpos = rpos;
		this.lpos = lpos;
		this.area = rpos - lpos - 1 + areaOfChilds;
	}
	void print() {
		System.out.println("lpos:" + lpos + ", rpos:" + rpos + ", area:" + area);
	}
}
public class Main {

	void printArray(int[] a) {
		for (int i = 0; i < a.length; i++) {
			System.out.print(a[i] + " ");
		}
		System.out.println();
	}

	void update(LinkedList<Lake> lakes, int l, int r) {
		LinkedList<Lake> childs = new LinkedList<Lake>();
		int areaOfChilds = 0;
		int i = 0, idx = -1;
		for (Lake lake : lakes) {
			if (l < lake.lpos && lake.rpos < r) {
				childs.addLast(lake);
				areaOfChilds += lake.area;
				if (idx == -1) idx = i;
			} else if (idx == -1 && r <= lake.lpos) {
				idx = i;
			}
			i++;
		}
		lakes.removeAll(childs);
		lakes.add((idx == -1 ? lakes.size() : idx), new Lake(l, r, areaOfChilds));
	}

	void debugPrint(LinkedList<Lake> lakes) {
		for (Lake lake : lakes) {
			lake.print();
		}
		System.out.println();
	}

	void solve(int[] a, int level, int cap, LinkedList<Lake> lakes) {
		//System.out.println("solve: " + level + ", " + cap);
		do {
			System.out.println("solve: " + level + ", " + cap);
		for (int i = 0; i < a.length;) {
			int l = -1, r = -1;
			if (a[i] == level && i+1 < a.length && a[i+1] == (level-1)) {
				l = i;
				for (i += 2; i < a.length; i++) {
					if (a[i] == level && a[i-1] == (level-1)) {
						r = i;
						break;
					}
				}
				if (r != -1) {
					update(lakes, l, r);
				}
			}
			if (r == -1) i++;
		}
		} while (cap > level++);
		//System.out.println(level);
		//debugPrint(lakes);
		//if (cap <= level) return;
		//solve(a, level+1, cap, lakes);
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		String line = sc.nextLine();
		char[] chars = line.toCharArray();
		int[] heights = new int[chars.length + 1];
		heights[0] = 0;  // 基準にする
		int bottom = 0;
		int top = 0;
		for (int i = 1; i < heights.length; i++) {
			int diff = 0;
			switch (chars[i-1]) {
			case '\\':
				diff = -1;
				break;
			case '/':
				diff = +1;
				break;
			case '_':
				diff = 0;
				break;
			}
			heights[i] = heights[i-1] + diff;
			bottom = Math.min(heights[i], bottom);
			top = Math.max(heights[i], top);
		}
		//printArray(heights);
		LinkedList<Lake> lakes = new LinkedList<Lake>();
		solve(heights, bottom+1, top, lakes);

		int sum = 0;
		for (Lake lake : lakes) {
			sum += lake.area;
		}

		System.out.println(sum);
		System.out.print(lakes.size());
		for (Lake lake : lakes) {
			System.out.print(" " + lake.area);
		}
		System.out.println();
	}

	public static void main(String[] args) {
		new Main().run();
	}

}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    // 現在のx座標
    public int lineNumber;

    // 現在の 層別未確定水たまりスタック
    public ArrayList<Short> stack;
    // 未確定水たまり層の始点
    public ArrayList<Short> stackStart;
    // 確定水たまりリスト
    public ArrayList<Short> puddles;
    // 確定水たまり層の始点
    public ArrayList<Short> puddleStart;
    // 現在の確定水たまりIdx
    public int puddleNumber = 0;
    // 現在の深さ
    public int currentDepth = 0;
    // 前回の水たまり水面高
    public int prevPuddleHeight = -1;

    public int sum = 0;

    /**
     * 指定の層へ水を追加する
     *
     * @param idx       追加する層Idx
     * @param n         追加量
     * @param isConfirm 層確定操作を行うかどうか
     */
    public void add(int idx, int n, boolean isConfirm) {
        // 初出層の場合はstackに追加
        if (this.stack.size() - 1 < idx) {
            this.stack.add(idx, (short) 0);
            this.stackStart.add(idx, (short) lineNumber);
        }
        // 追加動作
        this.stack.set(idx, (short) (this.stack.get(idx) + n));
        // 層確定操作
        if (isConfirm) {
            this.sum += this.stack.get(idx);
            // 現在の未確定水たまり層を、確定水たまりリストに移す
            this.puddles.add(puddleNumber, this.stack.get(idx));
            // 追加した確定水たまりの始点も設置
            this.puddleStart.add(puddleNumber, (short) this.stackStart.get(idx));
            // 初回の層確定操作でない && 前回の層確定操作の1つ上位層の場合
            if ((prevPuddleHeight != -1) && ((prevPuddleHeight - 1) == idx)) {
                // 繰り上がり動作を行う
                // 各確定水たまりについて、初めて (現在の水たまりの始点) < (ある水たまり始点) となるものを探す
                int start = this.puddleStart.get(puddleNumber);
                for (int i = 0; i <= puddleNumber; i++) {
                    // (現在の水たまりの始点) < (ある水たまり始点) Hit!!
                    if (start < this.puddleStart.get(i)) {
                        // ある地点の水たまりを吸収
                        // はじめに始点を更新
                        this.puddleStart.set(i, (short) start);
                        // 次に、その間の水たまり量をすべて吸収
                        for (int j = i + 1; j <= puddleNumber; j++) {
                            this.puddles.set(i, (short) (this.puddles.get(i) + this.puddles.get(j)));
                        }
                        for (int j = puddleNumber; j >= i + 1; j--) {
                            this.puddles.remove(j);
                            this.puddleStart.remove(j);
                        }
                        puddleNumber = i + 1;
                        break;
                    }
                }
            } else { // 繰り上がり動作を行わない場合
                puddleNumber++;
            }
            prevPuddleHeight = idx;
            this.stack.remove(idx);
            this.stackStart.remove(idx);
        }
    }

    public void up() {
        if (currentDepth == 0) {
            return;
        }
        currentDepth--;
        this.add(currentDepth, 1, true);
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void hori() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void down() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
        this.add(currentDepth, 1, false);
        currentDepth++;
    }

    public void print() {
        System.out.println(sum / 2);
        System.out.print(this.puddles.size());
        int len = this.puddles.size();
        for (int i = 0; i < len; i++) {
            System.out.print(" " + (this.puddles.get(i) / 2));
        }
        System.out.println();
    }

    public void go() {
        this.stack = new ArrayList<Integer>();
        this.stackStart = new ArrayList<Integer>();
        this.puddles = new ArrayList<Integer>();
        this.puddleStart = new ArrayList<Integer>();
        Scanner sc = new Scanner(System.in);
        String line = sc.next();
        String[] strings = line.split("");
        for (int i = 0; i < strings.length; i++) {
            String s = strings[i];
            this.lineNumber = i;
            switch (s) {
            case "\\":
                this.down();
                break;
            case "_":
                this.hori();
                break;
            case "/":
                this.up();
                break;
            }
        }
        print();
    }

    public static void main(String[] args) {
        Main cui = new Main();
        cui.go();
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.Stack;

class Main {
    public static void main (String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String input = br.readLine();
        Stack<Integer> stack = new Stack<Integer>();
        ArrayList<int[]> puddles = new ArrayList<int[]>();

        for (int i = 0; i < input.length(); i++) {
            if (input.charAt(i) == '\\') {
                stack.push(i);
            } else if (input.charAt(i) == '/' && !stack.empty()) {
                puddles.add(new int[] {stack.pop(), i});
            }
        }

        ArrayList<Integer> areas = new ArrayList<Integer>();
        int area;
        int totalArea = 0;
        for (int i = 0; i < input.length(); i++) {
            for (int[] puddle: puddles) {
                if (puddle[0] == i) {
                    area = puddle[1] - puddle[0] + calcArea(puddle[0] + 1, puddle[1] - 1, puddles);
                    areas.add(area);
                    totalArea += area;
                    i = puddle[1] + 1;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append(totalArea).append("\n").append(areas.size());
        if (areas.size() > 0) {
            sb.append(" ").append(areas.remove(0));
            for (int a: areas) {
                sb.append(" ").append(a);
            }
        }

        System.out.println(sb.toString());
    }

    public static int calcArea(int first, int last, ArrayList<int[]> puddles) {
        int area = 0;
        for (int i = first; i < last; i++) {
            for (int[] puddle: puddles) {
                if (puddle[0] == i) {
                    area += puddle[1] - puddle[0] + calcArea(puddle[0] + 1, puddle[1] - 1, puddles);
                    i = puddle[1] + 1;
                }
            }
        }
        return area;
    }
}

import java.io.*;
import java.util.Stack;

class Main{
	// -1 : '\' -2: '_' 

	public static void main(String[] args) {
		int MAX = 100;

		int[] squareOfEachSection = new int[MAX]; 

		int totalSquare = 0;

		for (int i = 0; i < squareOfEachSection.length; i++ ){
			squareOfEachSection[i] = 0;
		}

		// try(BufferedReader reader = new BufferedReader(new FileReader("input.txt")))
		try(BufferedReader reader = new BufferedReader(new InputStreamReader(System.in)))
		{

			String inputString = reader.readLine();

			Stack<Integer> stack = new Stack<>();

			int sectionIdentifier = 0;

			int numOfBackSlashInStack = 0;

			for (int i = 0; i < inputString.length(); i++) {
				char currChar = inputString.charAt(i);

				if (currChar != '/'){
					if (currChar == '\\'){
						numOfBackSlashInStack ++;
						stack.push(-1);
					}else {
						// '_'
						stack.push(-2);
					}

				}else {
					if (numOfBackSlashInStack > 0) {

						numOfBackSlashInStack --;
						// If we are in new section, should increment "sectionIAmIn" by 1
						boolean isInNewSection = true; 
						int minSectionId = 100;
						// squareOfWaterInthisSection = numGotPop; 
						// Example : \__/  , 3 item '_' '_' '\' got pop, it is 3. 
						// '\'+'/' = 1, 0.5 per each. else weight 1. 
						int numGotPop = 0;
						int itemPop = -5; // -5 has not special meaning

						// pop items out of stack until we hit "\"
						do{
							itemPop = stack.pop();
							numGotPop ++;
							if (itemPop > 0){
								minSectionId = minSectionId > itemPop ? itemPop : minSectionId;
								isInNewSection = false;
							}

							// while itempop is not -1 ('\')
						}while(itemPop != -1 );

						if (isInNewSection) {
								sectionIdentifier += 1;

							squareOfEachSection[sectionIdentifier] += numGotPop;
							totalSquare += numGotPop;

							for (int j = 0; j <= numGotPop; j++) {
								stack.push(sectionIdentifier);
							}
						}else {
							if (minSectionId < sectionIdentifier){

								for (int j = minSectionId + 1; j <= sectionIdentifier; j++){
									squareOfEachSection[minSectionId] += squareOfEachSection[j];
									squareOfEachSection[j] = 0;
								}

								sectionIdentifier = minSectionId;
							}

							squareOfEachSection[sectionIdentifier] += numGotPop;
							totalSquare += numGotPop;

							for (int j = 0; j <= numGotPop; j++) {
									stack.push(sectionIdentifier);

							}
						}



					} 
				} 
			} // end for

			System.out.println(totalSquare+"");
			System.out.print(sectionIdentifier+"");

			for (int i = 1; i <= sectionIdentifier; i++){
				System.out.print(" "+squareOfEachSection[i]);
			}
			System.out.println();

		} catch (Exception e) {
			e.printStackTrace();
		}


	}
}

import com.sun.tools.javac.util.Pair;

import java.io.IOException;
import java.util.*;

class Main {
	public static void main(String args[]) throws IOException {
		Scanner in = new Scanner(System.in);

		Stack<Integer> st = new Stack<>();
		int ch;
		int sum = 0;
		List<Integer> lakes = new ArrayList<>();
		Stack<Pair<Integer, Integer>> lakeStack = new Stack<>(); // first: left's \ pos, right: the lake's size
		for(int i=0; (ch = System.in.read()) != -1; i++) {
			if (ch == '\n' || ch == '\r') {
				break;
			}

			if(ch == '\\') {
				st.push(i);
			} else if(ch == '/') {
				if(st.empty() == true) {
					continue;
				}
				int top = st.pop();
				sum += i - top;

				int lakePoint = i - top;

				while(lakeStack.empty() == false) {
					Pair<Integer, Integer> p = lakeStack.pop();
					if(p.fst >= top) {
						lakePoint += p.snd;
					} else {
						lakeStack.push(p);
						break;
					}
				}
				lakeStack.push(new Pair<>(top, lakePoint));
			}
		}

		while(lakeStack.empty() == false) {
			Pair<Integer, Integer> p = lakeStack.pop();
			lakes.add(p.fst);
		}
		Collections.reverse(lakes);

		System.out.println(sum);
		System.out.print(lakes.size()+ " ");
		for(int i=0;i<lakes.size();i++) {
			System.out.print(lakes.get(i) + " ");
		}
		System.out.println("");
	}
}

import java.util.LinkedList;
import java.util.Scanner;
public class Main {
	static int anotherSide(int[] map,int x){//baseと同じ高さを持つ一番近いｘ座標を返す
		for(int i=x+1;i<map.length;i++){
			if(map[x]==map[i]) return i;
		}
		return -1;
	}
	static double crossProduct(int x1,int y1,int x2,int y2){
		return x1*y2-y1*x2;
	}
	public static void main(String[] args){
		Scanner scan=new Scanner(System.in);
		String data=scan.next();
		int N=data.length()+1;
		int[] map=new int[N];
		int height=0;
		for(int i=0;i<N;i++ ){
			map[i]=height;
			if(i==N-1){
				break;
			}else{
				if(data.charAt(i)=='\\'){
					height--;
				}else if(data.charAt(i)=='/'){
					height++;
				}else{
					//何もしない。高さが変わらない。
				}
			}
		}
		int base=0;
		int area=0;
		int All=0;
		int nextbase;
		boolean sign=false;
		LinkedList<Integer> answer=new LinkedList<Integer>();
		while(true){
			if(base==N-1) break;
			while(!(map[base]>map[base+1])){
				base++;
				if(base==N-1){
					sign=true;
					break;
				}
			}
			if(sign) break;
			nextbase=anotherSide(map,base);
			if(nextbase==-1){//見つからなかった。
				base++;
				continue;
			}else{//水たまりができる。
				//外積
				for(int i=base;i<nextbase;i++){
					area+=crossProduct(i,map[i],i+1,map[i+1]);
				}
				area+=crossProduct(nextbase,map[nextbase],base,map[base]);//面積が求まった
				area/=2;
				area=Math.abs(area);
				All+=area;
				answer.addLast(area);
				area=0;
				base=nextbase;
			}
		}
		System.out.println(All);
		System.out.print(answer.size());
		while(!answer.isEmpty()){
			System.out.print(" "+answer.poll());
		}
		System.out.println();
		scan.close();
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;

public class Main {
	public static void main(String[] args) {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		ArrayList<Integer> sg = new ArrayList<Integer>();

		int[] heights = null;
		String str = "";
		try {
			str = in.readLine();
			heights = new int[str.length() + 1];
			heights[0] = 0;

			int height = 0;
			for (int i = 1; i < (str.length() + 1); i++) {
				char c = str.charAt(i - 1);

				switch (c) {
				case '\\' :
					height--;
					break;
				case '/' :
					height++;
					break;
				}
				heights[i] = height;
			}

			int num = 0;

			int limit = str.length() + 1;
			for (int i = 0; i < limit; i++) {
				int th = heights[i];
				int tmin = th;

				for (int j = (i + 1); j < limit; j++) {
					if (th < heights[j]) break;

					if (th == heights[j]) {
						if (tmin == th) {
							break;
						} else {
							sg.add(i);
							sg.add(j);

							num++;
							i = (j - 1);
							break;
						}
					}

					if (tmin > heights[j]) tmin = heights[j];
				}
			}

			double[] areas = new double[num];
			for (int i = 0; i < areas.length; i++) {
				int start = sg.get(i * 2);
				int end = sg.get(i * 2 + 1);

				height = 0;
				double area = 0.0;
				for (int j = start; j < end; j++) {
					char c = str.charAt(j);

					area = area + height;
					switch (c) {
					case '\\' :
						height++;
						area = area + 0.5;
						break;
					case '/' :
						height--;
						area = area - 0.5;
						break;
						}
				}

				areas[i] = area;
			}

			int sum = 0;
			for (int i = 0; i < areas.length; i++) {
				sum = sum + (int)areas[i];
			}
			System.out.println(sum);

			System.out.print(num);
			for (int i = 0; i < num; i++) {
				System.out.print(" " + (int)areas[i]);
			}
			System.out.println();
		} catch (NumberFormatException e) {
			// TODO Auto-generated catch block
			e.printStackTrace();
		} catch (IOException e) {
			// TODO Auto-generated catch block
			e.printStackTrace();
		}
	}
}

