        Deque<IntPair> downPosPool = new ArrayDeque<>();

        int totalPool = 0;
        for (int i = 0; i < len; i++) {
            char ch = str.charAt(i);
            if (ch == '\\') {
                downPos.push(i);
            } else if (ch == '/' && !downPos.isEmpty()) {
                int j = downPos.pop();
                int a = i - j;
                totalPool += a;
                while (!downPosPool.isEmpty() && downPosPool.peek().int1 > j) {
                    a += downPosPool.pop().int2;
                }
                downPosPool.push(new IntPair(j, a));
            }
        }
        System.out.println(totalPool);

        int size = downPosPool.size();
        System.out.print(size + " ");
        for (int i = 0; i < size - 1; i++) {
            System.out.print(downPosPool.pollLast().int2 + " ");
        }
        System.out.print(downPosPool.pollLast().int2);
    }

    static class IntPair {
        int int1;
        int int2;
        IntPair(int i1, int i2) {
            int1 = i1;
            int2 = i2;
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		String[] str = sc.nextLine().split("");
		Deque<Integer> que = new ArrayDeque<>();
		Deque<List<Integer>> puddle = new ArrayDeque<>();
		for (int i = 0; i < str.length; i++) {
			if (str[i].equals("\\")) {
				que.add(i);
			} else if(str[i].equals("/")) {
				if (que.size() == 0) {
					continue;
				} else {
					int l = que.pollLast();
					int s = i - l;
					if(puddle.size() == 0) {
						puddle.addLast(new ArrayList<>());
						puddle.getLast().add(0, l);
						puddle.getLast().add(1, s);
					} else {
						if(l > puddle.getLast().get(0)) {
							puddle.addLast(new ArrayList<>());
							puddle.getLast().add(0, l);
							puddle.getLast().add(1, s);
						} else {
							List<Integer> list = puddle.pollLast();
							while (true) {
								s += list.get(1);
								if (puddle.size() == 0) {
									break;
								} else if(puddle.getLast().get(0) < l) {
									break;
								} else {
									list = puddle.pollLast();
								}
							}
							puddle.add(new ArrayList<>());
							puddle.getLast().add(0, l);
							puddle.getLast().add(1, s);
						}
					}
				}
			}
		}
		int sum = 0;
		Iterator<List<Integer>> it = puddle.iterator();
		while (it.hasNext()) {
			List<Integer> next = it.next();
			sum += next.get(1);
		}
		System.out.println(sum);
		if (puddle.size() == 0) {
			System.out.println(puddle.size());
		} else {
			System.out.print(puddle.size() + " ");
			it = puddle.iterator();
			while (it.hasNext()) {
				List<Integer> next = it.next();
				if(!it.hasNext()) {
					System.out.println(next.get(1));
				} else {
					System.out.print(next.get(1) + " ");
				}
			}
		}
	}
}

import java.util.ArrayList;
import java.util.Scanner;

/**
 * ACSD
 */
public class Main {
    // 現在のx座標
    public int lineNumber;

    // 現在の 層別未確定水たまりスタック
    public ArrayList<Integer> stack;
    // 未確定水たまり層の始点
    public ArrayList<Integer> stackStart;
    // 確定水たまりリスト
    // public ArrayList<Integer> puddles;
    public int[] puddles = new int[10000];
    // 確定水たまり層の始点
    // public ArrayList<Integer> puddleStart;
    public int[] puddleStart = new int[10000];
    // 現在の確定水たまりIdx
    public int puddleNumber = 0;
    // 現在の深さ
    public int currentDepth = 0;
    // 前回の水たまり水面高
    public int prevPuddleHeight = -1;

    public int sum = 0;

    /**
     * 指定の層へ水を追加する
     *
     * @param idx       追加する層Idx
     * @param n         追加量
     * @param isConfirm 層確定操作を行うかどうか
     */
    public void add(int idx, int n, boolean isConfirm) {
        // 初出層の場合はstackに追加
        if (this.stack.size() - 1 < idx) {
            this.stack.add(idx, 0);
            this.stackStart.add(idx, lineNumber);
        }
        // 追加動作
        this.stack.set(idx, (this.stack.get(idx) + n));
        // 層確定操作
        if (isConfirm) {
            this.sum += this.stack.get(idx);
            // 現在の未確定水たまり層を、確定水たまりリストに移す
            this.puddles[puddleNumber] = this.stack.get(idx) / 2;
            // 追加した確定水たまりの始点も設置
            this.puddleStart[puddleNumber] = this.stackStart.get(idx);
            // 初回の層確定操作でない && 前回の層確定操作の1つ上位層の場合
            if ((prevPuddleHeight != -1) && ((prevPuddleHeight - 1) == idx)) {
                // 繰り上がり動作を行う
                // 各確定水たまりについて、初めて (現在の水たまりの始点) < (ある水たまり始点) となるものを探す
                int start = this.puddleStart[puddleNumber];
                for (int i = 0; i <= puddleNumber; i++) {
                    // (現在の水たまりの始点) < (ある水たまり始点) Hit!!
                    if (start < this.puddleStart[i]) {
                        // ある地点の水たまりを吸収
                        // はじめに始点を更新
                        this.puddleStart[i] = start;
                        // 次に、その間の水たまり量をすべて吸収
                        for (int j = i + 1; j <= puddleNumber; j++) {
                            this.puddles[i] += this.puddles[j];
                        }
                        for (int j = puddleNumber; j >= i + 1; j--) {
                            this.puddles[j] = 0;
                            this.puddleStart[j] = 0;
                        }
                        puddleNumber = i + 1;
                        break;
                    }
                }
            } else { // 繰り上がり動作を行わない場合
                puddleNumber++;
            }
            prevPuddleHeight = idx;
            this.stack.remove(idx);
            this.stackStart.remove(idx);
        }
    }

    public void up() {
        if (currentDepth == 0) {
            return;
        }
        currentDepth--;
        this.add(currentDepth, 1, true);
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void hori() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
    }

    public void down() {
        for (int i = 0; i < currentDepth; i++) {
            this.add(i, 2, false);
        }
        this.add(currentDepth, 1, false);
        currentDepth++;
    }

    public void print() {
        System.out.println(sum / 2);
        int len = puddleNumber - 1;
        System.out.print(len);
        for (int i = 0; i < len; i++) {
            System.out.print(" " + this.puddles[i]);
        }
        System.out.println();
    }

    public void go() {
        this.stack = new ArrayList<Integer>();
        this.stackStart = new ArrayList<Integer>();
        this.puddles = new ArrayList<Integer>();
        this.puddleStart = new ArrayList<Integer>();
        Scanner sc = new Scanner(System.in);
        String line = sc.next();
        String[] strings = line.split("");
        for (int i = 0; i < strings.length; i++) {
            String s = strings[i];
            this.lineNumber = i;
            switch (s) {
            case "\\":
                this.down();
                break;
            case "_":
                this.hori();
                break;
            case "/":
                this.up();
                break;
            }
        }
        print();
    }

    public static void main(String[] args) {
        Main cui = new Main();
        cui.go();
    }
}

import java.util.Scanner;

public class Main {
	public static int sumarea(String str, int sdepth, int edepth) {
		int i, len, start = sdepth, end = edepth, depth = 0;
		double area = 0;
		len = str.length();
		for (i = 0; i < len; i++) {
			if (start > end && str.charAt(i) == '\\') {
				start--;
			} else {
				switch (str.charAt(i)) {
					case '\\':
						area += depth - 0.5;
						depth -= 1;
						break;
					case '/':
						area += depth + 0.5;
						depth += 1;
						break;
					case '_':
						area += depth;
						break;
					default:
						continue;
				}
			}
		}
		return (int) -area;
	}

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int i = 0, j = 0, len, start = -1, end = 0, depth = 0, sdepth = 0, edepth = 0, count = 0,memo=0;
		int sum = 0;
		String str;
		str = scan.next();
		len = str.length();
		j = len / 2 + 1;
		int[] area = new int[j];
		j=0;
		while (i < len) {
			for (i = memo; i < len; i++) {
				if (start == -1 && str.charAt(i) == '\\') {
					start = i;
					depth = 0;
					sdepth = 0;
				}
				if (start != -1) {
					switch (str.charAt(i)) {
						case '\\':
							depth -= 1;
							break;
						case '/':
							if (end == 0) {
								end = i;
								edepth = depth;
							}
							depth += 1;
							if (depth > edepth) {
								end = i;
								edepth = depth;
							}
							if (edepth == 0) {
								area[j] = sumarea(str.substring(start, end + 1), sdepth, edepth);
								sum += area[j];
								count++;
								j++;
								start = -1;
								end = 0;
							}
							break;
						default:
							continue;
					}
				}
			}
			if (start<end+1 && sdepth > edepth) {
				area[j] = sumarea(str.substring(start, end + 1), sdepth, edepth);
				sum += area[j];
				count++;
				i=end+1;
				j++;
				memo=end;
				start = -1;
				end = 0;
			}
			if(i>=len)break;
		}
		System.out.print(sum + "\n" + count + " ");
		for (i = 0; i < count; i++) {
			if (area[i] > 0)
				System.out.print(area[i] + " ");
		}
		scan.close();
	}
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {

	static Deque<Integer> mapStack;
	static Deque<Mizutamari> waterStack;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		String[] graph = sc.nextLine().split("");
		sc.close();
		mapStack = new ArrayDeque<>();
		waterStack = new ArrayDeque<>();

		for (int i = 0; i < graph.length; i++) {
			switch (graph[i]) {
			case "\\":
				mapStack.offerLast(i);
				break;
			case "/":
				if (mapStack.isEmpty()) continue;
				int start = mapStack.pollLast();
				int tmpArea = i - start;
				while (!waterStack.isEmpty() && waterStack.peekLast().getStartIdx() > start) {
					tmpArea += waterStack.pollLast().getArea();
				}
				waterStack.offerLast(new Mizutamari(start, tmpArea));
				break;
			case "_":
				continue;
			}

		}

		System.out.println(waterStack.stream().map(m -> m.getArea()).reduce(0, (x, y) -> x + y));
		System.out.print(waterStack.size());
		int len = waterStack.size();
		for (int i = 0; i < len; i++) {
			System.out.print(" ");
			System.out.print(waterStack.pollFirst());
		}
		System.out.print("\n");
	}

}

