       static double water(peak start, peak end, string data)
       {
           double result = 0;
           int revised_start = start.position;
           if (start.height > end.height)
           {
               int hight = start.height;
               for (int i = start.position+1; i < end.position; i++)
               {
                   if (data[i] == '_')
                       continue;
                   hight--;
                   if (hight == end.height)
                   {
                       revised_start = i;
                       break;
                   }
               }
           }
            int depth = 0;
            for (int j = revised_start; j <= end.position; j++)
            {

                if (data[j] == '/')
                {
                    depth--;
                    result += depth+0.5;
                    if (depth == 0)
                        break;
                }
                else if(data[j] == '_')
                {
                    result += depth;
                }else
                {
                    result += depth+0.5;
                    depth++;
                }

            }

           return result;
       }


