                        point.position = 0;
                    position.Add(point);
                    break;

                }
            }
            hight = highest;
            for (; count < Data.Length; count++)
            {

                if (Data[count] == '/')
                {
                    hight++;
                    if (down == true)
                    {
                        down = false;
                        up = true;
                    }
                    if (count == Data.Length - 1)
                    {
                        for (int i = position.Count - 2; i > start; i -= 2)
                        {
                            if (position[i].height < hight )
                            {
                                position.RemoveAt(i);
                                position.RemoveAt(i);
                            }
                        }
                        peak point = new peak();
                        point.height = hight;
                        point.position = count;
                        position.Add(point);

                    }
                }
                else if (Data[count] == '\\')
                {
                    hight--;
                    if (down == false && up == false)
