                        down = true;
                    }
                    else if (down == false && up == true)
                    {
                        for (int i = position.Count - 2; i > start; i-=2)
                        {
                            if (position[i].height < hight + 1)
                            {
                                position.RemoveAt(i);
                                position.RemoveAt(i);
                            }
                        }
                        down = true;
                        up = false;
