namespace ALDS_1_3_D
{
    class Program
    {
        static void Main(string[] args)
        {
            //入力
            char[] inputLine = Console.ReadLine().ToCharArray();

            //読み込んだバックスラッシュのインデックスを格納する。
            Stack<int> slashStack = new Stack<int>();

            //これまでの水たまりの面積と、水たまりの左端のスラッシュインデックスを格納する。
            Stack<Pond> pondStack = new Stack<Pond>();

            for (int i = 0; i < inputLine.Length; i++)
            {
                if (inputLine[i] == '\\')
                {
                    slashStack.Push(i);
                }

                if (inputLine[i] == '/' && slashStack.Count() > 0)
                {
                    int tmpIndex = slashStack.Pop();

                    Pond tmpPond = new Pond(tmpIndex, i - tmpIndex);

                    while (pondStack.Count() > 0 && pondStack.Peek().slashIndex > tmpPond.slashIndex)
                    {
                        tmpPond.SumPond(pondStack.Pop());
                    }

                    pondStack.Push(tmpPond);
                }
            }

            int totalVolume = 0;

            pondStack.ToList()
                     .ForEach(p => totalVolume += p.volume);
            //総面積
            Console.WriteLine(totalVolume);

            //水たまり総数
            Console.Write(pondStack.Count());

            //各水たまり面積
            pondStack.Reverse()
                     .ToList()
                     .ForEach(p => Console.Write(" " + p.volume));

            Console.WriteLine();
        }
    }

