public static class Program {
    public static void Main() {
        #region SetAutoFlushIsFalse
#if !DEBUG
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
#endif
        #endregion

        var str = Console.ReadLine();

        var downPos = new Stack<int>();
        var pools = new Stack<Pool>();
        var sumS = 0;
        for (int i = 0; i < str.Length; i++) {
            switch (str[i]) {
                case ('\\'):
                    downPos.Push(i);
                    break;
                case ('/'):
                    if (downPos.Count() == 0) {
                        continue;
                    }

                    var start = downPos.Pop();
                    var thisLayerS = i - start;

                    sumS += thisLayerS;

                    var underLayerPoolS = 0;
                    while (pools.Count() > 0 && pools.Peek().StartAt >= start) {
                        var underLayerPool = pools.Pop();
                        underLayerPoolS += underLayerPool.Area;
                    }

                    pools.Push(new Pool(start, underLayerPoolS + thisLayerS));
                    break;
                default:
                    break;
            }
        }

        Console.WriteLine(sumS);

        var arr = pools.Select(e => e.Area).Concat(new int[] { pools.Count()}).Reverse().ToArray();
        Console.WriteLine(string.Join(" ", arr));

        #region Flush
#if !DEBUG
        Console.Out.Flush();
        sw.Close();
#endif
        #endregion
    }

    struct Pool {
        public int StartAt { get; set; }
        public int Area { get; set; }

        public Pool(int startAt, int area) {
            this.StartAt = startAt;
            this.Area = area;
        }
    }
}

