namespace CSharpSample01
{

    struct Pool
    {
        public int left;
        public int area;
    }


    class Program
    {



        static void Main(string[] args)
        {
            //入力1(L)
            string S = Console.ReadLine();

            int sum_area = 0;           
            Stack<int> st = new Stack<int>();
            Stack<Pool> pool_st = new Stack<Pool>();

            for(int i = 0; i < S.Length; i++)
            {
                if(S[i] == '\\')
                {
                    st.Push(i);
                }
                else if(S[i] == '/')
                {
                    //対応する/があるので\と/の間に水がある
                    if(st.Count() != 0)
                    {
                        int j = st.Pop();
                        sum_area += (i - j);
                        int add_area = i - j;
                        while (pool_st.Count > 0 && j < pool_st.Peek().left)
                        {
                            add_area += pool_st.Pop().area;
                        }
                        pool_st.Push(new Pool() { left = j, area = add_area });
                    }

                }
            }

            Console.WriteLine(sum_area);
            Console.Write($"{pool_st.Count}");
            foreach(var s in pool_st.Reverse())
            {
                Console.Write($" {s.area}");
            }
            Console.WriteLine();
        }
    }

}

using System;
using System.Linq;
using System.Collections;
using System.Collections.Generic;

class WaterInfo
{
    public int area;
    public int startPosition;
    public WaterInfo(int a, int s)
    {
        area = a;
        startPosition = s;
    }
}

class Program
{
    public static void Main(string[] args)
    {
        string s = Console.ReadLine();
        Stack<int> slopeinfo = new Stack<int>();
        Stack<WaterInfo> waterinfo = new Stack<WaterInfo>();
        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] == '\\')
            {
                slopeinfo.Push(i);
            }
            if (s[i] == '/')
            {
                if (slopeinfo.Count == 0) continue;
                int startPosition = slopeinfo.Pop();
                int area = i - startPosition;
                while (waterinfo.Count > 0 && startPosition < waterinfo.Peek().startPosition)
                {
                    WaterInfo wi = waterinfo.Pop();
                    area += wi.area;
                }
                waterinfo.Push(new WaterInfo(area, startPosition));
            }
        }
        int[] areas = waterinfo.Select(x => x.area).Reverse().ToArray();
        if (areas.Length == 0)
        {
            Console.WriteLine("0");
            Console.WriteLine("0");
        }
        else
        {
            Console.WriteLine(areas.Sum());
            Console.Write("{0} ", areas.Length);
            for (int i = 0; i < areas.Length - 1; i++) Console.Write("{0} ", areas[i]);
            Console.WriteLine(areas[areas.Length - 1]);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;


namespace ALDS1_3_D
{
    class Program
    {
        static void Main(string[] args)
        {
            string input = Console.ReadLine();
            char[] map = input.ToCharArray();
            int[] height = SetHeight(map);
            int highest = HighestPos(height);

            bool pool = false;
            int height_s = 0;
            int total = 0;
            List<int> forward = new List<int>();
            List<int> back = new List<int>();

            //0=>highest
            for (int i = 0; i < highest ; i++)
            {
                if (!pool && map[i] == '\\')
                {
                    pool = true;
                    height_s = height[i];
                    total = 0;

                    while (pool)
                    {
                        switch (map[i])
                        {
                            case '\\':
                                total += (height_s - height[i]) * 2 + 1;
                                i++;
                                break;

                            case '_':
                                total += (height_s - height[i]) * 2 ;
                                i++;
                                break;

                            case '/':
                                if (height[i] == height_s - 1)
                                {
                                    pool = false;
                                    total += (height_s - height[i]) * 2 - 1; ;
                                    forward.Add(total / 2);
                                } else
                                {
                                    total += (height_s - height[i]) * 2 - 1;
                                    i++;
                                }
                                break;
                        }
                    }
                }
            }
            // back

            for (int i = height.Length - 1; i > highest; i--)
            {
                if (!pool && map[i - 1] == '/')
                {
                    pool = true;
                    height_s = height[i];
                    total = 0;

                    while (pool)
                    {
                        switch (map[i-1])
                        {
                            case '/':
                                total += (height_s - height[i]) * 2 + 1;
                                i--;
                                break;

                            case '_':
                                total += (height_s - height[i]) * 2;
                                i--;
                                break;

                            case '\\':
                                if (height[i] == height_s - 1)
                                {
                                    pool = false;
                                    total += (height_s - height[i]) * 2 - 1; ;
                                    back.Add(total / 2);
                                }
                                else
                                {
                                    total += (height_s - height[i]) * 2 - 1;
                                    i--;
                                }
                                break;
                        }
                    }
                }
            }

            for (int i = back.Count - 1; i >= 0; i--)
            {
                forward.Add(back[i]);
            }
            int all = 0;
            for (int i = 0; i < forward.Count; i++)
            {
                all += forward[i];
            }
            Console.WriteLine(all);
            Console.WriteLine(ListJoin(forward));

            while (true)
            {
                input = Console.ReadLine();
                if (string.IsNullOrEmpty(input)) break;
            }

        }

        public static int[] SetHeight(char[] map)
        {
            int count = 0;
            int min = 0;
            //calc BaseLine
            for (int i = 0; i < map.Length; i++)
            {
                switch (map[i])
                {
                    case '\\':
                        count--;
                        if (count <= min) min = count;
                        break;

                    case '/':
                        count++;
                        break;
                }
            }
            //set Height
            int[] height = new int[map.Length + 1];
            height[0] = 0 - min;
            for (int i = 0; i < map.Length; i++)
            {
                switch (map[i])
                {
                    case '\\':
                        height[i + 1] = height[i] - 1;
                        break;

                    case '/':
                        height[i + 1] = height[i] + 1;
                        break;

                    case '_':
                        height[i + 1] = height[i];
                        break;
                }
            }
            return height;
        }

        public static int HighestPos(int[] height)
        {
            int highest = height.Max();

            for (int i = 0; i < height.Length; i++)
            {
                if (height[i] == highest)
                {
                    return i;
                }
            }
            return 0;
        }

        public static string ListJoin (List<int> list)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append(list.Count);
            sb.Append(" ");
            for (int i = 0; i < list.Count; i++)
            {
                if (i != 0) sb.Append(" ");
                sb.Append(list[i]);
            }

            return sb.ToString();
        }
    }
}

using System;

class ALDS1_3_D {
    void run() {

        int i, j, narea, ssum;
        string s = Console.ReadLine().Trim();
        int d, dmin, dmax, total, slen = s.Length;
        d = dmin = dmax = 0;
        for (i=0;i<slen;i++) {
            if (s[i]=='\\') d--;
            else if (s[i]=='/')  d++;
            if (dmin>d) dmin=d;
            else if (dmax<d) dmax=d;
        }
        int[] start = new int[dmax-dmin+1];
        for (i=0; i<dmax-dmin+1; i++)  start[i] = -1;
        int[] h = new int[slen];

        total = 0;
        d = -dmin;
        for (i=0; i<slen; i++) {
            if (s[i]=='\\') start[d--]=i;
            else if (s[i]=='/') {
                d++;
                if (start[d]>=0) {
                    for (j=start[d]; j<i; j++)  h[j]++;
                    total += i-start[d];
                }
            }
        }

        Console.WriteLine("{0}", total);
        narea=ssum=0;
        foreach (int k in h) {
            ssum += k;
            if (k==0) {
                if (ssum>0) narea++;
                ssum=0;
            }
        }
        Console.Write("{0}", narea);
        if (narea>0) {
            foreach (int k in h) {
                ssum += k;
                if (k==0) {
                    if (ssum>0) Console.Write(" {0}", ssum);
                    ssum=0;
                }
            }
        }
        Console.WriteLine();
    }

    public static void Main()
    {
        ALDS1_3_D a = new ALDS1_3_D();
        a.run();
    }
}

