namespace ALDS1_3_D
{
    class Program
    {
        interface IStack { }
        class Flat : IStack { }
        class SlopeDown : IStack
        {
        }
        class Pond : IStack
        {
            public int area;
            public int wide;
        }
        static void Main(string[] args)
        {
            var line = Console.ReadLine();
            var stack = new Stack<IStack>();
            foreach (var c in line)
            {
                switch (c)
                {
                    case '\\': stack.Push(new SlopeDown()); break;
                    case '_': stack.Push(new Flat()); break;
                    case '/':
                        bool flag = false;
                        foreach (var item in stack) if (item is SlopeDown) { flag = true; break; }
                        if (flag)
                        {
                            int area = 1, wide = 2;
                            var toPop = new Stack<IStack>();
                            while (stack.Count > 0)
                            {
                                var top = stack.Pop();

                                if (top is SlopeDown)
                                {
                                    stack.Push(new Pond() { area = area, wide = wide });
                                    break;
                                }
                                else if (top is Flat)
                                {
                                    wide++;
                                    area++;
                                }
                                else if (top is Pond)
                                {
                                    area += (top as Pond).area + (top as Pond).wide;
                                    wide += (top as Pond).wide;
                                }
                            }
                        }
                        break;
                }
            }
            var s = new Stack<Pond>();
            int a = 0;
            while (stack.Count > 0)
            {
                var top = stack.Pop();
                if (top is Pond)
                {
                    s.Push(top as Pond);
                    a += (top as Pond).area;
                }
            }
            Console.WriteLine(a);
            Console.Write(s.Count);
            foreach (var p in s)
            {
                Console.Write(" " + p.area);
            }
            Console.WriteLine();
        }
    }
