							int height;
							int sum;

							sum = height = 0;
							for( int k=i; k<=j; k++ ) {
								c = region[k];
								if( '\\' == c ) {
									height--;
									sum += height;
								} else if( '/' == c ) {
									height++;
									sum += height;
									if( 0 == height ) {
										area.Add( sum*(-1) );
									}
								} else if( '_' == c ) {
									sum += height;
								}
							}

							i = j;
							break;
						}
					}
				}
			}

		}


		Console.WriteLine( area.Sum() );
		Console.Write( "{0}", area.Count );
		if( area.Count > 0 ) {
			Console.WriteLine( " {0}", String.Join( " ", area.ToArray() ) );
		} else {
			Console.WriteLine();
		}
		return;
	}
}

