using System;
using System.Linq;
using System.Collections.Generic;

namespace myApp
{
    class Program
    {
        public class Pair<T, U> {
            public Pair() {
            }

            public Pair(T first, U second) {
                this.First = first;
                this.Second = second;
            }

            public T First { get; set; }
            public U Second { get; set; }
        };
        static void Main(string[] args)
        {
            // 総面積
            var area = 0;

            // ＼ならば、その位置を表すiをスタックに積む
            // /ならば、対応する＼の位置を取り出し距離を総面積に加算する
            Stack<int>  S1 = new Stack<int>();

            // 水たまりの左の＼の位置と、面積のペアを積む
            // leftとiで挟まれる水たまりは取り出し、面積を合計してまた積む
            Stack<Pair<int, int>> S2 = new Stack<Pair<int, int>>();
            var line = Console.ReadLine().ToCharArray();
            for (int i = 0; i < line.Length; i++) {
                if (line[i] == '\\') {
                    S1.Push(i);
                } else if (line[i] == '/' && S1.Count > 0) {
                    int left = S1.Pop();
                    area += i - left;

                    int a = i - left;
                    while (S2.Count > 0 && S2.Peek().First > left) {
                        // leftより大きい、つまり内側
                        a += S2.Pop().Second;
                    }
                    S2.Push(new Pair<int, int>(left, a));
                }
            }

            // 総面積を出力する
            Console.WriteLine(area);

            // 水たまりの数とそれぞれの面積
            var ans = new List<int>();
            while (S2.Count > 0) {
                ans.Add(S2.Pop().Second);
            }
            ans.Reverse();
            Console.Write(ans.Count);
            for (int i = 0; i < ans.Count; i++) {
                Console.Write(" " + ans[i]);
            }
            Console.WriteLine();
        }
    }
}

