    class Program
    {
        static void Main(string[] args)
        {
            var line = Console.ReadLine();
            var lakes = new List<double>();
            var moutains = Mountain.Parse(line);
            var all = 0.0;

            for (int i = 0; i < moutains.Count; i++)
            {
                var height = moutains[i].Height;
                var isFirst = false;

                var right = moutains
                    .Skip(i)
                    .TakeWhile((m, index) =>
                    {
                        var result = m.Height <= height && !isFirst;
                        isFirst |= (m.Height == height && index != 0);
                        return result;
                    })
                    .ToArray();


                if (2 <= right.Length && right[right.Length - 1].Height == height && right[0].Water == null)
                {
                    var sum = 0.0;
                    for (int j = 0; j < right.Length - 1; j++)
                    {
                        right[j].Water = height;
                        sum += right[j].Area();
                    }

                    if (sum != 0.0)
                    {
                        lakes.Add(sum);
                        all += sum;
                    }

                    i += (right.Length - 2);
                }
            }

            System.Console.WriteLine(all);

            if (lakes.Count != 0)
            {
                System.Console.WriteLine(lakes.Count + " " + string.Join(" ", lakes.Select(x => x.ToString()).ToArray()));
            }
            else
            {
                System.Console.WriteLine(0);
            }
        }
    }

    class Mountain
    {
        public int? Right { get; set; }
        public int Height { get; set; }
        public int? Left { get; set; }
        public int Index { get; set; }
        public int? Water { get; set; }
        public double Area()
        {
            if (Water == null || Right == null)
            {
                return 0.0;
            }
            else
            {
                return Math.Abs((Math.Abs(Height - Water.Value) + Math.Abs(Right.Value - Water.Value)) / 2.0);
            }
        }
        public static IList<Mountain> Parse(string line)
        {
            var moutains = new List<Mountain>();
            var height = 0;
            var left = (int?)null;
            for (int i = 0; i < line.Length; i++)
            {
                var next = height;
                if (line[i] == '\\')
                {
                    next--;
                }
                else if (line[i] == '/')
                {
                    next++;
                }
                else
                {

                }

                moutains.Add(new Mountain()
                {
                    Left = left,
                    Height = height,
                    Right = next,
                    Index = i,
                });

                left = height;
                height = next;
            }

            moutains.Add(new Mountain()
            {
                Left = left,
                Height = height,
                Index = line.Length
            });

            return moutains;
        }
    }

