            for (var i = 0; i < input.Length; i++)
            {
                if (input[i] == '\\')
                {
                    pos.Push(i);
                }else if (input[i] == '/' && pos.Count > 0)
                {
                    var j = pos.Pop();    // 直前の\の場所
                    sum += i - j;
                    var a = i - j;
                    puddleCount++;
                    while (puddle.Count > 0 && puddle.Peek().First > j)
                    {
                        // 水たまりの統合
                        a += puddle.Pop().Second;
                        puddleCount--;
                    }
                    puddle.Push(new Pair<int, int>(j, a));
                }
            }
            WriteLine(sum);
            var result = new List<int>();

            var n = puddle.Count;
            for (var i = 0; i < n; i++)
            {
                result.Add(puddle.Pop().Second);
            }

            Write(puddleCount);
            result.Reverse();
            foreach (var i in result)
            {
               Write(" " + i); 
            }
            WriteLine();
        }
    }

