                {
                    case '\\':
                        height--;
                        break;
                    case '/':
                        height++;
                        break;
                }
                if (height > top) top = height;
                if (height < bottom) bottom = height;
            }

            // \ = 1
            // / = 2
            var csd = new byte[top - bottom, token.Length];

            height = top-1;
            var inc = 0;
            for (int i = 0; i < token.Length; i++)
            {
                switch (token[i])
                {
                    case '\\':
                        if (inc == -1 || inc==0) height++;
