using System.Collections.Generic;

class Program{
    class Area{
        public int area;
        public int height;
    }

    public static void Main(){
        var s=Console.ReadLine();

        var stack=new Stack();
        var areas=new Area[s.Length];
        var height=0;
        for(var i=0; i<s.Length; i++){
            var c=s[i];
            var area=0;
            switch(c){
                case '\\':{
                    stack.Push(i);
                    height--;
                    break;
                }
                case '/':{
                    if(stack.Count!=0){
                        var j=(int)stack.Pop();
                        var u=i-j+1;
                        var d=u-2;
                        area=(u+d)*1/2;
                    }
                    height++;
                    break;
                }
                default:{ // '_'
                    break;
                }
            }
            var a=new Area();
            a.area=area;
            a.height=height;
            areas[i]=a;
        }

        stack.Clear();
        var tmp=new Area();
        tmp.area=0;
        tmp.height=0;
        stack.Push(tmp);
        foreach(var area in areas){
            if(area.area==0){
                stack.Push(area);
            } else{
                var top=(Area)stack.Pop();
                while(top.height+1==area.height){
                    area.area+=top.area;
                    top=(Area)stack.Pop();
                }
                stack.Push(top);
                stack.Push(area);
            }
        }
        var result=new Stack();
        var sumArea=0;
        while(stack.Count!=0){
            var area=((Area)stack.Pop()).area;
            if(area!=0){
                result.Push(area);
                sumArea+=area;
            }
        }

        Console.WriteLine(sumArea);
        Console.Write(result.Count);
        while(result.Count!=0){
            var area=(int)result.Pop();
            Console.Write(" "+area);
        }
        Console.WriteLine();
    }
}

