using System;
using System.Collections.Generic;

class Areas_on_the_Cross_Section_Diagram {

    public struct Water {
        public int position;
        public int area;

        public Water(int p, int a) {
            position = p;
            area = a;
        }
    }

    public static void Main() {

        int num, sum;
        num = sum = 0;

        string str = Console.ReadLine();

        var box = new Stack<int>();
        var water = new Stack<Water>();

        for(int i = 0; i < str.Length; i++) {
            if(str[i] == '\\') box.Push(i);
            else if(str[i] == '/' && box.Count > 0) {
                int cmp = box.Pop();
                num = i - cmp;
                sum += num;

                while(water.Count > 0 && water.Peek().position > cmp) {
                    num += water.Peek().area;
                    water.Pop();
                }

                water.Push(new Water(cmp, num));
            }
        }

        int n = water.Count;

        Console.WriteLine(sum);
        Console.Write(n);

        for(int i = 0; i < n; i++) {
            Console.Write(" " + water.Pop().area);
        }

        Console.WriteLine();

    }
}

