    class Mountain
    {
        public int? Right { get; set; }
        public int Height { get; set; }
        public int? Left { get; set; }
        public int Index { get; set; }
        public int? Water { get; set; }
        public double Area()
        {
            if (Water == null || Right == null)
            {
                return 0.0;
            }
            else
            {
                return Math.Abs((Math.Abs(Height - Water.Value) + Math.Abs(Right.Value - Water.Value)) / 2.0);
            }
        }
        public static IList<Mountain> Parse(string line)
        {
            var moutains = new List<Mountain>();
            var height = 0;
            var left = (int?)null;
            for (int i = 0; i < line.Length; i++)
            {
                var next = height;
                if (line[i] == '\\')
                {
                    next--;
                }
                else if (line[i] == '/')
                {
                    next++;
                }
                else
                {

                }

                moutains.Add(new Mountain()
                {
                    Left = left,
                    Height = height,
                    Right = next,
                    Index = i,
                });

                left = height;
                height = next;
            }

            moutains.Add(new Mountain()
            {
                Left = left,
                Height = height,
                Index = line.Length
            });

            return moutains;
        }
    }

