class Program
{
    static string str;
    static int gnd=0, sum = 0;
    static void Main()
    {
         str = Console.ReadLine();
        int a = str.Length; int  cnt = 0, k = 0;
        int[] ind = new int[10];
        for (int i = 0; i < a; i++)
        {
            if (str[i] == '\\')
            {
                gnd = 0;
                for (int j = i; j < a; j++)
                {
                    if (str[j] == '\\')
                    { gnd++; }
                    else if (str[j] == '/')
                    {
                        gnd--;
                        if (gnd == 0)
                        {
                            cnt++;
                            ind[k] = measure(i, j);
                            k++;
                            i = j;
                            break;
                        }
                    }
                }
            }
        }
        Console.WriteLine(sum);
        Console.Write(cnt);
        for (int i = 0; i < cnt; i++)
        {
            Console.Write(" " + ind[i]);
        }
        Console.WriteLine();
    }

    private static int measure(int i, int j)
    {
        int tmp = 0; gnd = 0;
        for (; i <= j; i++)
        {
            if (str[i] == '\\')
            {
                tmp += gnd * 2 ;
                gnd++;
            }
            else if (str[i] == '/')
            {
                tmp += gnd * 2;
                gnd--;
            }
            else if(str[i] == '_')
            {                tmp += gnd * 2 ;            }
        }
        tmp /= 2;
        sum += tmp;
        return tmp;
    }

}

