    class ALDS1_3D
    {
        static void Main(string[] args)
        {
            for (;;)
            {
                string line = Console.ReadLine();
                if (string.IsNullOrEmpty(line))
                {
                    break;
                }

                int[] levels = new int[line.Length + 1];
                for (int i = 1; i < levels.Length; i++)
                {
                    switch (line[i - 1])
                    {
                        case '\\':
                            levels[i] = levels[i - 1] - 1;
                            break;
                        case '_':
                            levels[i] = levels[i - 1];
                            break;
                        case '/':
                            levels[i] = levels[i - 1] + 1;
                            break;
                    }
                }

                List<int> lakes = new List<int>();
                for (int i = 0; i < levels.Length - 1; i++)
                {
                    if (levels[i] > levels[i + 1])
                    {
                        bool isLake = false;
                        int j = i + 1;
                        for (; j < levels.Length; j++)
                        {
                            if (levels[j] == levels[i])
                            {
                                isLake = true;
                                break;
                            }
                        }

                        if (isLake)
                        {
                            int d = 0;
                            int s = 0;
                            for (int k = i; k < j; k++)
                            {
                                switch (levels[k + 1] - levels[k])
                                {
                                    case -1:
                                        d++;
                                        break;
                                    case 1:
                                        d--;
                                        break;
                                }
                                s += d;
                            }
                            lakes.Add(s);
                            i = j - 1;
                        }
                    }
                }

                int total = lakes.Sum();
                Console.WriteLine(total);
                Console.Write(lakes.Count);
                for (int i = 0; i < lakes.Count; i++)
                {
                    Console.Write(string.Format(" {0}", lakes[i]));
                }
                Console.WriteLine();
            }
        }
    }
