namespace Elementary_data_structures
{
    class Areas_on_the_Cross_Section_Diagram
    {
        static void Main(string[] args)
        {
            var token = Console.ReadLine();

            // \ = 1
            // / = 2
            // _ = 3
            var csd = new byte[token.Length];
            var depth = new short[token.Length];
            short d = 0;
            var inc = 0;
            for (int i = 0; i < token.Length; i++)
            {
                switch (token[i])
                {
                    case '\\':
                        if (inc == -1 || inc == 0) d++;
                        inc = -1;
                        csd[i] = 1;
                        break;
                    case '/':
                        if (inc == 1) d--;
                        csd[i] = 2;
                        inc = 1;
                        break;
                    case '_':
                        if (inc == 1) d--;
                        inc = 0;
                        csd[i] = 3;
                        break;
                }
                depth[i] = d;
            }

            // \ + water = 4
            // water + / = 5
            while(true)
            {
                var left = -1;
                var done = false;
                for (int j = 0; j < token.Length; j++)
                {
                    if (left==-1 && csd[j] == 1)
                    {
                        left = j;
                        d = depth[j];
                    }
                    else if (d == depth[j] && csd[j] == 2 && left != -1)
                    {
                        csd[left] = 4;
                        csd[j] = 5;
                        left = -1;
                        done = true;
                    }
                }
                if (!done) break;
                else if (left != -1) csd[left] = 0;
            }

            var areas = new List<int>();
            var area = 0;

            var pool = false;
            for (int j = 0; j < token.Length; j++)
            {
                if (pool && csd[j] == 5 && d == depth[j])
                {
                    pool = false;
                    area++;
                    d = 0;
                    area /= 2;
                    areas.Add(area);
                    area = 0;
                    continue;
                }
                if (!pool && csd[j] == 4)
                {
                    pool = true;
                    d = depth[j];
                }
                if (pool)
                    switch (csd[j])
                    {
                        case 3:
                            area += (depth[j] - d + 1) * 2;
                            break;
                        case 4:
                        case 5:
                            area += (depth[j] - d) * 2 + 1;
                            break;
                    }
            }

            var c = areas.Count;

            var sum = 0;
            for (int i = 0; i < c; i++)
                sum += areas[i];

            Console.WriteLine(sum);

            if (c == 0) Console.WriteLine(0);
            else
            {
                Console.Write(c + " ");
                for (int i = 0; i < c - 1; i++)
                    Console.Write(areas[i] + " ");
