		{
			string s = Console.ReadLine();
			int[] h = new int[s.Length + 1];
			h[0] = 0;
			for (int i = 0; i < s.Length; i++)
			{
				switch (s[i])
				{
					case '/':
						h[i + 1] = h[i] + 1;
						break;
					case '_':
						h[i + 1] = h[i];
						break;
					case '\\':
						h[i + 1] = h[i] - 1;
						break;
				}
			}
			int now = 0;
			List<Lake> lakes = new List<Lake>();
			while (now < h.Length - 1)
			{
				if (h[now] <= h[now + 1])
					now += 1;
				else
				{
					bool b = false;
					for (int i = now + 1; i < h.Length; i++)
					{
						if (h[now] == h[i])
						{
							Lake lake = new Lake();
							lake.left = now;
							lake.right = i;
							lakes.Add(lake);
							now = i;
							b = true;
							break;
						}
					}
					if (b == false)
						now += 1;
				}
			}
			foreach (Lake x in lakes)
			{
				for (int i = x.left; i < x.right; i++)
				{
					if (h[i] < h[i + 1])
						x.area += h[x.left] - h[i] - 0.5;
					else if (h[i] == h[i + 1])
						x.area += h[x.left] - h[i];
					else
						x.area += h[x.left] - h[i] + 0.5;
				}
			}
			int SumLakeArea = 0;
			foreach (Lake x in lakes)
			{
				SumLakeArea += (int)x.area;
			}
			Console.WriteLine(SumLakeArea);
			Console.Write(lakes.Count);
			if (lakes.Count != 0)
				Console.Write(" ");
			for (int i = 0; i < lakes.Count; i++)
			{
				Console.Write(lakes[i].area);
				Console.Write(i != lakes.Count - 1 ? " " : "\n");
			}
		}
	}
