using System.IO;
using System.Linq;

class Program
{
    class Area
    {
        public int pos;
        public int area;
    }
    static void Main(string[] args)
    {
        byte[] inputBuffer = new byte[2048];
        Stream inputStream = Console.OpenStandardInput(inputBuffer.Length);
        Console.SetIn(new StreamReader(inputStream, Console.InputEncoding, false, inputBuffer.Length));

        var str = System.Console.ReadLine();

        var leftPositions = new Stack<int>();
        var areas = new Stack<Area>();

        for (var i = 0; i < str.Length; i++)
        {
            var c = str[i];

            if (c == '_')
                continue;

            if (c == '\\')
            {
                areas.Push(new Area { pos = i, area = 0 });

                leftPositions.Push(i);
            }

            if (c == '/')
            {
                if (leftPositions.Count > 0)
                {
                    var leftPos = leftPositions.Pop();
                    while (areas.Peek().pos > leftPos)
                    {
                        var tmp = areas.Pop();
                        areas.Peek().area += tmp.area;
                    }
                    areas.Peek().area += i - leftPos;
                }
            }
        }

        var res = areas.Where(x => x.area != 0).Reverse();
        var sum = 0;
