using System;
using System.Collections.Generic;

class Program
{
	static void Main(string[] args)
	{
		string input = Console.ReadLine();

		int count = 0;
		LinkedList<int> list = new LinkedList<int>();

		int now_height = 0;
		int max_height = 0;


		for(int i=0; i<input.Length; i++)
		{
			string str = input.Substring(i, 1);
			switch(str)
			{
				case "\\":
				{
					now_height --;
					if((now_height > max_height) && list.Count > 0 )
					{
						break;
					}
					int height = now_height;
					int add = 1;
					int s = 1;

					int j;
					for(j=i+1; j<input.Length; j++)
					{
						switch(input.Substring(j, 1))
						{
							case "\\":
								add ++;
								height --;
								break;

							case "/":
								add --;
								height ++;
								if(max_height < height)
								{
									max_height = height;
								}
								break;

							case "_":
								break;
						}
						s += add;

						if(height == now_height + 1)
						{
							i = j;
							count ++;
							list.AddLast(s);
							break;
						}
						else if(height > now_height + 1)
						{
							break;
						}
					}
					break;
				}

				case "/":
					now_height ++;
					break;

				case "_":
					break;
			}

		}

		int area_sum = 0;
		foreach(int area in list)
		{
			area_sum += area;
		}
		Console.WriteLine(area_sum);

		Console.Write(count);
		foreach(int area in list)
		{
			Console.Write(" " + area);
		}
		Console.WriteLine();
	}
}

