using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class Program
{
    class Area
    {
        public int pos;
        public int area;
    }
    static void Main(string[] args)
    {
        var str = System.Console.ReadLine();

        var leftPositions = new Stack<int>();
        var areas = new Stack<Area>();

        for (var i = 0; i < str.Length; i++)
        {
            var c = str[i];

            if (c == '_')
                continue;

            if (c == '\\')
            {
                areas.Push(new Area { pos = i, area = 0 });

                leftPositions.Push(i);
            }

            if (c == '/')
            {
                if (leftPositions.Count > 0)
                {
                    var leftPos = leftPositions.Pop();
                    while (areas.Peek().pos > leftPos)
                    {
                        var tmp = areas.Pop();
                        areas.Peek().area += tmp.area;
                    }
                    areas.Peek().area += i - leftPos;
                }
            }
        }

        var res = areas.Where(x => x.area != 0).Reverse();
        var sum = 0;
        res.ToList().ForEach(x => sum += x.area);
        Console.WriteLine(sum);

        Console.Write(res.Count() + " ");
        res.ToList().ForEach(x => Console.Write(x.area + " "));
        Console.WriteLine();
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace ALDS1_3_D
{
    class Program
    {
        static int Main(string[] args)
        {
            var line = Console.ReadLine().Trim();
            //var line = @"\/\\\_/\\//__\/_/\/\__/";

            var stack = new Stack<int>();
            var list = new List<PoolArea>();
            var pool = new List<int>();

            for (int i = 0; i < line.Length; i++)
            {
                switch (line[i])
                {
                    case '\\':
                        stack.Push(i);
                        break;
                    case '/':
                        if (stack.Count > 0)
                        {
                            list.Add(new PoolArea(stack.Pop(), i));
                        }
                        break;
                    default:
                        break;
                }
            }

            Console.WriteLine(list.Select(x => x.AreaSize).Sum());

            if (list.Count == 0)
            {
                Console.WriteLine("0");
                return 0;
            }

            int index = list.Count - 1;
            do
            {
                var poolStart = list[index].Start;
                var poolSize = list[index].AreaSize;
                var nextIndex = -1;
                for (int i = index - 1; i >= 0; i--)
                {
                    if (list[i].Start > poolStart)
                    {
                        poolSize += list[i].AreaSize;
                    }
                    else
                    {
                        nextIndex = i;
                        break;
                    }
                }
                pool.Insert(0,poolSize);
                index = nextIndex;

            } while (index >= 0);

            Console.WriteLine(pool.Count + " " + String.Join(" ", pool.ToArray()));

            return 0;
        }

        class PoolArea
        {
            public PoolArea(int start, int end)
            {
                Start = start;
                End = end;
                AreaSize = End - Start;
            }

            public int AreaSize { get; }
            public int Start { get; }
            public int End { get; }
        }
    }
}

