        int up = 0;
        bool f;

        while (i < sz)
        {
            j = i;
            f = false;

            // 下りカウント
            while (j < sz)
            {
                if (s[j] == '\\')
                {
                    down++;
                    j++;
                }
                else
                    break;
            }

            // 高さが同じになるまでカウント
            while (j < sz)
            {
                     if (s[j] == '/')  up++;
                else if (s[j] == '\\') up--;
                // 平面は何もしない

                if (down == up)
                {
                    // 計算
                    l.Add(Calc(s, i, j));

                    i = j;
                    f = true;
                    break;
                }

                j++;
            }

            if (f) break;

            up = 0;
            down = 0;
            i++;
        }
    }

    static int Calc(string s, int st, int ed)
    {
        int tmp = st;
        int h = 0;
        double m = 0;

        while (st <= ed)
        {
            if (s[st] == '\\')
            {
                if (tmp != st && s[st-1] == '\\')
                    h++;
            }
            else if (s[st] == '/')
            {
                if (s[st-1] != '\\')
                    h--;
            }
            else if (s[st] == '_')
            {
                if (s[st-1] == '\\')
                    h++;
            }

            if (s[st] == '\\' || s[st] == '/')
                m += (0.5 + h);
            else
                m += h;

            st++;
        }

        return (int)m;
    }
}

