namespace Test
{
    class MainClass
    {
        public static void Main(string[] args)
        {
            var str = Console.ReadLine();
            var areas=new List<int>();

            for (int i = 0; i < str.Length; i++)
            {
                if (str[i] == '\\')
                {
                    var num = 0;
                    for (int j = i+1; j < str.Length; j++)
                    {
                        if (str[j] == '\\')
                        {
                            num++;
                        }
                        else if (str[j] == '/')
                        {
                            if (num == 0)
                            {
                                //水たまりができた
                                areas.Add(CalculatePoolArea(str.Substring(i,j-i+1)));
                                i = j;
                                break;
                            }
                            else
                            {
                                num--;
                            }
                        }
                    }
                }
            }

            Console.WriteLine(areas.Sum());
            Console.Write("{0} ", areas.Count);
            if (areas.Count != 0)
            {
                Console.WriteLine(string.Join(" ", Array.ConvertAll(areas.ToArray(), x => x.ToString())));
            }

            Console.Read();
        }

        private static int CalculatePoolArea(string p)
        {
            var depth = 0;
            var result = 0.0;
            foreach (var item in p)
            {
                if (item == '\\')
                {
                    result = result+ 0.5 + depth;
                    depth++;
                }
                else if (item == '/')
                {
                    depth--;
                    result = result + 0.5 + depth;
                }
                else
                {
                    result = result + depth;
                }
            }
            return (int)result;
        }
    }
