class Program
{
    private static int i = 0;
    private static List<int> l = null;

    static void Main()
    {
        string s = Console.ReadLine();
        int sz = s.Length;

        l = new List<int>();

        while(i < sz)
        {
            if (s[i] == '_' || s[i] == '/') 
            {
                // 平面、上りは次の文字列へ
                i++;
                continue;
            }
            else if (s[i] == '\\')
            {
                Pool(s, sz);
            }
        }

        int sum = 0;
        foreach (int n in l) sum += n;

        Console.WriteLine(sum);
        Console.WriteLine(string.Format("{0} {1}", l.Count, string.Join(" ", l)));
    }

    static void Pool(string s, int sz)
    {        
        int j = 0;

        int down = 0;
        int up = 0;
        bool f;

        while (i < sz)
        {
            j = i;
            f = false;

            // 下りカウント
            while (j < sz)
            {
                if (s[j] == '\\')
                {
                    down++;
                    j++;
                }
                else
                    break;
            }

            // 高さが同じになるまでカウント
            while (j < sz)
            {
                     if (s[j] == '/')  up++;
                else if (s[j] == '\\') up--;
                // 平面は何もしない

                if (down == up)
                {
                    // 計算
                    l.Add(Calc(s, i, j));

                    i = j;
                    up = 0;
                    down = 0;
                    f = true;
                    break;
                }

                j++;
            }

            if (f) break;

            i++;
        }
    }

    static int Calc(string s, int st, int ed)
    {
        int tmp = st;
        int h = 0;
        double m = 0;

        while (st <= ed)
        {
            if (s[st] == '\\')
            {
                if (tmp != st && s[st-1] == '\\')
                    h++;
            }
            else if (s[st] == '/')
            {
                if (s[st-1] != '\\')
                    h--;
            }
            else if (s[st] == '_')
            {
                if (s[st-1] == '\\')
                    h++;
            }

            if (s[st] == '\\' || s[st] == '/')
                m += (0.5 + h);
            else
                m += h;

            st++;
        }

        return (int)m;
    }
}

