public class Stack {
  private int[] stack = new int[1000000];
  private int pos = 0;

  public void Push(int x) {
    stack[pos++] = x;
  }

  public int Pop() {
    return stack[--pos];
  }

  public int Top() {
    return stack[pos-1];
  }

  public int Count {
    get {
      return pos;
    }
  }

  public void Print(string sep = " ") {
    if (Count <= 0) return;
    for (int i = pos-1; i > 0; i--) {
      Console.Write(stack[i] + sep);
    }
    Console.WriteLine(stack[0]);
  }

  public void PrintReverse(string sep = " ") {
    if (Count <= 0) return;
    for (int i = 0; i < pos-1; i++) {
      Console.Write(stack[i] + sep);
    }
    Console.WriteLine(stack[pos-1]);
  }
}

