class Program
{
	static void Main(string[] args)
	{
		string input = Console.ReadLine();

		int count = 0;
		LinkedList<int> list = new LinkedList<int>();


		for(int i=0; i<input.Length; i++)
		{
			string str = input.Substring(i, 1);
			switch(str)
			{
				case "\\":
				{
					int height = -1;
					int add = 1;
					int s = 1;

					int j;
					for(j=i+1; j<input.Length; j++)
					{
						switch(input.Substring(j, 1))
						{
							case "\\":
								add ++;
								height --;
								break;

							case "/":
								add --;
								height ++;
								break;

							case "_":
								break;
						}
						s += add;

						if(height == 0)
						{
							i = j;
							count ++;
							list.AddLast(s);
							break;
