using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
class Area
{
    public int pos;
    public int area;
}
class Program
{
    static void Main(string[] args){
    byte[] inputBuffer = new byte[2048];
    Stream inputStream = Console.OpenStandardInput(inputBuffer.Length);
    Console.SetIn(new StreamReader(inputStream, Console.InputEncoding, false, inputBuffer.Length));

    var str = System.Console.ReadLine();

    var leftPositions = new Stack<int>();
    var areas = new Stack<Area>();

    for (var i = 0; i < str.Length; i++)
    {
        var c = str[i];

        if (c == '_')
            continue;

        if (c == '\\')
        {
            areas.Push(new Area { pos = i, area = 0 });

            leftPositions.Push(i);
        }

        if (c == '/')
        {
            if (leftPositions.Count > 0)
            {
                var leftPos = leftPositions.Pop();
                while (areas.Peek().pos > leftPos)
                {
                    var tmp = areas.Pop();
                    areas.Peek().area += tmp.area;
                }
                areas.Peek().area += i - leftPos;
            }
        }
    }

    var res = areas.Where(x => x.area != 0).Reverse();
    var sum = 0;
    res.ToList().ForEach(x => sum += x.area);
    Console.WriteLine(sum);

    Console.Write(res.Count() + " ");
    res.ToList().ForEach(x => Console.Write(x.area + " "));
    Console.WriteLine();
}
}

using System;
using System.Collections.Generic;
using System.Text;

class Program
{
    public void Proc()
    {
        string inpt = Console.ReadLine();
        //string inpt = @"\\///\_/\/\\\\/_/\\///_\\\\\/_/\";
        Stack<int> s1 = new Stack<int>();
        Stack<KeyValuePair<int, int>> s2 = new Stack<KeyValuePair<int, int>>();


        long totalMenseki = 0;
        for(int i=0; i<inpt.Length; i++)
        {
            if(inpt[i] == '\\')
            {
                s1.Push(i);
            } else if(inpt[i] == '/' && s1.Count > 0)
            {
                int from = s1.Pop();
                int menseki = i - from;
                totalMenseki += menseki;
                while (s2.Count > 0)
                {
                    KeyValuePair<int, int> tmp = s2.Peek();
                    if(tmp.Key >= from)
                    {
                        menseki += tmp.Value;
                        s2.Pop();
                    } else
                    {
                        break;
                    }
                }
                s2.Push(new KeyValuePair<int, int>(i, menseki));
            }
        }
        Console.WriteLine(totalMenseki);
        StringBuilder ans = new StringBuilder();
        ans.Append(s2.Count);
        int[] ikeList = new int[s2.Count];
        for(int i=0; i<ikeList.Length; i++)
        {
            KeyValuePair<int, int> tmp = s2.Pop();
            ikeList[ikeList.Length - 1 - i] = tmp.Value;
        }
        foreach(int menseki in ikeList)
        {
            ans.Append(" ");
            ans.Append(menseki);
        }
        Console.WriteLine(ans.ToString());
    }

    static void Main(string[] args)

    {

        Program prg = new Program();
        prg.Proc();

    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace Elementary_data_structures
{
    class Areas_on_the_Cross_Section_Diagram
    {
        static void Main(string[] args)
        {
            var token = Console.ReadLine();

            var bottom = 0;
            var top = 0;
            var height = 0;
            for (int i = 0; i < token.Length; i++)
            {
                switch (token[i])
                {
                    case '\\':
                        height--;
                        break;
                    case '/':
                        height++;
                        break;
                }
                if (height > top) top = height;
                if (height < bottom) bottom = height;
            }

            // \ = 1
            // / = 2
            var csd = new int[top - bottom, token.Length];

            height = top - 1;
            var inc = 0;
            for (int i = 0; i < token.Length; i++)
            {
                switch (token[i])
                {
                    case '\\':
                        if (i > 0 && inc == -1) height++;
                        else if (i == 0) height++;
                        inc = -1;
                        csd[height, i] = 1;
                        break;
                    case '/':
                        if (i > 0 && inc == 1) height--;
                        csd[height, i] = 2;
                        inc = 1;
                        break;
                }
            }

            // water = 3
            // \ + water = 4
            // water + / = 5
            for (int i = 0; i < csd.GetLength(0); i++)
            {
                var left = -1;
                for (int j = 0; j < csd.GetLength(1); j++)
                {
                    if (csd[i, j] == 1)
                        left = j;
                    else if (csd[i, j] == 2 && left != -1)
                    {
                        csd[i, left] = 4;
                        csd[i, j] = 5;

                        for (int k = left + 1; k < j; k++)
                            csd[i, k] = 3;
                        left = -1;
                    }
                }
            }

            var areas = new List<int>();
            var area = 0;

            var pool = false;
            height = 0;
            for (int j = 0; j < csd.GetLength(1); j++)
            {
                if (pool && csd[height, j] == 5)
                {
                    pool = false;
                    area++;
                    height = 0;
                    area /= 2;
                    areas.Add(area);
                    area = 0;
                    continue;
                }

                for (int i = 0; i < csd.GetLength(0); i++)
                {
                    if (!pool && csd[i, j] == 4)
                    {
                        pool = true;
                        height = i;
                    }
                    if (pool)
                        switch (csd[i, j])
                        {
                            case 3:
                                area += 2;
                                break;
                            case 4:
                            case 5:
                                area++;
                                break;
                        }
                }
            }

            Console.WriteLine(areas.Sum());

            var c = areas.Count;

            if (c == 0) Console.WriteLine(0);
            else
            {
                Console.Write(c + " ");
                for (int i = 0; i < c - 1; i++)
                {
                    Console.Write(areas[i] + " ");
                }
                Console.WriteLine(areas[c - 1]);
            }
        }
    }
}

