using System;
using System.Collections.Generic;


class Program
{
    static void Main(string[] args)
    {
        Input CInput = new Input();

        List<Downdata> DownDB = new List<Downdata>();
        List<int> WaterSizeDB = new List<int>();

        var input = CInput.Line1_string();

        int cnt = 0, Data_W = 0, Data_H = 0;

        while (true)
        {
            if (cnt == input.Length) break;

            if (input[cnt].ToString() == "\\")
            {
                DownDB.Add(new Downdata(Data_W, Data_H));
                Data_H--;
            }
            else if (input[cnt].ToString() == "/")
            {
                for (int i = 0; i < DownDB.Count; i++)
                {
                    DownDB[i].WaterJudge(Data_W + 1, Data_H + 1); // +1????????????????????§?¨???¨??????
                }
                Data_H++;
            }
            Data_W++; cnt++;
        }

        int sum = 0, j, sample = 0;
        bool is_end = false;
        int CheckCompleteCount = 0;

        while (!is_end)
        {
            while (DownDB[CheckCompleteCount].InvalidCheck())
            {
                if (CheckCompleteCount + 1 == DownDB.Count) { is_end = true; break; }
                CheckCompleteCount++;
            }
            if (CheckCompleteCount + 1 == DownDB.Count) { WaterSizeDB.Add(DownDB[CheckCompleteCount].WaterSize()); break; }
            sum = DownDB[CheckCompleteCount].WaterSize();
            sample = CheckCompleteCount;
            j = CheckCompleteCount + 1;

            while (true)
            {
                if (j == DownDB.Count)
                {
                    WaterSizeDB.Add(sum);
                    is_end = true;
                    break;
                }
                if (DownDB[j].InvalidCheck())
                {
                    WaterSizeDB.Add(sum);
                    CheckCompleteCount++;
                    break;
                }

                if (DownDB[j].InsideW(DownDB[sample].GetW(), DownDB[sample].GetRightW()) == true)
                {
                    sum += DownDB[j].WaterSize();
                    CheckCompleteCount++;
                }
                else
                {
                    WaterSizeDB.Add(sum);
                    CheckCompleteCount++;
                    break;
                }
                j++;
            }
        }


        int total = 0;
        foreach (var value in WaterSizeDB)
        {
            total += value;
        }
        System.Console.WriteLine(total);
        System.Console.Write("{0}", WaterSizeDB.Count);
        for (int i = 0; i < WaterSizeDB.Count; i++)
        {
            System.Console.Write(" {0}", WaterSizeDB[i]);
        }
        System.Console.WriteLine();

    }
}

class Downdata
{
    private int m_W;  // ?¨??????§?¨?
    private int m_H;  // ??±???
    private int m_RightW;    // ?????????????????§?¨?

    public Downdata(int W, int H)
    {
        m_W = W;
        m_H = H;
        m_RightW = -1;
    }

    public int GetW()
    {
        return m_W;
    }
    public int GetRightW()
    {
        return m_RightW;
    }

    public bool WaterJudge(int W, int H)
    {
        if (m_RightW != -1) return true;
        if (m_H != H) return false;
        m_RightW = W;
        return true;
    }

    public int WaterSize()
    {
        return m_RightW - m_W - 1;
    }

    public bool InsideW(int W, int RightW)
    {
        if (W < m_W && RightW > m_RightW) return true;
        return false;
    }

    // ??????????????????water?????????????????????????????? true??§??????
    public bool InvalidCheck()
    {
        if (m_RightW == -1) return true;
        else return false;
    }
}







