using System;
using System.Collections.Generic;
using System.Text;

namespace ALDS1_3_D {
    class Program {
        static void Main(string[] args) {
            Dictionary<int, Stack<int>> dic = new Dictionary<int, Stack<int>>();
            Stack<KeyValuePair<int, int>> stk = new Stack<KeyValuePair<int, int>>();

            string input = Console.ReadLine();
            int h = 0;
            for (int i = 0; i < input.Length; i++) {
                if (input[i] == '\\') {
                    if (!dic.ContainsKey(h))
                        dic[h] = new Stack<int>();
                    dic[h].Push(i);
                    h--;
                }
                else if (input[i] == '/') {
                    h++;
                    stk.Push(new KeyValuePair<int, int>(h, i));
                }
            }

            List<int> areaList = new List<int>();
            int total = 0;
            int area = 0;
            int index = input.Length;
            while (stk.Count > 0) {
                KeyValuePair<int, int> cur = stk.Pop();
                int upH = cur.Key;
                int upW = cur.Value;

                if (!dic.ContainsKey(upH))
                    continue;

                int downW = upW;
                while (dic[upH].Count > 0 && downW >= upW) {
                    downW = dic[upH].Pop();
                }

                if (downW >= upW)
                    continue;

                if (index > downW) {
                    index = downW;
                    areaList.Add(area);
                    area = 0;
                }

                int tempArea = upW - downW;
                total += tempArea;
                area += tempArea;
            }
            areaList.Add(area);

            StringBuilder sb = new StringBuilder();
            sb.AppendLine(total.ToString());
            sb.Append(areaList.Count - 1);
            if (areaList.Count != 1)
                for (int i = areaList.Count - 1; i > 0; i--)
                    sb.AppendFormat(" {0}", areaList[i]);
            Console.WriteLine(sb);
        }
    }
}

