            for (int i = 0; i < line.Length; i++)
            {
                var next = height;
                if (line[i] == '\\')
                {
                    next--;
                }
                else if (line[i] == '/')
                {
                    next++;
                }
                else
                {

                }

                moutains.Add(new Mountain()
                {
                    Left = left,
                    Height = height,
                    Right = next,
                    Index = i,
                });

                left = height;
                height = next;
            }

            moutains.Add(new Mountain()
            {
                Left = left,
                Height = height,
                Index = line.Length
            });

            return moutains;
        }
