namespace ALDS1_3D{
    public class Program{
        public struct Pool{
            public int Place;
            public int Area;
        }

        public static void Main(string[] args){
            var S = Console.ReadLine();

            var stkLeft = new Stack<int>();
            var stkPool = new Stack<Pool>();

            for(var i = 0; i < S.Length; i++){
                if(S[i] == '\\'){
                    stkLeft.Push(i);
                }
                else if(S[i] == '/' && stkLeft.Count > 0){
                    var left = stkLeft.Pop();
                    var right = i;

                    var place = left;
                    var area = right - left;

                    while(stkPool.Count > 0 && stkPool.Peek().Place > place){
                        area += stkPool.Pop().Area;
                    }

                    stkPool.Push(new Pool {Place = place, Area = area});
                }
            }

            Console.WriteLine(stkPool.Sum(p => p.Area));

            var res = stkPool.Count + " ";
            res += string.Join(" ", stkPool.Select(p => p.Area.ToString()).Reverse().ToArray());
            Console.WriteLine(res.Trim());
        }
    }
}

