        private static int CalculatePoolArea(string p)
        {
            var depth = 0;
            var result = 0.0;
            foreach (var item in p)
            {
                if (item == '\\')
                {
                    result = result+ 0.5 + depth;
                    depth++;
                }
                else if (item == '/')
                {
                    depth--;
                    result = result + 0.5 + depth;
                }
                else
                {
                    result = result + depth;
                }
            }
            return (int)result;
        }
    }
