    public static void print(Stack<P> st)
    {
        var n = st.Count();
        if (n == 0) { Console.WriteLine(0); Console.WriteLine(0); return; }
        var asum = st.Pop().area;
        var sb = new StringBuilder();
        sb.Append(asum);
        var ret = asum.ToString();
        for (int i = 1; i < n; i++)
        {
            var w = st.Pop();
            sb.Insert(0, " ");
            sb.Insert(0, w.area);
            asum += w.area;
        }
        sb.Insert(0, " "); sb.Insert(0, n);
        Console.WriteLine(asum);
        Console.WriteLine(sb.ToString());
    }
    public static void getAns(string s)
    {
        var st1 = new Stack<int>();
        var st2 = new Stack<P>();
        for (int i = 0; i < s.Length; i++)
            if (s[i] == '\\') st1.Push(i);
            else if (s[i] == '/' && st1.Count() > 0)
            {
                var id = st1.Pop();
                var area = i - id;
                while (st2.Count() > 0 && id <= st2.Peek().id)
                {
                    area += st2.Peek().area;
                    st2.Pop();
                }
                st2.Push(new P { id = id, area = area });
            }
        print(st2);
    }
}

