	class Program
	{
		static void Main(string[] args)
		{
			var S = Console.ReadLine().ToCharArray();
			var field = new Stack<Point>();
			var spots = new Stack<Spot>();

			for (int i = 0; i < S.Length; i++)
			{
				var p = new Point { X = i, Type = S[i] };
				if (p.Type == '/')
				{
					if (field.Count != 0)
					{
						var fp = field.Pop();
						var w = 0;
						while (0 < spots.Count && fp.X < spots.Peek().To)
						{
							w += spots.Pop().Amount;
						}

						var sp = new Spot { From = fp.X, To = p.X, Amount = w + p.X - fp.X };
