// 構造体の定義
type Stack struct {
	//空のInterfaceで任意の型に対応
	stack [20000]interface{}
	top   int
}

// 構造体に、関数を組み込む
func (s *Stack) push(x interface{}) {
	s.stack[s.top] = x
	s.top++
}

func (s *Stack) pop() interface{} {
	if s.isEmpty() {
		return -1
	}
	s.top--
	v := s.stack[s.top]
	return v
}

func (s *Stack) isEmpty() bool {
	return s.top == 0
}

func (s *Stack) isFull() bool {
	//capで、配列の容量を取得
	return s.top == cap(s.stack)
}

