	l := len(list)
	result := make([]int, l)
	for i := 0; i < l; i++ {
		result[i], _ = strconv.Atoi(list[i])
	}
	return result
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := bufio.NewReader(fp)
	writer := bufio.NewWriter(os.Stdout)

	s := getNextLine(scanner)
	l := len(s)

	stack := make([]int, l)
	waters := make([]Water, l)
	p := -1
	wp := -1
	for i := 0; i < l; i++ {
		if s[i] == '\\' {
			p++
			stack[p] = i
			continue
		}
		if p == -1 {
			continue
		}
		if s[i] == '/' {
			water := Water{
				left: stack[p],
				mm:   i - stack[p],
			}
			for wp >= 0 && waters[wp].left > water.left {
				water.mm += waters[wp].mm
				wp--
			}
			wp++
			waters[wp] = water
			p--
			continue
		}
	}
	total := 0
	for i := 0; i <= wp; i++ {
		total += waters[i].mm
	}
	fmt.Fprintln(writer, total)
	fmt.Fprint(writer, wp+1)
	for i := 0; i <= wp; i++ {
		fmt.Fprint(writer, " ")
		fmt.Fprint(writer, waters[i].mm)
	}
	fmt.Fprintln(writer, "")

	writer.Flush()
}

type Water struct {
	left int
	mm   int
}

