type Flood struct {
	first int
	areas int
}

type Stack []interface{}

func (s *Stack) peek() (val interface{}, err error) {
	l := len(*s)
	if l > 0 {
		val = (*s)[l-1]
		return
	} else {
		err = fmt.Errorf("stack is empty")
		return
	}
}

func (s *Stack) push(val interface{}) {
	*s = append(*s, val)
}

func (s *Stack) pop() (val interface{}, err error) {
	l := len(*s)
	if l > 0 {
		*s, val = (*s)[:l-1], (*s)[l-1]
		return
	} else {
		err = fmt.Errorf("stack is empty")
		return
	}
}

var sc = bufio.NewScanner(os.Stdin)

func nextLine() string {
	sc.Scan()
	return sc.Text()
}

func main() {
	s := nextLine()
	stack := make(Stack, 0, len(s))
	floods := make(Stack, 0, len(s)/2)
	var sum int
	for i, c := range s {
		switch c {
		case '\\':
			stack.push(i)
		case '/':
			a, err := stack.pop()
			if err != nil {
				break
			}
			ai := a.(int)
			sum += i - ai
			f := Flood{i, i - ai}
			for {
				p, err := floods.peek()
				if err != nil {
					break
				}
				if p.(Flood).first > ai {
					f.areas += p.(Flood).areas
					floods.pop()
				} else {
					break
				}
			}
			floods.push(f)
		case '_':
		}
	}
	fmt.Println(sum)
	fmt.Print(len(floods))
	for _, f := range floods {
		fmt.Print(" ", f.(Flood).areas)
	}
	fmt.Println()
}

