	s1 := []int{}
	s2 := []pair{}

	sum := 0
	for i := 0; i < len(S); i++ {
		ch := S[i]
		if ch == '\\' {
			s1 = append(s1, i)
		} else if ch == '/' && len(s1) > 0 {
			j := s1[len(s1)-1]
			s1 = s1[:len(s1)-1]
			sum += i - j
			a := i - j
			for len(s2) > 0 && s2[len(s2)-1].x > j {
				a += s2[len(s2)-1].y
				s2 = s2[:len(s2)-1]
			}
			s2 = append(s2, pair{x: j, y: a})
		}
	}

	answers := []int{}
	for len(s2) > 0 {
		answers = append(answers, s2[len(s2)-1].y)
		s2 = s2[:len(s2)-1]
	}
	answers = Reverse(answers)
	fmt.Println(sum)
	if len(answers) == 0 {
		fmt.Println(len(answers))
	} else {
		fmt.Printf("%d ", len(answers))
