			fmt.Printf("%d\n", answers[i])
		} else {
			fmt.Printf("%d ", answers[i])
		}
	}
}

func Reverse(A []int) []int {
	res := []int{}

	n := len(A)
	for i := n - 1; i >= 0; i-- {
		res = append(res, A[i])
	}

	return res
}

