	ret := (*s)[last]
	*s = (*s)[:last]
	return ret
}

type S2 [][]int

func (s *S2) IsEmpty() bool {
	return len(*s) == 0
}

func (s *S2) Push(j, a int) {
	(*s) = append((*s), []int{j, a})
}

func (s *S2) Pop() (int, int) {
	last := len(*s) - 1
	ret := (*s)[last]
	*s = (*s)[:last]
	return ret[0], ret[1]
}

func (s *S2) Top() []int {
	return (*s)[len(*s)-1]
}

