	buf := bytes.Buffer{}

	buf.WriteString(strconv.Itoa(v.len()))
	buf.WriteString(" ")

	for i := 1; i <= v.top; i++ {
		valley := v.container[i]
		buf.WriteString(strconv.Itoa(valley.area))
		buf.WriteString(" ")
	}
	return strings.TrimRight(buf.String(), " ")
