func calcArea(inputText []byte) []*Pond {
	stack := []int{}
	ponds := []*Pond{}
	for currentPos, char := range inputText {
		switch char {
		case '\\':
			stack = append(stack, currentPos)
		case '/':
			if len(stack) > 0 {
				downPos := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				area := currentPos - downPos
				mergeTargetPonds, newPonds := findAndPartitionExistingPondsFor(downPos, currentPos, ponds)
				var pond *Pond
				if len(mergeTargetPonds) > 0 {
					for _, v := range mergeTargetPonds {
						area += v.area
					}
					pond = &Pond{downPos, currentPos, area}
				} else {
					pond = &Pond{downPos, currentPos, area}
				}
				ponds = append(newPonds, pond)
			}
		case '_':
			// do nothing
		default:
			panic(fmt.Errorf("unknown char: %s", char))
		}
	}
	return ponds
}

func findAndPartitionExistingPondsFor(start int, end int, ponds []*Pond) ([]*Pond, []*Pond) {
	mergeTargetPonds := []*Pond{}
	newPonds := []*Pond{}
	for i := 0; i < len(ponds); i++ {
		if ponds[i].start > start && ponds[i].end < end {
			mergeTargetPonds = append(mergeTargetPonds, ponds[i])
		} else {
			newPonds = append(newPonds, ponds[i])
		}
	}
	return mergeTargetPonds, newPonds
}

