	scan.Scan()
	in := strings.Split(scan.Text(), "")
	calcStack := NewStackV2(len(in))
	areaStack := NewStackV2(len(in))

	totalSum := 0
	for index, c := range in {
		if c == "\\" {
			calcStack.Push(index)
		} else if c == "/" && !calcStack.IsEmpty() {
			// 取出可以配对的 `\`
			a, _ := calcStack.Pop()
			// 计算横截面面积
			area := index - a.(int)
			// 横截面面积加入总面积
			totalSum += area

			// 将索引对加入面积栈
			for !areaStack.IsEmpty() {
				top, _ := areaStack.Top()
				if a.(int) < top.(Pair).first().(int) {
					area += top.(Pair).second().(int)
					areaStack.Pop()
				} else {
					break
				}
			}
			p := Pair{
				a,
				area,
			}
			areaStack.Push(p)
		}
	}

	fmt.Println(totalSum)
	areaSlice := []int{len(areaStack.GetBucket())}
	for _, i := range areaStack.GetBucket() {
		areaSlice = append(areaSlice, i.(Pair).second().(int))
	}
	trace(areaSlice)

}

