// 参考书籍实现版本
type StackV3 struct {
	top int
	capacity int
	bucket []interface{}
}

func NewStackV2(capacity int) StackV3 {
	return StackV3{
		top: 0,
		capacity: capacity,
		bucket: make([]interface{}, capacity),
	}
}

func (s *StackV3) Top() (interface{}, error) {
	if s.IsEmpty() {
		return 0, errors.New("栈空间已空")
	}

	x := s.bucket[s.top - 1]

	return x, nil
}

func (s *StackV3) Push(x interface{}) error {
	if s.IsFull() {
		return errors.New("栈空间已满")
	}

	s.bucket[s.top] = x
	s.top++

	return nil
}

func (s *StackV3) Pop() (interface{}, error) {
	if s.IsEmpty() {
		return 0, errors.New("栈空间已空")
	}

	x := s.bucket[s.top - 1]
	s.top--

	return x, nil
}

func (s *StackV3) IsFull() bool {
	return s.top >= s.capacity
}

func (s *StackV3) IsEmpty() bool {
	return s.top <= 0
}

func (s *StackV3) GetBucket() []interface{} {
	return s.bucket[:s.top]
}

