class Cell(object):
    def __init__(self, direction, x, y):
        self.direction = direction
        self.x = x
        self.y = y
        self.is_pond = False
        self.start_of_pond = False
        self.end_of_pond = False

    def get_area(self, pond_height):
        h = pond_height - self.y + 1
        if self.direction == 'f':
            return h - 1
        else:
            return h - 0.5

    @property
    def char(self):
        if self.direction == 'd':
            return '/'
        elif self.direction == 'u':
            return '\\'
        elif self.direction == 'f':
            return '|'

class Area(object):
    def __init__(self):
        self.cells = {}
        self.before_c = ''
        self.x = 0
        self.height = 0
        self.lowest = 0
        self.pond_area = []

    def put(self, c):
        if c == '\\':
            if self.before_c == '\\':
                self.height -= 1
            self.cells[self.x] = Cell('d', self.x, self.height)
        elif c == '/':
            if self.before_c == '/' or self.before_c == '_':
                self.height += 1
            self.cells[self.x] = Cell('u', self.x, self.height)
        elif c == '_':
            if self.before_c == '\\':
                self.height -= 1
            self.cells[self.x] = Cell('f', self.x, self.height)

        if self.cells[self.x].y < self.lowest:
            self.lowest = self.cells[self.x].y
        self.x += 1
        self.before_c = c

    def adjust_height(self):
        for i, c in self.cells.items():
            c.y -= self.lowest

    def is_pond(self):
        start_of_pond = None
        ponds = []
        for i_start in range(len(self.cells)):
            c_start = self.cells[i_start]

            if c_start.is_pond:
                ponds.append(c_start)
            if c_start.direction == 'u':
                if start_of_pond:
                    if start_of_pond.y == c_start.y:
                        start_of_pond = None
                        c_start.end_of_pond = True
                        self.pond_area.append(self.calc_area(ponds))
                        ponds = []
                continue
            if c_start.direction == 'f' and 0 == i_start:
                continue
            if c_start.direction == 'f' and not self.cells[i_start - 1].is_pond:
                continue
            if c_start.direction == 'f' and self.cells[i_start - 1].end_of_pond:
                continue

            for i_end in range(i_start+1, len(self.cells)):
                if c_start.is_pond:
                    break
                c_end = self.cells[i_end]
                if c_start.y <= c_end.y:
                    if c_end.direction == 'u':
                        for i in range(c_start.x, c_end.x+1):
                            self.cells[i].is_pond = True
                    elif c_end.direction == 'd':
                        continue
                    elif c_end.direction == 'f':
                        continue
                    break
            if not start_of_pond and c_start.is_pond:
                c_start.start_of_pond = True
                start_of_pond = c_start
            if c_start.is_pond and not c_start in ponds:
                ponds.append(c_start)

    def calc_area(self, ponds):
        area = 0
        height = ponds[0].y
        for c in ponds:
            area += c.get_area(height)
        return int(area)

    def show(self):
        for i, c in self.cells.items():
            p = 'p' if c.is_pond else ' '
            e = 'E' if c.end_of_pond else ''
            s = 'S' if c.start_of_pond else ''
            print('{0:02d}'.format(i) + p + c.char * (c.y+1) + e + s)

