class Cell(object):
    def __init__(self, direction, x, y):
        self.direction = direction
        self.x = x
        self.y = y
        self.is_pond = False

    def get_area(self, pond_height):
        h = pond_height - self.y + 1
        if self.direction == 'f':
            return h - 1
        else:
            return h - 0.5

    @property
    def char(self):
        if self.direction == 'd':
            return '/'
        elif self.direction == 'u':
            return '\\'
        elif self.direction == 'f':
            return '|'

class Area(object):
    def __init__(self):
        self.cells = []
        self.before_c = ''
        self.x = 0
        self.height = 0
        self.pond_idx = []
        self.area_list = []

    @property
    def top(self):
        return max([c.y for c in self.cells])

    def put(self, c):
        if c == '\\':
            if self.before_c == '\\':
                self.height -= 1
            self.cells.append(Cell('d', self.x, self.height))
        elif c == '/':
            if self.before_c == '/' or self.before_c == '_':
                self.height += 1
            self.cells.append(Cell('u', self.x, self.height))
        elif c == '_':
            if self.before_c == '\\':
                self.height -= 1
            self.cells.append(Cell('f', self.x, self.height))
        self.x += 1
        self.before_c = c

    def adjust_height(self):
        lowest = min([c.y for c in self.cells])
        for c in self.cells:
            c.y -= lowest

    def is_pond(self):
        for i_start in range(len(self.cells)):
            c_start = self.cells[i_start]
            if c_start.direction == 'u':
                continue
            if c_start.direction == 'f' and 0 == i_start:
                continue
            if c_start.direction == 'f' and not self.cells[i_start - 1].is_pond:
                continue

            for i_end in range(i_start+1, len(self.cells)):
                c_end = self.cells[i_end]
                if c_start.y <= c_end.y:
                    if c_end.direction == 'u':
                        c_start.is_pond = True
                        c_end.is_pond = True
                    elif c_end.direction == 'd':
                        continue
                    elif c_end.direction == 'f':
                        continue
                    break

    def collect_pond_idx(self):
        start = None
        start_c = None
        for c in self.cells:
            if c.is_pond and start == None:
                start = c.x
                start_c = c
            elif not c.is_pond and start != None:
                self.pond_idx.append((start, c.x - 1))
                start = None
                start_c = None
            elif c.is_pond and c.direction == 'd' and c.y == start_c.y:
                self.pond_idx.append((start, c.x - 1))
                start = c.x
                start_c = c
        if start != None:
            self.pond_idx.append((start, self.cells[-1].x))

    def get_area(self, idx):
        area = 0
        pond_height = self.cells[idx[0]].y
        for i in range(idx[0], idx[1]+1):
            area += self.cells[i].get_area(pond_height)
        return int(area)

    def get_area_list(self):
        for pond in self.pond_idx:
            self.area_list.append(self.get_area(pond))

    def show(self):
        for i, c in enumerate(self.cells):
            p = 'p' if c.is_pond else ' '
            print('{0:02d}'.format(i) + p + c.char * (c.y+1))

def run():
    area = Area()
    for l in input():
        area.put(l)
    area.adjust_height()
    area.is_pond()
    area.collect_pond_idx()
    area.get_area_list()
    # area.show()
    print(sum(area.area_list))
    if area.area_list:
        print(len(area.area_list), ' '.join([str(a) for a in area.area_list]))
    else:
        print(0)

