def load_data():
    A = [0]
    for s in stdinput():
        if s == '\\':
            A.append(A[-1] - 1)
        elif s == '_':
            A.append(A[-1])
        elif s == '/':
            A.append(A[-1] + 1) 
    return A

def create_edges(A):
    edges = []
    n = len(A)
    w = int(len(A)**0.5)
    for i in range(n):
        level = A[i]
        m_idx = i - 1
        for j in range(i - 1, max(-1, i - 1 - w), -1):
            if A[j] > level:
                break
            if A[j] == level:
                m_idx = j
                break
        edges.append([m_idx, i])
    return edges

def calc_areas(A, edges):
    areas = []
    begin, end = edges[-1]
    while begin != -1:
        area = calc_area(A, begin, end)
        if area > 0:
            areas.append(area)
        begin, end = edges[begin]
    return areas[::-1]


def calc_area(A, begin, end):
    if A[begin] != A[end]:
        return 0
    b_level = A[begin]
    area = 0
    for l1, l2 in zip(range(begin, end), range(begin+1, end + 1)):
        a1 = A[l1]
        a2 = A[l2]
        area += (b_level - a1 + b_level - a2) * 1 / 2
    return area

