						if k + 1 < l_arr.len() {
							let sum = l_arr.drain(k + 1..).sum::<usize>();
							l_arr[k] += sum;
						}
					}
				}
			}
			_ => {}
		}
	}

	let mut res = format!("{}\n", l_arr.iter().sum::<usize>());

	write!(res, "{}", l_arr.len());
	for l in l_arr {
		write!(res, " {}", l);
	}
	println!("{}", res);
}

