                        }
                    }
                }
                ()
            }
            '\\' => {
                stack1.push_back(index);
                stack2.push_back((index, 0, false));
            }
            _ => (),
        }
    }
    println!("{}", area);
    let stack2_answer: Vec<(usize, u32, bool)> = stack2.iter().filter(|&x| x.2).cloned().collect();
