fn solve() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin);

    let a: Vec<_> = sc.read::<String>().chars().collect();
    let mut ranges: Vec<(usize, usize)> = vec![];
    let mut stack = vec![];
    for (i, &x) in a.iter().enumerate() {
        match x {
            '\\' => stack.push(i),
            '/' => {
                if let Some(left) = stack.pop() {
                    if stack.is_empty() {
                        ranges.push((left, i));
                    }
                }
            },
            _ => (),
        }
    }
    stack.clear();
    for (i, &x) in a.iter().enumerate().rev() {
        match x {
            '/' => stack.push(i),
            '\\' => {
                if let Some(right) = stack.pop() {
                    if stack.is_empty() {
                        ranges.push((i, right));
                    }
                }
            },
            _ => (),
        }
    }
    ranges.sort();
    ranges.dedup();

    let ans: Vec<_> = ranges.iter().map(|&(l, r)| {
        let mut sum2 = 0;
        let mut depth = 0;
        for &x in a[l..r+1].iter() {
            match x {
                '\\' => {
                    sum2 += depth * 2 + 1;
                    depth += 1;
                },
                '/' => {
                    sum2 += depth * 2 - 1;
                    depth -= 1;
                },
                _ => {
                    sum2 += depth * 2;
                },
            }
        }
        sum2 / 2
    }).collect();

    let sum = ans.iter().sum::<u32>();
    println!("{}", sum);
    println!("{} {}", ans.len(), ans.iter().join(" "));
}

