fn adjust<T, U>(ar: &mut Vec<(T, U)>)
  where T: Sized + PartialOrd,
        U: Sized + std::ops::Add<Output = U>
{
  let len = ar.len();
  if len < 2 { return; }
  if ar[len - 1].0 > ar[len - 2].0 { return; }
  let last = ar.pop().unwrap();
  let b_last = ar.pop().unwrap();
  ar.push((last.0, last.1 + b_last.1));
  adjust(ar);
}

fn main() {
  let cin = stdin();
  let cin = cin.lock();
  let mut sc = Scanner::new(cin);
  let s = scan!(sc; String);
  let mut sl = Vec::new();
  let mut ar = Vec::new();
  for (i, c) in s.chars().enumerate() {
    match c {
      '\\' => sl.push(i),
      '/'  => {
        if let Some(idx) = sl.pop() {
          let a = i - idx;
          ar.push((idx, a));
          adjust(&mut ar);
        }
      },
      _    => {}
    }
  }
  println!("{}", ar.iter().map(|&(_, u)| u).sum::<usize>());
  print!("{}", ar.len());
  for &(_, u) in ar.iter() {
