unsafe fn problem(mut io: Io) {
    let ter: Vec<char> = io.r_s().chars().collect();

    let mut puddles = Vec::new();

    let mut water_height = 0;
    let mut i = 0;
    'b: loop {
        if i == ter.len() {
            io.wl(puddles.iter().sum::<i32>());
            io.w(puddles.len());
            for p in puddles {
                io.w(' ');
                io.w(p);
            }
            io.w('\n');
            return;
        }

        match ter[i] {
            '/' => water_height += 1,
            '\\' => {
                let mut j = i;
                let mut water = 0;
                let mut height = water_height;
                loop {
                    if j == ter.len() {
                        i += 1;
                        continue 'b;
                    }
                    match ter[j] {
                        '/' => {
                            height += 1;
                            water += (water_height - height) * 2 + 1;
                        }
                        '\\' => {
                            height -= 1;
                            water += (water_height - height) * 2 - 1;
                        }
                        _ => {
                            water += (water_height - height) * 2;
                        }
                    }
                    if height == water_height {
                        puddles.push(water / 2);
                        i = j + 1;
                        continue 'b;
                    }
                    j += 1;
                }
            }
            _ => (),
        }
        i += 1;
    }
}

