enum Record {
    DownSlope(usize),
    Puddle(u32),
}

impl Quiz {
    fn solve(self) -> Answer {
        let mut ans_v = Vec::new();
        let mut stack: Vec<Record> = Vec::new();

        for (idx, shape) in self.v.into_iter().enumerate() {
            dprintln!("{} {:?}", idx, shape);
            dprintln!(" stack {:?}", stack);
            match shape {
                LandShape::Down => stack.push(Record::DownSlope(idx)),
                LandShape::Plane => (),
                LandShape::Up   => {
                    let mut tv = Vec::new();
//                    while let Some(r) = stack.pop() {
//                        if let Record::Puddle(size) = r {
//                            tv.push(size);
//                        } else {
//                            stack.push(r);
//                            break;
//                        }
//                    }
                    loop {
                        match stack.last() {
                            Some(&Record::Puddle(size)) => {
                                stack.pop();
                                tv.push(size);
                            },
                            _ => break,
                        }
                    }

                    if let Some(Record::DownSlope(left)) = stack.pop() {
                        dprintln!("  puddle! {} -> {}, includes {:?}", left, idx, tv);
                        let sum_tv = tv.iter().fold(0, |s,x| s+x);
                        let size = (idx - left) as u32 + sum_tv;
                        stack.push(Record::Puddle(size));
                    } else {
                        dprintln!("  independent puddles {:?}", tv);
                        tv.reverse();
                        for e in tv.into_iter() {
                            ans_v.push(e);
                        }
                    }
                },
            }
        }
        for e in stack {
            if let Record::Puddle(size) = e {
                ans_v.push(size);
            }
        }

        let sum = ans_v.iter().fold(0, |cur, &x| cur+x);

        Answer { 
            sum: sum,
            v: ans_v
        }
    }
}

