fn solve() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin);

    let a: Vec<_> = sc.read::<String>().chars().collect();
    let mut ranges: Vec<(usize, usize)> = vec![];
    let mut stack = vec![];
    for (i, &x) in a.iter().enumerate() {
        match x {
            '\\' => stack.push(i),
            '/' => {
                if let Some(left) = stack.pop() {
                    if stack.is_empty() {
                        ranges.push((left, i));
                    }
                }
            },
            _ => (),
        }
    }
    stack.clear();
    for (i, &x) in a.iter().enumerate().rev() {
        match x {
            '/' => stack.push(i),
            '\\' => {
                if let Some(right) = stack.pop() {
                    if stack.is_empty() {
                        ranges.push((i, right));
                    }
                }
            },
            _ => (),
        }
    }
    ranges.sort();
    ranges.dedup();

    let ans: Vec<_> = ranges.iter().map(|&(l, r)| {
        let mut sum2 = 0;
        let mut depth = 0;
        for &x in a[l..r+1].iter() {
            match x {
                '\\' => {
                    sum2 += depth * 2 + 1;
                    depth += 1;
                },
                '/' => {
                    sum2 += depth * 2 - 1;
                    depth -= 1;
                },
                _ => {
                    sum2 += depth * 2;
                },
            }
        }
        sum2 / 2
    }).collect();

    let sum = ans.iter().sum::<u32>();
    println!("{}", sum);
    print!("{}", ans.len());
    if ans.len() > 0 {
        println!(" {}", ans.iter().join(" "));
    }
}

use std::io::*;
use std::str::FromStr;

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

type Area = (usize, usize);

fn main() {
    let token_str: String = read();

    let mut index_stack: Vec<usize> = vec![];
    let mut area_stack: Vec<Area> = vec![];

    let mut sum: usize = 0;

    for (i, token) in token_str.chars().enumerate() {
        match &token.to_string()[..] {
            "\\" => {
                index_stack.push(i);
            }
            "/" => {
                let j = index_stack.pop();
                match j {
                    Some(j) => {
                        let mut a = i - j;
                        sum += a;
                        loop {
                            let area_tuple = area_stack.pop();
                            match area_tuple {
                                Some(area) => {
                                    let (k, b) = area;
                                    if j < k {
                                        a += b;
                                    } else {
                                        area_stack.push((k, b));
                                        break;
                                    };
                                }
                                _ => {
                                    break;
                                }
                            };
                        }

                        area_stack.push((j, a));
                    }
                    _ => {}
                };
            }
            _ => {}
        }
    }

    println!("{}", sum);

    let area_stack_len = area_stack.len();
    if area_stack_len != 0 {
        print!("{} ", area_stack_len);
    } else {
        print!("{}", area_stack_len);
    }
    for i in 0..area_stack_len {
        let area = area_stack[i];
        if i != area_stack_len - 1 {
            print!("{} ", area.1);
        } else {
            print!("{}", area.1);
        }
    }
    println!("");
}

// ALDS 1_3_D: Areas on the Cross-Section Diagram

// input: \\///\_/\/\\\\/_/\\///__\\\_\\/_\/_/\

fn main() {
    let mut s1 :Vec<usize> = Vec::new();
    let mut s2 :Vec<(usize, usize)> = Vec::new();

    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();

    let mut sum = 0;

    for (i, c) in s.chars().enumerate() {
        match c {
            '\\' => {
                s1.push(i);
            },
            '/' => {
                if s1.len() > 0 {
                    let j = s1.pop().unwrap();
                    let mut a = i - j;
                    sum += a;
                    while s2.len() > 0 {
                        let pair = s2.pop().unwrap();
                        let first = pair.0;
                        let second = pair.1;
                        if first <= j  {
                            s2.push(pair);
                            break;
                        }
                        a += second;
                    }
                    s2.push((j, a));
                }
            },
            _ => {
                // Do nothing.
            }
        }
    }

    let mut ans: Vec<usize> = Vec::new();
    while s2.len() > 0 {
        let pair = s2.pop().unwrap();
        let second = pair.1;
        ans.push(second);
    }
    ans.reverse();

    println!("{}", sum);
    print!("{}", ans.len());
    for a in &ans {
        print!(" {}", a);
    }
    println!();
}
